import type { FigureSpec } from "@/lib/figureTypes";

export interface Question {
  q: string;
  choices: string[];
  answer: number; // index into choices
  explain: string;
  // Name of the Pattern (from data/curriculum.ts) within this subskill that
  // this question tests, when it maps cleanly to exactly one pattern's
  // method. Used to show a method-based explanation tied back to the
  // lesson when a student answers incorrectly. Omitted for questions that
  // don't cleanly map to a single current pattern.
  pattern?: string;
  // Shown as a pill on the practice quiz, same styling as worked examples.
  // Assigned by a length/complexity heuristic across the whole bank rather
  // than hand-graded per question -- a fast first pass, not a guarantee
  // every label is exactly right.
  difficulty?: "easy" | "medium" | "hard";
  // The exact substring of `q` (as it literally appears there) to render
  // underlined -- the tested word for a Words in Context question, or the
  // specific sentence a text-structure "underlined sentence" question is
  // asking about. Matches the real exam's own underline convention instead
  // of leaving the student to relocate it themselves.
  underline?: string;
  // One entry per choice, in authored order: for each wrong choice, the
  // index of the trap it represents in its pattern's `traps` list (see
  // data/curriculum.ts), or null. Always null for the correct answer.
  // Lets a miss say which mistake it was, not just that it was one.
  trapFor?: (number | null)[];
  // A table, graph, or plot drawn to scale from its own data (see
  // lib/figureTypes.ts), shown between the setup and the question.
  figure?: FigureSpec;
}

// Full practice question bank: original questions written to match official
// SAT digital format and difficulty (not sourced from any test-maker's
// question bank). Roughly 12-16 questions per subskill.
export const QUESTIONS: Record<string, Question[]> = {
  "rw-central-ideas": [
  { q: "Over the past decade, a city has converted more than sixty vacant lots into small neighborhood parks. The initiative never had a large budget to work with; what it had instead was a core group of volunteers who showed up, month after month, to plan and maintain each new site.\n\nWhich choice best states the main idea of the text?", choices: ["The park initiative succeeded largely because of steady volunteer effort rather than money.", "The city converted more than sixty vacant lots into parks over the past decade.", "Community projects can improve city neighborhoods in many different ways.", "Without a larger budget, the initiative will struggle to maintain its parks."], answer: 0, explain: "The text's point is what made the parks possible: not a big budget but a core of volunteers who kept showing up. The sixty lots are a supporting fact, and the line about community projects could describe almost any text.", pattern: "Whole-Passage Main Idea", difficulty: "easy", trapFor: [null, 0, 1, null], },
  { q: "When she first began layering electronic effects over traditional blues scales, critics dismissed the combination as a gimmick unworthy of serious attention. Audiences, however, responded immediately, filling clubs to hear a sound no one else was making.\n\nWhat is the main idea of the text?", choices: ["Critics dismissed her blend of electronics and blues, but audiences embraced it right away.", "Critics are generally unreliable judges of which new music will succeed.", "Audiences filled clubs to hear a sound that no other musician was making.", "Electronic effects have become a standard feature of modern blues music."], answer: 0, explain: "The text is built on a contrast: critics called her sound a gimmick, audiences loved it immediately. The claim about critics in general goes far beyond one musician, and the full clubs are one detail of the audience's side.", pattern: "Whole-Passage Main Idea", difficulty: "easy", trapFor: [null, 1, 2, null], },
  { q: "Automation eliminated hundreds of assembly-line jobs at the town's largest factory over the past five years. At the same time, it created a new wave of technician and repair positions, most of which sit unfilled because they require training the laid-off workers never received.\n\nWhich choice best captures the central idea of the text?", choices: ["Automation replaced assembly-line jobs with new positions the laid-off workers aren't trained for.", "Automation has cost the town's largest factory hundreds of jobs in the past five years.", "The factory now employs more technicians than it employs assembly-line workers.", "Technological change affects workers in many industries in different ways."], answer: 0, explain: "The text pairs lost assembly-line jobs with new technician jobs that sit empty because the laid-off workers lack the training. The job losses alone are only the first half, and nothing compares the numbers of technicians and line workers.", pattern: "Whole-Passage Main Idea", difficulty: "medium", trapFor: [null, 0, null, 1], },
  { q: "In temperate forests, earthworm activity speeds up nutrient cycling, breaking down leaf litter faster and making nutrients available to plant roots sooner. In northern forests that never had native earthworm populations, however, introducing earthworms can disrupt fungal networks that took centuries to establish.\n\nWhich choice best expresses the main idea of the text?", choices: ["Whether earthworms help or harm a forest depends on whether the forest evolved with them.", "Earthworms speed up nutrient cycling by breaking down leaf litter more quickly.", "Earthworms should be removed from northern forests to protect fungal networks.", "Northern forests depend more on fungal networks than temperate forests do."], answer: 0, explain: "The text sets a benefit (temperate forests) against a harm (northern forests with no native earthworms), so the point is that the effect depends on the forest. Faster nutrient cycling is only the first half, and the text never recommends removing earthworms.", pattern: "Whole-Passage Main Idea", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "A species of migratory bird has gradually shifted its route several hundred miles north over the past thirty years. Researchers tracking the shift found it tracks almost exactly with a corresponding decline in insect availability along the bird's traditional path.\n\nWhich choice best states the central idea of the text?", choices: ["The bird's northward route shift closely matches a decline in insects along its old path.", "The bird now migrates along a route several hundred miles north of its old one.", "Changes in the environment can affect animal behavior in many different ways.", "Insect populations have declined throughout the bird species' entire range."], answer: 0, explain: "The text's point is the connection researchers found: the route moved north as insects declined along the old path. The route change alone leaves out the finding, and 'throughout the entire range' overstates the insect decline.", pattern: "Whole-Passage Main Idea", difficulty: "easy", trapFor: [null, 0, 1, null], },
  { q: "Narrow streets are often assumed to worsen traffic, but the assumption doesn't hold up consistently. Paired with clear sightlines at intersections, narrow streets actually reduce vehicle speeds and improve pedestrian safety; without those sightlines, the safety benefit mostly disappears.\n\nWhat is the main idea of the text?", choices: ["Narrow streets improve pedestrian safety only when intersections have clear sightlines.", "Narrow streets are commonly assumed to make traffic worse than wide streets do.", "Narrow streets reduce vehicle speeds, which makes them safer for pedestrians.", "City planners should widen any streets that lack clear sightlines at intersections."], answer: 0, explain: "The text qualifies the benefit of narrow streets: it mostly disappears without clear sightlines. The common assumption is where the text starts, not its point, and the speed-and-safety choice drops the condition that matters.", pattern: "Whole-Passage Main Idea", difficulty: "medium", trapFor: [null, 0, 2, null], },
  { q: "Publishers rejected the novelist's earliest manuscripts as \"too experimental,\" citing the same fragmented, nonlinear style she was known for throughout her career. Decades later, that same style is what literary historians point to when they credit her with founding an entire movement.\n\nWhat is the main idea of the text?", choices: ["The experimental style publishers once rejected later earned her credit for founding a movement.", "Publishers rejected her earliest manuscripts for being too experimental.", "Literary historians now consider her the most important novelist of her era.", "Writers often have to wait many years before their work is appreciated."], answer: 0, explain: "The same style is rejected early and celebrated later; that turn is the main idea. The rejection alone is half the story, and 'most important novelist of her era' is never claimed.", pattern: "Whole-Passage Main Idea", difficulty: "easy", trapFor: [null, 2, null, 1], },
  { q: "The strike's specific demands were, by most historians' accounts, fairly modest and unremarkable for the era. What made the strike succeed was something else entirely: political groups that agreed on almost nothing else found common cause in supporting the workers, producing a unified public pressure rarely seen before or since.\n\nWhich choice best states the main idea of the text?", choices: ["The strike succeeded because of unusually unified public support, not because of its demands.", "The strike's demands were modest and typical of labor demands at the time.", "Political groups that usually disagree will sometimes cooperate on labor issues.", "The workers won support by making demands that every political group favored."], answer: 0, explain: "The text downplays the demands and credits the rare alliance of political groups. The modest demands are the opening point the text moves past, and the text never says the demands themselves won anyone over.", pattern: "Whole-Passage Main Idea", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "A river restoration project removed an aging dam that had blocked fish migration for over 60 years. Within two years of its removal, biologists counted salmon spawning nearly 40 miles upstream of the former dam site for the first time in decades.\n\nAccording to the text, what did biologists observe within two years of the dam's removal?", choices: ["Salmon were spawning nearly 40 miles upstream of the former dam.", "Salmon were still unable to migrate past the former dam site.", "The project had removed a dam more than 60 years old.", "Salmon had returned to spawn in every stream above the dam."], answer: 0, explain: "The observation is the salmon spawning 40 miles upstream. The dam's age is background, not something observed, and 'every stream' overstates what was counted.", pattern: "Detail Comprehension in Informational Texts", difficulty: "easy", trapFor: [null, 1, 0, 2], },
  { q: "A museum replaced its incandescent gallery lighting with LED fixtures in 2021. Energy costs for lighting fell by 62% the following year, while the museum reported no changes to its visitor attendance or gallery hours during that period.\n\nAccording to the text, what happened to the museum's lighting energy costs after the 2021 switch?", choices: ["They fell by 62% in the year after the switch.", "They rose by 62% in the year after the switch.", "They fell by 62% as visitor attendance also fell.", "They stopped entirely once the LEDs were installed."], answer: 0, explain: "The text states a 62% drop. 'Rose' reverses it, the text says attendance didn't change, and 'stopped entirely' overstates a 62% drop.", pattern: "Detail Comprehension in Informational Texts", difficulty: "easy", trapFor: [null, 1, null, 2], },
  { q: "Two neighborhoods installed different streetlights as part of a pilot program. In Neighborhood A, LED streetlights were linked to a 15% drop in reported nighttime accidents. In Neighborhood B, which installed motion-activated lighting instead, reported nighttime accidents rose by 4% over the same period.\n\nAccording to the text, what happened in Neighborhood B?", choices: ["Reported nighttime accidents rose by 4%.", "Reported nighttime accidents fell by 15%.", "LED streetlights were installed.", "Reported nighttime accidents fell by 4%."], answer: 0, explain: "The 15% drop and LED lights both belong to Neighborhood A; Neighborhood B, with motion-activated lighting, saw accidents rise by 4% instead. Mixing up which neighborhood had which result is the trap here.", pattern: "Detail Comprehension in Informational Texts", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "A species of desert ant forages almost exclusively within two hours of sunrise, despite daytime temperatures remaining mild enough for activity for several more hours. Researchers tracking individual ants found that colonies foraging later in the morning lost significantly more workers to predatory birds that become active as temperatures rise.\n\nWhich question does the text most directly attempt to answer?", choices: ["How many worker ants does a typical colony contain?", "Why do the ants restrict their foraging to such an early window?", "What temperature is too hot for the ants to survive?", "Which predatory bird species poses the greatest threat to the ants?"], answer: 1, explain: "The text links the early foraging window to survival (later foragers lose more workers to birds), directly explaining why the timing exists. The other questions sound plausible but are never actually addressed.", pattern: "Detail Comprehension in Informational Texts", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "The following text is from a novel. The narrator is helping her younger brother prepare for his first day at a new school.\n\nI laid out his shirt the night before, then laid out a second one when he couldn't decide, then a third. In the morning he wore the first one anyway, the one I'd picked before he'd even seen the others.\n\nAccording to the text, what does the narrator do the night before her brother's first day of school?", choices: ["She lays out several shirts because he can't decide which to wear.", "She packs his school supplies so that he won't forget anything.", "She insists that he wear the first shirt she chose for him.", "She reassures him that he will make new friends quickly."], answer: 0, explain: "She lays out a shirt, then a second and a third when he can't decide. He does end up in the first one, but the text never says she insisted; the other two choices describe things the text never mentions.", pattern: "Reading Literary Narratives and Poetry", difficulty: "easy", trapFor: [null, 2, 2, 0], },
  { q: "The following text is adapted from a novel.\n\nAunt Priya had run the family's bookshop for thirty years without ever once raising her voice at an employee, a fact the newer clerks found almost unsettling; more than one had confided to a coworker that they'd have preferred a scolding to the quiet, patient correction Aunt Priya offered instead, since a scolding, at least, would have been over quickly.\n\nAccording to the text, how do the newer clerks regard Aunt Priya's manner of correcting mistakes?", choices: ["They find it more uncomfortable than an outright scolding would be.", "They believe she is too lenient to run the shop effectively.", "They resent her thirty years of experience.", "They think she corrects mistakes too infrequently."], answer: 0, explain: "The clerks would have preferred a quick scolding over her quiet, patient correction — meaning they find the patient approach harder to sit through, not that she's lenient or corrects too rarely.", pattern: "Reading Literary Narratives and Poetry", difficulty: "medium", trapFor: [null, 0, 2, 2], },
  { q: "The following text is adapted from a poem.\n\nThe clock above the platform keeps the hour\nfor everyone but the one still waiting there;\nfor her, the minute hand has learned to loiter,\nto stretch each second thinner than she can bear.\n\nWhat does the poem suggest about how the person waiting experiences time?", choices: ["Time seems to drag for her even though the clock keeps steady time.", "She has waited so long that she no longer notices the clock at all.", "She believes the clock above the platform has stopped working.", "She feels that time is passing too quickly for her to prepare."], answer: 0, explain: "The clock keeps the hour 'for everyone but' her; for her the minute hand 'loiters' and each second stretches. That's time feeling slow, not a broken clock (the clock is fine for everyone else) and not time rushing.", pattern: "Reading Literary Narratives and Poetry", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "A gym introduced a point system that rewards members for attending classes; points can be redeemed for gym merchandise. In the year after the system launched, total class attendance rose by 35%, while the number of gym members stayed roughly the same.\n\nBased on the text, what can most reasonably be concluded?", choices: ["The rise in class attendance came from existing members attending more, not from new members.", "The point system attracted a large number of new members who attend classes regularly.", "Members attended more classes because the gym lowered its prices during the same year.", "The point system was the only reason that class attendance increased that year."], answer: 0, explain: "Attendance rose 35% while membership stayed flat, so the same people were coming more often. New members are ruled out by the flat membership, prices are never mentioned, and 'the only reason' claims more than the text shows.", pattern: "Reasonable Conclusions Supported by the Text", difficulty: "medium", trapFor: [null, 0, 0, 2], },
  { q: "A publisher requires every debut novelist under contract to complete a three-month, in-house editing bootcamp before submitting a first draft. Comparing books published under this system to a matched sample of debut novels from other publishers, the publisher found significantly fewer requests for major post-acceptance revisions. Every debut novel under the bootcamp system, however, still took at least a year to move from acceptance to publication, similar to the industry average.\n\nBased on the text, what would most likely have been true if the publisher had never introduced the bootcamp?", choices: ["Its debut novels would likely have required more major post-acceptance revisions.", "Its debut novels would have been published faster than the industry average.", "The publisher would have stopped accepting debut novelists altogether.", "Its debut novels would have needed no revisions of any kind."], answer: 0, explain: "The bootcamp is specifically linked to fewer major revision requests, so without it, that advantage would likely disappear. Publication timelines stayed at the industry average either way, so nothing supports a faster timeline.", pattern: "Reasonable Conclusions Supported by the Text", difficulty: "hard", trapFor: [null, 0, 0, 2], },
  { q: "A software company rolled out a new onboarding tutorial to new users of its app. Users who completed the tutorial were significantly more likely to still be using the app after three months than users who skipped it. Crucially, the company found that users who completed the tutorial and users who skipped it reported similar levels of interest in the app during initial sign-up surveys, before either group had seen the tutorial.\n\nIt can most reasonably be inferred that this initial-interest data was important for which reason?", choices: ["It ruled out a difference in initial interest as the reason for the gap in retention.", "It proved that every user who skipped the tutorial had low interest in the app.", "It showed that initial interest is a better predictor of retention than the tutorial is.", "It demonstrated that the sign-up survey was flawed and needed to be redesigned."], answer: 0, explain: "If the two groups had started out with different interest levels, that alone could explain the retention gap. Showing they started out similar closes off that alternative explanation, strengthening the case for the tutorial itself.", pattern: "Reasonable Conclusions Supported by the Text", difficulty: "hard", trapFor: [null, 2, 0, 0], },
  { q: "Many beekeepers assume that honeybees gather nectar from whatever flowers are closest to the hive. When biologist Talia Moreno tracked foragers from twelve hives, however, she found that bees routinely flew past nearby patches of clover to reach fields of wildflowers more than a mile away, where each flower held more nectar.\n\nWhich choice best states the main idea of the text?", choices: ["Moreno's tracking suggests that honeybees choose flowers by nectar reward, not just distance.", "Many beekeepers believe that honeybees visit the flowers closest to their hives.", "Honeybees are able to fly more than a mile from their hive to gather nectar.", "Wildflowers generally produce more nectar than clover does in most regions."], answer: 0, explain: "The text sets up a common assumption and then overturns it: bees skipped nearby clover for richer, farther flowers. The beekeepers' belief is only the setup, and the mile-long flights are one detail of the finding.", pattern: "Whole-Passage Main Idea", difficulty: "easy", trapFor: [null, 0, 2, null], },
  { q: "For years, the library in the town of Brellin measured its success by the number of books checked out, a figure that fell steadily through the 2010s. When the library began also counting visits to its free classes, homework help, and job-search workshops, a different picture emerged: overall use of the library had nearly doubled over the same period.\n\nWhich choice best states the main idea of the text?", choices: ["Counting only book checkouts hid the fact that the library was being used more than ever.", "Book checkouts at the Brellin library fell steadily throughout the 2010s.", "Libraries today offer many services besides lending books to the public.", "The library's job-search workshops became its single most popular service."], answer: 0, explain: "The falling checkouts are the misleading measure; the point is that a fuller count showed use nearly doubling. The statement about libraries in general could fit almost any text, and nothing ranks the services.", pattern: "Whole-Passage Main Idea", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "Octopuses have long been studied for their intelligence, but most of that research has focused on solving puzzles in laboratory tanks. Marine biologist Idris Okafor argues that such tests capture only a narrow slice of octopus behavior. In the wild, he notes, octopuses adjust their hunting strategies to tides, prey, and the presence of predators, a flexibility that no lab puzzle is designed to measure.\n\nWhich choice best states the main idea of the text?", choices: ["Okafor argues that lab puzzles miss much of what octopus intelligence looks like in the wild.", "Octopuses have been studied by scientists for many years because of their intelligence.", "Octopuses change their hunting strategies depending on the tides and their prey.", "Laboratory research on animal intelligence is rarely useful to marine biologists."], answer: 0, explain: "Okafor's argument is the text's point: puzzle tests capture a narrow slice, and the wild shows more. The hunting strategies are his supporting example, and he never dismisses lab research as useless.", pattern: "Whole-Passage Main Idea", difficulty: "medium", trapFor: [null, 0, 2, null], },
  { q: "Scholars of medieval manuscripts once treated the drawings in the margins of these books as idle doodles. Art historian Paulina Reyes has catalogued thousands of them, from snails battling knights to monkeys playing instruments, and she argues that readers expected and enjoyed them. The margins, in her view, were a space where artists could comment on, and even poke fun at, the serious text beside them.\n\nWhich choice best states the main idea of the text?", choices: ["Reyes argues that marginal drawings were a valued, often playful commentary on the text beside them.", "Medieval manuscripts often include drawings of snails, knights, and monkeys in the margins.", "Scholars once treated the drawings in medieval manuscript margins as idle doodles.", "Artists who drew in the margins were often criticized for mocking serious texts."], answer: 0, explain: "The text moves from the old view (doodles) to Reyes's argument (valued commentary), and her argument is the point. The snails and monkeys are examples, and the old view is what she argues against.", pattern: "Whole-Passage Main Idea", difficulty: "hard", trapFor: [null, 2, 0, null], },
  { q: "Engineers designing earthquake-resistant buildings once focused on making structures as rigid as possible. Many newer designs take a different approach. By placing flexible bearings between a building and its foundation, engineers allow the ground to move beneath the structure while the building itself sways only slightly, reducing the force that reaches its upper floors.\n\nWhich choice best states the main idea of the text?", choices: ["Engineers have moved from making buildings rigid to letting them move separately from the ground.", "Buildings in earthquake zones were once designed to be as rigid as possible.", "Flexible bearings reduce the amount of force that reaches a building's upper floors.", "Modern engineering has made buildings much safer during many kinds of disasters."], answer: 0, explain: "The text contrasts the old goal (rigidity) with the newer one (letting the ground move under the building). The old goal is only the starting point, the reduced force is one detail, and 'many kinds of disasters' goes beyond earthquakes.", pattern: "Whole-Passage Main Idea", difficulty: "medium", trapFor: [null, 0, 2, 1], },
  { q: "In 2019 the city of Kestrel Falls replaced its diesel buses with electric ones on four of its twelve routes. Over the next two years, riders on those four routes filed 40% fewer complaints about noise, though complaints about delays stayed about the same across the whole system.\n\nAccording to the text, what happened on the four routes with electric buses?", choices: ["Riders filed 40% fewer complaints about noise.", "Riders filed 40% fewer complaints about delays.", "Riders filed 40% more complaints about noise.", "Riders stopped complaining about noise at all."], answer: 0, explain: "The 40% drop was in noise complaints. Delay complaints stayed about the same, 'more' reverses the change, and 'stopped at all' overstates it.", pattern: "Detail Comprehension in Informational Texts", difficulty: "easy", trapFor: [null, 0, 1, 2], },
  { q: "Ecologist Hana Sato compared two kinds of hedgerows along farm fields. Hedgerows that were trimmed every year had fewer bird nests than untrimmed ones, but they had more nesting bumblebees, which prefer the sunnier, more open ground at their base.\n\nAccording to the text, how did the yearly-trimmed hedgerows compare with the untrimmed ones?", choices: ["They had fewer bird nests but more nesting bumblebees.", "They had more bird nests but fewer nesting bumblebees.", "They had fewer bird nests and fewer nesting bumblebees.", "They had no bird nests but many nesting bumblebees."], answer: 0, explain: "Trimmed hedgerows: fewer bird nests, more bumblebees. The second choice reverses both, the third reverses one, and 'no bird nests' overstates 'fewer'.", pattern: "Detail Comprehension in Informational Texts", difficulty: "medium", trapFor: [null, 1, 1, 2], },
  { q: "Some sea turtles return to lay eggs on the same beach where they hatched, even after decades at sea. Researchers have found that young turtles appear to record the unique magnetic signature of their home beach and later use Earth's magnetic field to find their way back.\n\nWhich question does the text most directly address?", choices: ["How do sea turtles find their way back to the beach where they hatched?", "Why do sea turtles spend several decades at sea before laying eggs?", "How many eggs does a sea turtle lay on the beach where it hatched?", "Which beaches around the world are most popular with nesting turtles?"], answer: 0, explain: "The research described explains how turtles navigate home: by the beach's magnetic signature. The decades at sea are mentioned but never explained, and egg counts and popular beaches never come up.", pattern: "Detail Comprehension in Informational Texts", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "Economist Rafael Duarte studied a program that gave small loans to street vendors. Vendors who received loans increased their sales by an average of 18% in the first year. Duarte cautions, however, that most of the increase came from vendors who were already selling more than their neighbors before the program began; vendors with the lowest sales saw little change.\n\nAccording to the text, what does Duarte say about the vendors who had the lowest sales before the program?", choices: ["Their sales changed little after they received loans.", "Their sales rose by an average of 18% in the first year.", "They accounted for most of the program's rise in sales.", "They were not allowed to receive loans from the program."], answer: 0, explain: "Duarte says the lowest-selling vendors 'saw little change.' The 18% is the average across all vendors, and most of the increase came from the vendors who were already doing well.", pattern: "Detail Comprehension in Informational Texts", difficulty: "hard", trapFor: [null, 0, 1, null], },
  { q: "The following text is adapted from a short story. Nell has just moved from the city to her grandfather's farm.\n\nNell had expected the farm to be quiet. Instead, the mornings were loud with roosters, the afternoons with the rattle of the old tractor, and the nights with a chorus of frogs from the pond. By the end of her first week, she found she could no longer fall asleep without them.\n\nWhich choice best states the main idea of the text?", choices: ["The farm isn't the quiet place Nell expected, and she quickly comes to depend on its sounds.", "The constant noise of the farm keeps Nell from sleeping during her first week there.", "Nell misses the city and wishes she could return to its familiar noises.", "Nell learns to operate her grandfather's old tractor during her first week."], answer: 0, explain: "Nell expected quiet, found noise, and by week's end can't sleep without it. Assuming the noise must bother her misreads the last sentence, and nothing says she misses the city.", pattern: "Reading Literary Narratives and Poetry", difficulty: "medium", trapFor: [null, 0, 2, null], },
  { q: "The following text is from a poem. The speaker describes a kitchen table.\n\nIt has held the bills and the birthday cakes,\nthe homework, the flour, the elbows of guests;\nits surface is scarred where a knife once slipped,\nand polished where every hand has rested.\n\nWhich choice best describes the speaker's view of the table?", choices: ["It carries the marks of a household's life, both the everyday and the special.", "It is too scarred and worn to be useful and should be replaced.", "It is a painful reminder of an accident that happened in the kitchen.", "It is valuable mainly because it is old and was carefully made."], answer: 0, explain: "The table holds bills and birthday cakes alike, and both its scars and its polish come from use. Nothing suggests replacing it, and the slipped knife is one small detail, not a painful memory.", pattern: "Reading Literary Narratives and Poetry", difficulty: "medium", trapFor: [null, 0, 2, 2], },
  { q: "The following text is adapted from a novel. Ruth has just been offered a promotion that would require her to move across the country.\n\nRuth read the email twice and then closed the laptop. She walked to the window, where the maple she had planted the spring she moved in was just starting to turn orange. She stood there a long while before she opened the laptop again.\n\nBased on the text, how does Ruth most likely feel about the offer?", choices: ["She is torn, weighing the offer against her attachment to her current home.", "She is thrilled and plans to accept the offer as soon as she can reply.", "She is angry that the company expects her to move so far away.", "She regrets planting a tree that she will now have to leave behind."], answer: 0, explain: "She rereads the email, stares at the tree she planted when she moved in, and pauses a long while: she's weighing what she'd leave. Nothing shows excitement or anger, and she never says she regrets planting the tree.", pattern: "Reading Literary Narratives and Poetry", difficulty: "medium", trapFor: [null, 0, 0, 2], },
  { q: "In a study of 500 households, researchers found that homes with smart thermostats used 10% less energy for heating than homes without them. However, the homes with smart thermostats were also, on average, newer and better insulated.\n\nBased on the text, what can most reasonably be concluded?", choices: ["The study alone can't show how much of the savings came from the thermostats themselves.", "Installing a smart thermostat will reduce heating energy use by 10% in any home.", "Insulation has little effect on how much energy a home uses for heating.", "Older homes are less likely than newer homes to benefit from smart thermostats."], answer: 0, explain: "The thermostat homes differed in other ways (newer, better insulated) that also save energy, so the study can't separate the effects. 'Any home' overstates the finding, and nothing in the text compares how much older homes would benefit.", pattern: "Reasonable Conclusions Supported by the Text", difficulty: "hard", trapFor: [null, 2, 0, 0], },
  { q: "A bakery began labeling its bread with the date it was baked. In the following month, sales of day-old bread fell by half, while sales of bread baked that morning rose by nearly the same number of loaves. Total bread sales were unchanged.\n\nBased on the text, what can most reasonably be concluded?", choices: ["After the labels appeared, many customers switched from day-old bread to fresh bread.", "The date labels led the bakery to sell more loaves of bread overall that month.", "Customers stopped buying day-old bread entirely once they could see the labels.", "The bakery lowered the price of its fresh bread during the same month."], answer: 0, explain: "Day-old sales fell by about as many loaves as fresh sales rose, with the total flat: customers switched. Total sales didn't rise, day-old sales fell by half rather than to zero, and prices are never mentioned.", pattern: "Reasonable Conclusions Supported by the Text", difficulty: "medium", trapFor: [null, 0, 2, 0], },
  { q: "Archaeologists excavating a Bronze Age settlement found grinding stones in nearly every house but ovens in only three of the forty houses they excavated. Each of the three houses with an oven also contained far more grinding stones than any other house.\n\nBased on the text, which conclusion is most reasonable?", choices: ["The few houses with ovens may have baked for other households as well as their own.", "Most households in the settlement did not grind any grain for their own use.", "The three houses with ovens were the homes of the settlement's leaders.", "Every household in the settlement baked its own bread each day."], answer: 0, explain: "Only three houses could bake, and those same houses held far more grinding equipment, which suggests they processed grain for more than one household. Grinding stones were in nearly every house, nothing points to leaders, and 37 houses had no oven.", pattern: "Reasonable Conclusions Supported by the Text", difficulty: "hard", trapFor: [null, 0, 0, null], },
],
  "rw-evidence": [
  { q: "A student researching urban heat claims that tree cover reduces what households spend on summer energy.\n\nWhich finding, if true, would most directly support the student's claim?", choices: ["Homes shaded by street trees used about 20% less electricity for summer cooling than similar unshaded homes.", "Neighborhoods with more tree cover had higher average property values than neighborhoods with little shade.", "The city planted over 5,000 street trees last year, more than in any previous year in its history.", "Residents of tree-lined streets reported spending more time outdoors during the summer months."], answer: 0, explain: "Only the first choice measures summer energy use and ties it to shade. Property values and time outdoors are related to trees but not to energy costs, and the number of trees planted says nothing about bills.", pattern: "Direct Quantitative Support", difficulty: "easy", trapFor: [null, 0, 1, 0], },
  { q: "An education researcher argues that early literacy programs have lasting benefits: children who take part in such programs before kindergarten, the researcher claims, still read better years later.\n\nWhich finding, if true, would most directly support the researcher's claim?", choices: ["Students who completed a pre-K literacy program scored 15% higher on 8th-grade reading tests than similar peers.", "Students who completed a pre-K literacy program scored higher on kindergarten reading tests than similar peers.", "More than 40,000 children enrolled in pre-K literacy programs across the state last year.", "By 8th grade, students who completed a pre-K literacy program scored slightly lower on reading tests than similar peers."], answer: 0, explain: "The claim is about benefits 'years later,' so the 8th-grade comparison fits. A kindergarten result is too soon to show a lasting benefit, enrollment numbers measure nothing, and the last choice points the wrong way.", pattern: "Direct Quantitative Support", difficulty: "medium", trapFor: [null, 0, 1, 2], },
  { q: "A company introduced a remote work policy in 2022. Its human resources director claims that the policy made employees more likely to stay with the company.\n\nWhich finding, if true, would most directly support the director's claim?", choices: ["Annual employee turnover at the company fell from 22% to 9% in the two years after the policy began.", "Annual employee turnover at the company rose from 9% to 22% in the two years after the policy began.", "Employees who work remotely report spending about 40 fewer minutes a day commuting than before.", "Most employees said in a survey that they prefer flexible schedules to fixed ones."], answer: 0, explain: "Staying with the company is measured by turnover, and the first choice shows turnover falling after the policy. The second reverses the direction; commute time and schedule preferences don't measure whether people stayed.", pattern: "Direct Quantitative Support", difficulty: "easy", trapFor: [null, 2, 1, 0], },
  { q: "A city launched a bike-share program with 300 stations. A transportation analyst claims that the program has reduced the number of short car trips people take in the city.\n\nWhich finding, if true, would most directly support the analyst's claim?", choices: ["Traffic sensors recorded 12% fewer car trips under two miles in the program's first year than in the year before.", "Traffic sensors recorded 12% more car trips under two miles in the program's first year than in the year before.", "Riders took more than 250,000 trips on the program's bikes during its first year of operation.", "Traffic sensors recorded no change in car trips longer than ten miles during the program's first year."], answer: 0, explain: "The claim is about short car trips, and only the first choice shows them falling. The second reverses the direction, bike trips alone don't show fewer car trips, and trips over ten miles aren't the ones the claim is about.", pattern: "Direct Quantitative Support", difficulty: "medium", trapFor: [null, 2, 1, 0], },
  { q: "A team of researchers surveyed adults about their sleep habits. The team claims that its sample was representative of the country's adult population as a whole.\n\nWhich finding, if true, would most directly support the team's claim?", choices: ["The age, income, and regional makeup of the participants closely matched national census figures.", "The study surveyed more than 12,000 adults, a larger sample than most earlier sleep studies used.", "The study's findings were published in a peer-reviewed journal after an independent review.", "Most of the participants were recruited from the student body of a single large university."], answer: 0, explain: "A sample is representative when it looks like the population, which is what matching census figures shows. A large sample can still be lopsided, peer review doesn't address who was surveyed, and a single university's students would undercut the claim.", pattern: "Direct Quantitative Support", difficulty: "medium", trapFor: [null, 1, 0, 2], },
  { q: "A nutritionist claims that people who follow a particular diet plan keep the weight off over the long term rather than regaining it within a few months.\n\nWhich finding, if true, would most directly support the nutritionist's claim?", choices: ["Two years after starting the plan, participants had kept off an average of 90% of the weight they lost.", "Participants lost an average of 14 pounds in the first three months of following the plan.", "Two years after starting the plan, participants had regained an average of 90% of the weight they lost.", "More than 200,000 people have bought the plan's guidebook since it was first released."], answer: 0, explain: "'Over the long term' needs a long follow-up, and the two-year result shows the weight stayed off. Three months is too short, regaining 90% points the other way, and sales figures measure nothing about weight.", pattern: "Direct Quantitative Support", difficulty: "medium", trapFor: [null, 0, 2, 1], },
  { q: "A historian argues that a nineteenth-century famine in a coastal region was worsened by wartime trade restrictions, not only by the poor harvests that preceded it.\n\nWhich finding, if true, would most directly support the historian's argument?", choices: ["Neighboring regions with similar harvest failures but open trade routes did not suffer comparable shortages.", "Food shortages in the coastal region began soon after the wartime trade restrictions took effect.", "Records show that harvests in the coastal region were poor for three years in a row.", "The wartime trade restrictions also cut off supplies of cloth, tools, and lamp oil to the region."], answer: 0, explain: "The comparison holds the harvest failures constant and changes only the trade routes, so the difference points to the restrictions. Timing alone could be coincidence, poor harvests support the other explanation, and cloth and tools say nothing about food.", pattern: "Ruling Out Alternative Explanations", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "An economist claims that a minimum wage increase in a particular city did not lead to significant job losses.\n\nWhich finding, if true, would most directly support the economist's claim?", choices: ["After the increase, low-wage employment in the city held steady, as it did in similar nearby cities that kept wages the same.", "Most business owners surveyed before the increase said they did not plan to cut any jobs because of it.", "Average hourly pay for low-wage workers in the city rose by 11% in the year after the increase.", "Low-wage employment in the city fell by 8% after the increase, while nearby cities without one saw no change."], answer: 0, explain: "Employment held steady in the city and in similar cities without the increase, so the increase didn't change the trend. Plans made beforehand aren't outcomes, higher pay doesn't measure jobs, and the last choice shows job losses.", pattern: "Ruling Out Alternative Explanations", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Transportation officials claim that a bridge redesign improved traffic flow rather than simply shifting congestion onto other roads.\n\nWhich finding, if true, would most directly support the officials' claim?", choices: ["Commute times fell on the bridge and its connecting roads, with no rise in traffic on alternate routes.", "Average rush-hour commute times across the redesigned bridge fell by about nine minutes.", "Traffic on the most popular alternate route increased by 20% after the redesign was finished.", "The redesign added a lane in each direction and widened the bridge's on-ramps."], answer: 0, explain: "To rule out shifted congestion you need to check the alternate routes, and only the first choice does. Faster bridge times alone would fit either explanation, and a 20% rise on an alternate route points toward shifting.", pattern: "Ruling Out Alternative Explanations", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "A school district claims that a new reading intervention closed the achievement gap between two groups of students.\n\nWhich finding, if true, would most directly support the district's claim?", choices: ["The gap narrowed from 18 points to 4, while a comparison group without the intervention saw no change.", "The gap narrowed from 18 points to 4 points during the years the intervention was in place.", "Teachers who used the intervention rated it highly in their end-of-year surveys.", "Both groups' reading scores rose by about the same amount while the intervention was used."], answer: 0, explain: "The comparison group rules out a gap that was closing anyway, so the first choice ties the change to the intervention. The second shows the gap narrowing but not why, teacher ratings aren't results, and equal gains would leave the gap unchanged.", pattern: "Ruling Out Alternative Explanations", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "A table shows the number of visitors to four museum exhibits last month: Fossils, 4,200; Textiles, 1,900; Space, 6,100; Ceramics, 2,400. A newsletter notes that among these exhibits, the most-visited last month was ______.\n\nWhich choice most effectively uses data from the table to complete the statement?", choices: ["Space, with 6,100 visitors.", "Fossils, with 4,200 visitors.", "Ceramics, with 2,400 visitors.", "Textiles, with 1,900 visitors."], answer: 0, explain: "Space has the highest visitor count. The other choices correctly report their own exhibit's number, but none of those is the maximum.", pattern: "Reading Data from a Graph or Table", difficulty: "easy", trapFor: [null, 0, 0, 0], },
  { q: "A bar graph shows a school's weekly cafeteria food waste, in pounds, over one month: Week 1, 340; Week 2, 310; Week 3, 275; Week 4, 260. A report on the school's waste-reduction program notes that after Week 1, food waste ______.\n\nWhich choice most effectively uses data from the graph to complete the statement?", choices: ["decreased in each subsequent week.", "increased in each subsequent week.", "stayed the same for the rest of the month.", "decreased, then rose sharply in Week 4."], answer: 0, explain: "Each week's value is lower than the one before it. 'Increased' reverses the direction, 'stayed the same' ignores the change, and Week 4 (260) is actually the lowest value, not a sharp rise.", pattern: "Reading Data from a Graph or Table", difficulty: "easy", trapFor: [null, null, null, 0], },
  { q: "A dental clinic claims that its new appointment-reminder texts reduced missed appointments. In the six months after the texts began, the clinic's monthly no-show rate fell from 18% to 9%. Over the same period, a similar clinic that did not send reminder texts saw its no-show rate fall from 17% to 15%.\n\nWhich choice best describes data that support the clinic's claim?", choices: ["The clinic's no-show rate fell 9 points, while the clinic without texts fell only 2 points.", "Both clinics saw their no-show rates decrease over the six-month period studied.", "The clinic's no-show rate of 9% was lower than the other clinic's no-show rate of 15%.", "The clinic sent an average of two reminder texts per scheduled appointment."], answer: 0, explain: "Comparing how much each clinic's rate actually changed (9 points vs. 2 points) rules out a general trend and isolates the texts' effect. The other choices either don't distinguish the two clinics' amount of change or don't measure the change at all.", pattern: "Reading Data from a Graph or Table", difficulty: "hard", trapFor: [null, 0, 0, null], },
  { q: "A software company claims that its new tutorial increased how long users engage with the app. Average weekly usage among users who completed the tutorial rose from 42 minutes to 58 minutes in the two months after it launched. Average weekly usage among users who skipped the tutorial rose from 40 minutes to 54 minutes over the same period.\n\nWhich choice best describes data that weaken the company's claim?", choices: ["Both groups' average weekly usage rose by a similar amount — about 16 minutes for tutorial users and about 14 minutes for those who skipped it.", "Users who completed the tutorial had higher average usage than those who skipped it, both before and after the tutorial launched.", "Tutorial users averaged 58 minutes of weekly usage in the two months after the tutorial launched.", "The company's tutorial takes an average of six minutes for new users to complete."], answer: 0, explain: "If both groups increased by nearly the same amount, something other than the tutorial is likely driving the change. The other choices are true but don't address whether the tutorial itself caused the increase.", pattern: "Reading Data from a Graph or Table", difficulty: "hard", trapFor: [null, 0, 0, null], },
  { q: "A short story states that a young musician feels overwhelmed with joy after finally being accepted into a prestigious conservatory.\n\nWhich quotation from the story most effectively illustrates this claim?", choices: ["\"She read the acceptance letter twice, then a third time, her hands shaking too much to hold the paper steady.\"", "\"She had submitted applications to six different conservatories that spring.\"", "\"The conservatory's audition process was known to be especially rigorous.\"", "\"She placed the letter on the kitchen table and went back to practicing scales.\""], answer: 0, explain: "The claim names overwhelming joy specifically. The other quotations are either neutral facts with no emotional content or show a muted, indifferent reaction — only the shaking-hands quotation shows the physical signs of overwhelming emotion.", pattern: "Selecting the Best Supporting Quotation", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "A historian argues that a nineteenth-century inventor's most significant contribution was not any single device but a manufacturing process that made mass production of his designs possible.\n\nWhich quotation from a biography of the inventor would most directly support this argument?", choices: ["\"His workshop employed over forty craftspeople at its peak, more than any competitor in the region.\"", "His interchangeable-parts system let lightly trained workers assemble identical parts, halving production time.", "\"He held twelve patents by the end of his career, more than any other inventor of his generation.\"", "\"His designs were praised for their elegant simplicity by critics of the era.\""], answer: 1, explain: "The claim is specific: the contribution was a manufacturing process, not scale or output or aesthetics. Only the interchangeable-parts quotation describes an actual process and its effect on production.", pattern: "Selecting the Best Supporting Quotation", difficulty: "medium", trapFor: [0, null, 0, 0], },
  { q: "A poem is said to convey the speaker's homesickness through a single recurring image rather than direct statement.\n\nWhich quotation from the poem most effectively illustrates this claim?", choices: ["\"I miss my home more with every mile.\"", "\"The porch light in my memory never quite goes out.\"", "\"Travel changes a person in ways both large and small.\"", "\"I wondered, some nights, if I'd made the right choice.\""], answer: 1, explain: "The claim specifies a technique — one recurring image, not a direct statement of the feeling. The first quotation states homesickness outright, and the other two are general reflections with no recurring image; only the porch-light quotation matches the claim's specific technique.", pattern: "Selecting the Best Supporting Quotation", difficulty: "medium", trapFor: [0, null, 0, 0], },
  { q: "A novel states that a diplomat remains outwardly gracious during a hostile negotiation while privately losing patience.\n\nWhich quotation most effectively illustrates this claim?", choices: ["\"He excused himself from the table and did not return for the remainder of the session.\"", "He smiled and thanked the delegation for their candor, though under the table his foot kept tapping.", "\"He had negotiated dozens of similar agreements over his long career.\"", "\"He later remarked to an aide that the session had tried his patience considerably.\""], answer: 1, explain: "The claim requires both halves at once — outward graciousness and hidden impatience, during the negotiation itself. Only the second quotation shows a gracious spoken response alongside a hidden physical sign of impatience at the same moment.", pattern: "Selecting the Best Supporting Quotation", difficulty: "hard", trapFor: [1, null, 0, 0], },
  { q: "Researchers hypothesize that a species of moth locates flowers primarily by scent rather than by color.\n\nWhich finding, if true, would most strongly support this hypothesis?", choices: ["Moths whose sense of smell was blocked took far longer to find flowers than moths whose color vision was blocked.", "The moths are active mainly at night, when the colors of most flowers are hard to see.", "The flowers the moths visit most often also produce the strongest scents in the area.", "The moths were observed visiting flowers of many different colors over a single night."], answer: 0, explain: "Blocking each sense in turn isolates which one the moths rely on, and losing smell hurt far more. The others are consistent with scent mattering but never test it: strong-scented flowers might also be the most visible ones.", pattern: "Evaluating a Hypothetical Finding's Effect on a Claim", difficulty: "hard", trapFor: [null, 0, 2, 1], },
  { q: "A city official claims that a new curbside composting program caused a significant drop in the amount of household waste sent to the landfill.\n\nWhich finding, if true, would most directly weaken this claim?", choices: ["Landfill waste had already been falling at the same rate for two years before the program began.", "The composting program is available to households in every neighborhood of the city.", "Participation in the program increased steadily throughout its first year of operation.", "Landfill waste in the city fell by 18% in the program's first year, the largest drop on record."], answer: 0, explain: "If waste was already falling at the same rate, the program didn't change the trend. Availability and participation describe the program, and a record drop would, if anything, support the official.", pattern: "Evaluating a Hypothetical Finding's Effect on a Claim", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "An economist claims that a country's new export tariff caused a decline in a specific industry's revenue.\n\nWhich finding, if true, would most strongly support this claim?", choices: ["Revenue in the industry fell after the tariff, while the same industry in a neighboring country without one kept growing.", "The industry had been the largest contributor to the country's economy for more than a decade.", "The industry's revenue fell in the year after the tariff took effect.", "Government officials debated the tariff's likely effects for months before it was passed."], answer: 0, explain: "The neighboring country is a comparison without the tariff, which rules out a region-wide slump. A drop after the tariff could have many causes, and the industry's size and the debate don't measure the effect.", pattern: "Evaluating a Hypothetical Finding's Effect on a Claim", difficulty: "hard", trapFor: [null, 0, 2, 0], },
  { q: "A researcher hypothesizes that a particular species of ant increases its foraging speed specifically because of a chemical trail laid by other ants, rather than for any other reason.\n\nWhich finding, if true, would most directly weaken this hypothesis?", choices: ["Ants foraging alone, with no chemical trail present, sped up their foraging just as much when the air temperature increased.", "Ants were observed laying chemical trails between the nest and multiple food sources.", "The chemical trail is composed of a pheromone unique to this ant species.", "Colonies with more ants tended to establish chemical trails more quickly than smaller colonies did."], answer: 0, explain: "If solitary ants with no trail present sped up just as much due to a completely different factor, the trail isn't necessary to produce faster foraging, undermining the claim that the trail itself is the cause.", pattern: "Evaluating a Hypothetical Finding's Effect on a Claim", difficulty: "hard", trapFor: [null, 0, 0, 0], },
  { q: "Nutrition researcher Amara Obi claims that students at a local high school eat more vegetables when the cafeteria places them at the start of the lunch line rather than at the end.\n\nWhich finding, if true, would most directly support the claim?", choices: ["On days when vegetables were placed first in line, students took 30% more vegetable servings than on other days.", "On days when vegetables were placed first in line, students took 30% fewer vegetable servings than on other days.", "Students at the school said they prefer cooked vegetables to raw vegetables by a two-to-one margin.", "The cafeteria serves about 900 lunches each day, and every lunch includes a vegetable side."], answer: 0, explain: "The claim compares vegetable-first days with other days, and the first choice shows more servings on those days. The second reverses the direction; preferences and the number of lunches served don't measure the effect of placement.", pattern: "Direct Quantitative Support", difficulty: "easy", trapFor: [null, 2, 0, 1], },
  { q: "A city official claims that adding protected bike lanes to Elm Avenue made the street safer for cyclists.\n\nWhich finding, if true, would most directly support the official's claim?", choices: ["Crashes involving cyclists on Elm Avenue fell from 31 in the year before the lanes to 12 in the year after.", "The number of cyclists using Elm Avenue rose from about 400 to about 900 per day after the lanes opened.", "Crashes involving only cars on Elm Avenue fell by 20% in the year after the lanes opened.", "Crashes involving cyclists on Elm Avenue rose from 12 in the year before the lanes to 31 in the year after."], answer: 0, explain: "Safety for cyclists is measured by cyclist crashes, and those fell. More riders is popularity, not safety; car-only crashes aren't about cyclists; and the last choice reverses the direction.", pattern: "Direct Quantitative Support", difficulty: "medium", trapFor: [null, 1, 0, 2], },
  { q: "An energy analyst claims that since 2015, the share of a country's electricity that comes from wind power has grown faster than the share that comes from solar power.\n\nWhich finding, if true, would most directly support the analyst's claim?", choices: ["Wind's share of the country's electricity rose from 4% to 12% since 2015, while solar's rose from 3% to 6%.", "The country installed more new solar panels than new wind turbines in every year since 2015.", "Wind's share of the country's electricity rose from 4% to 6% since 2015, while solar's rose from 3% to 12%.", "The country generated more electricity in 2023 than in any previous year on record."], answer: 0, explain: "The claim compares growth in shares: wind gained 8 points, solar 3. Counts of panels and turbines aren't shares of electricity, the third choice has solar growing faster, and total output says nothing about the mix.", pattern: "Direct Quantitative Support", difficulty: "hard", trapFor: [null, 0, 2, 1], },
  { q: "A school district claims that its new math tutoring program, rather than a statewide rise in scores, explains why its students' math scores improved this year.\n\nWhich finding, if true, would most directly support the district's claim?", choices: ["District math scores rose 9 points this year, while scores in similar districts without the program rose 1 point.", "District math scores rose 9 points this year, the largest one-year gain in the district's history.", "Students who used the program said in surveys that they felt more confident in math class.", "Math scores rose by about 9 points this year in school districts across the state."], answer: 0, explain: "Only a comparison with similar districts can separate the program from a statewide rise, and those districts barely moved. A record gain alone could be statewide, confidence isn't a score, and a statewide 9-point rise supports the alternative.", pattern: "Ruling Out Alternative Explanations", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "A coffee shop owner believes that the shop's sales rose last spring because it began offering oat milk, not because the weather was warmer than usual.\n\nWhich finding, if true, would most directly support the owner's belief?", choices: ["Sales rose 15% last spring, while a nearby shop without oat milk saw no change despite the same weather.", "The shop's sales rose by 15% last spring compared with the spring before.", "Last spring was the warmest spring in the town in more than a decade.", "Customers who ordered oat milk drinks tended to be younger than other customers."], answer: 0, explain: "The nearby shop had the same weather but no oat milk and no sales rise, which rules out the weather. A rise alone fits either explanation, and the record warmth supports the weather explanation.", pattern: "Ruling Out Alternative Explanations", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "A student is researching how often teens read for fun. Surveys in the town of Aldermoor found that 34% of teens read for fun daily in 2014, 28% in 2018, and 22% in 2022. The student notes that from 2014 to 2022, the share of Aldermoor teens who read for fun daily ______\n\nWhich choice most effectively uses data from the surveys to complete the statement?", choices: ["fell by 12 percentage points, from 34% to 22%.", "rose by 12 percentage points, from 22% to 34%.", "fell by 6 percentage points, from 34% to 28%.", "fell by half, from 34% to about 17%."], answer: 0, explain: "From 2014 (34%) to 2022 (22%) is a 12-point drop. The second choice runs the years backward, the third stops at 2018, and 17% isn't in the data.", pattern: "Reading Data from a Graph or Table", difficulty: "easy", trapFor: [null, 1, 0, 2], },
  { q: "A table shows average rainfall, in millimeters, in two towns in January and July. Tellmore: January 80, July 20. Wyncastle: January 30, July 95. A student claims that the two towns have their wettest months at opposite times of year.\n\nWhich choice most effectively uses data from the table to support the student's claim?", choices: ["Tellmore is wetter in January than July (80 vs. 20 mm), while Wyncastle is wetter in July (95 vs. 30 mm).", "Tellmore is wetter in July than January (80 vs. 20 mm), while Wyncastle is wetter in January (95 vs. 30 mm).", "Wyncastle gets more rain in July (95 mm) than Tellmore gets in January (80 mm).", "Both towns get at least 20 mm of rain in every month of the year."], answer: 0, explain: "Tellmore peaks in January and Wyncastle in July: opposite seasons. The second choice swaps the months, the third compares different months across towns, and the table only covers two months.", pattern: "Reading Data from a Graph or Table", difficulty: "medium", trapFor: [null, 1, 0, 2], },
  { q: "Researchers compared weeds in garden beds covered with different mulches. After eight weeks, beds covered with wood chips had 12 weeds per square meter, beds with straw had 18, beds with shredded leaves had 25, and beds of bare soil had 60. The researchers conclude that all three mulches reduced weeds and that ______\n\nWhich choice most effectively uses data from the study to complete the statement?", choices: ["wood chips worked best, cutting weeds to 12 per square meter compared with 60 in bare soil.", "shredded leaves worked best, cutting weeds to 25 per square meter compared with 60 in bare soil.", "straw worked least well, allowing 18 weeds per square meter compared with 12 for wood chips.", "wood chips removed nearly all weeds, leaving fewer than one per square meter."], answer: 0, explain: "Wood chips had the fewest weeds (12). Shredded leaves (25) did worst of the mulches, not best, straw wasn't the weakest, and 12 per square meter isn't 'nearly all' gone.", pattern: "Reading Data from a Graph or Table", difficulty: "medium", trapFor: [null, 0, 0, 2], },
  { q: "Before a new train line opened in a city, 55% of commuters drove, 30% took the bus, and 15% walked or biked. After it opened, 40% drove, 25% took the bus, 20% took the train, and 15% walked or biked. A planner claims that the train drew riders both from people who used to drive and from people who used to take the bus.\n\nWhich choice most effectively uses data from the study to support the planner's claim?", choices: ["After the line opened, the share who drove fell 15 points and the share who took the bus fell 5 points.", "After the line opened, 20% of commuters took the train, while 15% still walked or biked.", "After the line opened, the share who drove fell 5 points and the share who took the bus fell 15 points.", "After the line opened, the share who drove fell 15 points, from 55% to 40%."], answer: 0, explain: "The claim needs both groups to shrink, and the first choice shows both drops correctly (55 to 40, 30 to 25). The third swaps the numbers, and the last covers drivers only.", pattern: "Reading Data from a Graph or Table", difficulty: "hard", trapFor: [null, 0, 1, 0], },
  { q: "A student claims that in a novel, the narrator's grandmother shows kindness while keeping up a stern manner.\n\nWhich quotation from the novel most effectively illustrates the student's claim?", choices: ["\"Eat,\" she said, not looking up, and pushed the last of the bread across the table to me.", "She had lived in the same stone house for sixty years and never once painted its door.", "When I broke her favorite bowl, she laughed so hard that she had to sit down.", "She rarely spoke at dinner, and when she did, it was usually to correct someone's manners."], answer: 0, explain: "Giving away the last of the bread is kind; the curt 'Eat' without looking up is stern. The laughing grandmother is warm but not stern, and correcting manners shows sternness without kindness.", pattern: "Selecting the Best Supporting Quotation", difficulty: "medium", trapFor: [null, 0, 1, 0], },
  { q: "A literary critic argues that in a poem about loss, the speaker's grief is expressed through images of stillness.\n\nWhich quotation from the poem most effectively illustrates the critic's claim?", choices: ["\"The swing hangs motionless above the yard, / and even the dust on the sill has settled.\"", "\"I shouted your name at the rolling sea / until the gulls themselves fell silent.\"", "\"The yard was yours; you planted every rose / that climbs the fence beside the gate.\"", "\"Spring came late that year, and the rain / fell every day for weeks on end.\""], answer: 0, explain: "A motionless swing and settled dust are images of stillness. Shouting at the sea is grief, but loud and moving, not still; the roses recall the person without any stillness.", pattern: "Selecting the Best Supporting Quotation", difficulty: "medium", trapFor: [null, 1, 0, 0], },
  { q: "A historian claims that Clara Denholm, who wrote letters to her sister in the 1850s, was skeptical of the promised benefits of the new railway reaching her village.\n\nWhich quotation from Denholm's letters most effectively illustrates the historian's claim?", choices: ["\"They tell us the railway will bring prosperity; I will believe it when I see a single shop reopen.\"", "\"The railway workers arrived in March, and by summer the tracks had reached the edge of the village.\"", "\"What a marvel it is to reach the city in an afternoon, a journey that once took us two days!\"", "\"I confess I know little of engines, though our brother speaks of nothing else these days.\""], answer: 0, explain: "'I will believe it when I see' doubts the promised prosperity directly. The construction timeline is neutral, the 'marvel' line is enthusiastic, and admitting she knows little about engines isn't doubt about the benefits.", pattern: "Selecting the Best Supporting Quotation", difficulty: "hard", trapFor: [null, 0, 1, 0], },
  { q: "Plant biologist Nadia Ferrante hypothesizes that tomato plants grown near basil have fewer aphids because basil's scent repels the insects.\n\nWhich finding, if true, would most directly support Ferrante's hypothesis?", choices: ["Tomato plants surrounded by basil oil, with no basil plants nearby, had as few aphids as tomatoes grown near basil.", "Tomato plants grown near basil were taller on average than tomato plants grown on their own.", "Aphids were found on both the basil plants and the tomato plants growing in the same garden.", "Gardeners who grew basil near their tomatoes reported fewer aphid problems than other gardeners."], answer: 0, explain: "Basil oil supplies the scent without the plant, so matching results point to the scent itself. Plant height isn't aphids, and the gardeners' reports show basil and fewer aphids together without isolating the scent.", pattern: "Evaluating a Hypothetical Finding's Effect on a Claim", difficulty: "hard", trapFor: [null, 0, 1, 2], },
  { q: "A sleep researcher claims that teenagers who use phones in bed sleep less because light from the screen delays the body's release of melatonin, a hormone that promotes sleep.\n\nWhich finding, if true, would most directly weaken the researcher's claim?", choices: ["Teens who used phones in bed with the screen light filtered out slept just as little as other phone users.", "Teens who used phones in bed slept about 40 minutes less per night than teens who did not.", "Screen light has also been found to delay melatonin release in adults.", "Many teens say they mostly use their phones in bed to talk with friends."], answer: 0, explain: "If filtering out the light doesn't help, the light isn't what's cutting their sleep. The 40-minute gap fits the claim, the adult finding supports the mechanism, and what teens do on their phones doesn't test it.", pattern: "Evaluating a Hypothetical Finding's Effect on a Claim", difficulty: "hard", trapFor: [null, null, null, 0], },
  { q: "An ecologist claims that the recovery of a lake's trout population was caused by the removal of an invasive fish species in 2016.\n\nWhich finding, if true, would most strongly support the ecologist's claim?", choices: ["Trout also recovered in a second lake after the invasive fish were removed, but not in a similar lake where they remained.", "The trout population in the lake has grown steadily in every year since 2016.", "The invasive fish species was first introduced to the lake in the 1980s.", "Trout populations have been rising in many lakes across the region since 2016."], answer: 0, explain: "The comparison of lakes with and without the invasive fish isolates removal as the cause. Steady growth since 2016 only shows timing, and a region-wide rise suggests some other cause.", pattern: "Evaluating a Hypothetical Finding's Effect on a Claim", difficulty: "hard", trapFor: [null, 2, 0, null], },
],
  "rw-inferences": [
  { q: "Every prior attempt to breed the orchid in captivity had failed within its first year, so when this specimen survived to bloom, researchers immediately began ______.\n\nWhich choice most logically completes the text?", choices: ["documenting every environmental condition that differed from previous attempts", "assuming the success was accidental and unlikely to be repeated", "discontinuing the breeding program entirely", "publishing results without further observation"], answer: 0, explain: "Given a first-ever success after repeated failures, the logical next step is to carefully document what was different, to potentially replicate it.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "easy", trapFor: [null, 1, null, 0], },
  { q: "A centuries-old bridge has withstood earthquakes far exceeding its original design specifications. Given this pattern, engineers now believe the bridge's actual structural resilience ______.\n\nWhich choice most logically completes the text?", choices: ["exceeds what its original specifications indicate.", "was anticipated by the bridge's original builders using modern seismic standards.", "is shared by all other bridges built during the same era.", "has caused earthquakes in the region to become less frequent."], answer: 0, explain: "The bridge repeatedly surviving quakes beyond its stated design limits supports only a conclusion about its own resilience, not the builders' foresight, other bridges, or earthquake frequency.", pattern: "Multi-Step and Conditional Inferences", difficulty: "medium", trapFor: [null, null, 3, 3], },
  { q: "The negotiations had stalled for months over a single clause, so when both parties agreed to remove it entirely, the remaining terms were ______.\n\nWhich choice most logically completes the text?", choices: ["renegotiated from scratch", "finalized within days", "rejected by both sides", "kept secret from the public"], answer: 1, explain: "If the sole sticking point was removed, it logically follows that the rest of the already-agreed terms could be finalized quickly.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "easy", trapFor: [null, null, null, 1], },
  { q: "A species of desert lizard changes its foraging time from midday to dawn only in years following unusually hot summers. Since this shift occurs specifically after hot summers rather than at random, the lizard's foraging schedule appears to ______.\n\nWhich choice most logically completes the text?", choices: ["respond to recent temperatures rather than follow a fixed schedule.", "change permanently the first time a hot summer occurs.", "reflect an inability to survive hot summers at all.", "have no real connection to temperature conditions."], answer: 0, explain: "The shift's specific link to hot summers points to temperature-responsiveness, not permanent change, survival failure, or no connection at all.", pattern: "Multi-Step and Conditional Inferences", difficulty: "medium", trapFor: [null, 0, 3, null], },
  { q: "The startup had rejected every acquisition offer for a decade, so when it finally accepted one from a former competitor, analysts speculated that ______.\n\nWhich choice most logically completes the text?", choices: ["the company's finances had likely weakened considerably", "the founders had lost interest in the entire industry", "no other offers had ever been made", "the acquisition would be reversed within a year"], answer: 0, explain: "A sudden reversal of a decade-long pattern of rejection most reasonably suggests a change in underlying circumstances, such as financial pressure.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "medium", trapFor: [null, 0, null, 0], },
  { q: "A translated manuscript contains several idioms with no direct equivalent in the target language, and each idiom has been rendered differently by different translators over time. Because these renderings vary from translator to translator, translating the manuscript's untranslatable idioms most likely ______.\n\nWhich choice most logically completes the text?", choices: ["required each translator to make an individual interpretive choice.", "was intended by the original author to produce multiple accepted meanings.", "has never been successfully accomplished by any translator.", "produced translations that are all equally accurate to the original."], answer: 0, explain: "Varying renderings of the same untranslatable idiom directly point to individual interpretive choices, not authorial intent, translation failure, or equal accuracy — none of which the text supports.", pattern: "Multi-Step and Conditional Inferences", difficulty: "hard", trapFor: [null, null, 3, 3], },
  { q: "The committee had approved every prior proposal within a week, so when this one remained under review after two months, staff began to suspect ______.\n\nWhich choice most logically completes the text?", choices: ["an unusual objection had been raised", "the committee had stopped meeting entirely", "the proposal had already been rejected", "no further proposals would be considered"], answer: 0, explain: "A sharp break from a consistent fast-approval pattern most reasonably suggests something atypical is causing delay, such as an objection.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "easy", trapFor: [null, 0, 1, 0], },
  { q: "A river historically flooded every spring, but it has not flooded in the ten years since an upstream dam was completed. Given this decade-long change, the dam has most likely ______.\n\nWhich choice most logically completes the text?", choices: ["altered the river's seasonal flow patterns.", "eliminated the possibility of the river ever flooding again.", "revealed that spring flooding was never a real pattern to begin with.", "been built for the specific purpose of preventing recreational flooding."], answer: 0, explain: "A decade without the previously reliable spring flood, right after the dam's completion, supports a conservative conclusion about altered flow — not an absolute guarantee, a denial of the original pattern, or an unstated purpose.", pattern: "Multi-Step and Conditional Inferences", difficulty: "medium", trapFor: [null, 3, null, null], },
  { q: "The chef had used the same supplier for fifteen years, so when she abruptly switched to a new one right before the restaurant's biggest event, staff assumed ______.\n\nWhich choice most logically completes the text?", choices: ["the usual supplier had failed to meet an urgent need", "the restaurant was closing permanently", "the new supplier was cheaper in every case", "quality no longer mattered to the chef"], answer: 0, explain: "An abrupt switch from a long-standing supplier right before a critical event most reasonably implies the usual supplier could not meet a pressing need.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "medium", trapFor: [null, 0, 2, 1], },
  { q: "Fossil evidence shows a particular insect species disappeared from a region's fossil record for two million years before reappearing largely unchanged. Since the species shows no significant change upon reappearing, its two-million-year absence from the record most likely reflects ______.\n\nWhich choice most logically completes the text?", choices: ["survival elsewhere or a gap in local fossil preservation, rather than rapid evolutionary change.", "a period of extremely rapid evolution that later reversed itself completely.", "an error in the fossil record predating the gap.", "the complete absence of insects anywhere during that period."], answer: 0, explain: "Reappearing unchanged rules out rapid evolution as the explanation for the gap, pointing instead toward survival elsewhere or incomplete local preservation, not a claim about insects everywhere or the record's prior accuracy.", pattern: "Multi-Step and Conditional Inferences", difficulty: "hard", trapFor: [null, 0, null, 3], },
  { q: "The city council had rejected similar zoning changes three times before, so when it passed unanimously this time, observers concluded that ______.\n\nWhich choice most logically completes the text?", choices: ["support for the proposal had shifted since the earlier votes", "the council no longer had the authority to reject proposals", "the earlier rejections had been procedural errors", "future zoning proposals would automatically pass as well"], answer: 0, explain: "A unanimous pass after repeated rejections most reasonably implies a meaningful shift in circumstances or support, not a change in the council's authority or a rule about future votes.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "medium", trapFor: [null, 1, 1, 2], },
  { q: "A language has no native word for a specific color, yet its speakers can distinguish that color from others in visual tests. Because these speakers pass the visual tests despite lacking a word for the color, a language's vocabulary ______.\n\nWhich choice most logically completes the text?", choices: ["does not necessarily limit its speakers' visual perception.", "prevents its speakers from perceiving colors they cannot name.", "must include a word for every color that exists in its speakers' environment.", "has no relationship whatsoever to how speakers think about color."], answer: 0, explain: "Passing the visual test without a specific word supports a conservative claim that vocabulary and perception aren't strictly linked — not the opposite claim, an unsupported rule about every language, or an overreaching claim of zero relationship.", pattern: "Multi-Step and Conditional Inferences", difficulty: "medium", trapFor: [null, null, 3, 3], },
  { q: "The lab had published a null result twice before under different conditions, so when a third team found the same lack of effect using yet another method, the field began to ______.\n\nWhich choice most logically completes the text?", choices: ["treat the null result as increasingly well-supported", "dismiss all three studies as flawed", "conclude the original hypothesis had never been tested", "abandon the research area completely"], answer: 0, explain: "Convergent null results across independent methods most reasonably strengthen confidence in that result, rather than undermining it or ending inquiry.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "medium", trapFor: [null, 0, 1, 0], },
  { q: "A historical trade route fell out of use within a decade of a mountain pass along that route becoming impassable due to volcanic activity. Given how closely the route's decline followed the pass becoming impassable, the route's decline ______.\n\nWhich choice most logically completes the text?", choices: ["was likely connected to the loss of that specific pass.", "proves that the pass was the route's only viable path.", "shows that volcanic activity has no effect on trade routes generally.", "indicates the route had already been abandoned before the volcanic activity."], answer: 0, explain: "The tight timing between the pass becoming impassable and the route's decline supports a conservative inference of connection, not the stronger claim that the pass was the only viable path, a broad claim about trade routes generally, or a timeline reversal.", pattern: "Multi-Step and Conditional Inferences", difficulty: "medium", trapFor: [null, 3, 3, null], },
  { q: "The novelist had turned down every film adaptation offer for twenty years, citing creative control concerns, so when she finally agreed to one that gave the studio full script authority, critics speculated that ______.\n\nWhich choice most logically completes the text?", choices: ["her concerns about creative control had eased", "she had stopped writing novels altogether", "every future adaptation of her work would give studios full control", "the studio had misrepresented the terms of the deal"], answer: 0, explain: "She refused for twenty years because of creative control, then accepted a deal that gave control away; the simplest explanation is that her concern had changed. Nothing suggests she quit writing, 'every future adaptation' overreaches, and misrepresentation is pure assumption.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "medium", trapFor: [null, 0, 2, 1], },
  { q: "Most bats hunt insects using echolocation, sending out high-pitched calls and listening for the echoes. Some moths can hear these calls and dive toward the ground when they detect one. A few moth species, however, have no hearing organs at all. These moths most likely ______\n\nWhich choice most logically completes the text?", choices: ["rely on defenses other than hearing to avoid being caught by bats.", "are never hunted by bats that use echolocation to find prey.", "dive toward the ground whenever a bat calls somewhere nearby.", "have evolved the ability to produce echolocation calls themselves."], answer: 0, explain: "Moths without ears can't use the dive-on-hearing defense, so if they survive bats, they must rely on something else. Nothing says bats ignore them, they can't dive at a call they can't hear, and producing calls is a dramatic leap.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "medium", trapFor: [null, 1, null, 0], },
  { q: "Historians studying the diary of a nineteenth-century ship's cook noticed that its entries switch from careful handwriting to a hurried scrawl on the same day that the ship's log records a severe storm. The change in handwriting most likely indicates that ______\n\nWhich choice most logically completes the text?", choices: ["the cook wrote those entries under difficult conditions during the storm.", "a different person took over writing the diary after the storm.", "the cook was badly injured in the storm and never fully recovered.", "the ship's log exaggerated how severe the storm had really been."], answer: 0, explain: "Handwriting that turns hurried on the day of a storm points to writing in rough conditions. A new writer and a lasting injury both require facts the text doesn't give, and nothing questions the log.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "medium", trapFor: [null, 1, 0, 1], },
  { q: "In a survey of a town's residents, people who lived within a mile of the new park visited it about four times a month, while those who lived more than three miles away rarely visited at all. If the town wants a second park to be used as much as possible, planners should build it ______\n\nWhich choice most logically completes the text?", choices: ["near neighborhoods that are currently more than three miles from the first park.", "right next to the first park, so that the two parks can share a parking lot.", "much larger than the first park, so that it draws visitors from far away.", "in the least crowded part of town, where land is the least expensive."], answer: 0, explain: "Distance is what predicted use, so the new park should go where people don't have a park nearby. Building beside the first park serves the same people, and nothing in the survey says size attracts distant visitors.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "medium", trapFor: [null, null, 1, null], },
  { q: "Glaciers move slowly downhill, dragging rocks that scratch long grooves into the bedrock beneath them. Geologists have found such grooves in the bedrock of a region that is now a hot desert. This finding suggests that the region ______\n\nWhich choice most logically completes the text?", choices: ["was covered by glacial ice at some point in the distant past.", "will likely be covered by glaciers again in the near future.", "has always been too hot for glaciers to form there.", "was once home to many species of cold-adapted animals."], answer: 0, explain: "Glacial grooves mean a glacier once moved over that bedrock. The future and the animals are guesses beyond the evidence, and 'always too hot' contradicts it.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "easy", trapFor: [null, 0, null, 1], },
  { q: "In a taste test, participants sampled two glasses of the same juice. When told that one glass cost twice as much as the other, most participants said the \"expensive\" glass tasted better. The results suggest that ______\n\nWhich choice most logically completes the text?", choices: ["people's expectations about a product can shape how they judge its quality.", "the more expensive juice had been made with higher-quality fruit.", "people can always tell the difference between cheap and expensive products.", "juice companies should double the prices of all of their products."], answer: 0, explain: "The juice was identical, so only the price label differed; the label shaped the judgment. The fruit wasn't different, 'always tell the difference' is the opposite of what happened, and the pricing advice is a dramatic leap.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "easy", trapFor: [null, null, 2, 0], },
  { q: "Because an ancient city kept its written records on unbaked clay tablets, most of the tablets that survive today are ones that were hardened when the buildings storing them burned. Historians therefore caution that the surviving tablets ______\n\nWhich choice most logically completes the text?", choices: ["may overrepresent the records kept in buildings that happened to burn.", "prove that the city was destroyed by a single catastrophic fire.", "contain the most important records the city ever produced.", "were deliberately baked by scribes so they would last for centuries."], answer: 0, explain: "If fire decided which tablets survived, the survivors come mostly from buildings that burned, a skewed sample. Nothing says there was one great fire or that the survivors were the important ones, and the baking was accidental.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "hard", trapFor: [null, 2, 1, 1], },
  { q: "Emperor penguins huddle together in large groups during Antarctic winter storms. Within a huddle, individuals constantly shift positions, moving from the cold outer edge toward the warm center and back out again. This behavior suggests that the huddle ______\n\nWhich choice most logically completes the text?", choices: ["spreads its warmth among all of its members rather than only some.", "is controlled by the strongest penguins, who stay at the center.", "forms only during the very coldest storms of each winter.", "protects the penguins from every danger during the winter."], answer: 0, explain: "Constant rotation means each penguin takes turns at the warm center. The strongest staying put contradicts that, nothing limits huddling to the coldest storms, and 'every danger' overreaches.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "medium", trapFor: [null, 1, null, 2], },
  { q: "Archaeologists excavating a tenth-century farmhouse found the remains of a loom and hundreds of the clay weights used to hold its threads taut. Nearby, they found a pit filled with sheep bones. Together, these findings suggest that the household ______\n\nWhich choice most logically completes the text?", choices: ["likely made its own cloth, possibly from wool from sheep it raised.", "sold large amounts of cloth to traders from distant regions.", "was the wealthiest household in the entire region at the time.", "ate no meat at all other than the meat of its own sheep."], answer: 0, explain: "A loom and its weights point to weaving at home, and the sheep bones hint at a local wool source. Trade, wealth, and diet are assumptions or overreach.", pattern: "Logical Completion (Fill-in-the-Blank Style)", difficulty: "medium", trapFor: [null, 1, 0, 2], },
  { q: "Linguist Sara Imre notes that the word for \"tea\" in many languages resembles either \"cha\" or \"te.\" According to Imre, languages that borrowed the word from traders who arrived over land tend to use forms of \"cha,\" while those that borrowed it from traders who arrived by sea tend to use forms of \"te.\" If Imre is correct, a language whose word for tea resembles \"te\" most likely ______\n\nWhich choice most logically completes the text?", choices: ["first acquired the word through trade that arrived by sea.", "borrowed the word from traders who arrived over land.", "is spoken in a region where tea plants have never grown.", "borrowed the word more recently than languages that use \"cha.\""], answer: 0, explain: "Take Imre's pattern as given: \"te\" forms came by sea. The second choice reverses the pattern, and the text says nothing about where tea grows or when words were borrowed.", pattern: "Multi-Step and Conditional Inferences", difficulty: "medium", trapFor: [null, 1, 1, 1], },
  { q: "Researchers found that a certain wildflower produces more seeds in years with heavy spring rain. They also found that the flower's seeds are eaten mostly by a species of mouse whose population grows sharply in those same wet years. As a result, the number of new seedlings after a rainy spring ______\n\nWhich choice most logically completes the text?", choices: ["may be no higher than usual, since more of the seeds are likely to be eaten.", "will be much higher than usual, since the plants produce more seeds.", "will fall to zero, since the mice will eat every seed the plants produce.", "depends only on how much rain falls during the following spring."], answer: 0, explain: "More seeds, but also more mice eating them: the two effects may cancel out. The second choice uses only the first fact, 'every seed' overreaches, and nothing supports 'only next spring's rain.'", pattern: "Multi-Step and Conditional Inferences", difficulty: "hard", trapFor: [null, 0, 3, null], },
  { q: "A museum curator believes that a painting long credited to the artist Elena Voss was actually painted by one of her students. Voss always mixed her own pigments from local minerals, while her students bought ready-made paints from a supplier in the city. If the curator is correct, a chemical analysis of the painting would most likely find ______\n\nWhich choice most logically completes the text?", choices: ["paints like those sold by the city supplier rather than pigments made from local minerals.", "pigments mixed from the same local minerals that Voss herself always used.", "that the painting was made several decades earlier than historians had thought.", "that Voss had bought the paints her students used from the city supplier."], answer: 0, explain: "Assume the curator is right: a student painted it, and students used store-bought paint. Voss's own pigments would mean doubting the curator's view, and the painting's date and who paid for the paints aren't at issue.", pattern: "Multi-Step and Conditional Inferences", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "After a school library extended its closing time to 8 p.m., the number of students using the library in the evening rose sharply. The total number of library visits per week, however, stayed about the same. This suggests that ______\n\nWhich choice most logically completes the text?", choices: ["many students moved their visits to later hours rather than visiting more often.", "the later hours attracted many students who had never used the library before.", "extending the hours had no effect at all on how students used the library.", "students generally prefer studying at home to studying in the library."], answer: 0, explain: "Evening use rose while total visits held steady, so visits shifted to later hours. New users would have raised the total, 'no effect at all' ignores the shift, and home studying never comes up.", pattern: "Multi-Step and Conditional Inferences", difficulty: "medium", trapFor: [null, 0, 3, null], },
  { q: "In a long-running study of a songbird, older males sang more complex songs than younger males, and females chose to mate with males whose songs were more complex. Yet when researchers played recordings of complex and simple songs through speakers with no bird present, females showed no preference between them. Taken together, these findings suggest that females ______\n\nWhich choice most logically completes the text?", choices: ["may choose males for traits that come with age rather than for song complexity itself.", "prefer complex songs, since they mated with males whose songs were more complex.", "pay no attention at all to male song when they are choosing a mate.", "cannot hear the differences between the complex and simple songs."], answer: 0, explain: "Complex song goes with older males, but song alone doesn't sway females, so something else about older males probably does. The second choice ignores the playback result, the third overreaches, and the fourth explains only the playback, not the mating pattern.", pattern: "Multi-Step and Conditional Inferences", difficulty: "hard", trapFor: [null, 0, 3, 2], },
  { q: "In one study, students who took notes by hand remembered more of a lecture than students who typed their notes. The typists, however, recorded far more of the lecture word for word. If, as the researchers suggest, putting ideas into one's own words helps memory, the typists' disadvantage most likely came from ______\n\nWhich choice most logically completes the text?", choices: ["copying the lecture word for word instead of rephrasing its ideas.", "using laptops, which are more distracting than paper notebooks.", "recording too little of the lecture to study from afterward.", "being less interested in the lecture than the other students."], answer: 0, explain: "Accept the researchers' premise: rephrasing aids memory, and the typists rephrased the least. Distraction swaps in a different explanation, the typists recorded more, not less, and interest is never mentioned.", pattern: "Multi-Step and Conditional Inferences", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "Farmers in a valley planted a new variety of wheat that yields more grain than the old variety in dry years. In wet years, however, the new variety is more likely to be damaged by fungus. Since wet years have become more common in the valley over the past two decades, the new variety ______\n\nWhich choice most logically completes the text?", choices: ["may produce less grain in the valley than its dry-year results suggest.", "will outperform the old variety in the valley every year from now on.", "should be planted only in years that farmers expect to be dry.", "will be destroyed by fungus in every wet year from now on."], answer: 0, explain: "Its advantage is in dry years, its weakness in wet years, and wet years are more common, so the dry-year results overstate what to expect. The second choice ignores the fungus, the planting advice needs forecasting the text never mentions, and 'destroyed every wet year' overreaches.", pattern: "Multi-Step and Conditional Inferences", difficulty: "hard", trapFor: [null, 0, null, 3], },
],
  "rw-words-context": [
  { q: "As used in the text, 'the committee's austere approach to spending' most nearly means:", choices: ["generous", "strict and minimal", "confusing", "enthusiastic"], answer: 1, explain: "'Austere' in context of spending means strict, minimal, or frugal.", pattern: "Precise Synonym in Context", difficulty: "easy", underline: "austere", trapFor: [null, null, null, null], },
  { q: "Which choice completes the text with the most precise word? 'Despite the setback, her resolve remained ______.'", choices: ["unwavering", "confused", "loud", "temporary"], answer: 0, explain: "'Unwavering' precisely captures resolve that doesn't weaken despite a setback.", pattern: "Precise Synonym in Context", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "As used in the passage, 'the negotiations reached an impasse' most nearly means the negotiations:", choices: ["reached a formal agreement", "came to a standstill", "began for the first time", "were opened to the public"], answer: 1, explain: "An impasse is a point where no progress is possible, usually because the sides can't agree: a standstill.", pattern: "Precise Synonym in Context", difficulty: "medium", underline: "impasse", trapFor: [null, null, null, null], },
  { q: "Which choice completes the text with the most logical and precise word? 'The evidence was so ______ that the jury deliberated for less than an hour.'", choices: ["ambiguous", "compelling", "irrelevant", "delayed"], answer: 1, explain: "A quick deliberation implies the evidence was persuasive/compelling, not ambiguous or irrelevant.", pattern: "Precise Synonym in Context", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "As used in the text, 'a somewhat parochial view of the issue' most nearly means:", choices: ["globally informed", "narrow or limited in scope", "highly detailed", "recently developed"], answer: 1, explain: "'Parochial' describes a narrow, limited, often provincial perspective.", pattern: "Precise Synonym in Context", difficulty: "easy", underline: "parochial", trapFor: [null, null, null, null], },
  { q: "Which choice completes the text with the most precise word? 'The scientist's hypothesis, once considered ______, is now widely accepted.'", choices: ["fringe", "obvious", "irrelevant", "temporary"], answer: 0, explain: "'Fringe' captures a once-marginal idea that has since become mainstream, matching the described shift.", pattern: "Precise Synonym in Context", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "As used in the passage, 'the ruling set a precedent for future cases' most nearly means the ruling:", choices: ["was quickly overturned by a higher court", "became a model for later decisions", "applied only to the case at hand", "drew criticism from legal scholars"], answer: 1, explain: "A 'precedent' is a decision that serves as an example or standard for later, similar cases.", pattern: "Precise Synonym in Context", difficulty: "medium", underline: "precedent", trapFor: [null, null, null, null], },
  { q: "Which choice completes the text with the most precise word? 'The critique was ______, addressing only surface-level issues rather than the work's core argument.'", choices: ["cursory", "exhaustive", "hostile", "anonymous"], answer: 0, explain: "'Cursory' means hasty and superficial, matching a critique that only addresses surface issues.", pattern: "Precise Synonym in Context", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "As used in the text, 'the population's numbers began to dwindle' most nearly means the numbers:", choices: ["increased steadily", "decreased gradually", "remained constant", "fluctuated unpredictably"], answer: 1, explain: "'Dwindle' specifically means to decrease gradually, often toward a small amount.", pattern: "Precise Synonym in Context", difficulty: "easy", underline: "dwindle", trapFor: [null, null, null, null], },
  { q: "Which choice completes the text with the most precise word? 'Rather than confront the issue directly, the manager chose to ______ it in the weekly report.'", choices: ["highlight", "obscure", "celebrate", "quantify"], answer: 1, explain: "Avoiding direct confrontation while still including something in a report suggests downplaying or hiding it — 'obscure' fits precisely.", pattern: "Precise Synonym in Context", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "As used in the passage, 'her argument was notably terse' most nearly means her argument was:", choices: ["long and detailed", "brief and to the point", "emotionally charged", "difficult to follow"], answer: 1, explain: "'Terse' describes concise, often curt, brevity of expression.", pattern: "Precise Synonym in Context", difficulty: "easy", underline: "terse", trapFor: [null, null, null, null], },
  { q: "Which choice completes the text with the most precise word? 'The committee's decision was ______, reversing years of established policy without warning.'", choices: ["gradual", "abrupt", "predictable", "unanimous"], answer: 1, explain: "A sudden reversal 'without warning' is best matched by 'abrupt.'", pattern: "Precise Synonym in Context", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "As used in the text, 'the findings corroborate earlier studies' most nearly means the findings:", choices: ["contradict earlier studies", "confirm or support earlier studies", "were published before earlier studies", "are unrelated to earlier studies"], answer: 1, explain: "'Corroborate' means to confirm or provide supporting evidence for something.", pattern: "Precise Synonym in Context", difficulty: "medium", underline: "corroborate", trapFor: [null, null, null, null], },
  { q: "Which choice completes the text with the most precise word? 'The professor's explanation, while technically correct, was too ______ for beginning students to follow.'", choices: ["simplistic", "esoteric", "elementary", "encouraging"], answer: 1, explain: "'Esoteric' means understood only by a small, specialized group — fitting content too advanced for beginners.", pattern: "Precise Synonym in Context", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "As used in the passage, 'the treaty was largely a symbolic gesture' most nearly means the treaty:", choices: ["had significant practical enforcement mechanisms", "carried more ceremonial than practical weight", "was rejected by most signatories", "was kept entirely secret"], answer: 1, explain: "'Symbolic' here signals the treaty mattered more for its representative meaning than for concrete enforcement.", pattern: "Precise Synonym in Context", difficulty: "medium", underline: "symbolic", trapFor: [null, null, null, null], },
  { q: "Although the team's first prototype failed repeatedly, the engineers remained ______, convinced that small adjustments would eventually solve the problem.\n\nWhich choice completes the text with the most logical and precise word or phrase?", choices: ["optimistic", "complacent", "indifferent", "euphoric"], answer: 0, explain: "'Convinced that small adjustments would eventually solve the problem' describes hopeful confidence: optimistic. 'Euphoric' is far too strong for people facing repeated failure, and 'complacent' implies they'd stopped trying.", pattern: "Precise Synonym in Context", difficulty: "easy", trapFor: [null, 2, null, 2], },
  { q: "The historian's account is notably ______: she presents the evidence for each competing theory without favoring any of them.\n\nWhich choice completes the text with the most logical and precise word or phrase?", choices: ["evenhanded", "exhaustive", "partisan", "tentative"], answer: 0, explain: "Presenting every theory without favoring one is being evenhanded. 'Exhaustive' is about how complete the account is, not how fair it is.", pattern: "Precise Synonym in Context", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "Early reviews of the film were ______, neither enthusiastic nor harsh, but word of mouth eventually made it a box-office success.\n\nWhich choice completes the text with the most logical and precise word or phrase?", choices: ["lukewarm", "scathing", "effusive", "sporadic"], answer: 0, explain: "'Neither enthusiastic nor harsh' defines lukewarm. 'Scathing' (harsh) and 'effusive' (enthusiastic) are exactly what the text rules out.", pattern: "Precise Synonym in Context", difficulty: "medium", trapFor: [null, 2, 2, null], },
  { q: "The museum's new exhibit will feature fossils collected during a 2019 expedition to Mongolia.\n\nAs used in the text, what does the word “feature” most nearly mean?", choices: ["showcase", "characterize", "resemble", "advertise"], answer: 0, explain: "An exhibit that will feature fossils will present them prominently: showcase. 'Characterize' comes from the noun sense (a feature is a characteristic), which doesn't fit here.", pattern: "Multiple-Meaning Word Trap", difficulty: "easy", underline: "feature", trapFor: [null, 0, null, null], },
  { q: "The senator's proposal did not address the concerns that rural voters had raised about highway funding.\n\nAs used in the text, what does the word “address” most nearly mean?", choices: ["deal with", "deliver a speech to", "write a location on", "greet"], answer: 0, explain: "A proposal that doesn't address concerns doesn't deal with them. The other choices are other meanings of 'address' that don't fit a proposal and a set of concerns.", pattern: "Multiple-Meaning Word Trap", difficulty: "easy", underline: "address", trapFor: [null, 0, 0, 0], },
  { q: "After weeks of testing, the chemist was able to isolate the compound responsible for the plant's bitter taste.\n\nAs used in the text, what does the word “isolate” most nearly mean?", choices: ["separate out", "exclude socially", "confine alone", "locate precisely"], answer: 0, explain: "In chemistry, to isolate a compound is to separate it from everything else it's mixed with. 'Exclude socially' and 'confine alone' are the everyday meanings about people.", pattern: "Multiple-Meaning Word Trap", difficulty: "medium", underline: "isolate", trapFor: [null, 0, 0, 1], },
  { q: "The documentary's arresting opening shot, a lone polar bear on a shrinking ice floe, holds viewers' attention through the film's first minutes.\n\nAs used in the text, what does the word “arresting” most nearly mean?", choices: ["striking", "detaining", "halting", "delaying"], answer: 0, explain: "A shot that 'holds viewers' attention' is striking. 'Detaining' is the police sense of arrest, and 'halting' is the sense of arresting growth; neither fits a shot in a film.", pattern: "Multiple-Meaning Word Trap", difficulty: "hard", underline: "arresting", trapFor: [null, 0, 0, 1], },
  { q: "The findings are ______: the study included only eight participants, too few to support firm conclusions.\n\nWhich choice completes the text with the most logical and precise word or phrase?", choices: ["preliminary", "definitive", "fraudulent", "redundant"], answer: 0, explain: "Too few participants for firm conclusions means the findings are early and provisional: preliminary. 'Fraudulent' goes far beyond anything the text says about the study.", pattern: "Precise Synonym in Context", difficulty: "medium", trapFor: [null, null, 2, null], },
  { q: "The negotiator's tone was ______, carefully avoiding any word that might offend either side.\n\nWhich choice completes the text with the most logical and precise word or phrase?", choices: ["diplomatic", "blunt", "servile", "ambiguous"], answer: 0, explain: "Carefully avoiding offense to either side is being diplomatic. 'Servile' (overly eager to please) is too strong, and 'ambiguous' is about unclear meaning, not tact.", pattern: "Precise Synonym in Context", difficulty: "easy", trapFor: [null, null, 2, 0], },
  { q: "Rather than dismissing the unusual data as error, the astronomers ______ it, running new observations to see whether the pattern held.\n\nWhich choice completes the text with the most logical and precise word or phrase?", choices: ["scrutinized", "disregarded", "extrapolated", "celebrated"], answer: 0, explain: "Running new observations to check the pattern is examining it closely: scrutinized. 'Extrapolated' sounds technical but means extending a trend beyond the data, which isn't what they did.", pattern: "Precise Synonym in Context", difficulty: "hard", trapFor: [null, null, 1, 2], },
  { q: "Though the two poets are often grouped together, their styles are quite ______: one writes in spare, short lines, the other in long, ornate sentences.\n\nWhich choice completes the text with the most logical and precise word or phrase?", choices: ["distinct", "similar", "obscure", "consistent"], answer: 0, explain: "'Though... often grouped together' sets up a contrast, and the details show two very different styles: distinct.", pattern: "Precise Synonym in Context", difficulty: "easy", trapFor: [null, null, 1, null], },
  { q: "The mayor's proposal was ______ by the council: every member voted in favor, and several asked to be listed as cosponsors.\n\nWhich choice completes the text with the most logical and precise word or phrase?", choices: ["embraced", "tolerated", "considered", "rejected"], answer: 0, explain: "A unanimous vote plus requests to cosponsor is enthusiastic support: embraced. 'Tolerated' and 'considered' are far too weak for that response.", pattern: "Precise Synonym in Context", difficulty: "medium", trapFor: [null, 2, 2, null], },
  { q: "Some economists argue that the proposed tax is ______: it would raise little revenue while imposing significant costs on the businesses required to collect it.\n\nWhich choice completes the text with the most logical and precise word or phrase?", choices: ["counterproductive", "lucrative", "innovative", "controversial"], answer: 0, explain: "Costing more than it brings in means the tax works against its own purpose: counterproductive. The colon's explanation supports that specific judgment, not just that people disagree about it.", pattern: "Precise Synonym in Context", difficulty: "hard", trapFor: [null, null, null, 2], },
  { q: "The researchers' conclusions rest on a single, unusually large dataset.\n\nAs used in the text, what does the word “rest” most nearly mean?", choices: ["depend", "relax", "remain", "stop"], answer: 0, explain: "Conclusions that rest on a dataset depend on it. 'Relax' and 'stop' are other meanings of 'rest,' and 'remain' (as in 'rest assured') doesn't fit either.", pattern: "Multiple-Meaning Word Trap", difficulty: "medium", underline: "rest", trapFor: [null, 0, 0, 0], },
  { q: "The biography does not simply praise its subject; it ______ her decisions, weighing their costs as carefully as their achievements.\n\nWhich choice completes the text with the most logical and precise word or phrase?", choices: ["evaluates", "glorifies", "summarizes", "condemns"], answer: 0, explain: "Weighing costs as carefully as achievements is balanced judgment: evaluates. 'Condemns' is too one-sided, and 'summarizes' leaves out the weighing.", pattern: "Precise Synonym in Context", difficulty: "hard", trapFor: [null, null, 0, 2], },
],
  "rw-text-structure": [
  { q: "City officials have praised the new bike-share program for reducing downtown traffic within its first year. Ridership numbers tell a more complicated story, though — outside downtown, fewer than one in twenty bikes gets used on a typical day. Which choice best describes the function of the underlined sentence?", choices: ["It restates the main claim.", "It introduces a qualification that complicates the initial claim.", "It concludes the passage.", "It provides unrelated background information."], answer: 1, explain: "A counterexample right after a claim typically functions to complicate or qualify that claim.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "easy", underline: "Ridership numbers tell a more complicated story, though — outside downtown, fewer than one in twenty bikes gets used on a typical day.", trapFor: [null, null, null, null], },
  { q: "The subject of this profile spent much of her career as a court composer, writing dozens of pieces performed only for the nobility who employed her.\n\nShe is often remembered today as a reclusive figure who avoided public life — a portrayal her surviving letters, filled with references to a wide circle of friends and rivals, directly contradict.\n\nWhich choice best states the function of the first paragraph relative to the passage as a whole?", choices: ["To conclude the argument.", "To establish context before challenging a misconception.", "To provide irrelevant biographical trivia.", "To directly state the thesis."], answer: 1, explain: "Its role is to set up context that the rest of the passage will use to challenge a myth.", pattern: "Function of an Entire Paragraph", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Researchers recruited 240 participants and assigned each one, at random, to either a control group or a group that received eight weeks of the new therapy, with neither participants nor evaluators told which group was which.\n\nAt the end of the eight weeks, the therapy group showed a 34% reduction in reported symptoms, compared to a 6% reduction in the control group.\n\nWhich choice best states the function of the first paragraph relative to the passage as a whole?", choices: ["To explain why the researchers decided to study this therapy in the first place.", "To establish the process by which the following results were obtained.", "To summarize a competing study whose results differ from those that follow.", "To present the study's main results before the second paragraph explains them."], answer: 1, explain: "Methodology sections function to ground the results that follow, showing how they were produced.", pattern: "Function of an Entire Paragraph", difficulty: "medium", trapFor: [null, null, null, 0], },
  { q: "Extending free public transit to the entire metro area would cost the city an estimated $40 million a year in lost fare revenue.\n\nEven so, similar programs in other cities have shown that free transit reliably increases ridership enough to reduce road congestion and the city's associated maintenance costs.\n\nWhich choice best states the function of the first paragraph relative to the passage as a whole?", choices: ["To undermine the author's own argument.", "To acknowledge and address a likely objection to the proposal.", "To conclude the passage.", "To introduce an unrelated topic."], answer: 1, explain: "Presenting a potential drawback (cost) within a persuasive passage typically functions to preemptively address objections.", pattern: "Function of an Entire Paragraph", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A century-old dam that once supplied nearly all of the region's electricity has been slated for removal, following years of debate over its effect on the river's salmon population. The dam's removal, in the end, comes down to a single question: whether a fish population can outweigh a source of power the region has relied on for generations. Which choice best describes the function of the underlined sentence?", choices: ["To state the central trade-off underlying the decision described in the first sentence.", "To introduce new evidence about the salmon population.", "To contradict the decision described in the first sentence.", "To propose a solution to the debate over the dam."], answer: 0, explain: "The first sentence reports the decision and the debate; the underlined sentence names what the debate comes down to, fish against a long-relied-on power source. It doesn't add evidence, oppose the decision, or propose anything.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "easy", underline: "The dam's removal, in the end, comes down to a single question: whether a fish population can outweigh a source of power the region has relied on for generations.", trapFor: [null, 0, 1, null], },
  { q: "When rents near the old textile district doubled in eighteen months, one shop owner who had run the same bakery for over twenty years was forced to close for good.\n\nHer story is not unique: across the city, small businesses in rapidly gentrifying neighborhoods have closed at nearly triple the rate of those in more stable areas.\n\nWhich choice best states the function of the first paragraph relative to the passage as a whole?", choices: ["To provide a relatable, concrete entry point into a broader statistical discussion.", "To present a statistic that the second paragraph illustrates with an example.", "To argue that the bakery closed because of poor management rather than rising rents.", "To introduce the passage's main claim, which the second paragraph then challenges."], answer: 0, explain: "Anecdotes at the start of analytical passages typically function to make abstract or statistical content more relatable before broadening scope.", pattern: "Function of an Entire Paragraph", difficulty: "hard", trapFor: [null, null, null, 0], },
  { q: "For decades, marine biologists believed a particular deep-sea fish survives crushing pressure primarily because of an unusually flexible skeleton. Recent tissue samples suggest a different explanation is more complete: a specialized protein throughout the fish's cells that keeps its own cell membranes from collapsing under pressure. Which choice best describes the function of the underlined sentence?", choices: ["To present the explanation that the author ultimately endorses.", "To set up a contrast that highlights the author's preferred explanation.", "To describe the tissue samples that support the newer explanation.", "To show that the older explanation has been proven entirely false."], answer: 1, explain: "Presenting a rival view just before the author's own explanation typically functions to create a contrast that strengthens the preferred view.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "medium", underline: "For decades, marine biologists believed a particular deep-sea fish survives crushing pressure primarily because of an unusually flexible skeleton.", trapFor: [null, null, 0, 2], },
  { q: "Long before the neighborhood's rowhouses were subdivided into apartments, families here rented single-family homes for generations, often passing leases down within the same family.\n\nCensus records show the neighborhood's population nearly tripled between 1900 and 1920, driven mostly by workers arriving for jobs at the nearby rail yard.\n\nMany of those same rail-yard families would go on to found the mutual aid societies that still operate in the neighborhood today.\n\nWhich choice best states the function of the second paragraph relative to the passage as a whole?", choices: ["To disrupt the passage's argument.", "To ground the narrative in verifiable, quantitative context.", "To introduce a new and unrelated topic.", "To conclude the passage's argument."], answer: 1, explain: "Statistical paragraphs embedded within narrative typically function to substantiate the narrative with concrete data.", pattern: "Function of an Entire Paragraph", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "An earlier study concluded that a widely prescribed painkiller carries no increased cardiovascular risk, based on data drawn primarily from short-term hospital patients.\n\nA more recent analysis, tracking the same drug's effects over five years in outpatient settings, found a small but statistically significant increase in risk that the shorter study window would have been too brief to detect.\n\nWhich choice best states the function of the second paragraph relative to the passage as a whole?", choices: ["To support the earlier study's conclusion with additional data.", "To challenge a specific, previously cited claim with counter-evidence.", "To explain why the earlier study relied on short-term hospital patients.", "To show that the painkiller is too dangerous for any patient to use."], answer: 1, explain: "A paragraph structured to directly respond to a prior claim typically functions as a refutation using counter-evidence.", pattern: "Function of an Entire Paragraph", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Why did a species of freshwater fish that had thrived in a single lake for thousands of years suddenly vanish within a single decade? The likely answer, researchers now believe, traces back to a single invasive crayfish species introduced to the lake by anglers in the 1990s. Which choice best describes the function of the underlined sentence?", choices: ["To conclude the passage's findings.", "To frame the inquiry that structures the rest of the passage.", "To dismiss the passage's own topic as unimportant.", "To directly state the final conclusion."], answer: 1, explain: "A framing question at the start of a passage functions to establish the inquiry the passage will go on to explore and answer.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "easy", underline: "Why did a species of freshwater fish that had thrived in a single lake for thousands of years suddenly vanish within a single decade?", trapFor: [null, null, null, null], },
  { q: "At first glance, national test-score averages appear to support critics who argue that a widely adopted reading curriculum has failed students, showing no measurable improvement in the five years since its adoption.\n\nThose averages, however, obscure sharp regional differences: schools that implemented the curriculum with the recommended teacher training saw scores rise substantially, while schools that skipped the training saw scores fall.\n\nWhich choice best states the function of the first paragraph relative to the passage as a whole?", choices: ["To present the author's own view, which the second paragraph then supports.", "To present an opposing view honestly before the author complicates or undermines it.", "To explain why so many schools adopted the reading curriculum in the first place.", "To show that the curriculum raised test scores in every region where it was used."], answer: 1, explain: "Presenting opposing evidence before undermining it is a common structural move to strengthen the author's own argument through contrast.", pattern: "Function of an Entire Paragraph", difficulty: "hard", trapFor: [0, null, null, null], },
  { q: "In the fishing village where the subject was born, it was standard for boys as young as twelve to leave school permanently and join their fathers on multi-week voyages.\n\nSo when the subject instead begged his father to let him stay in school through his teenage years, risking the family's disapproval, it was a request that broke sharply with how the village expected a son to spend those years.\n\nWhich choice best states the function of the first paragraph relative to the passage as a whole?", choices: ["To conclude the biography.", "To provide context that helps explain the subject's later choices.", "To criticize the subject directly.", "To introduce an unrelated historical figure."], answer: 1, explain: "Contextual paragraphs in biographies typically function to help readers understand constraints or norms shaping the subject's choices.", pattern: "Function of an Entire Paragraph", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "A widely cited study found that students who took short breaks every 25 minutes retained significantly more material than students who studied in one uninterrupted block.\n\nThe study's authors note one limitation worth keeping in mind: all participants were undergraduates studying a single subject, so it remains unclear whether the same break pattern would hold for younger students or more demanding material.\n\nWhich choice best states the function of the second paragraph relative to the passage as a whole?", choices: ["To show that the study's findings are invalid and should be disregarded.", "To transparently acknowledge a constraint on how the findings should be interpreted.", "To describe a follow-up study that tested younger students on harder material.", "To restate the study's main finding about short breaks and memory."], answer: 1, explain: "Limitation paragraphs typically function to responsibly frame how confidently a study's findings should be interpreted, without fully discrediting them.", pattern: "Function of an Entire Paragraph", difficulty: "easy", trapFor: [null, null, null, 1], },
  { q: "A regional hospital system has struggled for years with emergency room wait times that regularly stretch past four hours during peak season. Rather than continuing to add beds, administrators are now piloting a program that routes non-emergency patients to nearby urgent care clinics before they ever reach the ER waiting room. Which choice best describes the function of the underlined sentence?", choices: ["To explain why adding more beds has failed to reduce wait times.", "To shift the passage's focus from diagnosis to a constructive response.", "To describe the severity of the wait-time problem in more detail.", "To argue that urgent care clinics should replace emergency rooms."], answer: 1, explain: "This kind of structural shift functions to move the passage from problem description into constructive proposal.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "easy", underline: "Rather than continuing to add beds, administrators are now piloting a program that routes non-emergency patients to nearby urgent care clinics before they ever reach the ER waiting room.", trapFor: [null, null, 0, 2], },
  { q: "A rival astronomer's model, which explains an unusual pattern in a distant star system's orbits by proposing an as-yet-undetected planet, is built on the same orbital data other astronomers in the field have used and accepted for years.\n\nThat same data, however, fits at least as well with a simpler explanation the rival model doesn't consider: two known planets whose orbits happen to align every few decades, temporarily producing the same pattern.\n\nWhich choice best states the function of the first paragraph relative to the passage as a whole?", choices: ["To present the author's own explanation, which the second paragraph then defends.", "To fairly represent an opposing position before the author's critique, lending the critique credibility.", "To argue that the orbital data other astronomers have relied on for years is unreliable.", "To describe a discovery that the second paragraph confirms with additional evidence."], answer: 1, explain: "Fairly representing an opposing view before critiquing it is a common strategy to make the eventual critique more persuasive and credible.", pattern: "Function of an Entire Paragraph", difficulty: "hard", trapFor: [0, null, null, null], },
  { q: "Many people assume that sharks must swim constantly to breathe. This is true of some species, such as the great white. The nurse shark, however, can rest motionless on the seafloor, pumping water over its gills with muscles in its mouth.\n\nWhich choice best describes the function of the underlined sentence in the text as a whole?", choices: ["It acknowledges that a common assumption holds in certain cases.", "It presents evidence that the common assumption is entirely correct.", "It explains how the nurse shark breathes while resting.", "It introduces a species that contradicts the common assumption."], answer: 0, explain: "The sentence concedes the assumption is true for some sharks before the text turns to an exception. It doesn't show the assumption is 'entirely correct,' since the next sentence limits it.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "medium", underline: "This is true of some species, such as the great white.", trapFor: [null, 2, 0, 0], },
  { q: "In 1928, Alexander Fleming noticed that mold growing on one of his bacterial cultures had killed the bacteria around it. Fleming's observation is often described as a lucky accident. But it was Fleming's years of experience studying bacteria that allowed him to recognize the importance of what he saw.\n\nWhich choice best describes the function of the underlined sentence in the text as a whole?", choices: ["It presents a common view that the text goes on to qualify.", "It states the main claim that the text argues for.", "It provides evidence that Fleming's discovery was carefully planned.", "It explains why Fleming's experience was important."], answer: 0, explain: "The sentence reports a popular view, and 'But' in the next sentence adds a qualification: luck alone doesn't explain it. The text's own claim comes after.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "medium", underline: "Fleming's observation is often described as a lucky accident.", trapFor: [null, null, null, 0], },
  { q: "For years, archaeologists believed that the ancient city of Tel Arvan was abandoned after a single catastrophic flood. Recent analysis of sediment layers, however, shows at least four separate floods over two centuries. The researchers now suggest that residents left gradually, a few families at a time, as flooding became more frequent.\n\nWhich choice best describes the overall structure of the text?", choices: ["It presents an earlier explanation, describes new evidence that challenges it, and then offers a revised explanation.", "It describes new evidence and then explains why that evidence supports the earlier explanation.", "It presents an earlier explanation and then describes evidence that supports it.", "It presents new evidence proving that the city was never flooded."], answer: 0, explain: "The text moves from the old view (one flood), to new evidence (four floods), to a new suggestion (gradual departure). The last choice overstates: the evidence shows more floods, not none.", pattern: "Describing the Structure of an Entire Passage", difficulty: "medium", trapFor: [null, 0, 1, 2], },
  { q: "Economist Rosa Delgado studies why some small towns recover after a major employer closes while others decline. Conventional wisdom holds that the key is how quickly a town attracts a new large employer. Delgado's data point elsewhere: towns with many small, locally owned businesses recovered faster, whether or not a new large employer arrived.\n\nWhich choice best describes the overall structure of the text?", choices: ["It introduces a researcher's question, describes a common answer to it, and then presents findings that suggest a different answer.", "It describes a common answer to a question and then presents findings that confirm it.", "It introduces a researcher's question and explains why it cannot yet be answered.", "It presents findings proving that large employers harm small towns."], answer: 0, explain: "Question, then conventional answer, then data that 'point elsewhere.' The last choice overstates: the data are about what helps recovery, not about large employers causing harm.", pattern: "Describing the Structure of an Entire Passage", difficulty: "hard", trapFor: [null, 0, 1, 2], },
  { q: "The Japanese art of kintsugi repairs broken pottery by filling the cracks with lacquer mixed with powdered gold. Rather than hiding the damage, the technique highlights it. The practice reflects the idea that an object's history, including its breaks, is part of its beauty.\n\nWhich choice best describes the function of the underlined sentence in the text as a whole?", choices: ["It identifies a key feature of kintsugi that the final sentence then interprets.", "It describes the materials used in kintsugi.", "It presents a criticism of kintsugi that the final sentence rejects.", "It introduces a second art form that contrasts with kintsugi."], answer: 0, explain: "The sentence names what's distinctive about kintsugi (it highlights damage), and the last sentence explains the idea behind that choice. The materials are described in the first sentence, not this one.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "medium", underline: "Rather than hiding the damage, the technique highlights it.", trapFor: [null, 0, 1, null], },
  { q: "A new battery design stores nearly twice as much energy as current lithium-ion batteries of the same size. Its developers say it could double the range of electric cars. So far, though, the battery has been produced only in small laboratory batches, and it loses capacity after a few hundred charges.\n\nWhich choice best describes the function of the underlined sentence in the text as a whole?", choices: ["It notes limitations that complicate the developers' prediction.", "It provides evidence that the developers' prediction is correct.", "It shows that the battery design has been proven a failure.", "It describes how the battery stores extra energy."], answer: 0, explain: "'Though' signals a complication: limited production and short life are reasons to be cautious about the prediction. Calling it proof of failure overstates a qualification.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "hard", underline: "So far, though, the battery has been produced only in small laboratory batches, and it loses capacity after a few hundred charges.", trapFor: [null, null, 1, 0], },
  { q: "Most birds that migrate long distances travel at night. Flying after dark lets them avoid daytime predators and the heat of the sun, and it leaves daylight hours free for feeding.\n\nSome species, however, reverse this pattern. Hawks and other large soaring birds migrate by day, riding columns of warm, rising air that form only when the sun heats the ground.\n\nWhich choice best describes the function of the second paragraph in the text as a whole?", choices: ["It presents an exception to the pattern described in the first paragraph and explains why it occurs.", "It provides additional reasons why most migrating birds choose to travel at night rather than by day.", "It explains why traveling at night would be dangerous for hawks and other large birds.", "It introduces the main claim of the text, which the first paragraph then supports with evidence."], answer: 0, explain: "'However' and 'reverse this pattern' mark the second paragraph as an exception, and it gives the reason: soaring birds need daytime rising air.", pattern: "Function of an Entire Paragraph", difficulty: "medium", trapFor: [null, 1, null, 0], },
  { q: "Photographs of Earth taken from lunar orbit in 1968, including the famous \"Earthrise\" image, showed the planet as a small, isolated sphere. Some historians argue that these images helped inspire the modern environmental movement. The first Earth Day was held less than two years later, in 1970.\n\nWhich choice best describes the function of the underlined sentence in the text as a whole?", choices: ["It offers a detail consistent with the historians' argument.", "It proves that the photographs caused the first Earth Day.", "It challenges the historians' argument.", "It describes what the \"Earthrise\" photograph shows."], answer: 0, explain: "The timing fits the historians' idea but doesn't establish cause. Following soon after is consistent with inspiration, not proof of it.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "hard", underline: "The first Earth Day was held less than two years later, in 1970.", trapFor: [null, 2, 1, 0], },
  { q: "Beginning in 2012, the city of Harlow installed parking meters that adjust prices based on demand, charging more on busy blocks and less on quiet ones.\n\nCritics argued that the meters were a disguised fee increase. Data from the city tell a different story: average parking prices fell slightly, and drivers spent less time circling in search of open spaces.\n\nWhich choice best describes the function of the first paragraph in the text as a whole?", choices: ["It introduces the program that the second paragraph evaluates.", "It presents the main argument of the text.", "It summarizes the critics' objections to the program.", "It provides data showing that the program succeeded."], answer: 0, explain: "The first paragraph only describes the program; the evaluation (critics versus data) comes in the second.", pattern: "Function of an Entire Paragraph", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "Why do some languages have dozens of words for colors while others have only a few? Linguists once assumed the answer lay in differences in how people perceive color. Some researchers now propose a more practical explanation: communities tend to develop more color words when distinguishing precise shades becomes useful, as when they begin producing dyed goods and paints.\n\nWhich choice best describes the function of the underlined sentence in the text as a whole?", choices: ["It poses the question that the rest of the text addresses.", "It states the explanation the text ultimately favors.", "It introduces an assumption that the text later rejects.", "It summarizes research on how people perceive color."], answer: 0, explain: "The opening question frames what the rest of the text tries to answer, first with an older assumption and then with a newer proposal.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "easy", underline: "Why do some languages have dozens of words for colors while others have only a few?", trapFor: [null, null, null, 0], },
  { q: "The tomato was introduced to Europe from the Americas in the 1500s.\n\nFor decades, however, many Europeans grew tomatoes only as ornamental plants, wary of eating a fruit related to poisonous nightshades.\n\nWhich choice best describes the function of the second paragraph in the text as a whole?", choices: ["It describes how the tomato was received after the event mentioned in the first paragraph.", "It explains why tomatoes were brought to Europe.", "It provides an example of the claim in the first paragraph.", "It argues that tomatoes are poisonous."], answer: 0, explain: "'However' signals that arrival didn't mean acceptance; the second paragraph describes the cautious reception.", pattern: "Function of an Entire Paragraph", difficulty: "easy", trapFor: [null, 0, 1, null], },
  { q: "The Svalbard Global Seed Vault stores more than a million seed samples from around the world. It is built deep inside a mountain on a remote Norwegian island, where permafrost keeps the seeds cold even if the power fails. The vault serves as a backup: if a disaster destroys a region's seed bank, samples can be sent back to restore lost crops, as happened in 2015, when researchers withdrew seeds to replace a collection damaged by war in Syria.\n\nWhich choice best describes the overall structure of the text?", choices: ["It describes what the vault contains, explains a feature of its location, and then describes its purpose with an example.", "It explains the vault's purpose and then argues that more vaults should be built.", "It describes a war in Syria and then explains how the war led to the vault's construction.", "It describes the vault's location and then lists the types of seeds it stores."], answer: 0, explain: "Contents, then location, then purpose with the 2015 example. No choice but the first gets all three moves in order without adding claims the text doesn't make.", pattern: "Describing the Structure of an Entire Passage", difficulty: "hard", trapFor: [null, 2, 0, 1], },
  { q: "Some animals use tools. Sea otters, for instance, float on their backs and crack open shellfish by striking them against stones balanced on their chests. Such behavior was once thought to be unique to humans and other primates.\n\nWhich choice best describes the function of the underlined sentence in the text as a whole?", choices: ["It provides an example supporting the claim in the first sentence.", "It presents a claim that the final sentence supports.", "It challenges the claim in the first sentence.", "It explains why tool use was once thought unique to primates."], answer: 0, explain: "'For instance' marks the otters as an example of animals using tools.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "easy", underline: "Sea otters, for instance, float on their backs and crack open shellfish by striking them against stones balanced on their chests.", trapFor: [null, null, 1, 0], },
  { q: "Supporters of a four-day school week argue that it saves districts money on transportation and utilities, and some districts have reported modest savings.\n\nThose savings are real but small, often less than 2 percent of a district's budget. Meanwhile, several studies have found that students in four-day districts score slightly lower on standardized tests than similar students in five-day districts.\n\nWhich choice best describes the function of the first paragraph in the text as a whole?", choices: ["It presents an argument for a policy that the second paragraph weighs against a drawback.", "It presents the text's main argument.", "It provides evidence that four-day school weeks lower test scores.", "It explains why districts have rejected four-day weeks."], answer: 0, explain: "The first paragraph gives the supporters' case; the second shrinks the benefit and adds a cost. The first paragraph isn't the text's own position.", pattern: "Function of an Entire Paragraph", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "The painter Georgia O'Keeffe is best known for her large, close-up paintings of flowers. Critics in the 1920s often interpreted these works in ways O'Keeffe herself rejected. She insisted that she painted flowers large simply so that busy viewers would take the time to see them.\n\nWhich choice best describes the function of the underlined sentence in the text as a whole?", choices: ["It introduces a disagreement that the final sentence elaborates from O'Keeffe's perspective.", "It presents the critics' interpretation as the correct one.", "It describes the subject matter of O'Keeffe's best-known paintings.", "It explains why O'Keeffe painted flowers large."], answer: 0, explain: "The sentence sets up a conflict between critics and artist, and the final sentence gives O'Keeffe's side. It doesn't endorse the critics.", pattern: "Function of a Sentence Within a Paragraph", difficulty: "medium", underline: "Critics in the 1920s often interpreted these works in ways O'Keeffe herself rejected.", trapFor: [null, 2, 0, 0], },
],
  "rw-cross-text": [
  { q: "Passage 1: Social media has given ordinary people direct tools to organize protests, coordinate mutual aid, and participate in public debate in ways that were unavailable a generation ago. \n\nPassage 2: Users increasingly report that brief, text-based exchanges online have replaced the sustained, in-person relationships that once anchored their sense of community.\n\nOn which point would both authors most likely agree?", choices: ["Social media has no measurable effects.", "Social media has significantly changed how people interact.", "Civic engagement is declining everywhere.", "Isolation is unrelated to technology."], answer: 1, explain: "Even with opposing conclusions, both authors would likely agree on the premise that social media has changed interaction patterns.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Passage 1: Online communities built around shared interests give people meaningful, sustained connection with others who understand them, and for many users, these communities have effectively replaced the real-world social circles they struggled to find locally. \n\nPassage 2: Even the most active online exchanges tend to be brief and text-based, lacking the shared physical presence that makes in-person relationships feel substantial over time.\n\nHow would the author of Passage 2 most likely respond to Passage 1's claim that online communities replace real-world ones effectively?", choices: ["By agreeing that online communities can fully replace real-world relationships", "By arguing that online interaction lacks the depth of in-person connection", "By arguing that online communities are more harmful than other kinds of social media", "By claiming that most people don't actually use online communities at all"], answer: 1, explain: "Passage 2's isolation-focused stance would most likely counter with a depth-of-connection argument.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "easy", trapFor: [0, null, 1, 2], },
  { q: "Passage 1: A once-endangered species' population has rebounded sharply in the two decades since strict hunting bans were enacted across its range. \n\nPassage 2: The same species' recovery closely tracks a large-scale habitat restoration effort completed over roughly the same period, well after hunting had already been banned for years with little population change.\n\nOn which point would both authors most likely agree?", choices: ["Hunting bans are unnecessary.", "The species' population has, in fact, recovered.", "Habitat restoration has no measurable effect.", "The recovery is temporary and will soon reverse."], answer: 1, explain: "Despite disagreeing on cause, both passages share the underlying premise that recovery occurred.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "medium", trapFor: [null, null, 0, null], },
  { q: "Passage 1: A once-endangered species' population has rebounded sharply in the two decades since strict hunting bans were enacted across its range. \n\nPassage 2: The same species' recovery closely tracks a large-scale habitat restoration effort completed over roughly the same period, well after hunting had already been banned for years with little population change.\n\nHow would the author of Passage 1, who emphasizes hunting bans, most likely respond to Passage 2's claim that habitat restoration alone explains the recovery?", choices: ["By fully agreeing that hunting bans played no role.", "By arguing that habitat restoration alone is insufficient without the bans.", "By denying that any recovery occurred.", "By ignoring the claim entirely."], answer: 1, explain: "An author emphasizing one cause would most likely argue the other explanation is incomplete without their preferred factor.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "easy", trapFor: [0, null, null, null], },
  { q: "Passage 1: Records from the period show the reformer benefited personally, and substantially, from nearly every policy she championed, a pattern too consistent to dismiss as coincidence. \n\nPassage 2: The reformer repeatedly pursued policies that cost her politically and personally, including one that alienated her own family's business interests for years.\n\nOn which point would both authors most likely agree?", choices: ["The reformer's policies affected her own interests.", "The reformer was motivated mainly by self-interest.", "The reformer's policies harmed her family's business.", "Politics involves difficult choices."], answer: 0, explain: "Passage 1 says she benefited from her policies; Passage 2 says they cost her. Either way, both agree her policies affected her own interests. The other specific choices take one side.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "Passage 1: Records from the period show the reformer benefited personally, and substantially, from nearly every policy she championed, a pattern too consistent to dismiss as coincidence. \n\nPassage 2: The reformer repeatedly pursued policies that cost her politically and personally, including one that alienated her own family's business interests for years.\n\nHow would the author of Passage 2, who argues the reforms were altruistic, most likely respond to Passage 1's emphasis on self-interest?", choices: ["By agreeing that the reformer's policies were driven mainly by self-interest", "By pointing to evidence of personal sacrifice that self-interest alone wouldn't explain", "By arguing that the records cited in Passage 1 were forged by her political rivals", "By denying that the reformer ever benefited from any of her policies"], answer: 1, explain: "An author arguing for altruistic motive would likely counter a self-interest claim with evidence of sacrifice inconsistent with pure self-interest.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "easy", trapFor: [0, null, 1, 2], },
  { q: "Passage 1: The structure's main chamber aligns with religious festival dates recorded in inscriptions found at the site, suggesting it served primarily ceremonial purposes. \n\nPassage 2: The same chamber aligns precisely with the solstice sunrise, a level of astronomical precision that would have required careful, sustained observation to achieve.\n\nOn which point would both authors most likely agree?", choices: ["The chamber's alignment with particular dates was not accidental.", "The chamber served mainly ceremonial purposes.", "The builders were skilled astronomers.", "Ancient structures are impressive."], answer: 0, explain: "Passage 1 reads the alignment as matching festival dates by design; Passage 2 says it required careful observation. Both treat the alignment as intentional, though they disagree about its purpose.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "hard", trapFor: [null, 0, 0, 1], },
  { q: "Passage 1: The structure's main chamber aligns with religious festival dates recorded in inscriptions found at the site, suggesting it served primarily ceremonial purposes. \n\nPassage 2: The same chamber aligns precisely with the solstice sunrise, a level of astronomical precision that would have required careful, sustained observation to achieve.\n\nHow would the author of Passage 1, who argues for a religious purpose, most likely respond to Passage 2's astronomical alignment evidence?", choices: ["By dismissing the alignment evidence as irrelevant to purpose.", "By arguing the alignment could have served religious ceremonies tied to celestial events.", "By fully abandoning the religious-purpose argument.", "By claiming no alignment evidence exists."], answer: 1, explain: "A religious-purpose argument can accommodate astronomical alignment evidence by tying celestial events to religious ceremony, rather than rejecting the evidence outright.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "easy", trapFor: [2, null, 0, null], },
  { q: "Passage 1: National poverty statistics show a clear decline in the years since the policy took effect, evidence the policy's supporters point to directly. \n\nPassage 2: Region-by-region data tell a different story: poverty fell in wealthier regions but rose just as sharply in poorer ones, suggesting the policy shifted hardship rather than reducing it overall.\n\nOn which point would both authors most likely agree?", choices: ["The policy had a measurable effect on poverty distribution.", "Poverty did not exist before the policy.", "The policy should be repealed immediately.", "No data exists on the policy's effects."], answer: 0, explain: "Both authors agree the policy had a measurable effect; they disagree on whether that effect was reduction or redistribution.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Passage 1: National poverty statistics show a clear decline in the years since the policy took effect, evidence the policy's supporters point to directly. \n\nPassage 2: Region-by-region data tell a different story: poverty fell in wealthier regions but rose just as sharply in poorer ones, suggesting the policy shifted hardship rather than reducing it overall.\n\nHow would the author of Passage 2, who argues poverty was merely redistributed, most likely respond to Passage 1's national poverty statistics showing an overall decline?", choices: ["By fully accepting the statistics as proof of poverty reduction.", "By arguing that national averages could mask regional shifts, and pointing to specific regional data.", "By denying any statistics exist.", "By agreeing the policy should be expanded further."], answer: 1, explain: "A redistribution argument would specifically challenge the interpretation of national averages by pointing to regional-level data.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "hard", trapFor: [0, null, null, null], },
  { q: "Passage 1: Fewer than two hundred fluent speakers of the language remain today, down from several thousand just two generations ago. \n\nPassage 2: A decade-long digital archiving project has now recorded and preserved the language's grammar, vocabulary, and oral storytelling traditions in detail sufficient for future generations to study and revive it.\n\nOn which point would both authors most likely agree?", choices: ["The language currently has a shrinking number of active speakers.", "Digital archiving is unnecessary.", "The language is not at risk in any sense.", "Spoken use and preservation are identical concepts."], answer: 0, explain: "Both authors would agree on the underlying fact of declining speakers, while disagreeing on whether preservation addresses the same concern as active use.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "Passage 1: Fewer than two hundred fluent speakers of the language remain today, down from several thousand just two generations ago. \n\nPassage 2: A decade-long digital archiving project has now recorded and preserved the language's grammar, vocabulary, and oral storytelling traditions in detail sufficient for future generations to study and revive it.\n\nHow would the author of Passage 1, focused on declining speakers, most likely respond to Passage 2's claim that digital archiving ensures preservation?", choices: ["By agreeing that archiving alone is equivalent to a living, spoken language.", "By arguing that archiving preserves records of the language but not its use as a living, spoken language.", "By denying that any archiving efforts exist.", "By stating the language is not actually declining."], answer: 1, explain: "An author focused on speaker decline would likely distinguish between preserved records and an actively living language.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "medium", trapFor: [0, null, null, null], },
  { q: "Passage 1: The indicator has consistently shown higher growth than more detailed regional data can account for, a gap that has widened in each of the last five years. \n\nPassage 2: Despite that gap, the indicator has correctly signaled the direction of every major economic turn for the past three decades, a track record few alternative measures can match.\n\nOn which point would both authors most likely agree?", choices: ["The indicator's growth figures do not always match more detailed regional data.", "The indicator is too unreliable to be useful.", "The indicator is the best available measure of economic turns.", "Measuring the economy is difficult."], answer: 0, explain: "Passage 2 opens with 'Despite that gap,' accepting the mismatch Passage 1 describes. They disagree only about whether it matters.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "hard", trapFor: [null, 0, 0, 1], },
  { q: "Passage 1: The indicator has consistently shown higher growth than more detailed regional data can account for, a gap that has widened in each of the last five years. \n\nPassage 2: Despite that gap, the indicator has correctly signaled the direction of every major economic turn for the past three decades, a track record few alternative measures can match.\n\nHow would the author of Passage 2, who defends the indicator's reliability, most likely respond to Passage 1's claim that it overstates growth?", choices: ["By agreeing that the overstatement makes the indicator unsuitable for tracking economic turns", "By arguing that a consistent overstatement still leaves the indicator useful for tracking economic turns", "By denying that there is any gap between the indicator and the regional data", "By proposing that economists replace the indicator with more detailed regional data"], answer: 1, explain: "A defender of the indicator's reliability would likely argue that a consistent bias still preserves its usefulness for tracking relative change over time.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "medium", trapFor: [0, null, 2, 1], },
  { q: "Passage 1: The painter's later canvases abandon the fine detail and realistic proportion that made her early work celebrated, replaced by loose, hurried brushwork many critics read as a falling-off in skill. \n\nPassage 2: The painter's own letters from that period describe the looser style as a deliberate departure, one she pursued for years despite knowing it would cost her some of her earlier admirers.\n\nOn which point would both authors most likely agree?", choices: ["The painter's later works differ noticeably from their earlier works.", "The painter stopped working entirely.", "Artistic evolution and decline are the same concept.", "No later works by this painter exist."], answer: 0, explain: "Both authors agree the later works are different from the earlier ones; they disagree only on how to interpret that difference.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "Passage 1: Many nutrition researchers have long recommended eating breakfast, citing studies in which breakfast eaters tended to weigh less than people who skipped the meal.\n\nPassage 2: Those studies were observational: they compared people who already chose to eat breakfast with those who didn't. When researchers randomly assigned participants to eat or skip breakfast, the difference in weight largely disappeared.\n\nBased on the texts, both authors would most likely agree with which statement?", choices: ["Some studies have found that people who eat breakfast tend to weigh less than people who skip it.", "Eating breakfast causes people to weigh less than they would if they skipped it.", "Observational studies of diet are too unreliable to be trusted at all.", "What people eat can affect how much they weigh over time."], answer: 0, explain: "Passage 2 doesn't dispute that the observational studies found a weight difference; it disputes what the difference means. So both accept that such studies exist.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "Passage 1: Many nutrition researchers have long recommended eating breakfast, citing studies in which breakfast eaters tended to weigh less than people who skipped the meal.\n\nPassage 2: Those studies were observational: they compared people who already chose to eat breakfast with those who didn't. When researchers randomly assigned participants to eat or skip breakfast, the difference in weight largely disappeared.\n\nBased on the texts, how would the author of Passage 2 most likely respond to the recommendation described in Passage 1?", choices: ["By arguing that the studies cited to support it don't show that breakfast itself leads to lower weight", "By agreeing that eating breakfast is an effective way for most people to lose weight", "By claiming that the studies described in Passage 1 never found any difference in weight", "By recommending that people eat several small meals a day instead of a large breakfast"], answer: 0, explain: "Passage 2 accepts that the difference appeared in observational studies but shows it vanishes when people are randomly assigned, so the studies don't show cause.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "medium", trapFor: [null, 0, 2, 1], },
  { q: "Passage 1: Rooftop solar panels have lowered electricity bills for many homeowners. Because these homes still rely on the grid at night, some utilities argue that solar owners are not paying their fair share of the cost of maintaining power lines.\n\nPassage 2: Rooftop solar reduces strain on the grid during hot afternoons, when demand peaks. That benefit, often ignored in debates over fairness, helps utilities avoid building expensive new power plants.\n\nBased on the texts, both authors would most likely agree with which statement?", choices: ["Rooftop solar panels affect the costs that utilities face.", "Solar owners pay less than their fair share of grid costs.", "Rooftop solar saves utilities money overall.", "Electricity is important to modern life."], answer: 0, explain: "Passage 1 raises the cost of maintaining power lines; Passage 2 describes costs solar helps utilities avoid. Both see solar as affecting utility costs, though they disagree about the direction.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "hard", trapFor: [null, 0, 0, 1], },
  { q: "Passage 1: Rooftop solar panels have lowered electricity bills for many homeowners. Because these homes still rely on the grid at night, some utilities argue that solar owners are not paying their fair share of the cost of maintaining power lines.\n\nPassage 2: Rooftop solar reduces strain on the grid during hot afternoons, when demand peaks. That benefit, often ignored in debates over fairness, helps utilities avoid building expensive new power plants.\n\nBased on the texts, how would the author of Passage 2 most likely respond to the utilities' argument in Passage 1?", choices: ["By claiming that the argument overlooks a way rooftop solar benefits the grid", "By agreeing that solar owners should pay higher fees", "By denying that homes with solar panels use the grid at night", "By arguing that homeowners should disconnect from the grid entirely"], answer: 0, explain: "Passage 2 points to a benefit 'often ignored in debates over fairness,' which is exactly what the utilities' argument leaves out.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "hard", trapFor: [null, 0, 2, 1], },
  { q: "Passage 1: The printing press, introduced in Europe in the mid-1400s, made books far cheaper and more plentiful. Many historians credit it with rapidly spreading literacy.\n\nPassage 2: Literacy rates in much of Europe rose only slowly for two centuries after the printing press appeared. Books were cheaper, but schooling remained rare, and most people had little reason to learn to read.\n\nBased on the texts, both authors would most likely agree with which statement?", choices: ["The printing press made books less expensive.", "The printing press rapidly increased literacy.", "A lack of schooling limited literacy in Europe for centuries.", "Reading is a valuable skill."], answer: 0, explain: "Passage 1 says books became 'far cheaper,' and Passage 2 grants that 'books were cheaper.' They disagree about how quickly literacy followed.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "Passage 1: The printing press, introduced in Europe in the mid-1400s, made books far cheaper and more plentiful. Many historians credit it with rapidly spreading literacy.\n\nPassage 2: Literacy rates in much of Europe rose only slowly for two centuries after the printing press appeared. Books were cheaper, but schooling remained rare, and most people had little reason to learn to read.\n\nBased on the texts, how would the author of Passage 2 most likely respond to the historians described in Passage 1?", choices: ["By arguing that cheaper books alone were not enough to make most people literate", "By agreeing that the printing press quickly made most Europeans literate", "By denying that the printing press made books cheaper", "By arguing that historians should study other inventions instead"], answer: 0, explain: "Passage 2 accepts cheaper books but says schooling and motivation were missing, so the press alone didn't spread literacy quickly.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "easy", trapFor: [null, 0, 2, 1], },
  { q: "Passage 1: In one study, crows that had been trapped by a particular person scolded that person for years afterward, even when the person wore different clothes. The researchers concluded that crows recognize individual human faces.\n\nPassage 2: The crow findings are striking, but the birds may be responding to features such as a person's gait or voice rather than the face itself. Until those cues are ruled out, claims about face recognition go beyond the evidence.\n\nBased on the texts, both authors would most likely agree with which statement?", choices: ["Crows can respond differently to a specific person who once trapped them.", "Crows recognize individual human faces, even when a person changes clothes.", "Crows identify people mainly by features such as their gait or voice.", "Birds can learn from their experiences with people."], answer: 0, explain: "Passage 2 calls the findings 'striking' and doesn't dispute the scolding; it disputes what cue the crows use.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "hard", trapFor: [null, 0, 0, 1], },
  { q: "Passage 1: In one study, crows that had been trapped by a particular person scolded that person for years afterward, even when the person wore different clothes. The researchers concluded that crows recognize individual human faces.\n\nPassage 2: The crow findings are striking, but the birds may be responding to features such as a person's gait or voice rather than the face itself. Until those cues are ruled out, claims about face recognition go beyond the evidence.\n\nBased on the texts, how would the author of Passage 2 most likely respond to the researchers' conclusion in Passage 1?", choices: ["By suggesting that the evidence could be explained by cues other than faces", "By accepting the conclusion as fully established", "By claiming that the crows did not react to the person at all", "By arguing that crows are less intelligent than other birds"], answer: 0, explain: "Passage 2 accepts the behavior but says gait or voice haven't been ruled out, so the face conclusion goes beyond the evidence.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "medium", trapFor: [null, 0, 2, 1], },
  { q: "Passage 1: Planting trees along city streets lowers summer temperatures, since shade and evaporation from leaves cool the air. Cities facing hotter summers should plant as many street trees as possible.\n\nPassage 2: Street trees do cool neighborhoods, but young trees need years of watering and care to survive. In several cities, a large share of newly planted trees died within five years because no money was set aside to maintain them.\n\nBased on the texts, both authors would most likely agree with which statement?", choices: ["Street trees can help lower temperatures in cities.", "Cities should plant as many street trees as possible.", "Most newly planted street trees die within five years.", "Cities face many environmental challenges."], answer: 0, explain: "Passage 2 opens by granting that 'street trees do cool neighborhoods.' It questions the plan, not the cooling.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "easy", trapFor: [null, 0, 0, 1], },
  { q: "Passage 1: Planting trees along city streets lowers summer temperatures, since shade and evaporation from leaves cool the air. Cities facing hotter summers should plant as many street trees as possible.\n\nPassage 2: Street trees do cool neighborhoods, but young trees need years of watering and care to survive. In several cities, a large share of newly planted trees died within five years because no money was set aside to maintain them.\n\nBased on the texts, how would the author of Passage 2 most likely respond to the recommendation in Passage 1?", choices: ["By cautioning that planting trees without funding their care may not produce the expected benefits", "By rejecting the claim that street trees lower temperatures", "By agreeing that cities should plant as many trees as possible, whatever the cost", "By recommending that cities build air-conditioned shelters instead"], answer: 0, explain: "Passage 2's concern is that trees die without maintenance money, so planting 'as many as possible' without that funding may not work.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "medium", trapFor: [null, 2, 0, 1], },
  { q: "Passage 1: Many readers see the novel's ending, in which the heroine leaves her family's farm for the city, as a triumph: she finally escapes a life that has confined her.\n\nPassage 2: The final chapter lingers on the farm's fields and the heroine's memories of them. Read closely, the ending suggests loss as much as escape; the novel doesn't treat her departure as simply a victory.\n\nBased on the texts, both authors would most likely agree with which statement?", choices: ["The novel ends with the heroine leaving her family's farm.", "The ending portrays the heroine's departure as a triumph.", "The heroine regrets leaving the farm.", "Endings are important in novels."], answer: 0, explain: "Both texts describe the same ending (she leaves the farm) and disagree about how to read it. Passage 2 says 'loss as much as escape,' which isn't regret.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "hard", trapFor: [null, 0, 0, 1], },
  { q: "Passage 1: Many readers see the novel's ending, in which the heroine leaves her family's farm for the city, as a triumph: she finally escapes a life that has confined her.\n\nPassage 2: The final chapter lingers on the farm's fields and the heroine's memories of them. Read closely, the ending suggests loss as much as escape; the novel doesn't treat her departure as simply a victory.\n\nBased on the texts, how would the author of Passage 2 most likely respond to the reading of the ending described in Passage 1?", choices: ["By arguing that it overlooks details that complicate reading the departure as simply a victory", "By agreeing that the novel presents the departure purely as a triumph", "By claiming that the heroine never actually leaves the farm", "By arguing that readers should ignore endings when interpreting novels"], answer: 0, explain: "Passage 2 points to the final chapter's attention to the fields and memories, details the triumphant reading doesn't account for.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "hard", trapFor: [null, 0, 2, 1], },
  { q: "Passage 1: Teenagers' internal clocks shift later during adolescence, making it hard for them to fall asleep early. Districts that moved high school start times from 7:30 to 8:30 saw students sleep more and attendance improve.\n\nPassage 2: Later start times can create problems for families: buses must be rescheduled, and after-school jobs and sports end later in the evening. Districts should weigh these costs before changing schedules.\n\nBased on the texts, both authors would most likely agree with which statement?", choices: ["Changing high school start times affects more than just how long students sleep.", "Later start times help students get more sleep.", "The costs of later start times outweigh the benefits.", "Teenagers need sleep."], answer: 0, explain: "Passage 1 reports better attendance as well as more sleep; Passage 2 points to buses, jobs and sports. Both show effects beyond sleep. Passage 2 never addresses whether students sleep more.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "hard", trapFor: [null, 0, 0, 1], },
  { q: "Passage 1: Teenagers' internal clocks shift later during adolescence, making it hard for them to fall asleep early. Districts that moved high school start times from 7:30 to 8:30 saw students sleep more and attendance improve.\n\nPassage 2: Later start times can create problems for families: buses must be rescheduled, and after-school jobs and sports end later in the evening. Districts should weigh these costs before changing schedules.\n\nBased on the texts, how would the author of Passage 1 most likely respond to Passage 2?", choices: ["By acknowledging the scheduling challenges but pointing to the benefits for students' sleep and attendance", "By agreeing that districts should keep their early start times to avoid disrupting families", "By denying that later start times would require districts to reschedule their buses", "By arguing that schools should eliminate after-school jobs and sports to make room for later starts"], answer: 0, explain: "Passage 1's case rests on sleep and attendance gains, so its author would weigh those against Passage 2's costs rather than deny the costs exist.", pattern: "Predicting One Author's Response to the Other's Claim", difficulty: "medium", trapFor: [null, 0, 2, 1], },
  { q: "Passage 1: Sending robotic probes to explore other planets costs far less than sending astronauts and puts no human lives at risk. For most scientific goals, robots are the better choice.\n\nPassage 2: Robots are slow and limited: a rover may spend a week doing what a trained geologist could do in an afternoon. For complex fieldwork, human explorers could accomplish far more.\n\nBased on the texts, both authors would most likely agree with which statement?", choices: ["Robotic probes and human explorers differ in what they can accomplish.", "Robots are the better choice for most scientific goals.", "Human explorers would accomplish more than robots on other planets.", "Space exploration is expensive."], answer: 0, explain: "Passage 1 favors robots for most goals and Passage 2 favors humans for complex fieldwork. Both treat the two as suited to different things.", pattern: "Finding Common Ground Between Disagreeing Authors", difficulty: "hard", trapFor: [null, 0, 0, 1], },
],
  "rw-rhetorical-synthesis": [
  { q: "Notes: (1) Bees pollinate 1/3 of food crops. (2) Bee populations declined 40% since 2006. (3) Colony collapse disorder is a leading cause. Goal: emphasize the economic stakes of bee decline. Which choice best accomplishes this goal?", choices: ["Bees pollinate about a third of food crops, making their 40% population decline since 2006 an economic concern.", "Bee populations have declined 40% since 2006, with colony collapse disorder as a leading cause.", "Scientists identified colony collapse disorder in 2006, the year bee populations began to decline.", "Colony collapse disorder, a leading cause of bee decline, is still not fully understood by researchers."], answer: 0, explain: "Only this choice connects the crop-pollination fact (economic relevance) with the decline statistic, matching the stated goal.", pattern: "Goal-Filtered Selection", difficulty: "hard", trapFor: [null, 2, 1, 1], },
  { q: "Notes: (1) The bridge was built in 1932. (2) It carries 50,000 vehicles daily. (3) It underwent renovation in 2015. Goal: highlight the bridge's importance to current traffic. Which choice best accomplishes this goal?", choices: ["The bridge, built in 1932, now carries 50,000 vehicles daily.", "The bridge, built in 1932, underwent a major renovation in 2015.", "Built in 1932, the bridge is one of the oldest in the region.", "The bridge was renovated in 2015 to handle its growing traffic."], answer: 0, explain: "This combines the vehicle count (current importance) while briefly noting its age, matching the stated goal about current traffic.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 2, 1, 1], },
  { q: "Notes: (1) The novelist published her first book at 19. (2) Her fifth novel won a national award. (3) She has written in three different genres. Goal: emphasize her versatility as a writer. Which choice best accomplishes this goal?", choices: ["The novelist has written award-winning work across three different genres.", "The novelist published her first book at age 19.", "Her fifth novel won a national award.", "She began writing novels at a young age."], answer: 0, explain: "Only this choice ties her range (three genres) to a mark of quality (award-winning), directly serving the versatility goal.", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 0, 0, 0], },
  { q: "Notes: (1) The startup raised $2 million in seed funding. (2) It has 15 employees. (3) Its product is used by over 10,000 customers. Goal: emphasize the company's growth relative to its size. Which choice best accomplishes this goal?", choices: ["Despite having only 15 employees, the company serves over 10,000 customers.", "The startup raised $2 million in seed funding and now has 15 employees.", "With $2 million in seed funding, the startup plans to hire more employees.", "The startup's product is now used by more than 10,000 customers."], answer: 0, explain: "The contrast between small team size and large customer base directly emphasizes growth relative to size, matching the goal.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 0, 1, 0], },
  { q: "Notes: (1) The park spans 200 acres. (2) It was designed by a famous landscape architect. (3) It attracts 2 million visitors annually. Goal: emphasize the park's popularity. Which choice best accomplishes this goal?", choices: ["The 200-acre park attracts 2 million visitors annually.", "The park was designed by a famous landscape architect.", "The park spans 200 acres.", "Landscape architecture is a specialized field."], answer: 0, explain: "The visitor count is the direct measure of popularity; combining it with size supports without diluting the goal.", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 0, 0, 1], },
  { q: "Notes: (1) The drug reduces symptoms in 70% of patients. (2) It was developed over 12 years. (3) Side effects occur in 5% of users. Goal: emphasize the drug's overall effectiveness while acknowledging a limitation. Which choice best accomplishes this goal?", choices: ["The drug reduces symptoms in 70% of patients, though 5% experience side effects.", "The drug was developed over 12 years.", "The drug reduces symptoms in 70% of patients.", "Side effects occur in a small percentage of users."], answer: 0, explain: "This is the only choice that combines effectiveness with an honest acknowledgment of the limitation, matching both parts of the goal.", pattern: "Goal-Filtered Selection", difficulty: "hard", trapFor: [null, 0, 0, 0], },
  { q: "Notes: (1) The school implemented a new mentoring program. (2) Graduation rates rose from 78% to 91% over three years. (3) The program pairs students with local professionals. Goal: emphasize the program's measurable impact. Which choice best accomplishes this goal?", choices: ["Since implementing its mentoring program, the school has seen graduation rates rise from 78% to 91%.", "The school's new mentoring program pairs students with local professionals in the community.", "Over three years, the school's graduation rate rose from 78% to 91%.", "The mentoring program, which pairs students with local professionals, was praised by parents."], answer: 0, explain: "The direct before/after statistic tied to the program is the clearest measure of impact, matching the stated goal.", pattern: "Goal-Filtered Selection", difficulty: "hard", trapFor: [null, 0, 0, 1], },
  { q: "Notes: (1) The city built 50 miles of new bike lanes. (2) Cycling injuries dropped 30%. (3) The project cost $12 million. Goal: emphasize a safety benefit of the project. Which choice best accomplishes this goal?", choices: ["After the city built 50 miles of new bike lanes, cycling injuries dropped 30%.", "The city spent $12 million to build 50 miles of new bike lanes.", "The city's 50 miles of new bike lanes have made cycling more popular.", "In recent years, cycling injuries in the city have dropped by 30%."], answer: 0, explain: "Only this choice directly connects the infrastructure change to the safety outcome, matching the goal.", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 2, 1, 0], },
  { q: "Notes: (1) The artist's exhibit features recycled materials. (2) It has toured five countries. (3) Critics have praised its environmental message. Goal: emphasize the exhibit's international reach. Which choice best accomplishes this goal?", choices: ["The exhibit, made from recycled materials, has toured five countries.", "Critics have praised its environmental message.", "The exhibit features recycled materials.", "The artist works with unconventional materials."], answer: 0, explain: "The touring statistic is the direct measure of international reach; combining it with a brief descriptor keeps focus on the goal.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 2, 0, 1], },
  { q: "Notes: (1) The satellite has operated for 15 years. (2) It was designed to last only 5 years. (3) It continues to send usable data. Goal: emphasize the satellite's unexpected durability. Which choice best accomplishes this goal?", choices: ["Though designed to last only 5 years, the satellite has operated for 15 and continues sending usable data.", "The satellite has operated for 15 years and continues to send usable data to Earth.", "The satellite was designed to last 5 years, a typical lifespan for satellites of its type.", "The satellite sends usable data that scientists rely on to study the climate."], answer: 0, explain: "Contrasting the intended lifespan with actual performance directly emphasizes unexpected durability, matching the goal.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 0, 1, 1], },
  { q: "Notes: (1) The company switched to solar power in 2018. (2) Energy costs fell by 40%. (3) Carbon emissions fell by 60%. Goal: emphasize both the financial and environmental benefits. Which choice best accomplishes this goal?", choices: ["Since switching to solar power in 2018, the company has cut energy costs by 40% and carbon emissions by 60%.", "Since switching to solar power in 2018, the company has cut its energy costs by 40%.", "Since switching to solar power in 2018, the company has cut its carbon emissions by 60%.", "The company switched to solar power in 2018 to meet new government regulations."], answer: 0, explain: "Only this choice includes both the financial (cost) and environmental (emissions) outcomes, matching the two-part goal.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "Notes: (1) The library added a maker space in 2020. (2) Teen visitation rose 45%. (3) The space includes 3D printers and sewing machines. Goal: emphasize the maker space's effect on teen engagement. Which choice best accomplishes this goal?", choices: ["After the library added a maker space in 2020, teen visitation rose 45%.", "The maker space includes 3D printers and sewing machines.", "The library added a maker space in 2020.", "Libraries often update their offerings over time."], answer: 0, explain: "The visitation statistic tied to the maker space directly demonstrates the engagement effect, matching the goal.", pattern: "Goal-Filtered Selection", difficulty: "hard", trapFor: [null, 0, 0, 1], },
  { q: "Notes: (1) The restaurant sources ingredients locally. (2) It reduced food waste by 25%. (3) It donates surplus food to shelters. Goal: emphasize the restaurant's community impact. Which choice best accomplishes this goal?", choices: ["The restaurant donates its surplus food to local shelters, reducing waste while supporting the community.", "The restaurant sources its ingredients locally and has reduced its food waste by 25%.", "By reducing its food waste by 25%, the restaurant has also lowered its operating costs.", "The restaurant, which sources its ingredients locally, is popular with residents."], answer: 0, explain: "Only this choice highlights the community-facing outcome (donations to shelters), matching the specific goal about community impact.", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 2, 1, 1], },
  { q: "Notes: (1) The app was launched in 2021. (2) It has one million downloads. (3) 92% of users rate it five stars. Goal: emphasize the app's positive reception among users. Which choice best accomplishes this goal?", choices: ["Since its 2021 launch, the app has been downloaded one million times, and 92% of its users rate it five stars.", "The app, launched in 2021, has been downloaded one million times.", "Since its launch in 2021, the app has been downloaded more times each year.", "The app was launched in 2021 and is now one of the most popular apps in its category."], answer: 0, explain: "The five-star rating from 92% of users is the direct sign of positive reception, and the download count shows it's at scale. (Downloads and users aren't the same thing, so the sentence keeps them separate.)", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 0, 1, 1], },
  { q: "Notes: (1) The clinic opened a telehealth program in 2019. (2) Patient wait times fell from 3 weeks to 3 days. (3) The program serves rural communities. Goal: emphasize how the program improved access to care. Which choice best accomplishes this goal?", choices: ["The clinic's telehealth program, which serves rural communities, cut patient wait times from 3 weeks to 3 days.", "The clinic opened a telehealth program in 2019 to serve rural communities.", "Patient wait times at the clinic fell from 3 weeks to 3 days after it hired more doctors.", "Telehealth programs like the clinic's have become more common since 2019."], answer: 0, explain: "Combining the population served (rural communities) with the concrete wait-time improvement directly addresses the access goal.", pattern: "Goal-Filtered Selection", difficulty: "hard", trapFor: [null, 0, 1, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• The Atacama Desert in Chile receives less than 1 millimeter of rain per year in some areas.\n\n• The McMurdo Dry Valleys in Antarctica have had almost no precipitation for thousands of years.\n\n• Scientists use both regions to test equipment designed for Mars.\n\n• The Atacama is a hot desert, while the Dry Valleys are extremely cold.\n\nThe student wants to emphasize a similarity between the two regions. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Both the Atacama Desert and the McMurdo Dry Valleys are dry enough that scientists use them to test equipment designed for Mars.", "The Atacama Desert is hot, while the McMurdo Dry Valleys are extremely cold.", "Some parts of the Atacama Desert receive less than 1 millimeter of rain per year.", "Scientists test Mars equipment in the Atacama Desert because its soil closely resembles Martian soil."], answer: 0, explain: "Only this choice states something the two regions share: extreme dryness and their use for testing Mars equipment. The second choice states a difference, and the third mentions only one region.", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 2, 0, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• A \"food desert\" is an area where residents have limited access to affordable, nutritious food.\n\n• In 2021, the town of Ridgeway opened a nonprofit grocery store in a neighborhood with no supermarket within three miles.\n\n• Within a year, the store had more than 4,000 regular customers.\n\n• The store is run by a board of local residents.\n\nThe student wants to introduce the Ridgeway store to an audience unfamiliar with the term \"food desert\". Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["In 2021, Ridgeway opened a nonprofit grocery store in a food desert, an area where residents have limited access to affordable, nutritious food.", "In 2021, Ridgeway opened a nonprofit grocery store in a food desert, and within a year it had more than 4,000 regular customers.", "A food desert is an area where residents have limited access to affordable, nutritious food.", "The Ridgeway grocery store, run by a board of local residents, has more than 4,000 regular customers."], answer: 0, explain: "The goal has two parts: introduce the store and make the term understandable. Only this choice does both. The second uses \"food desert\" without explaining it, and the third explains the term without introducing the store.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 3, 0, 2], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• The bee hummingbird, native to Cuba, is the smallest known bird.\n\n• It weighs about 2 grams.\n\n• The ostrich is the largest living bird.\n\n• An adult ostrich can weigh more than 100 kilograms.\n\nThe student wants to emphasize the difference in size between the smallest and largest living birds. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["The bee hummingbird weighs about 2 grams, while an adult ostrich can weigh more than 100 kilograms.", "The bee hummingbird, native to Cuba, is the smallest known bird.", "The bee hummingbird and the ostrich live on different continents.", "An adult ostrich, the largest living bird, can weigh more than 100 kilograms."], answer: 0, explain: "A size difference needs both sizes. Only this choice puts the two weights side by side.", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 0, 1, 0], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• Researchers wanted to know whether city noise changes how songbirds sing.\n\n• They recorded great tits in 10 cities and 10 nearby forests.\n\n• City birds sang at higher pitches than forest birds.\n\n• Higher-pitched songs are less likely to be drowned out by low-pitched traffic noise.\n\nThe student wants to present a possible explanation for the study's main finding. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Great tits in cities sang at higher pitches than those in forests, possibly because higher-pitched songs are less likely to be drowned out by traffic noise.", "Researchers recorded great tits in 10 cities and 10 nearby forests to learn whether city noise changes how songbirds sing.", "Great tits in cities sang at higher pitches than great tits living in forests.", "Great tits in cities sang at higher pitches because they learned their songs from other city bird species."], answer: 0, explain: "The goal asks for the finding plus a possible reason. The second choice describes the study's method and aim, the third gives the finding with no reason, and the fourth gives a reason that isn't in the notes.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 2, 0, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• The Voyager 1 space probe was launched in 1977.\n\n• In 2012, it became the first human-made object to enter interstellar space.\n\n• It still sends data to Earth using a transmitter with about the power of a refrigerator light bulb.\n\nThe student wants to emphasize how long it took Voyager 1 to reach interstellar space. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Launched in 1977, Voyager 1 did not reach interstellar space until 2012, 35 years later.", "In 2012, Voyager 1 became the first human-made object to enter interstellar space.", "Voyager 1 still sends data to Earth using a transmitter with about the power of a refrigerator light bulb.", "Voyager 1, launched in 1977, reached interstellar space faster than scientists had predicted."], answer: 0, explain: "Emphasizing how long the journey took requires both dates. Only this choice connects the 1977 launch to the 2012 arrival.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 0, 2, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• Mangrove forests grow along tropical coastlines.\n\n• Their dense roots reduce the height of storm waves.\n\n• Mangroves store carbon in their soil at high rates.\n\n• Many mangrove forests have been cleared for shrimp farming.\n\nThe student wants to present two benefits of mangrove forests. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Mangrove forests reduce the height of storm waves and store carbon in their soil at high rates.", "Mangrove forests grow along tropical coastlines, where many have been cleared for shrimp farming.", "The dense roots of mangrove forests reduce the height of storm waves.", "Mangrove forests reduce storm waves and provide shelter for many kinds of fish."], answer: 0, explain: "Two benefits are needed, both from the notes: reducing storm waves and storing carbon. The fish habitat in the last choice may be true, but it isn't in the notes.", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 2, 0, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• In 2019, a midsize city replaced several downtown parking lots with public plazas.\n\n• Business owners worried that fewer parking spaces would reduce sales.\n\n• Two years later, sales at downtown shops had risen 12%.\n\n• Foot traffic downtown also increased.\n\nThe student wants to emphasize that the outcome contradicted business owners' expectations. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Although business owners worried that replacing parking lots with plazas would reduce sales, downtown sales rose 12% within two years.", "Two years after the city replaced downtown parking lots with public plazas, foot traffic downtown increased.", "In 2019, the city replaced several downtown parking lots with public plazas, a change business owners worried about.", "Business owners who had opposed the plazas later voted to add more of them."], answer: 0, explain: "Showing a contradiction needs both the expectation (lower sales) and the result (higher sales). Only this choice pairs them.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• A typical LED bulb uses about 9 watts.\n\n• An incandescent bulb of similar brightness uses about 60 watts.\n\n• LED bulbs typically last about 25,000 hours.\n\n• Incandescent bulbs typically last about 1,000 hours.\n\nThe student wants to emphasize the difference in lifespan between the two types of bulbs. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["A typical LED bulb lasts about 25,000 hours, compared with about 1,000 hours for an incandescent bulb.", "An LED bulb uses about 9 watts, while an incandescent bulb of similar brightness uses about 60 watts.", "LED bulbs typically last about 25,000 hours.", "LED bulbs last longer than incandescent bulbs because they produce less heat."], answer: 0, explain: "The goal is lifespan, not energy use, and a difference needs both numbers. The heat explanation in the last choice isn't in the notes.", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 2, 0, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• Tardigrades are microscopic animals, usually less than 1 millimeter long.\n\n• They can survive being dried out for years by entering a state called cryptobiosis.\n\n• In 2007, tardigrades survived 10 days of exposure to outer space.\n\n• Tardigrades are found in moss, soil, and ocean sediment worldwide.\n\nThe student wants to introduce tardigrades to an audience unfamiliar with them. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Tardigrades, microscopic animals usually less than 1 millimeter long, are found in moss, soil, and ocean sediment worldwide.", "In 2007, tardigrades survived 10 days of exposure to outer space.", "Tardigrades survive being dried out by entering a state called cryptobiosis.", "Tardigrades are the toughest animals on Earth, able to survive any conditions."], answer: 0, explain: "An audience that doesn't know tardigrades first needs to learn what they are. Only this choice says so. The other two true choices assume the reader already knows, and the last overstates the notes.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 3, 3, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• In 2010, the town of Brennan recycled 18% of its household waste.\n\n• In 2015, the town began collecting food scraps for composting.\n\n• By 2022, Brennan recycled or composted 61% of its household waste.\n\n• The town's goal is to reach 75% by 2030.\n\nThe student wants to emphasize how much Brennan's recycling rate has changed. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Brennan went from recycling 18% of its household waste in 2010 to recycling or composting 61% by 2022.", "Brennan aims to recycle or compost 75% of its household waste by 2030.", "In 2015, Brennan began collecting food scraps for composting.", "Brennan's recycling rate rose after the town began fining residents who threw recyclables in the trash."], answer: 0, explain: "A change needs a before and an after. Only this choice gives both rates.", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 2, 0, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• Linguist Ana Ribeiro studies whistled languages, in which speakers communicate by whistling words.\n\n• Whistled languages are used in mountainous areas where sound must travel long distances.\n\n• Silbo Gomero, a whistled form of Spanish, is taught in schools on La Gomera in the Canary Islands.\n\n• Ribeiro is investigating whether the brain processes whistled speech the same way it processes spoken language.\n\nThe student wants to explain the aim of Ribeiro's research. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Ribeiro is investigating whether the brain processes whistled languages such as Silbo Gomero the same way it processes spoken language.", "Silbo Gomero, a whistled form of Spanish, is taught in schools on La Gomera.", "Whistled languages are used in mountainous areas where sound must travel long distances.", "Ribeiro has shown that the brain processes whistled speech differently from spoken language."], answer: 0, explain: "The aim of the research is the question Ribeiro is investigating. The last choice reports a result the notes never give; the notes say she is still investigating.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• Painter Frida Kahlo made about 55 self-portraits.\n\n• Photographer Cindy Sherman is known for photographs in which she poses as invented characters.\n\n• Both artists used their own image as the main subject of much of their work.\n\n• Kahlo's self-portraits often depict her real experiences, while Sherman's photographs depict fictional characters.\n\nThe student wants to emphasize a similarity between Kahlo and Sherman. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Both Frida Kahlo and Cindy Sherman used their own image as the main subject of much of their work.", "Kahlo's self-portraits often depict her real experiences, while Sherman's photographs depict fictional characters.", "Frida Kahlo made about 55 self-portraits.", "Kahlo and Sherman both worked mainly in photography."], answer: 0, explain: "Only this choice states what the two artists share. The second is a difference, the third is about Kahlo alone, and the last is false (Kahlo was a painter).", pattern: "Goal-Filtered Selection", difficulty: "easy", trapFor: [null, 2, 0, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• The Great Green Wall is a project to plant trees and restore land across Africa's Sahel region.\n\n• The project was launched in 2007.\n\n• Its goal is to restore 100 million hectares of degraded land by 2030.\n\n• As of 2020, about 4% of that goal had been reached.\n\nThe student wants to emphasize how far the project was from its goal as of 2020. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["As of 2020, the Great Green Wall had restored only about 4% of the 100 million hectares it aims to restore by 2030.", "Launched in 2007, the Great Green Wall is a project to restore land across Africa's Sahel region.", "The Great Green Wall aims to restore 100 million hectares of degraded land by 2030.", "By 2020, the Great Green Wall had restored most of the Sahel's degraded land."], answer: 0, explain: "The distance from the goal needs both the goal and the progress. Only this choice pairs the 4% with the 100 million hectares.", pattern: "Goal-Filtered Selection", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• Katherine Johnson was a mathematician who worked at NASA.\n\n• She calculated trajectories for early U.S. spaceflights.\n\n• Before his 1962 orbital flight, astronaut John Glenn asked that she personally check the computer's calculations.\n\n• She received the Presidential Medal of Freedom in 2015.\n\nThe student wants to emphasize the trust others placed in Johnson's work. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Before his 1962 orbital flight, astronaut John Glenn asked that NASA mathematician Katherine Johnson personally check the computer's calculations.", "Katherine Johnson received the Presidential Medal of Freedom in 2015.", "Katherine Johnson, a NASA mathematician, calculated trajectories for early U.S. spaceflights.", "Katherine Johnson designed the computer NASA used for John Glenn's flight."], answer: 0, explain: "Glenn asking her to check the computer's work is the clearest sign of trust. The medal shows recognition, a related but different idea, and the last choice isn't in the notes.", pattern: "Goal-Filtered Selection", difficulty: "hard", trapFor: [null, 2, 0, 1], },
  { q: "While researching a topic, a student has taken the following notes:\n\n• A seismometer is an instrument that records ground motion.\n\n• Scientists place seismometers near volcanoes.\n\n• Small earthquakes often increase in the weeks before an eruption.\n\n• Seismometer data helped scientists warn residents before the 1991 eruption of Mount Pinatubo.\n\nThe student wants to explain why scientists place seismometers near volcanoes. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: ["Scientists place seismometers near volcanoes because small earthquakes often increase in the weeks before an eruption.", "Seismometer data helped scientists warn residents before the 1991 eruption of Mount Pinatubo.", "A seismometer is an instrument that scientists use to record ground motion.", "Scientists place seismometers near volcanoes so that they can measure the temperature of the magma below."], answer: 0, explain: "The reason is that rising earthquake activity can signal an eruption. Only this choice connects that to where the instruments are placed.", pattern: "Goal-Filtered Selection", difficulty: "hard", trapFor: [null, 0, 0, 1], },
],
  "rw-transitions": [
  { q: "Which choice completes the text with the most logical transition? 'The experiment produced promising initial results. ______, further trials failed to replicate the effect.'", choices: ["Similarly", "However", "For example", "As a result"], answer: 1, explain: "The sentence shows a contrast (promising results vs. failed replication), which calls for 'however.'", pattern: "Identify the Logical Relationship First", difficulty: "hard", trapFor: [0, null, 3, 2], },
  { q: "'The company invested heavily in renewable energy. ______, its overall carbon emissions rose that year.' Which transition is most logical?", choices: ["Consequently", "Nevertheless", "Similarly", "For instance"], answer: 1, explain: "Investment in renewables would be expected to lower emissions, so the actual rise is a contrast — 'nevertheless' fits.", pattern: "Contrast vs. Concession", difficulty: "easy", trapFor: [1, null, 0, null], },
  { q: "'The team had lost its last six games. ______, they entered the championship as decisive underdogs.' Which transition is most logical?", choices: ["However", "Accordingly", "In contrast", "Nonetheless"], answer: 1, explain: "The losing streak directly and logically causes the underdog status, so a cause-and-effect transition like 'accordingly' is correct.", pattern: "Identify the Logical Relationship First", difficulty: "easy", trapFor: [0, null, 0, 0], },
  { q: "'The medication reduces inflammation effectively. ______, it can cause drowsiness in some patients.' Which transition is most logical?", choices: ["Therefore", "However", "Similarly", "For this reason"], answer: 1, explain: "The sentence shifts from a benefit to a drawback, which is a contrast best marked by 'however.'", pattern: "Identify the Logical Relationship First", difficulty: "easy", trapFor: [2, null, 0, 2], },
  { q: "'Researchers hypothesized that warmer water would speed larval development. ______, the data confirmed this prediction precisely.' Which transition is most logical?", choices: ["Conversely", "Indeed", "Nevertheless", "Meanwhile"], answer: 1, explain: "The data confirms rather than contradicts the hypothesis, so a confirming transition like 'indeed' fits, not a contrastive one.", pattern: "Identify the Logical Relationship First", difficulty: "medium", trapFor: [0, null, 0, 0], },
  { q: "'The bridge was closed for repairs for six months. ______, local businesses reported a sharp drop in customer traffic.' Which transition is most logical?", choices: ["Similarly", "During this time", "In contrast", "Regardless"], answer: 1, explain: "The sentence describes a concurrent effect happening during the closure, so a time-linking transition fits best.", pattern: "Identify the Logical Relationship First", difficulty: "medium", trapFor: [0, null, 0, 0], },
  { q: "'The novel was largely ignored upon its release. ______, it is now considered a landmark of the genre.' Which transition is most logical?", choices: ["Similarly", "Today", "For example", "Because of this"], answer: 1, explain: "The sentence contrasts the past reception with the present status, and 'today' clearly marks that shift in time.", pattern: "Identify the Logical Relationship First", difficulty: "easy", trapFor: [0, null, 3, 2], },
  { q: "'The city's population grew by 20% over the decade. ______, its public transit system saw only marginal expansion.' Which transition is most logical?", choices: ["As a result", "Meanwhile", "For instance", "Consequently"], answer: 1, explain: "The sentence shows a mismatch between two concurrent trends, which 'meanwhile' captures without implying causation.", pattern: "Identify the Logical Relationship First", difficulty: "medium", trapFor: [2, null, 3, 2], },
  { q: "'The two proposals differ in cost. ______, both aim to reduce the city's carbon footprint by the same percentage.' Which transition is most logical?", choices: ["Therefore", "Nonetheless", "For example", "Similarly"], answer: 1, explain: "Despite the cost difference, the shared goal is a point of similarity introduced as a concession, matching 'nonetheless.'", pattern: "Contrast vs. Concession", difficulty: "medium", trapFor: [1, null, null, 0], },
  { q: "'The professor's early papers focused narrowly on economic theory. ______, her later work expanded into sociology and political science.' Which transition is most logical?", choices: ["Similarly", "By contrast", "Consequently", "In short"], answer: 1, explain: "The sentence shows a shift from narrow to broad scope over time, which is best marked by a contrastive transition.", pattern: "Identify the Logical Relationship First", difficulty: "hard", trapFor: [0, null, 2, 0], },
  { q: "'The vaccine requires two doses spaced four weeks apart. ______, full immunity is not achieved until two weeks after the second dose.' Which transition is most logical?", choices: ["However", "Additionally", "In contrast", "Otherwise"], answer: 1, explain: "The sentence adds a further detail about the vaccine schedule, consistent with 'additionally' rather than a contrast.", pattern: "Identify the Logical Relationship First", difficulty: "hard", trapFor: [0, null, 0, 0], },
  { q: "'The company's stock price fell sharply after the announcement. ______, analysts had predicted a modest gain.' Which transition is most logical?", choices: ["Likewise", "In fact", "Yet", "Therefore"], answer: 2, explain: "The actual outcome (a sharp fall) directly contradicts the prediction (a modest gain), which calls for 'yet.'", pattern: "Identify the Logical Relationship First", difficulty: "medium", trapFor: [0, 1, null, 2], },
  { q: "'Many species migrate south for the winter. ______, some birds remain in colder climates year-round by adapting their foraging behavior.' Which transition is most logical?", choices: ["Similarly", "However", "As a result", "In particular"], answer: 1, explain: "The sentence introduces an exception to the general migratory pattern, which is a contrast best marked by 'however.'", pattern: "Identify the Logical Relationship First", difficulty: "hard", trapFor: [0, null, 2, 3], },
  { q: "'The renovation was completed under budget. ______, it finished two months ahead of schedule.' Which transition is most logical?", choices: ["However", "In addition", "Nonetheless", "Conversely"], answer: 1, explain: "Both facts (under budget, ahead of schedule) are positive and additive, not contrasting, so 'in addition' fits.", pattern: "Identify the Logical Relationship First", difficulty: "easy", trapFor: [0, null, 0, 0], },
  { q: "'The committee initially opposed the merger. ______, after reviewing updated financial projections, it approved the deal unanimously.' Which transition is most logical?", choices: ["Similarly", "However", "For example", "In particular"], answer: 1, explain: "The sentence shows a reversal in position after new information, which is a contrast best marked by 'however.'", pattern: "Identify the Logical Relationship First", difficulty: "hard", trapFor: [0, null, 3, 3], },
  { q: "Honeybees share the location of food through a \"waggle dance\" whose angle indicates direction relative to the sun. ______ bees that watch the dance can fly straight to a flower patch they have never visited.\n\nWhich choice completes the text with the most logical transition?", choices: ["As a result,", "However,", "For example,", "Similarly,"], answer: 0, explain: "Because the dance encodes direction, watching bees can fly straight to the food. That's a result of the first sentence.", pattern: "Identify the Logical Relationship First", difficulty: "easy", trapFor: [null, 0, 3, 0], },
  { q: "Some plants defend themselves by recruiting other species. ______ when caterpillars chew its leaves, the wild tobacco plant releases chemicals that attract insects that eat the caterpillars.\n\nWhich choice completes the text with the most logical transition?", choices: ["For instance,", "Nevertheless,", "In contrast,", "Therefore,"], answer: 0, explain: "The wild tobacco plant is a specific case of a plant recruiting other species, so the second sentence is an example of the first.", pattern: "Identify the Logical Relationship First", difficulty: "medium", trapFor: [null, 0, 0, 2], },
  { q: "The first commercial cell phones, introduced in the 1980s, weighed almost two pounds and cost thousands of dollars. ______ they sold well among business customers who valued being reachable on the road.\n\nWhich choice completes the text with the most logical transition?", choices: ["Even so,", "Consequently,", "Likewise,", "In other words,"], answer: 0, explain: "Heavy, expensive phones would be expected to sell poorly; they sold well despite that. 'Even so' signals that concession.", pattern: "Contrast vs. Concession", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "The new library building uses rooftop solar panels to generate much of its electricity. ______ it collects rainwater to irrigate the surrounding gardens.\n\nWhich choice completes the text with the most logical transition?", choices: ["Additionally,", "Instead,", "As a result,", "Regardless,"], answer: 0, explain: "Collecting rainwater is a second, separate green feature, so the relationship is addition. The solar panels don't cause the rainwater collection.", pattern: "Identify the Logical Relationship First", difficulty: "easy", trapFor: [null, 0, 2, 0], },
  { q: "Most substances expand as they warm. Water, ______ contracts as it warms from 0°C to 4°C.\n\nWhich choice completes the text with the most logical transition?", choices: ["however,", "therefore,", "for example,", "similarly,"], answer: 0, explain: "Water does the opposite of what most substances do over this range, so the relationship is contrast.", pattern: "Identify the Logical Relationship First", difficulty: "medium", trapFor: [null, 2, 3, 0], },
  { q: "Archaeologists first surveyed the site with ground-penetrating radar to locate buried walls. ______ they excavated only the areas where the radar had detected structures.\n\nWhich choice completes the text with the most logical transition?", choices: ["Next,", "In contrast,", "For instance,", "Nevertheless,"], answer: 0, explain: "The excavation followed the radar survey in time, and 'first' in the previous sentence sets up that sequence.", pattern: "Identify the Logical Relationship First", difficulty: "easy", trapFor: [null, 0, 3, 0], },
  { q: "Economists describe the tax as \"regressive.\" ______ it takes a larger share of income from lower-income households than from higher-income ones.\n\nWhich choice completes the text with the most logical transition?", choices: ["In other words,", "By contrast,", "For example,", "Moreover,"], answer: 0, explain: "The second sentence restates what \"regressive\" means in plain terms; it doesn't add a new point or give an example.", pattern: "Identify the Logical Relationship First", difficulty: "hard", trapFor: [null, 0, 3, 0], },
  { q: "Critics praised the documentary's striking footage of deep-sea creatures. ______ several scientists objected that its narration exaggerated how little is known about the deep ocean.\n\nWhich choice completes the text with the most logical transition?", choices: ["However,", "Therefore,", "Similarly,", "For instance,"], answer: 0, explain: "Praise from critics is followed by objections from scientists, which is a contrast.", pattern: "Identify the Logical Relationship First", difficulty: "easy", trapFor: [null, 2, 0, 3], },
  { q: "The research team's sample was small: only twelve volcanoes. ______ the pattern they observed was so consistent across all twelve that other researchers have taken it seriously.\n\nWhich choice completes the text with the most logical transition?", choices: ["Nonetheless,", "Accordingly,", "In fact,", "Likewise,"], answer: 0, explain: "A small sample would normally weaken a finding; other researchers take it seriously despite that, so the relationship is concession.", pattern: "Contrast vs. Concession", difficulty: "hard", trapFor: [null, 1, null, 0], },
  { q: "Octopuses can change the color of their skin in a fraction of a second to blend into their surroundings. ______ some species of cuttlefish can alter both the color and the texture of their skin.\n\nWhich choice completes the text with the most logical transition?", choices: ["Similarly,", "However,", "As a result,", "For example,"], answer: 0, explain: "Cuttlefish show a comparable ability in a different animal, so the relationship is similarity. Cuttlefish aren't an example of octopuses.", pattern: "Identify the Logical Relationship First", difficulty: "medium", trapFor: [null, 0, 2, 3], },
  { q: "In the 1800s, many European cities drew drinking water from rivers that also carried sewage. ______ outbreaks of cholera, a disease spread through contaminated water, were common.\n\nWhich choice completes the text with the most logical transition?", choices: ["Consequently,", "Nevertheless,", "In addition,", "Specifically,"], answer: 0, explain: "Contaminated drinking water led to cholera outbreaks, a cause-and-effect relationship.", pattern: "Identify the Logical Relationship First", difficulty: "medium", trapFor: [null, 0, 0, 0], },
  { q: "The architect's designs respond closely to local climate. ______ her houses in desert regions have thick earthen walls that keep interiors cool during the day.\n\nWhich choice completes the text with the most logical transition?", choices: ["For example,", "Nevertheless,", "Similarly,", "In contrast,"], answer: 0, explain: "Desert houses with cooling walls are a specific instance of designs responding to climate.", pattern: "Identify the Logical Relationship First", difficulty: "easy", trapFor: [null, 0, 0, 0], },
  { q: "The city council did not vote to close the aging bridge. ______ it approved funding to reinforce the bridge's supports.\n\nWhich choice completes the text with the most logical transition?", choices: ["Instead,", "Similarly,", "For instance,", "As a result,"], answer: 0, explain: "The council took a different action in place of closing the bridge, and 'instead' marks that replacement.", pattern: "Identify the Logical Relationship First", difficulty: "medium", trapFor: [null, 0, 3, 2], },
  { q: "Mercury is the planet closest to the Sun. ______ it is not the hottest planet in the solar system; Venus, whose thick atmosphere traps heat, is hotter.\n\nWhich choice completes the text with the most logical transition?", choices: ["Nevertheless,", "Therefore,", "For example,", "Similarly,"], answer: 0, explain: "Being closest to the Sun would suggest being hottest, but Mercury isn't the hottest. That's a concession, true despite the first sentence.", pattern: "Contrast vs. Concession", difficulty: "hard", trapFor: [null, 1, null, 0], },
  { q: "Tree rings are wider in years with plentiful rain and narrower in dry years. ______ scientists can use the rings of very old trees to reconstruct rainfall patterns from centuries before weather records existed.\n\nWhich choice completes the text with the most logical transition?", choices: ["Thus,", "Nonetheless,", "For example,", "In contrast,"], answer: 0, explain: "Because ring width tracks rainfall, scientists can read past rainfall from old rings. The second sentence is a consequence of the first.", pattern: "Identify the Logical Relationship First", difficulty: "medium", trapFor: [null, 0, 3, 0], },
],
  "rw-boundaries": [
  { q: "Which choice completes the text with the correct punctuation? 'The results were surprising ______ no one had predicted such a sharp decline.'", choices: [", ", "; ", " ", " and, "], answer: 1, explain: "Both sides are independent clauses, so they need a semicolon (or a period). A comma alone makes a comma splice, no punctuation makes a fused sentence, and 'and,' puts the comma on the wrong side of the conjunction.", pattern: "Independent Clause Joins (Comma, Semicolon, Period, or Conjunction)", difficulty: "easy", trapFor: [0, null, 2, 3], },
  { q: "Choose the option that correctly punctuates the sentence: 'She brought three things to the interview a resume, a portfolio, and a list of references.'", choices: ["...interview, a resume...", "...interview: a resume...", "...interview; a resume...", "...interview a resume..."], answer: 1, explain: "A colon correctly introduces a list after an independent clause.", pattern: "Using a Colon to Introduce a List, Explanation, or Elaboration", difficulty: "easy", trapFor: [3, null, 1, 3], },
  { q: "Which choice completes the text with the correct punctuation? 'The committee reviewed the proposal ______ it was ultimately rejected.'", choices: [", and", "; and", ": and", " and,"], answer: 0, explain: "A comma before a coordinating conjunction (and) correctly joins two independent clauses.", pattern: "Independent Clause Joins (Comma, Semicolon, Period, or Conjunction)", difficulty: "easy", trapFor: [null, 3, null, 3], },
  { q: "Choose the option that correctly punctuates the sentence: 'The museum's newest exhibit features work by three artists Chen Liu a sculptor Marisol Ortiz a painter and Amara Diallo a photographer.'", choices: ["artists: Chen Liu, a sculptor, Marisol Ortiz, a painter, and Amara Diallo, a photographer.", "artists: Chen Liu, a sculptor; Marisol Ortiz, a painter, and Amara Diallo, a photographer.", "artists; Chen Liu, a sculptor; Marisol Ortiz, a painter; and Amara Diallo, a photographer.", "artists: Chen Liu, a sculptor; Marisol Ortiz, a painter; and Amara Diallo, a photographer."], answer: 3, explain: "A colon introduces the list after the complete clause, and because each item already contains a comma (name, description), semicolons must separate every item — including before 'and Amara Diallo.'", pattern: "Semicolon-Separated Lists with Internal Commas", difficulty: "hard", trapFor: [0, 1, null, null], },
  { q: "Which choice completes the text with the correct punctuation? 'The engineers tested the bridge's load capacity ______ they found it exceeded safety requirements.'", choices: [", and", "; and", ": therefore", " but,"], answer: 0, explain: "Two independent clauses in a simple additive relationship are correctly joined by a comma plus coordinating conjunction.", pattern: "Independent Clause Joins (Comma, Semicolon, Period, or Conjunction)", difficulty: "easy", trapFor: [null, 3, null, 3], },
  { q: "Choose the option that correctly punctuates the sentence: 'Despite the storm the flight departed on time.'", choices: ["Despite the storm, the flight departed on time.", "Despite the storm; the flight departed on time.", "Despite, the storm the flight departed on time.", "Despite the storm: the flight departed on time."], answer: 0, explain: "An introductory dependent phrase is correctly followed by a comma before the independent clause.", pattern: "Introductory Phrases and Single-Boundary Commas", difficulty: "easy", trapFor: [null, 0, null, 0], },
  { q: "The report reached a single, blunt conclusion ______ no further funding.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: [": no", "; no", " no", ", and no"], answer: 0, explain: "The words after the blank ('no further funding') aren't a complete clause; they spell out what the conclusion was. A colon introduces that elaboration. A semicolon needs a complete clause on both sides.", pattern: "Using a Colon to Introduce a List, Explanation, or Elaboration", difficulty: "medium", trapFor: [null, 1, 3, null], },
  { q: "The recipe calls for four ingredients ______ flour, sugar, eggs, and butter.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: [": ", ", ", "; ", " such as: "], answer: 0, explain: "The complete clause announces 'four ingredients,' and a colon introduces the list itself. 'Such as:' puts a colon after an incomplete phrase, which is never correct.", pattern: "Using a Colon to Introduce a List, Explanation, or Elaboration", difficulty: "easy", trapFor: [null, 3, 1, 2], },
  { q: "Which choice completes the text with the correct punctuation? 'The novelist rarely gave interviews ______ she preferred to let her books speak for themselves.'", choices: [", ", "; ", ": for", " because,"], answer: 1, explain: "Both sides are independent clauses expressing related but distinct ideas, correctly joined by a semicolon.", pattern: "Independent Clause Joins (Comma, Semicolon, Period, or Conjunction)", difficulty: "medium", trapFor: [0, null, null, null], },
  { q: "Choose the option that correctly punctuates the sentence: 'The two finalists a young chemist and a veteran engineer were both highly qualified.'", choices: ["finalists, a young chemist and a veteran engineer, were both highly qualified.", "finalists a young chemist, and a veteran engineer, were both highly qualified.", "finalists; a young chemist and a veteran engineer; were both highly qualified.", "finalists: a young chemist and a veteran engineer were both highly qualified."], answer: 0, explain: "Commas correctly set off the nonessential appositive phrase describing the two finalists.", pattern: "Nonessential Appositives and Descriptive Phrases", difficulty: "hard", trapFor: [null, 1, 0, 1], },
  { q: "Which choice completes the text with the correct punctuation? 'The lecture covered one topic in depth ______ the ethics of artificial intelligence.'", choices: [": ", "; ", " ", ", and "], answer: 0, explain: "The complete clause ends on 'one topic,' and a colon introduces exactly which topic. A semicolon would need a complete clause after it; no punctuation runs the two together.", pattern: "Using a Colon to Introduce a List, Explanation, or Elaboration", difficulty: "medium", trapFor: [null, 1, 3, null], },
  { q: "Choose the option that correctly punctuates the sentence: 'The hikers reached the summit exhausted but they still had the descent ahead of them.'", choices: ["summit exhausted, but they still had the descent ahead of them.", "summit exhausted; but they still had the descent ahead of them.", "summit exhausted but, they still had the descent ahead of them.", "summit, exhausted but they still had the descent ahead of them."], answer: 0, explain: "A comma correctly precedes the coordinating conjunction 'but' joining two independent clauses.", pattern: "Independent Clause Joins (Comma, Semicolon, Period, or Conjunction)", difficulty: "medium", trapFor: [null, 3, 3, null], },
  { q: "Which choice completes the text with the correct punctuation? 'The results were inconclusive ______ the researchers called for a larger follow-up study.'", choices: [", so", "; so", ": so", " so,"], answer: 0, explain: "A comma before the coordinating conjunction 'so' correctly joins the two independent clauses.", pattern: "Independent Clause Joins (Comma, Semicolon, Period, or Conjunction)", difficulty: "medium", trapFor: [null, 3, null, 3], },
  { q: "Choose the option that correctly punctuates the sentence: 'Marie Curie who discovered radium won two Nobel Prizes.'", choices: ["Marie Curie, who discovered radium, won two Nobel Prizes.", "Marie Curie who discovered radium, won two Nobel Prizes.", "Marie Curie, who discovered radium won two Nobel Prizes.", "Marie Curie; who discovered radium; won two Nobel Prizes."], answer: 0, explain: "Commas correctly set off the nonessential relative clause describing Marie Curie on both sides.", pattern: "Nonessential Appositives and Descriptive Phrases", difficulty: "hard", trapFor: [null, 1, 1, 0], },
  { q: "Which choice completes the text with the correct punctuation? 'The board approved the merger unanimously ______ a decision that surprised many analysts.'", choices: [", ", "; ", " ", ", and "], answer: 0, explain: "'A decision that surprised many analysts' renames the whole preceding action and ends the sentence, so a single comma sets it off. A semicolon would need a complete clause after it.", pattern: "Nonessential Appositives and Descriptive Phrases", difficulty: "medium", trapFor: [null, 0, 2, null], },
  { q: "Marine biologist Ayana Brooks spent a decade recording a single pod of orcas off the coast of Washington ______ her recordings revealed that each family group uses its own distinct set of calls.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["Washington; her", "Washington, her", "Washington her", "Washington, and, her"], answer: 0, explain: "Both sides are complete clauses, so they need a semicolon (or a period). A lone comma is a comma splice, nothing at all is a fused sentence, and 'and,' misplaces the comma.", pattern: "Independent Clause Joins (Comma, Semicolon, Period, or Conjunction)", difficulty: "medium", trapFor: [null, 0, 2, 3], },
  { q: "The first transcontinental telegraph line was completed in October 1861 ______ just two days later, the Pony Express, which had carried mail across the West for eighteen months, shut down.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["1861. Just", "1861, just", "1861 just", "1861: and just"], answer: 0, explain: "'The first transcontinental telegraph line was completed in October 1861' and 'just two days later, the Pony Express... shut down' are both complete sentences, so a period separates them. The long middle of the second sentence makes a comma splice easy to miss.", pattern: "Independent Clause Joins (Comma, Semicolon, Period, or Conjunction)", difficulty: "hard", trapFor: [null, 0, 2, null], },
  { q: "The volcano had been dormant for centuries ______ scientists still monitored it around the clock.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: [", but", "; but", ", ", " but,"], answer: 0, explain: "Two complete clauses joined by 'but' need a comma before the conjunction, not a semicolon with it and not a comma after it.", pattern: "Independent Clause Joins (Comma, Semicolon, Period, or Conjunction)", difficulty: "easy", trapFor: [null, 3, 0, 3], },
  { q: "The festival's lineup included three headliners: Ondine Park, a jazz pianist from Montreal ______ the Hollis Brothers, a bluegrass trio; and Sade Okafor, a spoken-word poet.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["Montreal; the", "Montreal, the", "Montreal: the", "Montreal the"], answer: 0, explain: "Each list item contains its own comma (name, description), and the rest of the list already uses semicolons, so a semicolon must separate the first item from the second too.", pattern: "Semicolon-Separated Lists with Internal Commas", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "For the camping trip, Lena packed a tent ______ a sleeping bag, a camp stove, and a water filter.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["tent, a", "tent; a", "tent: a", "tent a"], answer: 0, explain: "None of the list items contains an internal comma, so plain commas separate them. Semicolons here would be an overcorrection.", pattern: "Semicolon-Separated Lists with Internal Commas", difficulty: "medium", trapFor: [null, 2, null, null], },
  { q: "The ornithologist Tomás Rivera ______ a researcher who has banded more than ten thousand songbirds, argues that city lights disrupt migration far more than previously thought.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["Rivera, a researcher", "Rivera a researcher", "Rivera; a researcher", "Rivera: a researcher"], answer: 0, explain: "'A researcher who has banded more than ten thousand songbirds' is a nonessential description inserted mid-sentence. It already has a closing comma after 'songbirds,' so it needs an opening comma to match.", pattern: "Nonessential Appositives and Descriptive Phrases", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "The city's oldest building ______ a limestone chapel completed in 1784 — now houses a small history museum.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["building — a", "building, a", "building a", "building; a"], answer: 0, explain: "The inserted description closes with a dash, so it must open with a dash too. Nonessential elements take the same mark on both sides.", pattern: "Nonessential Appositives and Descriptive Phrases", difficulty: "hard", trapFor: [null, 1, 1, 0], },
  { q: "After three failed prototypes ______ the engineering team finally produced a drone that could fly through heavy rain.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["prototypes, the", "prototypes; the", "prototypes: the", "prototypes the"], answer: 0, explain: "'After three failed prototypes' is an introductory phrase, not a complete clause, so a single comma separates it from the main clause. A semicolon or colon would need a complete clause before it.", pattern: "Introductory Phrases and Single-Boundary Commas", difficulty: "easy", trapFor: [null, 0, 0, 1], },
  { q: "Having spent two summers cataloging the tide pools near her hometown ______ Priya recognized the rare sea slug immediately.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["hometown, Priya", "hometown; Priya", "hometown. Priya", "hometown Priya"], answer: 0, explain: "The opening participial phrase ('Having spent...') can't stand on its own, so it's joined to the main clause with a comma. A period or semicolon would leave it as a fragment.", pattern: "Introductory Phrases and Single-Boundary Commas", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "The three ______ proposals were posted online so that residents could compare them before the vote.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["candidates'", "candidate's", "candidates", "candidates's"], answer: 0, explain: "The proposals belong to three candidates, so the plural possessive is needed: add the apostrophe after the plural -s.", pattern: "Possessive vs. Plural Noun Forms", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "Each spring, the botanical garden opens ______ greenhouse to visitors, showing off orchids that bloom for only a few weeks.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["its", "it's", "its'", "their"], answer: 0, explain: "'Its' is the possessive (the garden's greenhouse). 'It's' only ever means 'it is,' and 'its'' is not a word.", pattern: "Possessive vs. Plural Noun Forms", difficulty: "hard", trapFor: [null, 2, 2, null], },
  { q: "The committee's final report recommended ______ the city expand its network of protected bike lanes by 2030.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["that", ", that", ": that", "; that"], answer: 0, explain: "'That the city expand...' is the object of 'recommended,' and nothing separates a verb from the clause that completes it.", pattern: "Recognizing When No Punctuation Is Needed", difficulty: "medium", trapFor: [null, 0, 0, null], },
  { q: "The volunteers who arrived before sunrise ______ rewarded with a clear view of the comet.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["were", ", were", "; were", " — were"], answer: 0, explain: "'Who arrived before sunrise' identifies which volunteers are meant, so it's essential and takes no punctuation, and nothing separates the subject from its verb.", pattern: "Recognizing When No Punctuation Is Needed", difficulty: "hard", trapFor: [null, 2, null, 2], },
  { q: "The study's recommendation was simple ______ at least eight hours of sleep before any major exam.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: [": at", "; at", " at", ", and at"], answer: 0, explain: "What follows the blank isn't a complete clause; it spells out the recommendation. A colon introduces that elaboration, while a semicolon would need a complete clause on both sides.", pattern: "Using a Colon to Introduce a List, Explanation, or Elaboration", difficulty: "medium", trapFor: [null, 1, 3, null], },
  { q: "The museum's new wing will house artifacts from several ancient civilizations ______ Egypt, Mesopotamia, and the Indus Valley.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: [", including", ", including:", ": including", "; including"], answer: 0, explain: "'Including' already introduces the examples, so no colon follows it. A colon after an incomplete phrase like 'including' is never correct.", pattern: "Using a Colon to Introduce a List, Explanation, or Elaboration", difficulty: "hard", trapFor: [null, 2, null, null], },
],
  "rw-form-structure": [
  { q: "Which choice completes the sentence with correct subject-verb agreement? 'The list of items ______ long.'", choices: ["are", "is", "were", "have been"], answer: 1, explain: "The subject is 'list' (singular), not 'items,' so the singular verb 'is' is correct.", pattern: "Subject-Verb Agreement with Distracting Phrases", difficulty: "easy", trapFor: [0, null, 0, 0], },
  { q: "Which choice maintains parallel structure? 'She enjoys hiking, swimming, and ______.'", choices: ["to bike", "biking", "bikes", "she bikes"], answer: 1, explain: "To match the -ing form of 'hiking' and 'swimming,' the parallel choice is 'biking.'", pattern: "Parallel Structure in Lists and Comparisons", difficulty: "easy", trapFor: [0, null, 0, 0], },
  { q: "Which choice completes the sentence with correct subject-verb agreement? 'Neither the manager nor the employees ______ available for comment.'", choices: ["was", "were", "is", "has been"], answer: 1, explain: "With 'neither/nor,' the verb agrees with the nearer subject, 'employees' (plural), so 'were' is correct.", pattern: "Subject-Verb Agreement with Distracting Phrases", difficulty: "hard", trapFor: [2, null, 2, 2], },
  { q: "Which choice completes the sentence with the correct pronoun? 'Each of the museums published ______ annual report online.'", choices: ["their", "its", "it's", "they're"], answer: 1, explain: "'Each' is singular, so the pronoun must be singular too: 'its.' 'Their' matches the nearby plural 'museums' instead of the true subject, and 'it's' means 'it is.'", pattern: "Pronoun Agreement and Reference", difficulty: "easy", trapFor: [0, null, 3, 3], },
  { q: "Which choice maintains parallel structure? 'The manual explains how to install the software, configure the settings, and ______.'", choices: ["troubleshooting common errors", "how you troubleshoot common errors", "troubleshoot common errors", "for troubleshooting common errors"], answer: 2, explain: "To match the base-verb form of 'install' and 'configure,' the parallel choice is 'troubleshoot.'", pattern: "Parallel Structure in Lists and Comparisons", difficulty: "hard", trapFor: [0, 0, null, 0], },
  { q: "Which choice completes the sentence with correct subject-verb agreement? 'The list of recommendations, compiled by three separate committees, ______ ready for review.'", choices: ["is", "are", "were", "being"], answer: 0, explain: "The subject is 'list,' which is singular. 'Of recommendations' and 'compiled by three separate committees' are interruptions, so the verb is 'is.'", pattern: "Subject-Verb Agreement with Distracting Phrases", difficulty: "medium", trapFor: [null, 0, 0, null], },
  { q: "Which choice completes the sentence without a dangling modifier? 'Having reviewed thousands of pages of testimony, ______.'", choices: ["the committee released its report", "the report was released by the committee", "the committee's report was released", "the release of the report followed"], answer: 0, explain: "Whoever 'reviewed thousands of pages' must come right after the comma, and that's the committee. The report, the committee's report and the release didn't review anything.", pattern: "Modifier Placement and Dangling Modifiers", difficulty: "hard", trapFor: [null, 2, 0, 0], },
  { q: "Which choice completes the sentence with correct subject-verb agreement? 'Either the coach or the players ______ responsible for the delay.'", choices: ["is", "are", "was", "has been"], answer: 1, explain: "With 'either/or,' the verb agrees with the nearer subject, 'players' (plural), so 'are' is correct.", pattern: "Subject-Verb Agreement with Distracting Phrases", difficulty: "hard", trapFor: [2, null, 2, 2], },
  { q: "Which choice maintains parallel structure? 'The policy aims to reduce costs, increase efficiency, and ______.'", choices: ["improving customer satisfaction", "improve customer satisfaction", "customer satisfaction is improved", "for improving customer satisfaction"], answer: 1, explain: "To match 'reduce' and 'increase,' the parallel base-verb form is 'improve.'", pattern: "Parallel Structure in Lists and Comparisons", difficulty: "medium", trapFor: [0, null, 0, 0], },
  { q: "Which choice completes the sentence with the correct pronoun? 'The company revised its policy after ______ received numerous complaints.'", choices: ["it", "they", "them", "its"], answer: 0, explain: "'Company' is a singular collective noun in this context, so the singular pronoun 'it' is correct.", pattern: "Pronoun Agreement and Reference", difficulty: "easy", trapFor: [null, 2, 2, 3], },
  { q: "Which choice correctly avoids a dangling modifier? '______, the ancient manuscript was carefully restored.'", choices: ["Discovered in a monastery archive", "Having discovered it in a monastery archive", "Discovering it in a monastery archive", "To discover it in a monastery archive"], answer: 0, explain: "This choice clearly modifies 'the ancient manuscript,' which was itself discovered, avoiding a dangling modifier.", pattern: "Modifier Placement and Dangling Modifiers", difficulty: "medium", trapFor: [null, 0, 0, 0], },
  { q: "Which choice completes the sentence with correct subject-verb agreement? 'A number of proposals ______ still under review.'", choices: ["is", "are", "was", "has been"], answer: 1, explain: "'A number of' takes a plural verb when referring to multiple countable items, so 'are' is correct.", pattern: "Subject-Verb Agreement with Distracting Phrases", difficulty: "easy", trapFor: [1, null, 1, 1], },
  { q: "Which choice maintains parallel structure? 'The workshop taught participants not only how to write code but also ______.'", choices: ["debugging it effectively", "how to debug it effectively", "the debugging of it", "it being debugged effectively"], answer: 1, explain: "To match 'how to write' in the first part of the 'not only...but also' construction, the parallel choice is 'how to debug.'", pattern: "Parallel Structure in Lists and Comparisons", difficulty: "medium", trapFor: [1, null, 1, 1], },
  { q: "Which choice completes the sentence with the correct pronoun? 'The two bridges were closed so that engineers could inspect ______ supports.'", choices: ["their", "its", "there", "they're"], answer: 0, explain: "The supports belong to the two bridges, a plural antecedent, so the possessive is 'their.' 'There' and 'they're' are sound-alikes that aren't possessives.", pattern: "Pronoun Agreement and Reference", difficulty: "hard", trapFor: [null, null, 3, 3], },
  { q: "Which choice completes the sentence with correct subject-verb agreement? 'Each of the proposed amendments ______ debated at length.'", choices: ["were", "was", "are", "have been"], answer: 1, explain: "'Each' is singular, so the singular verb 'was' correctly agrees, even though 'amendments' is plural.", pattern: "Subject-Verb Agreement with Distracting Phrases", difficulty: "medium", trapFor: [0, null, 0, 0], },
  { q: "The collection of letters, diaries, and photographs that historians recovered from the attic ______ now on display at the county museum.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["is", "are", "were", "have been"], answer: 0, explain: "The subject is 'collection,' which is singular. Everything between it and the verb describes the collection, so the verb is 'is.'", pattern: "Subject-Verb Agreement with Distracting Phrases", difficulty: "hard", trapFor: [null, 0, 0, 0], },
  { q: "According to the report, the number of students enrolled in coding classes ______ tripled over the past five years.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["has", "have", "having", "are"], answer: 0, explain: "'The number of' refers to a single quantity, so it takes a singular verb: 'has tripled.' ('A number of' is the plural one.)", pattern: "Subject-Verb Agreement with Distracting Phrases", difficulty: "medium", trapFor: [null, 1, null, 0], },
  { q: "Along the northern rim of the canyon ______ a series of ancient cliff dwellings, some more than eight hundred years old.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["runs", "run", "are running", "running"], answer: 0, explain: "The sentence is inverted: its subject, 'a series,' comes after the verb, and it's singular, so the verb is 'runs.' 'Dwellings' is inside the phrase describing the series.", pattern: "Subject-Verb Agreement with Distracting Phrases", difficulty: "hard", trapFor: [null, 0, 0, null], },
  { q: "The internship program is designed to help students build professional networks, gain hands-on experience, and ______.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["explore potential careers", "exploring potential careers", "potential careers can be explored", "to explore potential careers"], answer: 0, explain: "The list continues 'build...' and 'gain...,' so the third item must be the same base-verb form: 'explore.'", pattern: "Parallel Structure in Lists and Comparisons", difficulty: "medium", trapFor: [null, 0, 0, 0], },
  { q: "For many commuters, cycling to work is not only cheaper than driving but also ______.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["healthier", "it is healthier", "being healthier", "more health for them"], answer: 0, explain: "'Not only cheaper... but also' needs matching forms on both sides: 'cheaper' pairs with 'healthier.'", pattern: "Parallel Structure in Lists and Comparisons", difficulty: "hard", trapFor: [null, 1, 1, 1], },
  { q: "When the orchestra announced ______ new season, subscriptions sold out within a day.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["its", "their", "it's", "there"], answer: 0, explain: "'The orchestra' is a single group, so it takes the singular possessive 'its.' 'It's' means 'it is,' and 'there' isn't a possessive.", pattern: "Pronoun Agreement and Reference", difficulty: "medium", trapFor: [null, 2, 3, 3], },
  { q: "Every one of the paintings in the exhibition was restored before ______ was shipped to the museum.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["it", "they", "them", "its"], answer: 0, explain: "'Every one' is singular, so the pronoun is 'it.' 'They' matches the nearby plural 'paintings' instead of the actual antecedent.", pattern: "Pronoun Agreement and Reference", difficulty: "hard", trapFor: [null, 0, 0, 3], },
  { q: "By the time the rescue boat arrived, the stranded hikers ______ on the rocky ledge for nearly nine hours.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["had waited", "waited", "have waited", "will have waited"], answer: 0, explain: "The waiting happened before another past event (the boat arriving), so it takes the past perfect: 'had waited.'", pattern: "Verb Tense and Form Consistency", difficulty: "medium", trapFor: [null, 2, 0, 0], },
  { q: "Since the new transit line opened last year, average commute times in the region ______ by almost fifteen minutes.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["have fallen", "fell", "had fallen", "will fall"], answer: 0, explain: "'Since... last year' describes a change that continues up to now, which calls for the present perfect: 'have fallen.'", pattern: "Verb Tense and Form Consistency", difficulty: "medium", trapFor: [null, 2, 0, 0], },
  { q: "After reviewing the evidence, the jury decided ______ the defendant's alibi.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["to accept", "accepting", "to accepting", "accept"], answer: 0, explain: "'Decide' is followed by an infinitive: 'decided to accept.'", pattern: "Verb Tense and Form Consistency", difficulty: "hard", trapFor: [null, 1, 1, 1], },
  { q: "A pioneer of electronic music, ______\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["Mara Ellison built her first synthesizer from salvaged radio parts.", "the first synthesizer that Mara Ellison built came from salvaged radio parts.", "salvaged radio parts were what Mara Ellison used to build her first synthesizer.", "Mara Ellison's first synthesizer was built from salvaged radio parts."], answer: 0, explain: "'A pioneer of electronic music' describes a person, so that person must come right after the comma. In the other choices it modifies a synthesizer, radio parts, or (via the possessive) a synthesizer again.", pattern: "Modifier Placement and Dangling Modifiers", difficulty: "hard", trapFor: [null, 0, 0, 1], },
  { q: "Built in 1889 for the World's Fair in Paris, ______\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["the Eiffel Tower was initially criticized by many prominent artists.", "many prominent artists initially criticized the Eiffel Tower.", "the criticism of the Eiffel Tower initially came from many prominent artists.", "the Eiffel Tower's design was initially criticized by many prominent artists."], answer: 0, explain: "What was 'built in 1889' is the tower, so 'the Eiffel Tower' must follow the comma. The artists, the criticism and the design weren't built in 1889.", pattern: "Modifier Placement and Dangling Modifiers", difficulty: "medium", trapFor: [null, 0, 0, 1], },
  { q: "The glacier retreated nearly two kilometers over the past century, ______ a valley that had been buried under ice for thousands of years.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["exposing", "it exposed", "exposes", "and exposing"], answer: 0, explain: "The sentence already has its main verb ('retreated'), so what follows the comma must be a non-finite phrase: 'exposing.' A second finite verb creates a comma splice.", pattern: "Finite vs. Non-Finite Verb Forms", difficulty: "hard", trapFor: [null, 0, 0, null], },
  { q: "Researchers are still trying to determine ______ so quickly after the first frost.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["why the leaves of this species change color", "why do the leaves of this species change color", "why did the leaves of this species change color", "why the leaves of this species changing color"], answer: 0, explain: "The embedded question is the object of 'determine,' so it uses statement word order ('why the leaves... change'), not question order ('why do the leaves...').", pattern: "Finite vs. Non-Finite Verb Forms", difficulty: "hard", trapFor: [null, 1, 1, null], },
  { q: "The city council voted to postpone ______ the new parking regulations until after the holiday season.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?", choices: ["enforcing", "to enforce", "enforce", "enforced"], answer: 0, explain: "'Postpone' is followed by the -ing form: 'postpone enforcing.'", pattern: "Finite vs. Non-Finite Verb Forms", difficulty: "medium", trapFor: [null, 2, 2, null], },
],
  "m-linear-eq-1var": [
  { q: "Solve for x: 3x + 7 = 22", choices: ["5", "7", "15", "29/3"], answer: 0, explain: "3x = 15, so x = 5.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "easy", trapFor: [null, null, 1, null], },
  { q: "If 2(x - 4) = 10, what is the value of x?", choices: ["3", "7", "9", "14"], answer: 2, explain: "2x - 8 = 10 → 2x = 18 → x = 9.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "medium", trapFor: [null, 1, null, 1], },
  { q: "In the equation 4x + k = 4x + 7, k is a constant. For which value of k does the equation have infinitely many solutions?", choices: ["7", "Any value except 7", "0", "-7"], answer: 0, explain: "The 4x terms cancel, leaving k = 7. If k is 7, that statement is always true, so every x works: infinitely many solutions. Any other k leaves a false statement, which means no solution.", pattern: "No-Solution and Infinite-Solution Equations", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "Solve for x: 5(x + 2) = 3x + 18", choices: ["2", "4", "6", "8"], answer: 1, explain: "5x + 10 = 3x + 18 → 2x = 8 → x = 4.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "easy", trapFor: [null, null, null, 1], },
  { q: "A number increased by 12 equals three times the number. What is the number?", choices: ["4", "6", "8", "12"], answer: 1, explain: "x + 12 = 3x → 12 = 2x → x = 6.", pattern: "Translating a Word Problem into an Equation", difficulty: "easy", trapFor: [2, null, null, null], },
  { q: "Solve for x: (2x - 3)/5 = 7", choices: ["16", "19", "38", "41"], answer: 1, explain: "2x - 3 = 35 → 2x = 38 → x = 19.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "easy", trapFor: [null, null, 1, null], },
  { q: "A rental company charges a flat fee of $25 plus $0.20 per mile. If a customer's bill is $61, how many miles did they drive?", choices: ["120", "150", "180", "200"], answer: 2, explain: "25 + 0.2m = 61 → 0.2m = 36 → m = 180.", pattern: "Translating a Word Problem into an Equation", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Solve for x: 6x - 9 = 2x + 15", choices: ["4", "6", "8", "10"], answer: 1, explain: "4x = 24 → x = 6.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "If 3(2x + 1) - 5 = 4x + 8, what is the value of x?", choices: ["3", "5", "7", "10"], answer: 1, explain: "6x + 3 - 5 = 4x + 8 → 6x - 2 = 4x + 8 → 2x = 10 → x = 5.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Twice a number, decreased by 7, equals 15. What is the number?", choices: ["8", "11", "14", "22"], answer: 1, explain: "2x - 7 = 15 → 2x = 22 → x = 11.", pattern: "Translating a Word Problem into an Equation", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Solve for x: -4(x - 3) = 2x", choices: ["1", "2", "3", "4"], answer: 1, explain: "-4x + 12 = 2x → 12 = 6x → x = 2.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A gym charges a $50 sign-up fee plus $30 per month. After how many months will total cost reach $260?", choices: ["6", "7", "8", "9"], answer: 1, explain: "50 + 30m = 260 → 30m = 210 → m = 7.", pattern: "Translating a Word Problem into an Equation", difficulty: "medium", trapFor: [null, null, 1, null], },
  { q: "Solve for x: 7x + 4 = 2(x + 12) - 1", choices: ["3", "3.4", "3.6", "3.8"], answer: 3, explain: "7x + 4 = 2x + 24 - 1 → 7x + 4 = 2x + 23 → 5x = 19 → x = 3.8.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "The sum of three consecutive integers is 72. What is the smallest of the three integers?", choices: ["22", "23", "24", "25"], answer: 1, explain: "Let the integers be x, x+1, x+2. Sum: 3x + 3 = 72 → 3x = 69 → x = 23.", pattern: "Translating a Word Problem into an Equation", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "If 3x + 5 = 17, what is the value of 6x + 10?", choices: ["34", "4", "24", "22"], answer: 0, explain: "6x + 10 is exactly 2(3x + 5), so it equals 2(17) = 34. No need to find x first.", pattern: "Solving for a Related Expression Without Fully Isolating x", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "If x/3 + 2 = 7, what is the value of x + 6?", choices: ["21", "15", "5", "11"], answer: 0, explain: "x/3 = 5, so x = 15 and x + 6 = 21. Stopping at x = 15 answers a different question.", pattern: "Solving for a Related Expression Without Fully Isolating x", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "If 4a - 8 = 20, what is the value of a - 2?", choices: ["5", "7", "28", "3"], answer: 0, explain: "4a - 8 = 4(a - 2), so 4(a - 2) = 20 and a - 2 = 5.", pattern: "Solving for a Related Expression Without Fully Isolating x", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "If 2(3y - 1) = 22, what is the value of 3y?", choices: ["12", "4", "11", "24"], answer: 0, explain: "Divide by 2: 3y - 1 = 11, so 3y = 12. (y itself is 4, but the question asks for 3y.)", pattern: "Solving for a Related Expression Without Fully Isolating x", difficulty: "hard", trapFor: [null, 0, 1, 2], },
  { q: "If 7 - 2x = 3, what is the value of 4x - 14?", choices: ["-6", "2", "6", "-10"], answer: 0, explain: "4x - 14 = -2(7 - 2x) = -2(3) = -6. Or solve: x = 2, so 4(2) - 14 = -6.", pattern: "Solving for a Related Expression Without Fully Isolating x", difficulty: "hard", trapFor: [null, 0, 2, null], },
  { q: "How many solutions does the equation 3(x + 4) = 3x + 12 have?", choices: ["Infinitely many", "No solution", "Exactly one", "Exactly two"], answer: 0, explain: "Distributing gives 3x + 12 = 3x + 12, which is true for every x.", pattern: "No-Solution and Infinite-Solution Equations", difficulty: "easy", trapFor: [null, 1, 0, null], },
  { q: "In the equation 4(2x - 1) = 8x + c, c is a constant. If the equation has no solution, which of the following must be true?", choices: ["c ≠ -4", "c = -4", "c = 4", "c = 0"], answer: 0, explain: "Distributing gives 8x - 4 = 8x + c, so the x-terms cancel and -4 = c remains. If c = -4 there are infinitely many solutions; any other value leaves a false statement: no solution.", pattern: "No-Solution and Infinite-Solution Equations", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "Which equation has no solution?", choices: ["2(x + 3) = 2x + 5", "2(x + 3) = 2x + 6", "2(x + 3) = 3x + 6", "2(x + 3) = x + 6"], answer: 0, explain: "2(x + 3) = 2x + 6. With 2x + 5 on the right, the x-terms cancel and 6 = 5 is false: no solution. 2x + 6 gives infinitely many; the other two have one solution each.", pattern: "No-Solution and Infinite-Solution Equations", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "Maria has $240 in savings and adds $15 each week. Jon has $420 and spends $15 each week. After how many weeks will they have the same amount of money?", choices: ["6", "12", "18", "4"], answer: 0, explain: "240 + 15w = 420 - 15w, so 30w = 180 and w = 6. Using only one person's $15 per week gives 12.", pattern: "Translating a Word Problem into an Equation", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Five less than three times a number is equal to the number increased by 11. What is the number?", choices: ["8", "-1.5", "13", "4"], answer: 0, explain: "'Five less than three times a number' is 3n - 5, so 3n - 5 = n + 11 and n = 8. Writing 5 - 3n reverses 'less than' and gives -1.5; writing 3(n - 5) gives 13.", pattern: "Translating a Word Problem into an Equation", difficulty: "hard", trapFor: [null, 0, 2, null], },
  { q: "A plumber charges a $65 service fee plus $48 per hour of work. Which equation gives the total charge C, in dollars, for h hours of work?", choices: ["C = 48h + 65", "C = 65h + 48", "C = 113h", "C = 48(h + 65)"], answer: 0, explain: "The $48 is charged per hour, so it multiplies h; the $65 fee is charged once, so it's added on its own.", pattern: "Translating a Word Problem into an Equation", difficulty: "easy", trapFor: [null, 1, null, null], },
  { q: "After a $12 discount, the price of a jacket is two-thirds of its original price. What was the original price, in dollars?", choices: ["36", "24", "18", "8"], answer: 0, explain: "p - 12 = (2/3)p, so (1/3)p = 12 and p = 36. The discounted price is $24.", pattern: "Translating a Word Problem into an Equation", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "What value of x satisfies (3/4)x - 5 = 7?", choices: ["16", "9", "8/3", "3"], answer: 0, explain: "Add 5: (3/4)x = 12. Multiply by 4/3: x = 16. Multiplying 12 by 3/4 instead gives 9.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "What value of x satisfies 0.4(x - 20) = 0.2x + 6?", choices: ["70", "130", "-10", "35"], answer: 0, explain: "0.4x - 8 = 0.2x + 6, so 0.2x = 14 and x = 70. Not distributing to the 20 gives 130; making -8 into +8 gives -10.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "hard", trapFor: [null, 1, 0, null], },
  { q: "What value of x satisfies 2x/3 + 1 = x - 4?", choices: ["15", "13", "-15", "5"], answer: 0, explain: "Multiply every term by 3: 2x + 3 = 3x - 12, so x = 15. Multiplying only some terms by 3 gives 13.", pattern: "Standard Isolate-the-Variable Equations", difficulty: "medium", trapFor: [null, 1, 0, null], },
],
  "m-linear-func": [
  { q: "A linear function has a slope of 3 and passes through (2, 5). What is f(0)?", choices: ["-1", "2", "5", "11"], answer: 0, explain: "5 = 3(2) + b → b = -1, so f(0) = -1.", pattern: "Finding Slope from Two Points or Function Values", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A taxi charges $3 plus $2 per mile. Which function models the cost C for m miles?", choices: ["C = 3m + 2", "C = 2m + 3", "C = 3m - 2", "C = 5m"], answer: 1, explain: "Base fee $3 is the constant; $2 per mile is the rate multiplied by m.", pattern: "Extracting Slope and Intercept from a Real-World Scenario", difficulty: "easy", trapFor: [0, null, null, null], },
  { q: "A linear function f has f(0) = 4 and f(3) = 13. What is the slope of f?", choices: ["2", "3", "4", "9"], answer: 1, explain: "Slope = (13 - 4) / (3 - 0) = 9/3 = 3.", pattern: "Finding Slope from Two Points or Function Values", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A plant grows at a constant rate. It is 8 inches tall after 2 weeks and 20 inches tall after 5 weeks. What is its growth rate in inches per week?", choices: ["3", "4", "5", "6"], answer: 1, explain: "Rate = (20 - 8) / (5 - 2) = 12/3 = 4 inches per week.", pattern: "Finding Slope from Two Points or Function Values", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A phone plan costs $40 per month plus $0.10 per text over the plan limit. If a customer's bill is $46.50, how many texts over the limit did they send?", choices: ["55", "60", "65", "70"], answer: 2, explain: "40 + 0.1t = 46.5 → 0.1t = 6.5 → t = 65.", pattern: "Extracting Slope and Intercept from a Real-World Scenario", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A linear function models a car's value depreciating from $28,000 at year 0 to $16,000 at year 4. What is the annual rate of depreciation?", choices: ["$2,000", "$3,000", "$4,000", "$5,000"], answer: 1, explain: "(28000 - 16000) / 4 = 12000 / 4 = 3000 dollars per year.", pattern: "Finding Slope from Two Points or Function Values", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A linear function f has slope -2 and passes through (4, 1). What is f(1)?", choices: ["5", "7", "9", "11"], answer: 1, explain: "Using point-slope: f(1) = 1 + (-2)(1 - 4) = 1 + 6 = 7.", pattern: "Finding Slope from Two Points or Function Values", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A water tank starts with 500 gallons and drains at 25 gallons per minute. Which function models the volume V after t minutes?", choices: ["V = 500 + 25t", "V = 500 - 25t", "V = 25t - 500", "V = 25(500 - t)"], answer: 1, explain: "Draining means volume decreases over time, so the correct model subtracts 25t from the starting volume.", pattern: "Extracting Slope and Intercept from a Real-World Scenario", difficulty: "easy", trapFor: [1, null, null, null], },
  { q: "A linear function passes through (0, -3) and (6, 9). What is its equation?", choices: ["y = 2x - 3", "y = 2x + 3", "y = -2x - 3", "y = 3x - 3"], answer: 0, explain: "Slope = (9 - (-3))/(6 - 0) = 12/6 = 2; y-intercept is -3, so y = 2x - 3.", pattern: "Finding Slope from Two Points or Function Values", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A membership costs $15 to join plus $4 per visit. After how many visits does the total cost reach $47?", choices: ["6", "7", "8", "9"], answer: 2, explain: "15 + 4v = 47 → 4v = 32 → v = 8.", pattern: "Extracting Slope and Intercept from a Real-World Scenario", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A candle is 10 inches tall and burns at a rate of 0.5 inches per hour. Which function models its height h after t hours?", choices: ["h = 10 + 0.5t", "h = 10 - 0.5t", "h = 0.5t - 10", "h = 0.5(10 - t)"], answer: 1, explain: "The candle's height decreases over time, so the function must subtract 0.5t from the starting height of 10.", pattern: "Extracting Slope and Intercept from a Real-World Scenario", difficulty: "easy", trapFor: [1, null, null, null], },
  { q: "A delivery service charges a $6 base fee plus $1.50 per mile. If a delivery costs $18, how many miles was it?", choices: ["6", "7", "8", "9"], answer: 2, explain: "6 + 1.5m = 18 → 1.5m = 12 → m = 8.", pattern: "Extracting Slope and Intercept from a Real-World Scenario", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "If f(x) = 4x - 9, what is the value of f(-3)?", choices: ["-21", "3", "-3", "21"], answer: 0, explain: "f(-3) = 4(-3) - 9 = -12 - 9 = -21. Dropping the negative sign on -3 gives 3.", pattern: "Evaluating a Function and Solving for Input Given Output", difficulty: "easy", trapFor: [null, 1, null, null], },
  { q: "The function g is defined by g(x) = 5x + 2. If g(k) = 37, what is the value of k?", choices: ["7", "187", "39", "5"], answer: 0, explain: "g(k) = 37 is an output: 5k + 2 = 37, so k = 7. Plugging 37 in as the input gives g(37) = 187.", pattern: "Evaluating a Function and Solving for Input Given Output", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "If f(x) = 3x - 4, which expression is equivalent to f(x + 2)?", choices: ["3x + 2", "3x - 2", "3x + 6", "5x - 4"], answer: 0, explain: "Replace every x with (x + 2): 3(x + 2) - 4 = 3x + 6 - 4 = 3x + 2. Adding 2 without multiplying it by 3 gives 3x - 2.", pattern: "Evaluating a Function and Solving for Input Given Output", difficulty: "hard", trapFor: [null, 2, 2, null], },
  { q: "A linear function f satisfies f(2) = 11 and f(6) = 23. What is the value of f(10)?", choices: ["35", "3", "31", "47"], answer: 0, explain: "The slope is (23 - 11)/(6 - 2) = 3, so each increase of 4 in x adds 12: f(10) = 23 + 12 = 35. The slope itself is 3.", pattern: "Finding Slope from Two Points or Function Values", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "For x = 1, 3, and 5, a linear function takes the values 7, 13, and 19, respectively. Which equation defines the function?", choices: ["y = 3x + 4", "y = 6x + 1", "y = (1/3)x + 20/3", "y = 3x + 7"], answer: 0, explain: "y rises by 6 each time x rises by 2, so the slope is 6/2 = 3. Then 7 = 3(1) + b gives b = 4. Using 6 as the slope ignores that x goes up by 2, not 1.", pattern: "Finding Slope from Two Points or Function Values", difficulty: "hard", trapFor: [null, null, 0, null], },
  { q: "A phone battery is at 85% charge and loses 4 percentage points of charge per hour of use. Which function gives the charge C(h), in percent, after h hours of use?", choices: ["C(h) = 85 - 4h", "C(h) = 85 + 4h", "C(h) = 4 - 85h", "C(h) = 81h"], answer: 0, explain: "Start at 85 and subtract 4 for each hour: 85 - 4h. The rate term needs a negative sign because the charge is decreasing.", pattern: "Extracting Slope and Intercept from a Real-World Scenario", difficulty: "easy", trapFor: [null, 1, 0, null], },
  { q: "The function P(t) = 18t + 240 gives the total number of pages a student has read t days after starting a summer reading log. What is the best interpretation of 18 in this context?", choices: ["The student reads 18 pages per day.", "The student had read 18 pages when the log began.", "The student reads for 18 days.", "The student will finish the log in 18 days."], answer: 0, explain: "18 multiplies t, the number of days, so it's the rate: pages per day. The 240 is the number already read when the log began.", pattern: "Extracting Slope and Intercept from a Real-World Scenario", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "A taxi ride costs $2.50 plus $1.75 per mile. A rider has $20. What is the greatest whole number of miles the rider can travel?", choices: ["10", "11", "12", "9"], answer: 0, explain: "2.50 + 1.75m ≤ 20, so 1.75m ≤ 17.50 and m ≤ 10. Ignoring the $2.50 fee gives 20/1.75 ≈ 11.4, or 11 miles.", pattern: "Extracting Slope and Intercept from a Real-World Scenario", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "A bamboo plant grows at a constant rate. It was 30 centimeters tall on day 4 and 66 centimeters tall on day 10. How tall was it on day 0, in centimeters?", choices: ["6", "30", "36", "12"], answer: 0, explain: "The rate is (66 - 30)/(10 - 4) = 6 cm per day. Four days before day 4 it was 30 - 4(6) = 6 cm.", pattern: "Finding Slope from Two Points or Function Values", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "If h(x) = -2x + 5, what is the value of h(-4)?", choices: ["13", "-3", "3", "-13"], answer: 0, explain: "h(-4) = -2(-4) + 5 = 8 + 5 = 13. A negative times a negative is positive; treating -2(-4) as -8 gives -3.", pattern: "Evaluating a Function and Solving for Input Given Output", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "The function f is defined by f(x) = (1/2)x - 3. For what value of x is f(x) = 5?", choices: ["16", "-0.5", "4", "1"], answer: 0, explain: "Set the output to 5: (1/2)x - 3 = 5, so (1/2)x = 8 and x = 16. f(5) = -0.5 answers a different question.", pattern: "Evaluating a Function and Solving for Input Given Output", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "The graph of a linear function f in the xy-plane passes through (0, -6) and (3, 0). What is the value of f(5)?", choices: ["4", "-6", "3", "16"], answer: 0, explain: "The slope is (0 - (-6))/(3 - 0) = 2 and the y-intercept is -6, so f(5) = 2(5) - 6 = 4. The 3 is the x-intercept, and -6 is the y-intercept, not f(5).", pattern: "Reading Slope and Intercept Directly from a Graph", difficulty: "medium", trapFor: [null, 2, 2, null], },
  { q: "A line in the xy-plane has an x-intercept of 4 and a y-intercept of -2. What is the slope of the line?", choices: ["1/2", "2", "-1/2", "-2"], answer: 0, explain: "The line passes through (4, 0) and (0, -2): slope = (0 - (-2))/(4 - 0) = 2/4 = 1/2. Swapping rise and run gives 2.", pattern: "Reading Slope and Intercept Directly from a Graph", difficulty: "hard", trapFor: [null, 0, null, 2], },
  { q: "Company A charges $40 plus $0.15 per mile to rent a truck. Company B charges $25 plus $0.25 per mile. For how many miles will the two companies charge the same amount?", choices: ["150", "100", "60", "37.5"], answer: 0, explain: "40 + 0.15m = 25 + 0.25m, so 15 = 0.10m and m = 150.", pattern: "Extracting Slope and Intercept from a Real-World Scenario", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "If f(x) = 2x + 1 and f(a) = 9, what is the value of f(2a)?", choices: ["17", "18", "8", "19"], answer: 0, explain: "f(a) = 9 means 2a + 1 = 9, so a = 4 and f(2a) = f(8) = 17. Doubling f(a) gives 18, and f(9) = 19 uses the output as an input.", pattern: "Evaluating a Function and Solving for Input Given Output", difficulty: "hard", trapFor: [null, 2, null, 0], },
],
  "m-linear-eq-2var": [
  { q: "What is the slope of the line 4x + 2y = 8?", choices: ["-2", "2", "4", "-4"], answer: 0, explain: "Solve for y: y = -2x + 4, so slope = -2.", pattern: "Extracting Slope from Standard Form", difficulty: "easy", trapFor: [null, 1, 0, 0], },
  { q: "Which line is perpendicular to y = (1/2)x + 3?", choices: ["y = (1/2)x - 1", "y = -2x + 5", "y = 2x + 1", "y = -(1/2)x + 5"], answer: 1, explain: "Perpendicular slopes are negative reciprocals; the reciprocal of 1/2 negated is -2.", pattern: "Parallel and Perpendicular Line Relationships", difficulty: "medium", trapFor: [1, null, 0, null], },
  { q: "What is the slope of the line passing through (1, 4) and (5, 12)?", choices: ["1", "2", "3", "4"], answer: 1, explain: "Slope = (12 - 4)/(5 - 1) = 8/4 = 2.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Which line is parallel to 3x - y = 6?", choices: ["y = 3x + 1", "y = -3x + 1", "y = (1/3)x + 1", "y = -(1/3)x + 1"], answer: 0, explain: "3x - y = 6 rearranges to y = 3x - 6, so a parallel line must also have slope 3.", pattern: "Parallel and Perpendicular Line Relationships", difficulty: "medium", trapFor: [null, null, null, 1], },
  { q: "What is the x-intercept of the line 2x + 5y = 20?", choices: ["4", "8", "10", "20"], answer: 2, explain: "Set y = 0: 2x = 20 → x = 10.", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "What is the y-intercept of the line 6x - 3y = 9?", choices: ["-3", "-2", "3", "2"], answer: 0, explain: "Set x = 0: -3y = 9 → y = -3.", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Which equation represents a line with slope -3 passing through (2, 1)?", choices: ["y = -3x + 7", "y = -3x - 5", "y = 3x - 5", "y = -3x + 1"], answer: 0, explain: "Using point-slope: 1 = -3(2) + b → b = 7, so y = -3x + 7.", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Two lines are perpendicular. If one has a slope of -4, what is the slope of the other?", choices: ["4", "-4", "1/4", "-1/4"], answer: 2, explain: "Perpendicular slopes are negative reciprocals: the reciprocal of -4 negated is 1/4.", pattern: "Parallel and Perpendicular Line Relationships", difficulty: "medium", trapFor: [null, 1, null, 0], },
  { q: "What is the slope of a line parallel to the x-axis?", choices: ["0", "1", "Undefined", "-1"], answer: 0, explain: "A horizontal line has a slope of 0.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Which line has an undefined slope?", choices: ["y = 5", "x = 5", "y = 5x", "y = x + 5"], answer: 1, explain: "A vertical line, x = constant, has an undefined slope.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "What is the slope of the line 9x + 3y = 15?", choices: ["-3", "3", "-9", "5"], answer: 0, explain: "Solve for y: y = -3x + 5, so slope = -3.", pattern: "Extracting Slope from Standard Form", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "Which point lies on the line y = 4x - 7?", choices: ["(1, -3)", "(2, 2)", "(0, 7)", "(3, 4)"], answer: 0, explain: "At x = 1: y = 4(1) - 7 = -3, matching the point (1, -3).", pattern: "Solving for One Variable Given the Other's Value", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "What is the slope of the line 3x - 4y = 12 in the xy-plane?", choices: ["3/4", "-3/4", "3", "-3"], answer: 0, explain: "Solve for y: -4y = -3x + 12, so y = (3/4)x - 3. The slope is 3/4. Reading the 3 straight off standard form gives the wrong value.", pattern: "Extracting Slope from Standard Form", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "In the xy-plane, the line 2x + ky = 10, where k is a constant, has a slope of -1/3. What is the value of k?", choices: ["6", "-6", "3", "2/3"], answer: 0, explain: "Solving for y gives slope -2/k. Setting -2/k = -1/3 gives k = 6.", pattern: "Extracting Slope from Standard Form", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "What is the y-intercept of the graph of 5x - 2y = 14 in the xy-plane?", choices: ["(0, -7)", "(0, 7)", "(14/5, 0)", "(0, -5/2)"], answer: 0, explain: "Set x = 0: -2y = 14, so y = -7. (14/5, 0) is the x-intercept.", pattern: "Extracting Slope from Standard Form", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "Line k passes through (0, 4) and is parallel to the line y = -3x + 1. Which equation defines line k?", choices: ["y = -3x + 4", "y = (1/3)x + 4", "y = 3x + 4", "y = -3x + 1"], answer: 0, explain: "Parallel lines have the same slope, -3, and the line crosses the y-axis at 4: y = -3x + 4. The last choice is the original line itself.", pattern: "Parallel and Perpendicular Line Relationships", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "Line m passes through the origin and is perpendicular to the line 2x + 5y = 7. Which equation defines line m?", choices: ["y = (5/2)x", "y = -(5/2)x", "y = -(2/5)x", "y = (2/5)x"], answer: 0, explain: "2x + 5y = 7 has slope -2/5. A perpendicular slope is the negative reciprocal: 5/2. Flipping the fraction without changing the sign gives -5/2.", pattern: "Parallel and Perpendicular Line Relationships", difficulty: "hard", trapFor: [null, 0, 1, null], },
  { q: "Lines ℓ and n are perpendicular. Line ℓ passes through (1, 2) and (4, 8). What is the slope of line n?", choices: ["-1/2", "1/2", "-2", "2"], answer: 0, explain: "Line ℓ has slope (8 - 2)/(4 - 1) = 2, so line n has slope -1/2.", pattern: "Parallel and Perpendicular Line Relationships", difficulty: "medium", trapFor: [null, 0, null, 1], },
  { q: "A school cafeteria's weekly lunch purchases satisfy 3.5s + 5t = 1,400, where s is the number of student lunches and t is the number of teacher lunches. What does 5 represent in this context?", choices: ["The cost, in dollars, of one teacher lunch", "The cost, in dollars, of one student lunch", "The total weekly lunch budget, in dollars", "The number of teacher lunches purchased each week"], answer: 0, explain: "5 multiplies t, the number of teacher lunches, so it's the price per teacher lunch. 1,400 is the total budget.", pattern: "Interpreting a Constant or Coefficient in a Real-World Equation", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "The equation y = 900 - 60x gives the distance y, in miles, a train still has to travel x hours after leaving the station. What does 900 represent?", choices: ["The total length of the trip, in miles", "The train's speed, in miles per hour", "The number of hours the trip takes", "The distance the train travels in 60 hours"], answer: 0, explain: "When x = 0 the train hasn't left yet, so y = 900 is the whole trip. 60 is the speed.", pattern: "Interpreting a Constant or Coefficient in a Real-World Equation", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "The equation y = 900 - 60x gives the distance y, in miles, a train still has to travel x hours after leaving the station. What is the x-intercept of the graph, and what does it represent?", choices: ["15; the number of hours the whole trip takes", "900; the total length of the trip, in miles", "60; the train's speed, in miles per hour", "15; the train's speed, in miles per hour"], answer: 0, explain: "Set y = 0: 900 = 60x, so x = 15. The distance left reaches 0 after 15 hours, when the trip ends.", pattern: "Interpreting a Constant or Coefficient in a Real-World Equation", difficulty: "hard", trapFor: [null, null, 0, 2], },
  { q: "A florist sells roses for $3 each and tulips for $2 each. She earns $250 from selling r roses and t tulips. Which equation represents this situation?", choices: ["3r + 2t = 250", "2r + 3t = 250", "5(r + t) = 250", "r + t = 250"], answer: 0, explain: "Each rose brings $3 and each tulip $2, so the earnings are 3r + 2t. Swapping the prices is the most common error.", pattern: "Translating a Word Scenario into a Two-Variable Equation", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "A gym charges a one-time $60 fee plus $25 per month. Over m months, a member has also bought p protein bars at $2.50 each and spent $235 in total. Which equation represents this situation?", choices: ["60 + 25m + 2.50p = 235", "60m + 25 + 2.50p = 235", "85m + 2.50p = 235", "60 + 25m + 2.50 = 235p"], answer: 0, explain: "The $60 fee is paid once, so it stands alone; $25 is per month and $2.50 is per bar. Multiplying the one-time fee by m is the classic mistake.", pattern: "Translating a Word Scenario into a Two-Variable Equation", difficulty: "hard", trapFor: [null, 1, 1, null], },
  { q: "A chemist mixes x liters of a 10% acid solution with y liters of a 30% acid solution to make 20 liters of a 25% acid solution. Which system of equations represents this situation?", choices: ["x + y = 20 and 0.10x + 0.30y = 5", "x + y = 20 and 0.10x + 0.30y = 0.25", "x + y = 5 and 0.10x + 0.30y = 20", "x + y = 20 and 0.10x + 0.30y = 25"], answer: 0, explain: "The volumes add to 20 liters. The acid adds too: 25% of 20 liters is 5 liters of acid, so 0.10x + 0.30y = 5.", pattern: "Translating a Word Scenario into a Two-Variable Equation", difficulty: "hard", trapFor: [null, 2, 2, null], },
  { q: "The equation 4x - 3y = 24 relates x and y. What is the value of y when x = 3?", choices: ["-4", "4", "8.25", "12"], answer: 0, explain: "Substitute x = 3: 12 - 3y = 24, so -3y = 12 and y = -4. Substituting 3 for y instead gives x = 8.25.", pattern: "Solving for One Variable Given the Other's Value", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "If (a, 7) is a solution to the equation 3x + 2y = 29, what is the value of a?", choices: ["5", "4", "43/3", "7"], answer: 0, explain: "The point's y-value is 7: 3a + 2(7) = 29, so 3a = 15 and a = 5. Putting 7 in for x gives 4.", pattern: "Solving for One Variable Given the Other's Value", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "In the equation 2x + 5y = 40, y = x - 6. What is the value of x?", choices: ["10", "4", "46/7", "34/7"], answer: 0, explain: "Substitute the whole expression: 2x + 5(x - 6) = 40, so 7x - 30 = 40 and x = 10. Multiplying only the x by 5 gives 46/7.", pattern: "Solving for One Variable Given the Other's Value", difficulty: "hard", trapFor: [null, null, 2, 1], },
],
  "m-systems": [
  { q: "How many solutions does this system have? y = 2x + 1 and y = 2x - 3", choices: ["No solution", "One solution", "Infinite solutions", "Cannot be determined"], answer: 0, explain: "Same slope, different y-intercepts means the lines are parallel and never intersect.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Solve the system: x + y = 10, x - y = 2. What is x?", choices: ["4", "6", "8", "12"], answer: 1, explain: "Adding the equations: 2x = 12, so x = 6.", pattern: "Solving for a Specific Value via Elimination", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Solve the system: 2x + y = 11, x - y = 1. What is y?", choices: ["2", "3", "4", "5"], answer: 1, explain: "Adding the equations gives 3x = 12, so x = 4. Then from x - y = 1: y = x - 1 = 3.", pattern: "Solving for a Specific Value via Elimination", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "How many solutions does the system y = 3x + 2 and y = 3x + 2 have (the same equation written twice)?", choices: ["No solution", "Exactly one solution", "Infinitely many solutions", "Exactly two solutions"], answer: 2, explain: "Identical equations represent the same line, so every point on it is a solution — infinitely many.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Solve the system: 3x - 2y = 4, x + 2y = 8. What is x?", choices: ["2", "3", "4", "5"], answer: 1, explain: "Adding the equations: 4x = 12, so x = 3.", pattern: "Solving for a Specific Value via Elimination", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A system has one equation with slope 2 and another with slope -1. How many solutions does the system have?", choices: ["No solution", "Exactly one solution", "Infinitely many solutions", "Cannot be determined without intercepts"], answer: 1, explain: "Different slopes guarantee the lines intersect at exactly one point, regardless of intercepts.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Solve the system: y = x + 3, 2x + y = 15. What is x?", choices: ["2", "3", "4", "5"], answer: 2, explain: "Substitute: 2x + (x + 3) = 15 → 3x + 3 = 15 → 3x = 12 → x = 4.", pattern: "Solving for a Specific Value via Elimination", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A system has two equations representing lines with the same slope and the same y-intercept. How many solutions does the system have?", choices: ["No solution", "Exactly one solution", "Infinitely many solutions", "Exactly two solutions"], answer: 2, explain: "Identical slope and intercept means the lines are the same line, so every point is a solution.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Solve the system: 4x + 3y = 18, x = 3. What is y?", choices: ["1", "2", "3", "4"], answer: 1, explain: "Substitute x = 3: 12 + 3y = 18 → 3y = 6 → y = 2.", pattern: "Solving for a Specific Value via Elimination", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A concert venue sells two ticket types. Let a = adult tickets and c = child tickets. If a + c = 200 and 25a + 15c = 4200, how many adult tickets were sold?", choices: ["100", "120", "140", "160"], answer: 1, explain: "From a + c = 200, c = 200 - a. Substitute: 25a + 15(200 - a) = 4200 → 10a + 3000 = 4200 → 10a = 1200 → a = 120.", pattern: "Solving for a Specific Value via Elimination", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Solve the system: y = -x + 6, y = 2x - 3. What is the x-coordinate of the solution?", choices: ["1", "2", "3", "4"], answer: 2, explain: "Set equal: -x + 6 = 2x - 3 → 9 = 3x → x = 3.", pattern: "Solving for a Specific Value via Elimination", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A system of two linear equations has no solution. What must be true about the two lines?", choices: ["They have the same slope and different y-intercepts.", "They have different slopes.", "They have the same slope and the same y-intercept.", "They intersect at exactly one point."], answer: 0, explain: "Parallel lines (same slope, different intercepts) never intersect, giving no solution.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "3x + 2y = 16\n3x - 2y = 8\n\nWhat is the value of x in the solution to the system of equations above?", choices: ["4", "2", "8/3", "6"], answer: 0, explain: "Adding the equations eliminates y: 6x = 24, so x = 4.", pattern: "Solving for a Specific Value via Elimination", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "2x + 3y = 17\n3x + 2y = 18\n\nIf (x, y) is the solution to the system above, what is the value of x + y?", choices: ["7", "35", "4", "1"], answer: 0, explain: "Adding the equations gives 5x + 5y = 35, so x + y = 7 with no need to find x and y. Subtracting gives x - y = 1 instead.", pattern: "Solving for a Specific Value via Elimination", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "5x - 3y = 11\n2x - 3y = 2\n\nWhat is the value of y in the solution to the system above?", choices: ["4/3", "3", "-4/3", "13/3"], answer: 0, explain: "Subtracting the second equation from the first gives 3x = 9, so x = 3. Then 2(3) - 3y = 2, so y = 4/3.", pattern: "Solving for a Specific Value via Elimination", difficulty: "hard", trapFor: [null, null, 1, null], },
  { q: "A theater sold 300 tickets. Adult tickets cost $12 and student tickets cost $7, and total sales were $2,900. How many student tickets were sold?", choices: ["140", "160", "150", "100"], answer: 0, explain: "a + s = 300 and 12a + 7s = 2,900. Substituting a = 300 - s gives 3,600 - 5s = 2,900, so s = 140. 160 is the number of adult tickets.", pattern: "Solving for a Specific Value via Elimination", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A coffee shop sells small drinks for $3 and large drinks for $5. One morning it sold 70 drinks for a total of $270. How many more small drinks than large drinks did it sell?", choices: ["10", "40", "30", "70"], answer: 0, explain: "s + l = 70 and 3s + 5l = 270, so 210 + 2l = 270, l = 30 and s = 40. The difference is 10.", pattern: "Solving for a Specific Value via Elimination", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "4x - y = 10\n2x + 3y = 12\n\nIf (x, y) is the solution to the system above, what is the value of 6x + 2y?", choices: ["22", "5", "-2", "18"], answer: 0, explain: "Adding the equations gives exactly 6x + 2y = 22. Subtracting instead gives 2x - 4y = -2.", pattern: "Solving for a Specific Value via Elimination", difficulty: "hard", trapFor: [null, null, 1, null], },
  { q: "0.5x + 0.2y = 4\nx - 0.2y = 5\n\nWhat is the value of x in the solution to the system above?", choices: ["6", "5", "9", "18"], answer: 0, explain: "Adding the equations eliminates y: 1.5x = 9, so x = 6.", pattern: "Solving for a Specific Value via Elimination", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "The sum of two numbers is 58 and their difference is 14. What is the larger number?", choices: ["36", "22", "44", "29"], answer: 0, explain: "x + y = 58 and x - y = 14. Adding gives 2x = 72, so x = 36. 22 is the smaller number.", pattern: "Solving for a Specific Value via Elimination", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "How many solutions does the system 2x - y = 5 and 4x - 2y = 10 have?", choices: ["Infinitely many", "Exactly one", "No solution", "Exactly two"], answer: 0, explain: "The second equation is the first multiplied by 2, so both describe the same line.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "3x + ky = 9\n6x + 4y = 18\n\nIn the system above, k is a constant. For what value of k does the system have infinitely many solutions?", choices: ["2", "4", "-2", "1/2"], answer: 0, explain: "The second equation is 2 times the first when every coefficient doubles: 2k = 4, so k = 2. Copying the 4 across compares the equations without scaling them.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "y = 4x + 3\n8x - 2y = c\n\nIn the system above, c is a constant. For what value of c does the system have infinitely many solutions?", choices: ["-6", "6", "3", "-3"], answer: 0, explain: "Substituting y: 8x - 2(4x + 3) = c, so -6 = c. With c = -6 every point on the line works; any other c gives no solution.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "Which of the following systems of equations has no solution?", choices: ["y = 2x + 1 and y = 2x - 4", "y = 2x + 1 and y = -2x + 1", "y = 2x + 1 and 4x - 2y = -2", "y = 2x + 1 and 2y = 4x + 2"], answer: 0, explain: "Same slope and different y-intercepts means parallel lines that never meet. The last two choices are the same line as y = 2x + 1 rewritten, so they have infinitely many solutions.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "medium", trapFor: [null, null, 1, 1], },
  { q: "How many solutions does the system x + 3y = 6 and 2x + 6y = 15 have?", choices: ["No solution", "Infinitely many", "Exactly one", "Exactly two"], answer: 0, explain: "In slope-intercept form, y = -x/3 + 2 and y = -x/3 + 2.5: same slope, different intercepts, so the lines are parallel. Doubling the first equation gives 2x + 6y = 12, not 15, so the lines never meet.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "A system of two linear equations has exactly one solution. Which statement must be true?", choices: ["The lines have different slopes.", "The lines have the same slope and different y-intercepts.", "The lines have the same slope and the same y-intercept.", "The lines have the same y-intercept."], answer: 0, explain: "Lines cross at exactly one point only when their slopes differ. Equal slopes give either no solution or infinitely many.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "2x + by = 7\n4x + 10y = 14\n\nIn the system above, b is a constant. If the system has infinitely many solutions, what is the value of b?", choices: ["5", "10", "2.5", "7"], answer: 0, explain: "Doubling the first equation must give the second: 2b = 10, so b = 5.", pattern: "Determining the Number of Solutions Without Fully Solving", difficulty: "medium", trapFor: [null, 1, null, null], },
],
  "m-linear-ineq": [
  { q: "Solve: -3x + 6 > 0", choices: ["x > 2", "x < 2", "x > -2", "x < -2"], answer: 1, explain: "-3x > -6 → dividing by -3 flips the inequality → x < 2.", pattern: "Solving with the Sign-Flip Rule", difficulty: "easy", trapFor: [0, null, null, null], },
  { q: "Which point satisfies y ≤ 2x - 1?", choices: ["(0, 0)", "(1, 5)", "(0, -2)", "(2, 5)"], answer: 2, explain: "At (0,-2): -2 ≤ 2(0)-1 = -1, which is true.", pattern: "Matching a Graph, Table, or Point to an Inequality or System", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Solve: 5x + 3 ≤ 2x + 18", choices: ["x ≤ 5", "x ≥ 5", "x ≤ 7", "x ≥ 7"], answer: 0, explain: "3x ≤ 15 → x ≤ 5.", pattern: "Solving with the Sign-Flip Rule", difficulty: "easy", trapFor: [null, 1, null, null], },
  { q: "A parking garage charges $4 for the first hour and $2 for each additional hour. What is the maximum number of whole hours a driver can park while keeping the total charge at or below $20?", choices: ["7", "8", "9", "10"], answer: 2, explain: "Total cost = 4 + 2(h - 1) ≤ 20 → 2(h-1) ≤ 16 → h - 1 ≤ 8 → h ≤ 9.", pattern: "Word Problems with Inequality Language", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Solve: -2(x - 3) < 10", choices: ["x > -2", "x < -2", "x > 8", "x < 8"], answer: 0, explain: "-2x + 6 < 10 → -2x < 4 → dividing by -2 flips the inequality → x > -2.", pattern: "Solving with the Sign-Flip Rule", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "Which inequality represents 'the sum of a number and 8 is at most 20'?", choices: ["x + 8 ≥ 20", "x + 8 ≤ 20", "x + 8 > 20", "x + 8 < 20"], answer: 1, explain: "'At most' translates to ≤, so x + 8 ≤ 20.", pattern: "Word Problems with Inequality Language", difficulty: "easy", trapFor: [null, null, null, 0], },
  { q: "Solve: 4x - 7 ≥ 9", choices: ["x ≥ 4", "x ≤ 4", "x ≥ 0.5", "x ≤ 0.5"], answer: 0, explain: "4x ≥ 16 → x ≥ 4.", pattern: "Solving with the Sign-Flip Rule", difficulty: "easy", trapFor: [null, 1, null, null], },
  { q: "A student needs an average of at least 90 across 4 tests to earn an A. Scores so far are 85, 92, 88. What is the minimum score needed on the 4th test?", choices: ["90", "93", "95", "97"], answer: 2, explain: "(85+92+88+x)/4 ≥ 90 → 265 + x ≥ 360 → x ≥ 95.", pattern: "Word Problems with Inequality Language", difficulty: "hard", trapFor: [1, null, null, null], },
  { q: "Which point satisfies the inequality 3x + 2y < 12?", choices: ["(4, 0)", "(2, 2)", "(0, 6)", "(4, 1)"], answer: 1, explain: "At (2,2): 3(2)+2(2) = 10 < 12, which is true.", pattern: "Matching a Graph, Table, or Point to an Inequality or System", difficulty: "medium", trapFor: [1, null, 1, null], },
  { q: "Solve: -x/2 + 3 ≥ 1", choices: ["x ≤ 4", "x ≥ 4", "x ≤ -4", "x ≥ -4"], answer: 0, explain: "-x/2 ≥ -2 → multiply by -2 and flip: x ≤ 4.", pattern: "Solving with the Sign-Flip Rule", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "A vending machine only accepts orders under $10. Snacks cost $1.25 each. What is the maximum number of snacks that can be purchased?", choices: ["6", "7", "8", "9"], answer: 1, explain: "1.25n < 10 → n < 8. Since n must be a whole number strictly less than 8, the maximum is 7 (buying 8 would cost exactly $10, not under it).", pattern: "Word Problems with Inequality Language", difficulty: "medium", trapFor: [null, null, 0, null], },
  { q: "Solve: 2x + 5 > 4x - 3", choices: ["x < 4", "x > 4", "x < -4", "x > -4"], answer: 0, explain: "5 + 3 > 4x - 2x → 8 > 2x → x < 4.", pattern: "Solving with the Sign-Flip Rule", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "Which inequality is equivalent to -4x + 7 ≥ 23?", choices: ["x ≤ -4", "x ≥ -4", "x ≤ 4", "x ≥ -7.5"], answer: 0, explain: "Subtract 7: -4x ≥ 16. Dividing by -4 flips the sign: x ≤ -4.", pattern: "Solving with the Sign-Flip Rule", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "Which inequality is equivalent to (3 - 2x)/5 < 1?", choices: ["x > -1", "x < -1", "x > 1", "x < 1"], answer: 0, explain: "Multiply by 5: 3 - 2x < 5, so -2x < 2. Dividing by -2 flips the sign: x > -1.", pattern: "Solving with the Sign-Flip Rule", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "Which inequality is equivalent to x - 9 > -4?", choices: ["x > 5", "x < 5", "x > -13", "x < -13"], answer: 0, explain: "Add 9 to both sides: x > 5. Adding never flips the sign; only multiplying or dividing by a negative does.", pattern: "Solving with the Sign-Flip Rule", difficulty: "easy", trapFor: [null, 1, null, null], },
  { q: "Which values of x satisfy -3 < 2x + 5 ≤ 11?", choices: ["-4 < x ≤ 3", "-4 ≤ x < 3", "-1 < x ≤ 8", "-3 < x ≤ 6"], answer: 0, explain: "Subtract 5 from all three parts: -8 < 2x ≤ 6. Divide by 2: -4 < x ≤ 3. The strict and non-strict ends stay where they were.", pattern: "Solving with the Sign-Flip Rule", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "Which inequality is equivalent to 3(x - 2) ≥ 5x + 4?", choices: ["x ≤ -5", "x ≥ -5", "x ≤ 5", "x ≥ 5"], answer: 0, explain: "3x - 6 ≥ 5x + 4, so -2x ≥ 10. Dividing by -2 flips the sign: x ≤ -5.", pattern: "Solving with the Sign-Flip Rule", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "A club needs at least $600 for a trip. It has raised $180 so far and earns $15 for each car it washes. Which inequality represents the number of cars, c, the club must wash to reach its goal?", choices: ["180 + 15c ≥ 600", "180 + 15c > 600", "15c ≥ 600", "180c + 15 ≥ 600"], answer: 0, explain: "'At least $600' includes exactly $600, so the sign is ≥. The $180 already raised is added once; $15 is earned per car.", pattern: "Word Problems with Inequality Language", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "A club needs at least $600 for a trip. It has raised $180 so far and earns $15 for each car it washes. What is the minimum number of cars the club must wash?", choices: ["28", "29", "40", "52"], answer: 0, explain: "180 + 15c ≥ 600, so 15c ≥ 420 and c ≥ 28. Exactly 28 cars reaches $600, which counts as 'at least.' Ignoring the $180 gives 40.", pattern: "Word Problems with Inequality Language", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "Kai's scores on four quizzes are 78, 85, 90, and 82. What is the lowest score on a fifth quiz that will give Kai an average of at least 85 on all five quizzes?", choices: ["90", "85", "89", "92"], answer: 0, explain: "The five scores must total at least 5(85) = 425. The first four total 335, so the fifth must be at least 90. Scoring just 85 keeps the average below 85.", pattern: "Word Problems with Inequality Language", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "An elevator can carry at most 1,500 pounds. A worker who weighs 180 pounds rides with boxes that weigh 45 pounds each. What is the greatest number of boxes the worker can bring?", choices: ["29", "30", "33", "28"], answer: 0, explain: "180 + 45b ≤ 1,500, so b ≤ 29.3, and the greatest whole number of boxes is 29. Rounding up to 30 goes over the limit; ignoring the worker's weight gives 33.", pattern: "Word Problems with Inequality Language", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A phone plan costs $35 per month plus $0.05 per text message. A student wants to spend less than $50 in a month. What is the greatest number of text messages the student can send?", choices: ["299", "300", "1,000", "700"], answer: 0, explain: "35 + 0.05t < 50, so t < 300. 'Less than' excludes exactly $50, so 300 texts is too many and the answer is 299.", pattern: "Word Problems with Inequality Language", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "Which point (x, y) is a solution to the inequality y > 3x - 2?", choices: ["(1, 2)", "(2, 4)", "(0, -3)", "(3, 6)"], answer: 0, explain: "(1, 2): 2 > 1 ✓. (2, 4) lands exactly on the boundary (4 > 4 is false), and the other two fall below the line.", pattern: "Matching a Graph, Table, or Point to an Inequality or System", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "Which point (x, y) is a solution to the system of inequalities y ≤ x + 4 and y > -2x + 1?", choices: ["(1, 3)", "(0, 0)", "(-2, 3)", "(2, 7)"], answer: 0, explain: "(1, 3) satisfies both: 3 ≤ 5 and 3 > -1. (0, 0) satisfies only the first, and (2, 7) only the second. A solution must satisfy every inequality.", pattern: "Matching a Graph, Table, or Point to an Inequality or System", difficulty: "hard", trapFor: [null, 2, null, 2], },
  { q: "Which set of points consists only of solutions to y < 2x + 1?", choices: ["(0, 0), (1, 2), (2, 4)", "(0, 0), (1, 3), (2, 4)", "(0, 2), (1, 2), (2, 4)", "(1, 1), (2, 6), (3, 5)"], answer: 0, explain: "Check every point: 0 < 1, 2 < 3 and 4 < 5 all hold. Each other set contains one point that fails, such as (1, 3), where 3 < 3 is false.", pattern: "Matching a Graph, Table, or Point to an Inequality or System", difficulty: "hard", trapFor: [null, 0, 0, 0], },
  { q: "The graph of an inequality in the xy-plane shows a dashed line through (0, 3) and (3, 0), with the region above the line shaded. Which inequality does the graph represent?", choices: ["y > -x + 3", "y ≥ -x + 3", "y < -x + 3", "y ≤ -x + 3"], answer: 0, explain: "The line through (0, 3) and (3, 0) is y = -x + 3. Shading above means y is greater, and a dashed line means points on the line aren't included, so the sign is strict.", pattern: "Matching a Graph, Table, or Point to an Inequality or System", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Which system of inequalities is satisfied by the point (3, -1)?", choices: ["y < x - 3 and y > -2", "y > x - 3 and y < -2", "y < x - 3 and y < -2", "y ≥ 2x and y ≤ 0"], answer: 0, explain: "For (3, -1): -1 < 0 and -1 > -2 are both true. In the third choice the first inequality holds but -1 < -2 fails, and a solution must satisfy both.", pattern: "Matching a Graph, Table, or Point to an Inequality or System", difficulty: "hard", trapFor: [null, null, 2, null], },
],
  "m-equiv-expr": [
  { q: "Factor completely: x² - 9", choices: ["(x-3)(x+3)", "(x-9)(x+1)", "(x-3)²", "(x+9)(x-1)"], answer: 0, explain: "This is a difference of squares: a² - b² = (a-b)(a+b).", pattern: "Recognizing Factoring Patterns Instantly", difficulty: "easy", trapFor: [null, null, 0, null], },
  { q: "Which expression is equivalent to 2x(x + 3)?", choices: ["2x² + 3", "2x² + 6x", "2x + 6x", "x² + 6x"], answer: 1, explain: "Distribute: 2x·x + 2x·3 = 2x² + 6x.", pattern: "Expanding and Combining Polynomial Expressions", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Factor completely: x² + 8x + 15", choices: ["(x+3)(x+5)", "(x+1)(x+15)", "(x+5)²", "(x-3)(x-5)"], answer: 0, explain: "We need two numbers that multiply to 15 and add to 8: 3 and 5, so (x+3)(x+5).", pattern: "Recognizing Factoring Patterns Instantly", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Which expression is equivalent to (x + 4)²?", choices: ["x² + 16", "x² + 4x + 16", "x² + 8x + 16", "x² + 8x + 8"], answer: 2, explain: "(x+4)² = x² + 2(4)x + 16 = x² + 8x + 16.", pattern: "Expanding and Combining Polynomial Expressions", difficulty: "easy", trapFor: [3, 3, null, null], },
  { q: "Simplify: (3x²y)(4xy³)", choices: ["7x³y⁴", "12x³y⁴", "12x²y³", "7x²y³"], answer: 1, explain: "Multiply coefficients (3×4=12) and add exponents of matching variables: x^(2+1)=x³, y^(1+3)=y⁴.", pattern: "Applying the Laws of Exponents", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Factor completely: 4x² - 25", choices: ["(2x-5)(2x+5)", "(4x-5)(x+5)", "(2x-25)(2x+1)", "(4x-25)(x+1)"], answer: 0, explain: "This is a difference of squares: (2x)² - 5² = (2x-5)(2x+5).", pattern: "Recognizing Factoring Patterns Instantly", difficulty: "easy", trapFor: [null, 0, 0, 0], },
  { q: "Which expression is equivalent to 3(x - 2) + 4(x + 1)?", choices: ["7x - 2", "7x + 2", "x - 2", "7x - 6"], answer: 0, explain: "3x - 6 + 4x + 4 = 7x - 2.", pattern: "Expanding and Combining Polynomial Expressions", difficulty: "easy", trapFor: [null, 2, null, null], },
  { q: "Simplify the rational expression: (x² - 4)/(x - 2)", choices: ["x + 2", "x - 2", "x² - 2", "x + 4"], answer: 0, explain: "x² - 4 factors to (x-2)(x+2); dividing by (x-2) leaves x + 2.", pattern: "Simplifying Rational Expressions via Factoring", difficulty: "medium", trapFor: [null, null, 0, null], },
  { q: "Which expression is equivalent to x²(x - 5) + 5x²?", choices: ["x³", "x³ - 5x²", "2x³ - 5x²", "x³ + 10x²"], answer: 0, explain: "x³ - 5x² + 5x² = x³.", pattern: "Expanding and Combining Polynomial Expressions", difficulty: "medium", trapFor: [null, null, 1, 2], },
  { q: "Factor completely: 2x² + 7x + 3", choices: ["(2x+1)(x+3)", "(2x+3)(x+1)", "(x+1)(x+3)", "(2x+7)(x+1)"], answer: 0, explain: "Testing (2x+1)(x+3): 2x² + 6x + x + 3 = 2x² + 7x + 3, matching the expression.", pattern: "Recognizing Factoring Patterns Instantly", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Simplify: (x³)/(x⁻²)", choices: ["x", "x⁵", "x⁻⁵", "x⁻⁶"], answer: 1, explain: "Dividing powers of the same base subtracts exponents: x^(3 - (-2)) = x⁵. Subtracting a negative exponent adds it.", pattern: "Applying the Laws of Exponents", difficulty: "easy", trapFor: [null, null, 1, 0], },
  { q: "Which expression is equivalent to (2x - 3)(x + 4)?", choices: ["2x² + 5x - 12", "2x² - 5x - 12", "2x² + 5x + 12", "2x² - x - 12"], answer: 0, explain: "Expand: 2x·x + 2x·4 - 3·x - 3·4 = 2x² + 8x - 3x - 12 = 2x² + 5x - 12.", pattern: "Expanding and Combining Polynomial Expressions", difficulty: "medium", trapFor: [null, 2, 2, null], },
  { q: "Which radical expression is equivalent to x^(2/3)?", choices: ["(∛x)²", "√(x³)", "(√x)³", "∛(x³)"], answer: 0, explain: "x^(a/b) means the b-th root of x, raised to the a power: with a=2 and b=3, x^(2/3) is the cube root of x, squared — (∛x)². √(x³) and (√x)³ both flip the fraction, using 3 as the power and 2 as the root instead of the reverse. ∛(x³) mistakenly simplifies to x itself, ignoring the numerator entirely.", pattern: "Applying the Laws of Exponents", difficulty: "medium", trapFor: [null, 2, 2, null], },
  { q: "Factor completely: x² - x - 12", choices: ["(x-4)(x+3)", "(x+4)(x-3)", "(x-6)(x+2)", "(x-12)(x+1)"], answer: 0, explain: "We need two numbers multiplying to -12 and adding to -1: -4 and 3, giving (x-4)(x+3).", pattern: "Recognizing Factoring Patterns Instantly", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Which expression is equivalent to 9x² - 16y²?", choices: ["(3x - 4y)(3x + 4y)", "(3x - 4y)²", "(9x - 4y)(x + 4y)", "(9x - 16y)(x + y)"], answer: 0, explain: "Both terms are perfect squares: 9x² = (3x)² and 16y² = (4y)², so this is a difference of squares, (3x - 4y)(3x + 4y).", pattern: "Recognizing Factoring Patterns Instantly", difficulty: "easy", trapFor: [null, 0, 0, 0], },
  { q: "If x² - y² = 48 and x + y = 8, what is the value of x - y?", choices: ["6", "40", "56", "384"], answer: 0, explain: "x² - y² factors as (x + y)(x - y), so 48 = 8(x - y) and x - y = 6. There's no need to find x and y.", pattern: "Recognizing Factoring Patterns Instantly", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "Which expression is equivalent to x² - 10x + 25?", choices: ["(x - 5)²", "(x + 5)²", "(x - 5)(x + 5)", "(x - 25)(x - 1)"], answer: 0, explain: "25 is 5², and the middle term is -2·5·x, so this is a perfect square trinomial: (x - 5)².", pattern: "Recognizing Factoring Patterns Instantly", difficulty: "easy", trapFor: [null, null, 0, 1], },
  { q: "For x ≠ -2 and x ≠ -3, which expression is equivalent to (x² - 9)/(x² + 5x + 6)?", choices: ["(x - 3)/(x + 2)", "(x + 3)/(x + 2)", "-9/(5x + 6)", "(x - 3)/(x + 3)"], answer: 0, explain: "Factor both: (x - 3)(x + 3) over (x + 2)(x + 3). The shared factor (x + 3) cancels, leaving (x - 3)/(x + 2).", pattern: "Simplifying Rational Expressions via Factoring", difficulty: "medium", trapFor: [null, null, 0, null], },
  { q: "For x ≠ 3, which expression is equivalent to (2x - 6)/(3 - x)?", choices: ["-2", "2", "2x", "-1/2"], answer: 0, explain: "2x - 6 = 2(x - 3), and 3 - x = -(x - 3). So the expression is 2(x - 3) / -(x - 3) = -2.", pattern: "Simplifying Rational Expressions via Factoring", difficulty: "hard", trapFor: [null, 2, 0, null], },
  { q: "For x ≠ 1 and x ≠ -1, which expression is equivalent to 3/(x - 1) - 2/(x + 1)?", choices: ["(x + 5)/(x² - 1)", "(x + 1)/(x² - 1)", "1/(x² - 1)", "5/(x² - 1)"], answer: 0, explain: "Use the common denominator (x - 1)(x + 1) = x² - 1: 3(x + 1) - 2(x - 1) = 3x + 3 - 2x + 2 = x + 5.", pattern: "Simplifying Rational Expressions via Factoring", difficulty: "hard", trapFor: [null, null, null, 0], },
  { q: "For x ≠ 0, which expression is equivalent to (x² + 4x)/x?", choices: ["x + 4", "x² + 4", "4x", "x² + 3x"], answer: 0, explain: "Factor the numerator: x(x + 4)/x = x + 4. You can only cancel the x because it multiplies the whole numerator.", pattern: "Simplifying Rational Expressions via Factoring", difficulty: "easy", trapFor: [null, 0, 0, 1], },
  { q: "For x ≠ 0, which expression is equivalent to (x⁵ · x³)/x²?", choices: ["x⁶", "x¹³", "x^(15/2)", "x¹⁰"], answer: 0, explain: "Multiplying adds exponents (5 + 3 = 8) and dividing subtracts them (8 - 2 = 6): x⁶.", pattern: "Applying the Laws of Exponents", difficulty: "easy", trapFor: [null, 0, 0, null], },
  { q: "For x > 0, which expression is equivalent to (8x⁶)^(2/3)?", choices: ["4x⁴", "2x²", "4x^(20/3)", "(16/3)x⁴"], answer: 0, explain: "Apply the power to each factor. 8^(2/3) = (∛8)² = 2² = 4, and (x⁶)^(2/3) = x^(6·2/3) = x⁴. That gives 4x⁴.", pattern: "Applying the Laws of Exponents", difficulty: "hard", trapFor: [null, 2, 0, null], },
  { q: "What is the value of 2⁻³ · 2⁵?", choices: ["4", "1/4", "2⁻¹⁵", "-4"], answer: 0, explain: "Same base, so add the exponents: -3 + 5 = 2, and 2² = 4. A negative exponent means a reciprocal, never a negative number.", pattern: "Applying the Laws of Exponents", difficulty: "easy", trapFor: [null, null, 0, 1], },
  { q: "If 3^(2x) · 3^(x + 1) = 3¹⁰, what is the value of x?", choices: ["3", "10/3", "9", "11/3"], answer: 0, explain: "Same base, so add the exponents: 2x + (x + 1) = 10, so 3x = 9 and x = 3.", pattern: "Applying the Laws of Exponents", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Which expression is equivalent to (3x² - 2x + 5) - (x² + 4x - 1)?", choices: ["2x² - 6x + 6", "2x² + 2x + 4", "2x² - 6x + 4", "4x² + 2x + 4"], answer: 0, explain: "Distribute the negative to every term of the second polynomial: 3x² - 2x + 5 - x² - 4x + 1 = 2x² - 6x + 6.", pattern: "Expanding and Combining Polynomial Expressions", difficulty: "medium", trapFor: [null, 0, 0, null], },
  { q: "Which expression is equivalent to (x - 3)(x² + 2x - 4)?", choices: ["x³ - x² - 10x + 12", "x³ - x² + 2x + 12", "x³ + 5x² - 10x + 12", "x³ + 2x² - 4x - 3"], answer: 0, explain: "x(x² + 2x - 4) = x³ + 2x² - 4x and -3(x² + 2x - 4) = -3x² - 6x + 12. Combining like terms gives x³ - x² - 10x + 12.", pattern: "Expanding and Combining Polynomial Expressions", difficulty: "hard", trapFor: [null, 2, 2, null], },
  { q: "The expression (2x + a)(x - 5) is equivalent to 2x² - 7x - 15, where a is a constant. What is the value of a?", choices: ["3", "-3", "7", "-15"], answer: 0, explain: "Expanding gives 2x² + (a - 10)x - 5a. Matching the x-terms, a - 10 = -7, so a = 3, and the constant term checks: -5(3) = -15.", pattern: "Expanding and Combining Polynomial Expressions", difficulty: "hard", trapFor: [null, 2, null, null], },
  { q: "Which expression is equivalent to 4x(x - 2) + 3x²?", choices: ["7x² - 8x", "-x", "4x² - 5x", "7x² - 2"], answer: 0, explain: "4x(x - 2) = 4x² - 8x, and adding 3x² gives 7x² - 8x. x² terms and x terms are unlike, so they can't be combined further.", pattern: "Expanding and Combining Polynomial Expressions", difficulty: "easy", trapFor: [null, 1, 1, null], },
],
  "m-nonlinear-eq": [
  { q: "How many real solutions does x² + 4x + 5 = 0 have?", choices: ["0", "1", "2", "Cannot be determined"], answer: 0, explain: "Discriminant = 16 - 20 = -4, which is negative, so there are no real solutions.", pattern: "Determining the Number of Solutions via the Discriminant", difficulty: "medium", trapFor: [null, null, 1, null], },
  { q: "Solve: x² - 5x + 6 = 0", choices: ["x = 1, 6", "x = 2, 3", "x = -2, -3", "x = 6, -1"], answer: 1, explain: "Factors to (x-2)(x-3) = 0, so x = 2 or x = 3.", pattern: "Solving a Quadratic by Factoring or the Quadratic Formula", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "How many real solutions does x² - 6x + 9 = 0 have?", choices: ["0", "1", "2", "Infinitely many"], answer: 1, explain: "Discriminant = 36 - 36 = 0, meaning exactly one repeated real solution.", pattern: "Determining the Number of Solutions via the Discriminant", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Solve: x² = 49", choices: ["x = 7 only", "x = -7 only", "x = 7 or x = -7", "No real solution"], answer: 2, explain: "Taking the square root of both sides gives x = ±7.", pattern: "Solving a Quadratic by Factoring or the Quadratic Formula", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Solve for x: √(x + 3) = 5", choices: ["x = 2", "x = 8", "x = 22", "x = 28"], answer: 2, explain: "Square both sides: x + 3 = 25, so x = 22. Checking: √25 = 5. Valid.", pattern: "Solving Radical Equations and Checking for Extraneous Solutions", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "How many real solutions does 2x² + 3x + 5 = 0 have?", choices: ["0", "1", "2", "Cannot be determined"], answer: 0, explain: "Discriminant = 9 - 40 = -31, which is negative, so there are no real solutions.", pattern: "Determining the Number of Solutions via the Discriminant", difficulty: "medium", trapFor: [null, null, 1, null], },
  { q: "Solve: x² - 2x - 15 = 0", choices: ["x = 3, -5", "x = 5, -3", "x = -3, -5", "x = 3, 5"], answer: 1, explain: "Factors to (x-5)(x+3) = 0, so x = 5 or x = -3.", pattern: "Solving a Quadratic by Factoring or the Quadratic Formula", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Solve for x: (x - 2)/(x + 1) = 3, given x ≠ -1.", choices: ["x = -2.5", "x = 2.5", "x = -5", "x = 5"], answer: 0, explain: "Multiplying both sides by (x+1): x - 2 = 3(x + 1) → x - 2 = 3x + 3 → -5 = 2x → x = -2.5.", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "How many real solutions does x² + 6x + 9 = 0 have, and what is/are the solution(s)?", choices: ["One solution, x = -3", "Two solutions, x = 3 and x = -3", "No real solutions", "Two solutions, x = -3 and x = 9"], answer: 0, explain: "x² + 6x + 9 factors to (x+3)², giving one repeated solution, x = -3.", pattern: "Determining the Number of Solutions via the Discriminant", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Solve for x: x² - 3x = 0", choices: ["x = 0 only", "x = 3 only", "x = 0 or x = 3", "x = -3 or x = 0"], answer: 2, explain: "Factor: x(x - 3) = 0, so x = 0 or x = 3.", pattern: "Solving a Quadratic by Factoring or the Quadratic Formula", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "Solve for x: √(2x - 1) = 3", choices: ["x = 2", "x = 4", "x = 5", "x = 7"], answer: 2, explain: "Square both sides: 2x - 1 = 9 → 2x = 10 → x = 5. Checking: √9 = 3. Valid.", pattern: "Solving Radical Equations and Checking for Extraneous Solutions", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "How many real solutions does the equation x² + 2x + 1 = 0 have?", choices: ["0", "1", "2", "Cannot be determined"], answer: 1, explain: "This factors to (x+1)² = 0, giving discriminant 0 and exactly one repeated real solution.", pattern: "Determining the Number of Solutions via the Discriminant", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "What are all the solutions to 3x² = 12x?", choices: ["x = 0 and x = 4", "x = 4 only", "x = 0 only", "x = -4 and x = 0"], answer: 0, explain: "Move everything to one side and factor: 3x² - 12x = 3x(x - 4) = 0, so x = 0 or x = 4. Dividing both sides by x would lose the x = 0 solution.", pattern: "Solving a Quadratic by Factoring or the Quadratic Formula", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "What are the solutions to x² - 6x + 4 = 0?", choices: ["x = 3 ± √5", "x = 3 ± 2√5", "x = -3 ± √5", "x = 6 ± 2√5"], answer: 0, explain: "It doesn't factor over the integers, so use the quadratic formula: x = (6 ± √(36 - 16))/2 = (6 ± √20)/2 = (6 ± 2√5)/2 = 3 ± √5.", pattern: "Solving a Quadratic by Factoring or the Quadratic Formula", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "What are the solutions to x² + 2x = 15?", choices: ["x = -5 and x = 3", "x = 5 and x = -3", "x = 15 and x = 13", "x = 0 and x = -2"], answer: 0, explain: "Set the equation equal to zero first: x² + 2x - 15 = 0, which factors as (x + 5)(x - 3) = 0. So x = -5 or x = 3.", pattern: "Solving a Quadratic by Factoring or the Quadratic Formula", difficulty: "medium", trapFor: [null, null, 1, 1], },
  { q: "What are all the solutions to |x - 4| = 7?", choices: ["x = 11 and x = -3", "x = 11 only", "x = 3 and x = -11", "x = -3 only"], answer: 0, explain: "x - 4 is either 7 or -7, so x = 11 or x = -3.", pattern: "Solving Absolute Value Equations", difficulty: "easy", trapFor: [null, 0, null, 0], },
  { q: "How many solutions does |2x + 1| + 5 = 2 have?", choices: ["0", "1", "2", "Infinitely many"], answer: 0, explain: "Isolate the absolute value first: |2x + 1| = -3. An absolute value can never be negative, so there's no solution.", pattern: "Solving Absolute Value Equations", difficulty: "medium", trapFor: [null, null, 1, null], },
  { q: "What are all the solutions to |x + 3| = 2x?", choices: ["x = 3 only", "x = 3 and x = -1", "x = -1 only", "There are no solutions."], answer: 0, explain: "Case 1: x + 3 = 2x gives x = 3, which checks (|6| = 6). Case 2: x + 3 = -2x gives x = -1, but then 2x = -2, and an absolute value can't equal a negative number. So x = -1 is extraneous.", pattern: "Solving Absolute Value Equations", difficulty: "hard", trapFor: [null, 2, 2, null], },
  { q: "In the equation x² + kx + 16 = 0, k is a positive constant. If the equation has exactly one real solution, what is the value of k?", choices: ["8", "4", "16", "32"], answer: 0, explain: "Exactly one real solution means the discriminant is zero: k² - 4(1)(16) = 0, so k² = 64 and k = 8 (k is positive).", pattern: "Determining the Number of Solutions via the Discriminant", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "How many real solutions does 2x² - 3x - 4 = 0 have?", choices: ["0", "1", "2", "Infinitely many"], answer: 2, explain: "The discriminant is (-3)² - 4(2)(-4) = 9 + 32 = 41. It's positive, so there are two real solutions. Getting -23 instead means the sign of -4ac was dropped.", pattern: "Determining the Number of Solutions via the Discriminant", difficulty: "medium", trapFor: [1, null, null, null], },
  { q: "What is the solution to √(x + 7) = x + 1?", choices: ["x = 2", "x = -3 and x = 2", "x = -3", "x = 3 and x = -2"], answer: 0, explain: "Squaring gives x + 7 = x² + 2x + 1, so x² + x - 6 = 0 and x = 2 or x = -3. Check both: x = 2 gives √9 = 3 ✓, but x = -3 gives √4 = 2 while x + 1 = -2 ✗. Only x = 2 works.", pattern: "Solving Radical Equations and Checking for Extraneous Solutions", difficulty: "medium", trapFor: [null, 0, 0, null], },
  { q: "How many solutions does √(3x - 2) + 4 = 2 have?", choices: ["0", "1", "2", "Infinitely many"], answer: 0, explain: "Isolate the root: √(3x - 2) = -2. A square root is never negative, so there's no solution. Squaring anyway gives x = 2, which fails the check: √4 + 4 = 6, not 2.", pattern: "Solving Radical Equations and Checking for Extraneous Solutions", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "The system y = x² - 4 and y = 3x has two solutions, (x₁, y₁) and (x₂, y₂). What is the value of x₁ + x₂?", choices: ["3", "4", "9", "-3"], answer: 0, explain: "Substitute: x² - 4 = 3x, so x² - 3x - 4 = 0 = (x - 4)(x + 1). The x-values are 4 and -1, and their sum is 3.", pattern: "Solving a Linear-Quadratic System by Substitution", difficulty: "medium", trapFor: [null, 1, 2, null], },
  { q: "How many solutions does the system y = 2x + 1 and y = x² - 2x + 5 have?", choices: ["0", "1", "2", "Infinitely many"], answer: 1, explain: "Substitute: x² - 2x + 5 = 2x + 1, so x² - 4x + 4 = 0 = (x - 2)². There's one repeated x-value, so the line touches the parabola at exactly one point, (2, 5).", pattern: "Solving a Linear-Quadratic System by Substitution", difficulty: "hard", trapFor: [null, null, 1, null], },
  { q: "If (x, y) is a solution to the system y = x² and y = x + 6, and x > 0, what is the value of y?", choices: ["9", "3", "4", "6"], answer: 0, explain: "Substitute: x² = x + 6, so x² - x - 6 = 0 = (x - 3)(x + 2). Since x > 0, x = 3, and y = 3² = 9.", pattern: "Solving a Linear-Quadratic System by Substitution", difficulty: "medium", trapFor: [null, 2, null, null], },
  { q: "The function f(x) = x² + bx - 12, where b is a constant, has a graph that passes through (3, 0). What is the value of f(-2)?", choices: ["-10", "1", "-6", "3"], answer: 0, explain: "f(3) = 0 gives 9 + 3b - 12 = 0, so b = 1. Then f(-2) = 4 - 2 - 12 = -10.", pattern: "Finding an Unknown Constant from a Given Root, Then Evaluating", difficulty: "medium", trapFor: [null, 0, null, 2], },
  { q: "One solution to x² + kx + 12 = 0, where k is a constant, is x = -3. What is the other solution?", choices: ["x = -4", "x = 7", "x = 4", "x = 3"], answer: 0, explain: "Substituting x = -3: 9 - 3k + 12 = 0, so k = 7. Then x² + 7x + 12 = (x + 3)(x + 4), and the other solution is x = -4.", pattern: "Finding an Unknown Constant from a Given Root, Then Evaluating", difficulty: "hard", trapFor: [null, 0, null, null], },
],
  "m-nonlinear-func": [
  { q: "The function f(x) = 2(3)^x models growth. What is the growth factor per unit increase in x?", choices: ["2", "3", "6", "2/3"], answer: 1, explain: "The base of the exponential, 3, is the growth factor per unit x.", pattern: "Modeling Growth and Decay with Exponential Functions", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "The vertex of f(x) = (x-2)² + 5 is:", choices: ["(2, 5)", "(-2, 5)", "(2, -5)", "(5, 2)"], answer: 0, explain: "In vertex form (x-h)² + k, the vertex is (h, k) = (2, 5).", pattern: "Reading Vertex Form Directly", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "A population of bacteria doubles every 3 hours, starting at 100. Which function models the population P after t hours?", choices: ["P = 100(2)^(t/3)", "P = 100(2)^(3t)", "P = 100(3)^(t/2)", "P = 100 + 2t"], answer: 0, explain: "Doubling every 3 hours means the exponent should reach 1 full doubling when t = 3, matching t/3 in the exponent.", pattern: "Modeling Growth and Decay with Exponential Functions", difficulty: "medium", trapFor: [null, null, null, 0], },
  { q: "The graph of f(x) = -(x+1)² + 4 opens in which direction, and what is its maximum value?", choices: ["Opens upward; minimum value 4", "Opens downward; maximum value 4", "Opens upward; minimum value -1", "Opens downward; maximum value -1"], answer: 1, explain: "The negative leading coefficient means the parabola opens downward, with maximum value equal to k = 4 at the vertex.", pattern: "Reading Vertex Form Directly", difficulty: "medium", trapFor: [1, null, 1, 0], },
  { q: "An investment of $2,000 grows at 5% annual interest, compounded yearly. Which function models the value V after t years?", choices: ["V = 2000(1.05)^t", "V = 2000(0.05)^t", "V = 2000 + 1.05t", "V = 2000(1.5)^t"], answer: 0, explain: "Annual compounding at 5% growth uses a base of 1 + 0.05 = 1.05 raised to the number of years.", pattern: "Modeling Growth and Decay with Exponential Functions", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "What are the x-intercepts of f(x) = x² - 4x - 5?", choices: ["x = 1, 5", "x = -1, 5", "x = 1, -5", "x = -1, -5"], answer: 1, explain: "Factoring: x² - 4x - 5 = (x-5)(x+1), so x = 5 or x = -1.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A radioactive substance decays at a rate of 10% per year, starting at 500 grams. Which function models the amount A after t years?", choices: ["A = 500(0.9)^t", "A = 500(1.1)^t", "A = 500(0.1)^t", "A = 500 - 10t"], answer: 0, explain: "A 10% decay per year means 90% remains each year, giving a base of 0.9 raised to the number of years.", pattern: "Modeling Growth and Decay with Exponential Functions", difficulty: "medium", trapFor: [null, null, 1, 0], },
  { q: "What is the maximum value of the function f(x) = -2(x - 3)² + 8?", choices: ["3", "8", "-2", "6"], answer: 1, explain: "The vertex form shows the vertex at (3, 8); since the coefficient is negative, this is a maximum value of 8.", pattern: "Reading Vertex Form Directly", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Which transformation describes g(x) = (x - 3)² compared to f(x) = x²?", choices: ["Shift left 3 units", "Shift right 3 units", "Shift up 3 units", "Shift down 3 units"], answer: 1, explain: "Replacing x with (x-3) shifts the graph horizontally to the right by 3 units.", pattern: "Graph Transformations (Shifts)", difficulty: "easy", trapFor: [0, null, 1, 1], },
  { q: "A car's value decreases by 12% each year from an initial price of $30,000. What is the value after 2 years?", choices: ["$23,232", "$26,400", "$22,320", "$24,000"], answer: 0, explain: "30000(0.88)² = 30000(0.7744) = 23,232.", pattern: "Modeling Growth and Decay with Exponential Functions", difficulty: "medium", trapFor: [null, null, null, 0], },
  { q: "What is the axis of symmetry of the parabola f(x) = 2(x + 5)² - 1?", choices: ["x = 5", "x = -5", "x = -1", "x = 1"], answer: 1, explain: "In vertex form (x-h)², the axis of symmetry is x = h; here x + 5 = x - (-5), so h = -5.", pattern: "Reading Vertex Form Directly", difficulty: "medium", trapFor: [0, null, null, null], },
  { q: "What is the minimum value of f(x) = 3(x + 4)² - 7?", choices: ["-7", "-4", "4", "7"], answer: 0, explain: "In vertex form a(x - h)² + k, the vertex is (h, k) = (-4, -7). Since a = 3 is positive, the parabola opens up and the minimum value is k = -7.", pattern: "Reading Vertex Form Directly", difficulty: "easy", trapFor: [null, null, 0, null], },
  { q: "Which statement is true about the graph of y = -2(x - 1)² + 9?", choices: ["It has a maximum value of 9 at x = 1.", "It has a minimum value of 9 at x = 1.", "It has a maximum value of 9 at x = -1.", "It has a maximum value of -2 at x = 1."], answer: 0, explain: "The vertex is (1, 9), and the negative leading coefficient means the parabola opens down, so (1, 9) is a maximum.", pattern: "Reading Vertex Form Directly", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "A town has 12,000 residents, and its population increases by 3% each year. Which function gives the population P after t years?", choices: ["P = 12,000(1.03)^t", "P = 12,000(0.03)^t", "P = 12,000(1.3)^t", "P = 12,000 + 360t"], answer: 0, explain: "Growing by 3% means each year's population is 103% of the last: multiply by 1.03 each year.", pattern: "Modeling Growth and Decay with Exponential Functions", difficulty: "easy", trapFor: [null, 1, null, 0], },
  { q: "A patient is given 80 milligrams of a medication, and the amount in the body decreases by 25% each hour. How many milligrams remain after 3 hours?", choices: ["33.75", "20", "1.25", "45"], answer: 0, explain: "Each hour 75% remains: 80(0.75)³ = 80(0.421875) = 33.75. Subtracting 20 mg each hour would be linear, not a 25% decrease.", pattern: "Modeling Growth and Decay with Exponential Functions", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "A 640-gram sample of a radioactive isotope loses half its mass every 5 days. Which function gives the mass M, in grams, after d days?", choices: ["M = 640(1/2)^(d/5)", "M = 640(1/2)^(5d)", "M = 640(5)^(d/2)", "M = 640 - 64d"], answer: 0, explain: "The mass halves once per 5 days, so the number of halvings after d days is d/5.", pattern: "Modeling Growth and Decay with Exponential Functions", difficulty: "hard", trapFor: [null, null, null, 0], },
  { q: "For x = 0, 1, 2, and 3, the values of a function g are 5, 15, 45, and 135, respectively. Which statement best describes g?", choices: ["Exponential: each value is 3 times the previous one.", "Linear: each value is 10 more than the previous one.", "Linear: each value is 3 more than the previous one.", "Exponential: each value is 10 times the previous one."], answer: 0, explain: "The differences (10, 30, 90) aren't constant, but the ratios (15/5, 45/15, 135/45) are all 3, so g is exponential with a factor of 3. Checking only the first pair gives a difference of 10 and looks linear.", pattern: "Reading Linear vs. Exponential Growth From a Table", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "For x = 0, 1, 2, and 3, the values of a function f are 200, 160, 128, and 102.4, respectively. Which equation could define f?", choices: ["f(x) = 200(0.8)^x", "f(x) = 200 - 40x", "f(x) = 200(0.2)^x", "f(x) = 200(1.2)^x"], answer: 0, explain: "The ratios are all 0.8 (160/200, 128/160, 102.4/128), so f shrinks by the same factor each step: exponential decay. The first difference is 40, but the next is 32, so it isn't linear.", pattern: "Reading Linear vs. Exponential Growth From a Table", difficulty: "hard", trapFor: [null, 2, null, null], },
  { q: "The graph of g(x) = f(x + 2) - 3 is the graph of f shifted in which way?", choices: ["2 units left and 3 units down", "2 units right and 3 units down", "2 units left and 3 units up", "3 units left and 2 units down"], answer: 0, explain: "Adding 2 inside the function moves the graph 2 units left; subtracting 3 outside moves it 3 units down.", pattern: "Graph Transformations (Shifts)", difficulty: "medium", trapFor: [null, 0, null, 1], },
  { q: "The graph of f(x) = 2^x has a horizontal asymptote at y = 0. What is the horizontal asymptote of the graph of g(x) = 2^(x - 1) + 4?", choices: ["y = 4", "y = 0", "y = -1", "y = 3"], answer: 0, explain: "Shifting right 1 unit doesn't move a horizontal line, but adding 4 moves every point, including the asymptote, up 4 units: y = 4.", pattern: "Graph Transformations (Shifts)", difficulty: "hard", trapFor: [null, 2, 1, null], },
  { q: "Which statement is true about the function f(x) = 5(2)^x - 3?", choices: ["f(x) > -3 for all values of x.", "f(x) ≥ 5 for all values of x.", "The minimum value of f is -3.", "f(x) < -3 for all values of x."], answer: 0, explain: "5(2)^x is always positive but gets as close to 0 as you like, so f(x) is always greater than -3 but never reaches it. That means -3 isn't a minimum value.", pattern: "Minimum, Maximum, and Asymptote Reasoning for Exponential Functions", difficulty: "medium", trapFor: [null, 0, 1, 2], },
  { q: "The function g(x) = -4(0.5)^x + 10 is defined for all real x. As x increases without bound, g(x) gets closer and closer to what value?", choices: ["10", "-4", "6", "0"], answer: 0, explain: "As x grows, (0.5)^x shrinks toward 0, so -4(0.5)^x approaches 0 and g(x) approaches 10.", pattern: "Minimum, Maximum, and Asymptote Reasoning for Exponential Functions", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "What is the minimum value of f(x) = x² - 8x + 3?", choices: ["-13", "4", "3", "51"], answer: 0, explain: "The vertex is at x = -b/(2a) = 8/2 = 4, and f(4) = 16 - 32 + 3 = -13. The minimum value is the y-coordinate, not x = 4.", pattern: "Finding the Vertex of a Quadratic from Standard Form", difficulty: "medium", trapFor: [null, 0, null, 2], },
  { q: "What is the maximum value of g(x) = -3x² + 12x + 5?", choices: ["17", "2", "-31", "5"], answer: 0, explain: "x = -b/(2a) = -12/(2·-3) = 2, and g(2) = -12 + 24 + 5 = 17. Using x = -2 by mistake gives -31.", pattern: "Finding the Vertex of a Quadratic from Standard Form", difficulty: "hard", trapFor: [null, 0, 2, null], },
  { q: "If f(x) = 2x² - 3x + 1, what is the value of f(-2)?", choices: ["15", "-1", "3", "23"], answer: 0, explain: "f(-2) = 2(-2)² - 3(-2) + 1 = 2(4) + 6 + 1 = 15. (-2)² is +4; squaring the input must include its sign.", pattern: "Evaluating a Function and Interpreting Its Output in Context", difficulty: "easy", trapFor: [null, 0, null, 0], },
  { q: "The function V(n) = 1,200(0.85)^n models the value, in dollars, of a laptop n years after it was purchased. What is the best interpretation of 1,200 in this context?", choices: ["The laptop's value, in dollars, when it was purchased", "The laptop's value, in dollars, after one year", "The amount, in dollars, the laptop's value decreases each year", "The number of years until the laptop has no value"], answer: 0, explain: "When n = 0, (0.85)^0 = 1, so V(0) = 1,200: the value at purchase. The value after one year is 1,200(0.85) = 1,020.", pattern: "Evaluating a Function and Interpreting Its Output in Context", difficulty: "medium", trapFor: [null, null, null, null], },
],
  "m-ratios-rates": [
  { q: "A recipe uses 2 cups of flour for 12 cookies. How many cups are needed for 30 cookies?", choices: ["4", "5", "6", "7.5"], answer: 1, explain: "2/12 = x/30 → x = 60/12 = 5.", pattern: "Setting Up Proportions Correctly", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A car travels 150 miles in 3 hours. What is its rate in miles per hour?", choices: ["30", "45", "50", "60"], answer: 2, explain: "150 ÷ 3 = 50 mph.", pattern: "Setting Up Proportions Correctly", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A map has a scale of 1 inch = 25 miles. If two cities are 4.5 inches apart on the map, how far apart are they in reality?", choices: ["100 miles", "112.5 miles", "125 miles", "150 miles"], answer: 1, explain: "4.5 × 25 = 112.5 miles.", pattern: "Setting Up Proportions Correctly", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A factory produces 480 units in 8 hours. At this rate, how many units are produced in 5 hours?", choices: ["250", "280", "300", "320"], answer: 2, explain: "480/8 = 60 units per hour; 60 × 5 = 300.", pattern: "Setting Up Proportions Correctly", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A paint mixture uses blue and white paint in a ratio of 3:5. If 24 quarts of blue paint are used, how many quarts of white paint are needed?", choices: ["30", "35", "40", "45"], answer: 2, explain: "3/5 = 24/x → x = 24 × 5/3 = 40.", pattern: "Setting Up Proportions Correctly", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A car's fuel efficiency is 32 miles per gallon. How many gallons are needed for a 400-mile trip?", choices: ["10", "12.5", "15", "20"], answer: 1, explain: "400 ÷ 32 = 12.5 gallons.", pattern: "Setting Up Proportions Correctly", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A recipe requires 3 eggs for every 2 cups of flour. How many eggs are needed for 8 cups of flour?", choices: ["9", "10", "12", "14"], answer: 2, explain: "3/2 = x/8 → x = 24/2 = 12.", pattern: "Setting Up Proportions Correctly", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A pump fills a pool at a rate of 15 gallons per minute. How many minutes does it take to fill a 2,400-gallon pool?", choices: ["120", "140", "160", "180"], answer: 2, explain: "2400 ÷ 15 = 160 minutes.", pattern: "Setting Up Proportions Correctly", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A photo is enlarged so its dimensions increase by a scale factor of 2.5. If the original width is 4 inches, what is the new width?", choices: ["8 inches", "9 inches", "10 inches", "12 inches"], answer: 2, explain: "4 × 2.5 = 10 inches.", pattern: "Setting Up Proportions Correctly", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A container holds a mixture of sand and gravel in a ratio of 2:3. If the total mixture weighs 60 pounds, how much does the gravel weigh?", choices: ["20 pounds", "24 pounds", "30 pounds", "36 pounds"], answer: 3, explain: "Total parts = 2+3 = 5; gravel is 3/5 of 60 = 36 pounds.", pattern: "Setting Up Proportions Correctly", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "A cyclist travels at a constant rate of 18 miles per hour. How long will it take to travel 45 miles?", choices: ["2 hours", "2.25 hours", "2.5 hours", "3 hours"], answer: 2, explain: "45 ÷ 18 = 2.5 hours.", pattern: "Setting Up Proportions Correctly", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A store sells notebooks in packs, with a price of $12 for 8 notebooks. What is the cost per notebook?", choices: ["$1.25", "$1.50", "$1.75", "$2.00"], answer: 1, explain: "12 ÷ 8 = $1.50 per notebook.", pattern: "Setting Up Proportions Correctly", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A car travels at a constant speed of 66 feet per second. What is its speed in miles per hour? (1 mile = 5,280 feet)", choices: ["45", "96.8", "0.75", "4.5"], answer: 0, explain: "66 ft/s × 3,600 s/h = 237,600 ft/h, and 237,600 ÷ 5,280 = 45 mph. Multiplying by 5,280 instead of dividing gives 96.8; converting seconds to minutes but not to hours gives 0.75.", pattern: "Unit Conversion Chains", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "A recipe calls for 750 milliliters of broth. About how many cups of broth is this? (1 cup ≈ 240 milliliters)", choices: ["3.125", "180,000", "510", "0.32"], answer: 0, explain: "750 ÷ 240 = 3.125 cups. Multiplying by 240 turns the conversion factor upside down; 240 ÷ 750 = 0.32 divides the wrong way.", pattern: "Unit Conversion Chains", difficulty: "easy", trapFor: [null, 0, null, 0], },
  { q: "A printer prints 18 pages per minute. At this rate, how many pages can it print in 2.5 hours?", choices: ["2,700", "45", "1,080", "7.2"], answer: 0, explain: "2.5 hours is 150 minutes, and 18 × 150 = 2,700. Multiplying 18 by 2.5 skips the hours-to-minutes step; 1,080 is one hour's worth.", pattern: "Unit Conversion Chains", difficulty: "easy", trapFor: [null, 1, 1, 0], },
  { q: "A machine uses 3.6 kilograms of plastic per hour. How many grams of plastic does it use per minute? (1 kilogram = 1,000 grams)", choices: ["60", "216,000", "0.06", "3,600"], answer: 0, explain: "3.6 kg/h = 3,600 g/h, and 3,600 ÷ 60 = 60 g/min. 216,000 multiplies by 60 instead of dividing; 3,600 is still grams per hour.", pattern: "Unit Conversion Chains", difficulty: "medium", trapFor: [null, 0, 1, 1], },
  { q: "A snail moves at 0.5 inch per second. At this rate, how many feet does it travel in 4 minutes?", choices: ["10", "1,440", "2", "120"], answer: 0, explain: "4 minutes is 240 seconds, so it moves 0.5 × 240 = 120 inches, which is 120 ÷ 12 = 10 feet. 120 stops at inches; 1,440 multiplies by 12 instead of dividing.", pattern: "Unit Conversion Chains", difficulty: "medium", trapFor: [null, 0, 1, 1], },
  { q: "A metal has a density of 7.8 grams per cubic centimeter. What is the mass, in kilograms, of a block of this metal with a volume of 500 cubic centimeters?", choices: ["3.9", "3,900", "64.1", "0.064"], answer: 0, explain: "Mass = 7.8 × 500 = 3,900 grams = 3.9 kilograms. 3,900 leaves the answer in grams; 500 ÷ 7.8 ≈ 64.1 divides where it should multiply.", pattern: "Unit Conversion Chains", difficulty: "hard", trapFor: [null, 1, 0, 0], },
  { q: "On a scale drawing, 2 centimeters represent 5 meters. A wall in the drawing is 7 centimeters long. How long is the actual wall, in meters?", choices: ["17.5", "2.8", "14", "35"], answer: 0, explain: "2/5 = 7/x, so x = 35/2 = 17.5 meters. Setting up 5/2 = 7/x mismatches the units and gives 2.8; 35 multiplies 7 by 5 without dividing by 2.", pattern: "Setting Up Proportions Correctly", difficulty: "easy", trapFor: [null, 0, null, 1], },
  { q: "A basketball player made 21 of her first 35 free throws. If she continues at the same rate, how many of her next 60 free throws is she expected to make?", choices: ["36", "100", "46", "24"], answer: 0, explain: "21/35 = 0.6, and 0.6 × 60 = 36. 100 comes from 35/21 × 60, a flipped rate; 24 is the number she'd be expected to miss.", pattern: "Setting Up Proportions Correctly", difficulty: "medium", trapFor: [null, 0, null, 1], },
  { q: "At a museum, the ratio of adults to children is 4 to 7. There are 21 more children than adults. How many people are at the museum?", choices: ["77", "33", "49", "28"], answer: 0, explain: "The difference is 7 - 4 = 3 parts, so each part is 21 ÷ 3 = 7 people. The total is 11 parts: 11 × 7 = 77. 49 and 28 are the children and the adults.", pattern: "Setting Up Proportions Correctly", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "The quantities x and y are directly proportional, and y = 12 when x = 8. What is the value of y when x = 20?", choices: ["30", "13.3", "24", "18"], answer: 0, explain: "y/x stays 12/8 = 1.5, so y = 1.5 × 20 = 30. 24 treats the change as additive (x rose by 12, so y rises by 12), and 13.3 uses the ratio 8/12 upside down.", pattern: "Setting Up Proportions Correctly", difficulty: "easy", trapFor: [null, 0, 1, null], },
  { q: "At a school, the ratio of teachers to students is 1 to 18. If the school has s students, which expression represents the number of teachers?", choices: ["s/18", "18s", "s/19", "18/s"], answer: 0, explain: "There is 1 teacher for every 18 students, so the number of teachers is s ÷ 18. 18s multiplies instead of dividing, s/19 treats the ratio as part-to-whole, and 18/s flips it.", pattern: "Expressing One Quantity as an Algebraic Ratio Expression", difficulty: "medium", trapFor: [null, 2, 1, 0], },
  { q: "A jar contains only red and blue marbles, in a ratio of 3 to 5. If the jar contains m marbles in all, which expression gives the number of red marbles?", choices: ["3m/8", "3m/5", "5m/8", "8m/3"], answer: 0, explain: "Red is 3 of every 3 + 5 = 8 marbles, so there are 3m/8 red marbles. 3m/5 uses the part-to-part ratio as if it were part-to-whole; 5m/8 is the blue marbles.", pattern: "Expressing One Quantity as an Algebraic Ratio Expression", difficulty: "medium", trapFor: [null, 1, null, 0], },
  { q: "A mixture contains water and juice concentrate in a ratio of w to c. If the mixture contains 12 liters of concentrate, which expression gives the number of liters of water?", choices: ["12w/c", "12c/w", "12w/(w + c)", "w/(12c)"], answer: 0, explain: "water/concentrate = w/c, so water = 12 × w/c. 12c/w flips the ratio; 12w/(w + c) treats 12 as the whole mixture.", pattern: "Expressing One Quantity as an Algebraic Ratio Expression", difficulty: "hard", trapFor: [null, 0, 1, 2], },
  { q: "A car uses g gallons of gas to travel 240 miles. At this rate, how many gallons will it use to travel d miles?", choices: ["gd/240", "240d/g", "240g/d", "d/(240g)"], answer: 0, explain: "The car uses g/240 gallons per mile, so d miles take gd/240 gallons. The other choices divide where they should multiply or flip the rate.", pattern: "Expressing One Quantity as an Algebraic Ratio Expression", difficulty: "hard", trapFor: [null, 0, 2, 0], },
  { q: "In a club, the ratio of juniors to seniors is 2 to 3. If there are j juniors, which expression gives the total number of members?", choices: ["5j/2", "3j/2", "2j/3", "5j/3"], answer: 0, explain: "There are 3/2 seniors per junior, so seniors = 3j/2 and the total is j + 3j/2 = 5j/2. 3j/2 counts only the seniors; 2j/3 flips the ratio.", pattern: "Expressing One Quantity as an Algebraic Ratio Expression", difficulty: "medium", trapFor: [null, 1, 0, null], },
],
  "m-percentages": [
  { q: "A shirt originally $40 is discounted 25%. What is the sale price?", choices: ["$10", "$25", "$30", "$35"], answer: 2, explain: "25% of 40 is 10; 40 - 10 = 30.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "easy", trapFor: [0, null, null, null], },
  { q: "A value increases from 80 to 100. What is the percent increase?", choices: ["20%", "25%", "80%", "100%"], answer: 1, explain: "(100-80)/80 = 0.25 = 25%.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A restaurant bill is $60 before an 18% tip. What is the total bill including tip?", choices: ["$68.80", "$70.80", "$72.80", "$78.00"], answer: 1, explain: "18% of 60 is 10.80; 60 + 10.80 = 70.80.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "An item's price increases by 20% and then decreases by 20%. Compared to the original price, the final price is:", choices: ["The same as the original", "4% lower than the original", "4% higher than the original", "40% lower than the original"], answer: 1, explain: "If original is 100: after +20% it's 120; after -20% of 120 (24), it's 96 — a net 4% decrease.", pattern: "Successive Percent Changes (Compounding, Not Additive)", difficulty: "hard", trapFor: [0, null, null, null], },
  { q: "A population of 5,000 grows by 8% in one year. What is the new population?", choices: ["5,040", "5,300", "5,400", "5,500"], answer: 2, explain: "5000 × 1.08 = 5,400.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A laptop originally priced at $900 is on sale for $720. What is the percent discount?", choices: ["15%", "18%", "20%", "25%"], answer: 2, explain: "(900-720)/900 = 180/900 = 0.20 = 20%.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A savings account earns 4% annual interest. If the initial deposit is $2,500, what is the balance after one year (simple interest)?", choices: ["$2,540", "$2,580", "$2,600", "$2,625"], answer: 2, explain: "4% of 2500 is 100; 2500 + 100 = 2600.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A test has 80 questions. If a student answers 68 correctly, what percent did they get right?", choices: ["80%", "82.5%", "85%", "87.5%"], answer: 2, explain: "68/80 = 0.85 = 85%.", pattern: "Finding What Percent One Number Is of Another", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A company's revenue fell from $500,000 to $425,000. What is the percent decrease?", choices: ["10%", "15%", "20%", "25%"], answer: 1, explain: "(500000-425000)/500000 = 75000/500000 = 0.15 = 15%.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A price is marked up 30% from its wholesale cost of $50. What is the marked-up price?", choices: ["$60", "$62.50", "$65", "$70"], answer: 2, explain: "30% of 50 is 15; 50 + 15 = 65.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "If a value is increased by 50% and then decreased by 50%, what is the final value compared to the original?", choices: ["The same as the original", "25% lower than the original", "25% higher than the original", "50% lower than the original"], answer: 1, explain: "Starting at 100: +50% gives 150; -50% of 150 (75) gives 75 — a net 25% decrease from 100.", pattern: "Successive Percent Changes (Compounding, Not Additive)", difficulty: "hard", trapFor: [0, null, null, null], },
  { q: "A city's population of 240,000 is projected to grow 5% per year. What is the approximate population after 2 years?", choices: ["252,000", "264,000", "264,600", "270,000"], answer: 2, explain: "Each year multiplies by 1.05: 240,000 × 1.05² = 240,000 × 1.1025 = 264,600. Adding 5% twice (10% of 240,000) gives 264,000, which misses the growth on the first year's growth.", pattern: "Successive Percent Changes (Compounding, Not Additive)", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "A jacket costs $80. During a sale, its price is reduced by 15%. What is the sale price?", choices: ["$68", "$12", "$65", "$92"], answer: 0, explain: "15% of 80 is 12, so the sale price is 80 - 12 = $68. $12 is the discount, not the price.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "After a 20% discount, a lamp costs $36. What was the original price of the lamp?", choices: ["$45", "$43.20", "$28.80", "$180"], answer: 0, explain: "The sale price is 80% of the original: 0.8p = 36, so p = 45. Adding 20% of $36 gives $43.20, but the 20% was taken from the original price, not the sale price. $180 treats $36 as 20% of the original.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "medium", trapFor: [null, null, null, 1], },
  { q: "A town's population increased from 12,500 to 14,000. By what percent did the population increase?", choices: ["12%", "10.7%", "15%", "1.5%"], answer: 0, explain: "The increase is 1,500, and 1,500 ÷ 12,500 = 0.12 = 12%. Dividing by the new population, 14,000, gives about 10.7%.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A restaurant adds 6% sales tax to a $45 meal. The customer also leaves a tip of 20% of the $45 pre-tax price. What is the total amount the customer pays?", choices: ["$56.70", "$57.24", "$11.70", "$47.70"], answer: 0, explain: "Tax is 0.06 × 45 = 2.70 and the tip is 0.20 × 45 = 9, so the total is 45 + 2.70 + 9 = $56.70. $57.24 figures the tip on the taxed amount; $11.70 is just the tax and tip.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "hard", trapFor: [null, null, 0, null], },
  { q: "A sample of 60 people found that 45% of them preferred Brand A. How many people in the sample preferred Brand A?", choices: ["27", "45", "33", "133"], answer: 0, explain: "45% of 60 is 0.45 × 60 = 27. 33 is the number who did not prefer Brand A, and 133 divides 60 by 0.45.", pattern: "Straightforward Percent Change and Discount Problems", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A store raises the price of a coat by 25%, then puts the coat on sale for 20% off the new price. The sale price is what percent of the original price?", choices: ["100%", "105%", "95%", "80%"], answer: 0, explain: "1.25 × 0.80 = 1.00, so the sale price equals the original price. Subtracting 20% from 25% gives 105%, but the 20% is taken from a larger price.", pattern: "Successive Percent Changes (Compounding, Not Additive)", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "A car's value decreases by 15% each year. If the car is worth $20,000 now, what will it be worth in 2 years?", choices: ["$14,450", "$14,000", "$17,000", "$14,750"], answer: 0, explain: "20,000 × 0.85 × 0.85 = $14,450. Taking 30% off at once gives $14,000, but the second year's 15% comes off a smaller value. $17,000 is one year.", pattern: "Successive Percent Changes (Compounding, Not Additive)", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "A population of bacteria increases by 40% every hour. By what percent has the population increased after 2 hours?", choices: ["96%", "80%", "196%", "140%"], answer: 0, explain: "Two hours multiply the population by 1.4 × 1.4 = 1.96, a 96% increase. Adding 40% twice gives 80%; 196% is the new population as a percent of the old one, not the increase.", pattern: "Successive Percent Changes (Compounding, Not Additive)", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "The price of a ticket increased by 10% in 2022 and by 10% again in 2023. The 2023 price is what percent greater than the price before both increases?", choices: ["21%", "20%", "110%", "121%"], answer: 0, explain: "1.1 × 1.1 = 1.21, so the price is 21% greater. 20% adds the two increases; 121% is the new price as a percent of the old one.", pattern: "Successive Percent Changes (Compounding, Not Additive)", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "A quantity q is increased by 30%, and the result is then decreased by 30%. Which expression represents the final quantity?", choices: ["0.91q", "q", "0.7q", "1.09q"], answer: 0, explain: "q × 1.3 × 0.7 = 0.91q. An increase and an equal-percent decrease don't cancel, because the decrease applies to a larger number.", pattern: "Successive Percent Changes (Compounding, Not Additive)", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "What percent of 250 is 40?", choices: ["16%", "625%", "160%", "84%"], answer: 0, explain: "40 ÷ 250 = 0.16 = 16%. 625% divides 250 by 40, reversing the part and the whole.", pattern: "Finding What Percent One Number Is of Another", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "A school has 480 students, and 132 of them walk to school. The rest arrive by bus or car. What percent of the students do not walk to school?", choices: ["72.5%", "27.5%", "37.9%", "36.4%"], answer: 0, explain: "480 - 132 = 348 students don't walk, and 348 ÷ 480 = 0.725 = 72.5%. 27.5% is the percent who do walk.", pattern: "Finding What Percent One Number Is of Another", difficulty: "medium", trapFor: [null, 2, null, null], },
  { q: "Last year a farm harvested 800 bushels of corn. This year it harvested 1,000 bushels. This year's harvest is what percent of last year's harvest?", choices: ["125%", "80%", "25%", "20%"], answer: 0, explain: "1,000 ÷ 800 = 1.25 = 125%. A result over 100% is expected here, since this year's harvest is larger. 80% reverses the part and whole; 25% is the percent increase, a different question.", pattern: "Finding What Percent One Number Is of Another", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "If x is 150% of y, then y is what percent of x?", choices: ["About 66.7%", "150%", "50%", "About 33.3%"], answer: 0, explain: "x = 1.5y, so y = x/1.5 = (2/3)x, or about 66.7% of x. 150% just repeats the given relationship in the wrong direction.", pattern: "Finding What Percent One Number Is of Another", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "A store buys a phone for $240 and sells it for $300. The store's profit is what percent of the price it paid?", choices: ["25%", "20%", "60%", "125%"], answer: 0, explain: "The profit is $60, and 60 ÷ 240 = 25%. Dividing by the selling price, $300, gives 20%. 125% is the selling price as a percent of the cost.", pattern: "Finding What Percent One Number Is of Another", difficulty: "medium", trapFor: [null, 0, null, null], },
],
  "m-one-var-data": [
  { q: "A data set has a much larger mean than median. What does this suggest?", choices: ["The data are skewed right.", "The data are symmetric.", "The data are skewed left.", "The data have no spread."], answer: 0, explain: "A mean pulled higher than the median suggests high-value outliers pulling the mean up (right skew).", pattern: "Comparing Mean and Median to Detect Skew", difficulty: "easy", trapFor: [null, null, 1, null], },
  { q: "In the data set 3, 5, 6, 8, 40, the value 40 is changed to 10. Which statement about the mean and median of the data set is true?", choices: ["The mean decreases, and the median stays the same.", "The mean and the median both decrease.", "The median decreases, and the mean stays the same.", "Neither the mean nor the median changes."], answer: 0, explain: "The mean falls from 62/5 = 12.4 to 32/5 = 6.4. The median is still the middle value, 6, because 10 is still the largest value.", pattern: "How Changing a Data Set Changes Its Statistics", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "For the data set 4, 6, 6, 8, 10, 50, which statement about the mean and median is true?", choices: ["The mean is greater than the median, because 50 pulls the mean up.", "The median is greater than the mean, because 50 pulls the median up.", "The mean and the median are equal, because the data set has a mode.", "The mean is less than the median, because 50 is an outlier."], answer: 0, explain: "The mean is 84/6 = 14 and the median is (6 + 8)/2 = 7. The high value 50 pulls the mean up but barely affects the median.", pattern: "Comparing Mean and Median to Detect Skew", difficulty: "medium", trapFor: [null, 1, null, 1], },
  { q: "Two data sets have the same mean but Data Set A has a much larger standard deviation than Data Set B. What does this indicate?", choices: ["Set A's values are more spread out than Set B's.", "Set A's values are larger, on average, than Set B's.", "Set A contains more values than Set B does.", "Set A's values are closer together than Set B's."], answer: 0, explain: "Standard deviation measures spread. The means are equal, so Set A isn't larger on average; its values are just more spread out around that mean.", pattern: "Interpreting Standard Deviation as Spread", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "A data set has a median greater than its mean. What does this most likely suggest?", choices: ["The data are symmetric.", "The data are skewed left.", "The data are skewed right.", "The data have no outliers."], answer: 1, explain: "A mean pulled below the median suggests low-value outliers dragging the mean down (left skew).", pattern: "Comparing Mean and Median to Detect Skew", difficulty: "medium", trapFor: [null, null, 1, null], },
  { q: "In a box plot, which value does the line inside the box represent?", choices: ["The mean", "The median", "The mode", "The range"], answer: 1, explain: "The line inside a box plot's box represents the median of the data set.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A class's test scores have a mean of 78 and a standard deviation of 6. A student scored 90. About how many standard deviations above the mean is this score?", choices: ["1", "2", "3", "4"], answer: 1, explain: "(90 - 78)/6 = 12/6 = 2 standard deviations above the mean.", pattern: "Interpreting Standard Deviation as Spread", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Which statistic describes the difference between the maximum and minimum values in a data set?", choices: ["Mean", "Median", "Range", "Standard deviation"], answer: 2, explain: "Range is defined as maximum value minus minimum value.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A teacher removes one extremely low score from a set of exam scores. What is the most likely effect on the mean of the remaining scores?", choices: ["The mean increases.", "The mean decreases.", "The mean stays the same.", "The mean becomes equal to the median."], answer: 0, explain: "The low score was pulling the average down, so removing it raises the mean.", pattern: "How Changing a Data Set Changes Its Statistics", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Which measure of spread uses every data point in its calculation, rather than just the extremes or the middle value?", choices: ["Standard deviation", "Range", "Interquartile range", "Maximum value"], answer: 0, explain: "Standard deviation uses every value's distance from the mean. The range uses only the two extremes, and the interquartile range only the quartiles.", pattern: "Interpreting Standard Deviation as Spread", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A data set has values: 12, 15, 15, 18, 20. What is the mode?", choices: ["12", "15", "18", "20"], answer: 1, explain: "15 appears twice, more than any other value, making it the mode.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "The bar graph shows the number of pets owned by each of 20 students.\n\nWhat is the median number of pets owned by these students?", choices: ["1", "1.25", "8", "2"], answer: 0, explain: "Listed in order, the 10th and 11th values are both 1 (the 0s fill spots 1–5 and the 1s fill 6–13), so the median is 1. 1.25 is the mean; 8 is a frequency, not a number of pets.", pattern: "Reading Values and Basic Statistics Directly from a Graph or Table", difficulty: "medium", figure: {"kind": "bar", "xLabel": "Number of pets", "y": {"label": "Number of students", "min": 0, "max": 10, "step": 2}, "bars": [{"label": "0", "value": 5}, {"label": "1", "value": 8}, {"label": "2", "value": 4}, {"label": "3", "value": 3}]}, trapFor: [null, null, 1, null], },
  { q: "The table shows the scores of 20 students on a 5-point quiz.\n\nWhat is the mean score?", choices: ["3.65", "3.5", "5", "4"], answer: 0, explain: "Total points = 2(3) + 3(5) + 4(8) + 5(4) = 73, and 73 ÷ 20 = 3.65. 3.5 averages the four scores without weighting them by how many students earned each; 5 averages the frequencies.", pattern: "Reading Values and Basic Statistics Directly from a Graph or Table", difficulty: "hard", figure: {"kind": "table", "header": ["Score", "Number of students"], "rows": [[2, 3], [3, 5], [4, 8], [5, 4]]}, trapFor: [null, 1, 1, null], },
  { q: "The histogram shows the heights of 40 plants. Each bar includes its left endpoint but not its right endpoint.\n\nHow many plants are at least 20 centimeters tall?", choices: ["20", "12", "8", "34"], answer: 0, explain: "Both the 20–30 bin (12) and the 30–40 bin (8) count, for 20 plants. 12 stops after the first qualifying bin.", pattern: "Reading Values and Basic Statistics Directly from a Graph or Table", difficulty: "easy", figure: {"kind": "histogram", "x": {"label": "Height (centimeters)", "min": 0, "max": 40, "step": 10}, "y": {"label": "Number of plants", "min": 0, "max": 16, "step": 2}, "bins": [{"from": 0, "to": 10, "count": 6}, {"from": 10, "to": 20, "count": 14}, {"from": 20, "to": 30, "count": 12}, {"from": 30, "to": 40, "count": 8}]}, trapFor: [null, 2, 2, null], },
  { q: "The bar graph shows how many siblings each student in a class has.\n\nHow many students have at least 2 siblings?", choices: ["7", "5", "16", "2"], answer: 0, explain: "Students with 2 siblings (5) and with 3 siblings (2) both count: 7. Stopping at the first bin gives 5; 16 counts everyone with at least 1.", pattern: "Reading Values and Basic Statistics Directly from a Graph or Table", difficulty: "easy", figure: {"kind": "bar", "xLabel": "Number of siblings", "y": {"label": "Number of students", "min": 0, "max": 10, "step": 2}, "bars": [{"label": "0", "value": 4}, {"label": "1", "value": 9}, {"label": "2", "value": 5}, {"label": "3", "value": 2}]}, trapFor: [null, 2, null, 2], },
  { q: "The dot plot shows the number of books each of 11 students read last month.\n\nWhich statement about the data is true?", choices: ["The mean is greater than the median.", "The median is greater than the mean.", "The mode is greater than the median.", "The mean, median, and mode are equal."], answer: 0, explain: "The median and mode are both 3, and the mean is 42/11 ≈ 3.8: the high value 9 pulls the mean above the median.", pattern: "Comparing Mean and Median to Detect Skew", difficulty: "medium", figure: {"kind": "dotplot", "x": {"label": "Number of books read", "min": 0, "max": 10, "step": 1}, "values": [1, 2, 2, 3, 3, 3, 4, 4, 5, 6, 9]}, trapFor: [null, 1, null, null], },
  { q: "At a small company, most employees earn between $40,000 and $60,000 a year, but the owner earns $400,000. Which measure gives a better idea of a typical employee's salary, and why?", choices: ["The median, because the owner's salary pulls the mean far upward.", "The mean, because it is calculated using every salary at the company.", "The median, because the owner's salary pulls the median far upward.", "The mean, because the owner's salary pulls the mean downward."], answer: 0, explain: "One huge salary drags the mean up, while the median stays in the middle of the typical salaries. It's the mean, not the median, that the outlier distorts, and it pulls the mean up, not down.", pattern: "Comparing Mean and Median to Detect Skew", difficulty: "easy", trapFor: [null, 0, null, 1], },
  { q: "A histogram of a data set has a long tail extending to the left. Which statement about the data set is most likely true?", choices: ["The mean is less than the median.", "The mean is greater than the median.", "The mean and the median are equal.", "The standard deviation is zero."], answer: 0, explain: "A left tail means some unusually low values, which pull the mean down below the median.", pattern: "Comparing Mean and Median to Detect Skew", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "Two classes took the same test. Class A's scores were 70, 75, 80, 85, and 90. Class B's scores were 60, 70, 80, 90, and 100. Which statement is true?", choices: ["The means are equal, and Class B's scores have the larger standard deviation.", "The means are equal, and Class A's scores have the larger standard deviation.", "Class B has the larger mean, because its highest score is higher.", "The standard deviations are equal, because the means are equal."], answer: 0, explain: "Both means are 80. Class B's scores sit farther from 80, so its standard deviation is larger. Equal means say nothing about spread.", pattern: "Interpreting Standard Deviation as Spread", difficulty: "medium", trapFor: [null, null, null, 1], },
  { q: "Set I is 2, 4, 6, 8, 10. Set II is 12, 14, 16, 18, 20. Set III is 1, 6, 6, 6, 11. Which statement about the standard deviations of the sets is true?", choices: ["Sets I and II have equal standard deviations.", "Set II has a larger standard deviation because its values are larger.", "Set III has the smallest standard deviation because three values are equal.", "Set I has a larger standard deviation than Set III."], answer: 0, explain: "Set II is Set I shifted up by 10, which doesn't change the spread. Set III's 1 and 11 sit 5 away from its mean of 6, farther than any value in Set I, so Set III is the most spread out.", pattern: "Interpreting Standard Deviation as Spread", difficulty: "hard", trapFor: [null, 1, null, null], },
  { q: "The standard deviation of the weights of apples in Crate X is 12 grams, and in Crate Y it is 4 grams. Which conclusion is best supported?", choices: ["The apple weights in Crate X vary more than those in Crate Y.", "The apples in Crate X are heavier on average than those in Crate Y.", "Crate X contains three times as many apples as Crate Y.", "A typical apple in Crate X weighs about 12 grams."], answer: 0, explain: "Standard deviation measures how much the weights vary. It says nothing about the average weight or the number of apples.", pattern: "Interpreting Standard Deviation as Spread", difficulty: "easy", trapFor: [null, 1, null, 0], },
  { q: "A data set has a mean of 20 and a median of 18. If 5 is added to every value in the data set, what are the new mean and median?", choices: ["Mean 25, median 23", "Mean 25, median 18", "Mean 20, median 18", "Mean 100, median 90"], answer: 0, explain: "Adding 5 to every value shifts every measure of center up by 5. The median shifts too, since every value moves.", pattern: "How Changing a Data Set Changes Its Statistics", difficulty: "easy", trapFor: [null, 0, 2, null], },
  { q: "The data set 3, 7, 8, 12, 15 has a range of 12. If the value 10 is added to the data set, what happens to the range?", choices: ["It stays the same.", "It increases.", "It decreases.", "It becomes 10."], answer: 0, explain: "10 is between the minimum (3) and the maximum (15), so the range is still 15 - 3 = 12.", pattern: "How Changing a Data Set Changes Its Statistics", difficulty: "easy", trapFor: [null, 1, 1, null], },
  { q: "The mean of 8 numbers is 15. When a ninth number is added, the mean of the 9 numbers is 16. What is the ninth number?", choices: ["24", "16", "1", "31"], answer: 0, explain: "The 8 numbers total 8 × 15 = 120, and the 9 numbers total 9 × 16 = 144. The ninth number is 144 - 120 = 24.", pattern: "How Changing a Data Set Changes Its Statistics", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A data set of 9 values has a median of 40. Two values, 10 and 90, are added to the data set. What is the median of the new data set?", choices: ["40", "Less than 40", "Greater than 40", "It cannot be determined."], answer: 0, explain: "One new value is below 40 and one is above it, so 40 is still the middle value: the 6th of 11.", pattern: "How Changing a Data Set Changes Its Statistics", difficulty: "hard", trapFor: [null, 0, 0, null], },
  { q: "A teacher discovers that one score in a data set was recorded as 58 instead of 85. After the error is corrected, which statistic must increase?", choices: ["The mean", "The median", "The range", "The mode"], answer: 0, explain: "Raising any value by 27 raises the total, so the mean must increase. The median, range, and mode change only if that score sits in the middle, at an extreme, or among the most common values.", pattern: "How Changing a Data Set Changes Its Statistics", difficulty: "hard", trapFor: [null, 0, 1, null], },
],
  "m-two-var-data": [
  { q: "A scatterplot shows points rising steadily at a constant rate, forming a straight-line pattern. Which model best fits?", choices: ["Linear", "Quadratic", "Exponential", "No relationship"], answer: 0, explain: "A constant rate of increase forming a straight-line pattern is the definition of a linear relationship.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "In a linear regression, what does a residual represent?", choices: ["The actual y-value minus the predicted y-value", "The predicted y-value minus the actual y-value", "The slope of the line of best fit", "How strongly the two variables are correlated"], answer: 0, explain: "A residual is the actual value minus the predicted value from the model.", pattern: "Interpreting Residuals", difficulty: "easy", trapFor: [null, 0, null, 1], },
  { q: "A scatterplot shows a strong negative linear association between hours of TV watched and exam scores. Which best describes this relationship?", choices: ["As TV hours increase, exam scores tend to increase.", "As TV hours increase, exam scores tend to decrease.", "There is no relationship between TV hours and exam scores.", "TV hours cause exam scores to decrease."], answer: 1, explain: "A negative association means the two variables move in opposite directions, without necessarily implying causation.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A line of best fit for a data set is given by y = 2.5x + 10. What does the slope of 2.5 represent in context?", choices: ["The predicted value of y when x = 0.", "The predicted change in y for each 1-unit increase in x.", "The difference between the largest and smallest y-values.", "How closely the data points fall along the line."], answer: 1, explain: "In a linear model, the slope represents the predicted rate of change in y per unit increase in x.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A data set's scatterplot shows points that curve upward with an increasingly steep rate, consistent with repeated multiplicative growth. Which model best fits?", choices: ["Linear", "Exponential", "Constant", "Negative linear"], answer: 1, explain: "Increasingly steep, multiplicative growth is characteristic of an exponential model, not a straight line.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "medium", trapFor: [1, null, null, null], },
  { q: "In a scatterplot, a point far from the overall pattern of the other points is called a(n):", choices: ["Residual", "Outlier", "Intercept", "Coefficient"], answer: 1, explain: "A point that doesn't fit the general pattern of the data is called an outlier.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A line of best fit predicts y = 45 for a given x-value, but the actual observed y-value is 50. What is the residual?", choices: ["-5", "5", "45", "50"], answer: 1, explain: "Residual = actual - predicted = 50 - 45 = 5.", pattern: "Interpreting Residuals", difficulty: "easy", trapFor: [0, null, null, null], },
  { q: "A scatterplot shows data points scattered with no discernible pattern. What does this suggest about the relationship between the two variables?", choices: ["A strong positive linear relationship", "A strong negative linear relationship", "Little to no linear relationship", "A perfect exponential relationship"], answer: 2, explain: "Random scatter with no visible trend indicates little to no linear association between the variables.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Extrapolating a line of best fit far beyond the range of the original data is risky primarily because:", choices: ["The line's slope will change automatically.", "The relationship may not hold outside the observed data range.", "Residuals become negative.", "The y-intercept becomes invalid."], answer: 1, explain: "A model fit to a certain data range may not accurately describe the relationship for values well outside that range.", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "The scatterplot shows the number of hours each of 10 students studied and the student's test score. The line of best fit is y = 4.2x + 61.\n\nWhat test score does the line of best fit predict for a student who studied 5 hours?", choices: ["82", "65.2", "21", "90"], answer: 0, explain: "y = 4.2(5) + 61 = 21 + 61 = 82. 65.2 adds 4.2 once instead of five times; 21 leaves off the 61.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "easy", figure: {"kind": "scatter", "x": {"label": "Hours studied", "min": 0, "max": 8, "step": 1}, "y": {"label": "Test score", "min": 60, "max": 100, "step": 10}, "points": [[1, 64], [2, 68], [2, 71], [3, 72], [4, 79], [5, 78], [5, 85], [6, 86], [7, 90], [8, 93]], "line": {"slope": 4.2, "intercept": 61}}, trapFor: [null, null, null, null], },
  { q: "The scatterplot shows the number of hours each of 10 students studied and the student's test score. The line of best fit is y = 4.2x + 61.\n\nWhat is the residual for the student who studied 5 hours and scored 78?", choices: ["-4", "4", "78", "82"], answer: 0, explain: "The line predicts 82. Residual = actual - predicted = 78 - 82 = -4. Subtracting the other way gives 4.", pattern: "Interpreting Residuals", difficulty: "medium", figure: {"kind": "scatter", "x": {"label": "Hours studied", "min": 0, "max": 8, "step": 1}, "y": {"label": "Test score", "min": 60, "max": 100, "step": 10}, "points": [[1, 64], [2, 68], [2, 71], [3, 72], [4, 79], [5, 78], [5, 85], [6, 86], [7, 90], [8, 93]], "line": {"slope": 4.2, "intercept": 61}}, trapFor: [null, 0, null, null], },
  { q: "The scatterplot shows a data set and its line of best fit, y = -1.5x + 40.\n\nWhat is the residual for the data point (10, 28)?", choices: ["3", "-3", "25", "28"], answer: 0, explain: "The line predicts -1.5(10) + 40 = 25, so the residual is 28 - 25 = 3. Predicted minus actual gives -3.", pattern: "Interpreting Residuals", difficulty: "medium", figure: {"kind": "scatter", "x": {"label": "x", "min": 0, "max": 16, "step": 2}, "y": {"label": "y", "min": 0, "max": 45, "step": 5}, "points": [[0, 41], [2, 36], [4, 35], [6, 30], [8, 29], [10, 28], [12, 21], [14, 20], [16, 16]], "line": {"slope": -1.5, "intercept": 40}}, trapFor: [null, 0, null, null], },
  { q: "A data point on a scatterplot has a residual of -6 with respect to the line of best fit. Which statement must be true?", choices: ["The point lies 6 units below the line.", "The point lies 6 units above the line.", "The line has a slope of -6.", "The data have a negative correlation."], answer: 0, explain: "A negative residual means actual < predicted, so the point sits below the line. A residual describes one point, not the line's slope or the overall correlation.", pattern: "Interpreting Residuals", difficulty: "easy", trapFor: [null, 0, 1, 1], },
  { q: "The scatterplot shows the points (1, 7), (3, 8), and (5, 10) and the line of best fit y = 2x + 3.\n\nWhich point has the largest positive residual?", choices: ["(1, 7)", "(3, 8)", "(5, 10)", "All three residuals are equal."], answer: 0, explain: "Predicted values are 5, 9, and 13, so the residuals are 7 - 5 = 2, 8 - 9 = -1, and 10 - 13 = -3. Only (1, 7) has a positive residual. Computing predicted minus actual would make (5, 10) look largest.", pattern: "Interpreting Residuals", difficulty: "hard", figure: {"kind": "scatter", "x": {"label": "x", "min": 0, "max": 6, "step": 1}, "y": {"label": "y", "min": 0, "max": 16, "step": 2}, "points": [[1, 7], [3, 8], [5, 10]], "line": {"slope": 2, "intercept": 3}}, trapFor: [null, null, 0, null], },
  { q: "Which description of the residuals suggests that a line of best fit is a good model for the data?", choices: ["The residuals are small and show no clear pattern.", "All of the residuals are positive.", "The residuals increase steadily as x increases.", "The residuals are all equal to the slope."], answer: 0, explain: "A good linear fit leaves small, patternless residuals. All-positive residuals mean the line runs too low, and a steady trend in the residuals means the data curve away from the line.", pattern: "Interpreting Residuals", difficulty: "medium", trapFor: [null, null, null, 1], },
  { q: "A model predicts that a plant will be 14.5 centimeters tall after 20 days. The plant's actual height after 20 days is 13.2 centimeters. What is the residual?", choices: ["-1.3", "1.3", "13.2", "27.7"], answer: 0, explain: "Residual = actual - predicted = 13.2 - 14.5 = -1.3. Predicted minus actual gives 1.3.", pattern: "Interpreting Residuals", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "The table shows four values of x and their corresponding values of y.\n\nWhich type of model best fits the data in the table?", choices: ["Exponential growth", "Linear growth", "Exponential decay", "Linear decay"], answer: 0, explain: "Each y-value is double the one before, so y grows by a constant factor: exponential growth. Linear growth would add the same amount each time, but the increases are 5, 10, and 20.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "easy", figure: {"kind": "table", "header": ["x", "y"], "rows": [[0, 5], [1, 10], [2, 20], [3, 40]]}, trapFor: [null, 1, null, null], },
  { q: "The table shows the value of y for each of four values of x.\n\nWhich type of model best fits these data?", choices: ["Linear decay", "Exponential decay", "Linear growth", "Exponential growth"], answer: 0, explain: "y drops by the same amount, 6, each time, so the decrease is linear. Exponential decay would drop by the same percent each time.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "easy", figure: {"kind": "table", "header": ["x", "y"], "rows": [[0, 50], [1, 44], [2, 38], [3, 32]]}, trapFor: [null, 1, null, null], },
  { q: "The table shows four values of x and their corresponding values of y.\n\nWhich statement best describes the relationship between x and y?", choices: ["y decreases exponentially, halving each time x increases by 1.", "y decreases linearly, falling by 400 each time x increases by 1.", "y decreases linearly, falling by about 233 each time x increases by 1.", "y increases exponentially, doubling each time x increases by 1."], answer: 0, explain: "The drops are 400, 200, and 100, which aren't constant, but each value is half the one before: exponential decay. The first drop alone makes it look linear.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "medium", figure: {"kind": "table", "header": ["x", "y"], "rows": [[0, 800], [1, 400], [2, 200], [3, 100]]}, trapFor: [null, 0, 0, null], },
  { q: "The population of a town, in thousands, x years after 2000 is modeled by y = 12(1.03)^x. What does 1.03 represent in this model?", choices: ["The population grows by 3% each year.", "The population grows by 1.03 thousand people each year.", "The population grows by 103% each year.", "The population in 2000 was 1.03 thousand."], answer: 0, explain: "Multiplying by 1.03 each year adds 3% of the current population. Adding 1.03 thousand each year would be a linear model; 12 is the population in 2000.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "The line of best fit y = 0.8x + 12 models the price y, in dollars, of a large pizza with x toppings at several restaurants. What does 12 represent in this model?", choices: ["The predicted price of a large pizza with no toppings", "The predicted increase in price for each added topping", "The number of toppings on the most expensive pizza", "The price of each topping, in dollars"], answer: 0, explain: "12 is the value of y when x = 0: the predicted price with no toppings. 0.8 is the predicted increase per topping.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "The scatterplot shows a data set in which y increases as x increases.\n\nWhich equation could model the data?", choices: ["y = 3(1.2)^x", "y = 3 + 1.2x", "y = 3(0.8)^x", "y = 3 - 1.2x"], answer: 0, explain: "Increases that keep getting larger mean growth by a factor: y = 3(1.2)^x. y = 3 + 1.2x grows by the same 1.2 each time, and the other two decrease.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "medium", figure: {"kind": "scatter", "x": {"label": "x", "min": 0, "max": 10, "step": 1}, "y": {"label": "y", "min": 0, "max": 20, "step": 5}, "points": [[0, 3.0], [1, 3.6], [2, 4.32], [3, 5.18], [4, 6.22], [5, 7.46], [6, 8.96], [7, 10.75], [8, 12.9], [9, 15.48], [10, 18.58]]}, trapFor: [null, 0, null, null], },
  { q: "The scatterplot shows the heights of children aged 2 to 10 years, along with the line of best fit y = 2.5x + 31, where y is height in inches and x is age in years.\n\nWhich is the best reason NOT to use this line to predict the height of a 40-year-old?", choices: ["Age 40 is far outside the range of ages used to create the model.", "The slope of 2.5 is too small to give a meaningful prediction.", "The model would predict a height of less than 31 inches.", "The y-intercept of the model changes for adults."], answer: 0, explain: "The model describes growth between ages 2 and 10. People stop growing, so extending the line to 40 (131 inches) makes no sense.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "medium", figure: {"kind": "scatter", "x": {"label": "Age (years)", "min": 2, "max": 10, "step": 1}, "y": {"label": "Height (inches)", "min": 30, "max": 60, "step": 5}, "points": [[2, 36], [3, 38.5], [4, 41], [5, 43], [6, 46], [7, 48.5], [8, 51], [9, 53], [10, 56]], "line": {"slope": 2.5, "intercept": 31}}, trapFor: [null, null, null, null], },
  { q: "Which description of a scatterplot indicates the strongest negative linear association between x and y?", choices: ["The points fall close to a line that slopes downward.", "The points are loosely scattered around a line that slopes downward.", "The points fall close to a line that slopes upward.", "The points are spread out with no visible trend."], answer: 0, explain: "Negative means y tends to decrease as x increases (a downward slope), and strong means the points stay close to the line.", pattern: "Choosing the Right Model Shape from a Scatterplot's Pattern", difficulty: "easy", trapFor: [null, null, null, null], },
],
  "m-probability": [
  { q: "A bag has 4 red and 6 blue marbles. What is the probability of drawing a red marble?", choices: ["4/10", "6/10", "4/6", "1/4"], answer: 0, explain: "4 red out of 10 total = 4/10.", pattern: "Basic and Compound Probability", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Two independent events A and B have P(A) = 0.5 and P(B) = 0.4. What is P(A and B)?", choices: ["0.9", "0.2", "0.1", "0.45"], answer: 1, explain: "For independent events, P(A and B) = P(A) × P(B) = 0.5 × 0.4 = 0.2.", pattern: "Basic and Compound Probability", difficulty: "easy", trapFor: [0, null, null, null], },
  { q: "A standard six-sided die is rolled. What is the probability of rolling a number greater than 4?", choices: ["1/6", "1/3", "1/2", "2/3"], answer: 1, explain: "Numbers greater than 4 are 5 and 6, so 2 out of 6 outcomes = 1/3.", pattern: "Basic and Compound Probability", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A survey of 200 people finds that 120 own a car and 80 own a bike, with 50 owning both. What is the probability that a randomly selected person owns at least one of the two?", choices: ["0.65", "0.75", "0.85", "1.00"], answer: 1, explain: "P(car or bike) = P(car) + P(bike) - P(both) = 120/200 + 80/200 - 50/200 = 150/200 = 0.75.", pattern: "Basic and Compound Probability", difficulty: "medium", trapFor: [null, null, null, 1], },
  { q: "A deck has 52 cards. What is the probability of drawing a card that is a heart, given that the card drawn is red?", choices: ["1/4", "1/2", "1/13", "1/26"], answer: 1, explain: "All red cards are either hearts or diamonds (26 total), and 13 of those are hearts: 13/26 = 1/2.", pattern: "Conditional Probability", difficulty: "medium", trapFor: [0, null, null, null], },
  { q: "Two dice are rolled. What is the probability that both show a 6?", choices: ["1/6", "1/3", "1/36", "1/18"], answer: 2, explain: "P(6 and 6) = (1/6)(1/6) = 1/36, since the rolls are independent. Adding 1/6 + 1/6 = 1/3 would be the 'or'-style mistake.", pattern: "Basic and Compound Probability", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "In a class of 30 students, 18 play soccer and 12 play basketball, with 6 playing both. What is the probability a randomly chosen student plays neither sport?", choices: ["0.1", "0.2", "0.3", "0.4"], answer: 1, explain: "P(soccer or basketball) = 18/30 + 12/30 - 6/30 = 24/30 = 0.8, so P(neither) = 1 - 0.8 = 0.2.", pattern: "Basic and Compound Probability", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A weighted coin lands heads 70% of the time. If flipped twice, what is the probability of getting heads both times?", choices: ["0.35", "0.49", "0.70", "1.40"], answer: 1, explain: "P(heads and heads) = 0.7 × 0.7 = 0.49, assuming independent flips.", pattern: "Basic and Compound Probability", difficulty: "easy", trapFor: [null, null, null, 0], },
  { q: "A jar has 3 green, 5 yellow, and 2 purple marbles. What is the probability of NOT drawing a yellow marble?", choices: ["1/2", "1/4", "3/10", "1/3"], answer: 0, explain: "P(yellow) = 5/10 = 1/2, so P(not yellow) = 1 - 1/2 = 1/2. 3/10 mistakes the probability of drawing green for the answer.", pattern: "Basic and Compound Probability", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A medical test correctly gives a negative result for 95% of people who do not have a certain condition. Among 400 tested people who do not have the condition, about how many would be expected to receive a false positive result?", choices: ["10", "20", "30", "40"], answer: 1, explain: "The test is wrong for 5% of people without the condition: 5% of 400 = 20 false positives.", pattern: "Conditional Probability", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "The table summarizes the answers of 200 students who were asked whether they prefer online or in-person classes.\n\nIf a student who prefers online classes is selected at random, what is the probability that the student is in 10th grade?", choices: ["33/53", "3/5", "33/100", "20/53"], answer: 0, explain: "106 students prefer online (40 + 66), and 66 of them are tenth graders: 66/106 = 33/53. 3/5 is the chance a tenth grader prefers online, the reverse condition; 33/100 divides by all 200 students.", pattern: "Conditional Probability", difficulty: "hard", figure: {"kind": "table", "header": ["", "Online", "In person", "Total"], "rows": [["9th grade", 40, 50, 90], ["10th grade", 66, 44, 110], ["Total", 106, 94, 200]]}, trapFor: [null, 1, 0, null], },
  { q: "The table summarizes the answers of 200 students who were asked whether they prefer online or in-person classes.\n\nIf a 10th grader is selected at random, what is the probability that the student prefers online classes?", choices: ["3/5", "33/53", "33/100", "2/5"], answer: 0, explain: "Only the 110 tenth graders count, and 66 of them prefer online: 66/110 = 3/5. 33/53 is the reverse question; 2/5 is the tenth graders who prefer in-person.", pattern: "Conditional Probability", difficulty: "medium", figure: {"kind": "table", "header": ["", "Online", "In person", "Total"], "rows": [["9th grade", 40, 50, 90], ["10th grade", 66, 44, 110], ["Total", 106, 94, 200]]}, trapFor: [null, 1, 0, null], },
  { q: "The table shows 150 plants classified by flower color and height.\n\nIf a white plant is selected at random, what is the probability that it is short?", choices: ["11/20", "11/30", "11/15", "1/2"], answer: 0, explain: "Only the 100 white plants count, and 55 are short: 55/100 = 11/20. 11/30 divides by all 150 plants; 11/15 divides by the 75 short plants, which answers 'given short, what's the chance it's white?'", pattern: "Conditional Probability", difficulty: "medium", figure: {"kind": "table", "header": ["", "Tall", "Short", "Total"], "rows": [["Red", 30, 20, 50], ["White", 45, 55, 100], ["Total", 75, 75, 150]]}, trapFor: [null, 0, 1, null], },
  { q: "The table shows 150 plants classified by flower color and height.\n\nIf a tall plant is selected at random, what is the probability that it is red?", choices: ["2/5", "3/5", "1/5", "2/3"], answer: 0, explain: "There are 30 + 45 = 75 tall plants, and 30 are red: 30/75 = 2/5. 3/5 is the chance a red plant is tall; 1/5 divides by all 150 plants.", pattern: "Conditional Probability", difficulty: "medium", figure: {"kind": "table", "header": ["", "Tall", "Short", "Total"], "rows": [["Red", 30, 20, 50], ["White", 45, 55, 100], ["Total", 75, 75, 150]]}, trapFor: [null, 1, 0, null], },
  { q: "At a school, 60% of students take a language class, and 25% of students take both a language class and an art class. If a student who takes a language class is chosen at random, what is the probability that the student also takes art?", choices: ["5/12", "1/4", "3/20", "17/20"], answer: 0, explain: "Restrict to language students: 0.25 ÷ 0.60 = 5/12. 1/4 uses all students as the denominator.", pattern: "Conditional Probability", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "Two fair six-sided dice are rolled. Given that the sum of the dice is 8, what is the probability that both dice show a 4?", choices: ["1/5", "1/36", "1/6", "5/36"], answer: 0, explain: "Only 5 outcomes sum to 8: (2, 6), (3, 5), (4, 4), (5, 3), (6, 2). One of them is (4, 4), so the probability is 1/5. 1/36 ignores the condition.", pattern: "Conditional Probability", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "In a group of 40 people, 24 have a dog, and 10 have both a dog and a cat. If a dog owner is selected at random, what is the probability that the person also has a cat?", choices: ["5/12", "1/4", "3/5", "7/12"], answer: 0, explain: "Restrict to the 24 dog owners: 10/24 = 5/12. 1/4 divides by all 40 people; 7/12 is the dog owners without a cat.", pattern: "Conditional Probability", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "Machine A makes 600 items a day, and 3% of them are defective. Machine B makes 400 items a day, and 5% of them are defective. If a defective item from one day is chosen at random, what is the probability that it came from Machine A?", choices: ["9/19", "3/8", "3/5", "9/500"], answer: 0, explain: "Machine A makes 18 defective items and Machine B makes 20, so 18 of the 38 defective items came from A: 9/19. 3/5 is A's share of all items, not of defective ones; 9/500 divides by all 1,000 items.", pattern: "Conditional Probability", difficulty: "hard", trapFor: [null, null, null, 0], },
  { q: "A spinner has 8 equal sections numbered 1 through 8. What is the probability that the spinner lands on a number that is even or greater than 5?", choices: ["5/8", "7/8", "3/16", "1/4"], answer: 0, explain: "The qualifying numbers are 2, 4, 6, 7, and 8: 5/8. Adding 4/8 + 3/8 = 7/8 counts 6 and 8 twice.", pattern: "Basic and Compound Probability", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "A fair coin is flipped 3 times. What is the probability that it lands heads all 3 times?", choices: ["1/8", "1/6", "1/2", "3/8"], answer: 0, explain: "Each flip is independent: (1/2)(1/2)(1/2) = 1/8.", pattern: "Basic and Compound Probability", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A bag contains 5 red, 3 blue, and 2 green tiles. A tile is drawn at random and put back, and then a second tile is drawn. What is the probability that both tiles are red?", choices: ["1/4", "1", "2/9", "1/2"], answer: 0, explain: "With replacement the draws are independent: (5/10)(5/10) = 1/4. Adding 1/2 + 1/2 = 1 treats 'and' like 'or'; 2/9 is the answer without replacement.", pattern: "Basic and Compound Probability", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "A bag contains 5 red, 3 blue, and 2 green tiles. Two tiles are drawn at random without replacement. What is the probability that both tiles are red?", choices: ["2/9", "1/4", "1/5", "4/9"], answer: 0, explain: "After one red is drawn, 4 of the 9 remaining tiles are red: (5/10)(4/9) = 20/90 = 2/9. 1/4 assumes the first tile was put back.", pattern: "Basic and Compound Probability", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "The probability of rain on Saturday is 0.3, and the probability of rain on Sunday is 0.4. The two events are independent. What is the probability that it rains on neither day?", choices: ["0.42", "0.3", "0.12", "0.58"], answer: 0, explain: "No rain Saturday (0.7) and no rain Sunday (0.6): 0.7 × 0.6 = 0.42. 0.3 comes from 1 - (0.3 + 0.4), adding probabilities that should be multiplied; 0.58 is rain on at least one day.", pattern: "Basic and Compound Probability", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "An integer from 1 through 20 is chosen at random. What is the probability that it is a multiple of 3 or a multiple of 5?", choices: ["9/20", "1/2", "1/20", "3/50"], answer: 0, explain: "There are 6 multiples of 3 and 4 multiples of 5, but 15 is both, so 6 + 4 - 1 = 9 numbers qualify: 9/20. 1/2 counts 15 twice.", pattern: "Basic and Compound Probability", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "A class of 25 students includes 15 who play an instrument. Two students are chosen at random, one after the other, without replacement. What is the probability that both play an instrument?", choices: ["7/20", "9/25", "6/5", "3/5"], answer: 0, explain: "(15/25)(14/24) = 210/600 = 7/20. 9/25 assumes the first student could be chosen again; 6/5 adds the probabilities instead of multiplying.", pattern: "Basic and Compound Probability", difficulty: "hard", trapFor: [null, null, 0, null], },
],
  "m-inference": [
  { q: "As sample size increases, what typically happens to margin of error?", choices: ["It increases", "It decreases", "It stays the same", "It becomes zero"], answer: 1, explain: "Larger samples generally produce more precise estimates, decreasing margin of error.", pattern: "Sample Size's Effect on Margin of Error", difficulty: "easy", trapFor: [0, null, null, null], },
  { q: "A poll of 500 randomly selected voters is used to estimate an election outcome. This is an example of:", choices: ["A causal experiment", "Inference from sample statistics", "A controlled experiment", "An observational bias study"], answer: 1, explain: "Using a random sample to estimate a population parameter is sample-based statistical inference.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A 95% confidence interval for a population mean is (48, 56). Which statement correctly interprets this interval?", choices: ["It is plausible that the population mean is between 48 and 56.", "95% of the individual values in the population are between 48 and 56.", "The population mean is exactly 52.", "Every sample of this size will have a mean between 48 and 56."], answer: 0, explain: "The interval gives plausible values for the population mean. It says nothing about individual values, it doesn't pin the mean to 52, and other samples would produce somewhat different intervals.", pattern: "Interpreting Confidence Intervals Correctly", difficulty: "medium", trapFor: [null, 0, 1, 1], },
  { q: "A researcher increases the sample size from 100 to 400 while keeping the same confidence level. What is the most likely effect on the width of the confidence interval?", choices: ["It will widen.", "It will narrow.", "It will remain exactly the same.", "It cannot be determined."], answer: 1, explain: "Larger sample sizes generally produce narrower confidence intervals, reflecting more precise estimates.", pattern: "Sample Size's Effect on Margin of Error", difficulty: "hard", trapFor: [0, null, null, null], },
  { q: "A survey samples only people who visit a particular gym to estimate the exercise habits of an entire city's population. What is the main issue with this approach?", choices: ["The sample size is too large.", "The sample is not representative of the general population.", "Surveys cannot measure exercise habits.", "Gyms do not track visitor data."], answer: 1, explain: "Sampling only gym visitors introduces bias, since this group is unlikely to represent the exercise habits of the broader population.", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A random sample of 1,000 households finds an average of 2.3 children per household, with a margin of error of ±0.15. Which range best reflects a plausible value for the true population average?", choices: ["2.0 to 2.6", "2.15 to 2.45", "1.85 to 2.75", "2.3 exactly, with no range"], answer: 1, explain: "Margin of error is added and subtracted from the sample statistic: 2.3 ± 0.15 gives a range of 2.15 to 2.45.", pattern: "Interpreting Confidence Intervals Correctly", difficulty: "easy", trapFor: [null, null, null, 1], },
  { q: "Which sampling method is most likely to produce a sample that generalizes well to the overall population?", choices: ["Surveying only volunteers who respond to an online ad", "Randomly selecting participants from the full population", "Surveying only people in one specific neighborhood", "Surveying only people known personally to the researcher"], answer: 1, explain: "Random selection from the full population is designed specifically to minimize selection bias and support generalization.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A poll's margin of error is reported as ±3 percentage points at a 95% confidence level. What does this most accurately mean?", choices: ["The poll's estimate is guaranteed to be within 3 points of the true value.", "The true value is likely within 3 points of the poll's estimate.", "About 3% of the people surveyed gave answers that were not accurate.", "The number of people surveyed was about 3% of the population."], answer: 1, explain: "Margin of error at a given confidence level describes the plausible range around the estimate, not a claim about respondent honesty or exact sample size.", pattern: "Interpreting Confidence Intervals Correctly", difficulty: "medium", trapFor: [1, null, null, null], },
  { q: "A random sample of 400 adults in a city found that 32% walk to work. There are 150,000 adults in the city. Based on the sample, about how many adults in the city walk to work?", choices: ["48,000", "128", "102,000", "4,800"], answer: 0, explain: "32% of 150,000 = 48,000. 128 is the number in the sample (32% of 400); 102,000 is the adults who don't walk.", pattern: "Estimating a Population Count from a Sample Proportion", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "A random sample of 250 of a school's 1,800 students found that 45 of them bike to school. Based on the sample, about how many students at the school bike to school?", choices: ["324", "45", "1,476", "405"], answer: 0, explain: "45/250 = 18%, and 18% of 1,800 = 324. 45 is only the sample's count; 1,476 is the students who don't bike.", pattern: "Estimating a Population Count from a Sample Proportion", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "To estimate how many of a town's 20,000 residents use the public library, a researcher surveyed 200 people as they left the library. Of these, 180 said they use the library at least once a month. Which statement is true?", choices: ["The sample isn't representative, so it can't give a good estimate for the town.", "About 18,000 of the town's residents use the library at least once a month.", "About 180 of the town's residents use the library at least once a month.", "The sample is too small, since it includes only 1% of the town's residents."], answer: 0, explain: "Everyone surveyed was leaving the library, so library users are heavily overrepresented. Scaling 90% up to the town (18,000) repeats the bias; 200 people would be plenty if they had been chosen at random.", pattern: "Estimating a Population Count from a Sample Proportion", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "In a random sample of 80 boxes from a shipment of 5,000 boxes, 6 boxes were damaged. Based on the sample, what is the best estimate of the number of damaged boxes in the shipment?", choices: ["375", "6", "480", "4,625"], answer: 0, explain: "6/80 = 7.5%, and 7.5% of 5,000 = 375. 6 is just the sample's count, and 4,625 is the undamaged boxes.", pattern: "Estimating a Population Count from a Sample Proportion", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "A biologist catches 60 fish in a lake, tags them, and releases them. A week later, she catches 80 fish, and 12 of them are tagged. Assuming the tagged fish mixed evenly with the others, what is the best estimate of the number of fish in the lake?", choices: ["400", "128", "16", "4,800"], answer: 0, explain: "The second catch is 12/80 = 15% tagged, so the 60 tagged fish are about 15% of the lake: 60 ÷ 0.15 = 400. 16 comes from setting up the proportion upside down.", pattern: "Estimating a Population Count from a Sample Proportion", difficulty: "hard", trapFor: [null, null, 0, null], },
  { q: "Based on a random sample, an estimated 0.8% of the 12,500 households in a town have a solar water heater. Which is the best estimate of the number of households in the town with a solar water heater?", choices: ["100", "1,000", "10", "12,400"], answer: 0, explain: "0.8% is 0.008, and 0.008 × 12,500 = 100. Using 0.08 (8%) gives 1,000.", pattern: "Estimating a Population Count from a Sample Proportion", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A random sample of 900 voters estimated that 54% support a proposal, with a margin of error of 3.5 percentage points. Which is the most appropriate conclusion?", choices: ["It is plausible that 50.5% to 57.5% of all voters support the proposal.", "Between 50.5% and 57.5% of the voters in the sample support the proposal.", "Exactly 54% of all voters support the proposal.", "It is certain that a majority of all voters support the proposal."], answer: 0, explain: "54 ± 3.5 gives plausible values for all voters from 50.5% to 57.5%. In the sample, exactly 54% supported it, and neither 'exactly 54%' nor 'certain' fits an estimate.", pattern: "Interpreting Confidence Intervals Correctly", difficulty: "medium", trapFor: [null, 0, 1, 1], },
  { q: "A study estimates that the mean commute time of a city's workers is 27 minutes, with a margin of error of 4 minutes. Which value is NOT a plausible value for the true mean commute time?", choices: ["32 minutes", "23.5 minutes", "27 minutes", "30 minutes"], answer: 0, explain: "The plausible values run from 27 - 4 = 23 to 27 + 4 = 31 minutes. Only 32 falls outside that range.", pattern: "Interpreting Confidence Intervals Correctly", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Two random samples were used to estimate the mean height of a type of seedling. Sample A gave 14.2 cm with a margin of error of 0.6 cm. Sample B gave 14.5 cm with a margin of error of 1.5 cm. Both used the same confidence level. Which is the most likely reason Sample B's margin of error is larger?", choices: ["Sample B was smaller than Sample A.", "Sample B was larger than Sample A.", "The seedlings in Sample B were taller.", "Sample B used a lower confidence level."], answer: 0, explain: "At the same confidence level, a smaller sample gives a less precise estimate and a larger margin of error. A larger sample would shrink it.", pattern: "Sample Size's Effect on Margin of Error", difficulty: "medium", trapFor: [null, 0, null, 1], },
  { q: "A 95% confidence interval for the proportion of a school's students who own a bike is 0.42 to 0.50. Which statement is supported by the interval?", choices: ["It is plausible that at most half of the school's students own a bike.", "Exactly 46% of the school's students own a bike.", "Between 42% and 50% of the students in every class own a bike.", "It is certain that at least 42% of the students own a bike."], answer: 0, explain: "Every value in the interval is at most 0.50, so 'at most half' is plausible. The interval doesn't give an exact value, describe each class, or make anything certain.", pattern: "Interpreting Confidence Intervals Correctly", difficulty: "medium", trapFor: [null, 1, 0, 1], },
  { q: "An interval estimate of the mean household size is 2.4 to 2.8 people for Town A and 2.7 to 3.1 people for Town B. Which conclusion is best supported?", choices: ["It is unclear which town has the larger mean, because the intervals overlap.", "Town B has a larger mean household size than Town A does.", "Every household in Town B is larger than every household in Town A.", "Town A has a larger mean household size, since its interval starts lower."], answer: 0, explain: "Values from 2.7 to 2.8 are plausible for both towns, so the data don't settle which mean is larger. The intervals describe means, not individual households.", pattern: "Interpreting Confidence Intervals Correctly", difficulty: "hard", trapFor: [null, 1, 0, null], },
  { q: "A researcher reports that the mean amount of sleep for teens in a district is 7.1 hours per night, with a margin of error of 0.3 hours at a 95% confidence level. Which is the best interpretation?", choices: ["The mean for all teens in the district is plausibly between 6.8 and 7.4 hours.", "95% of the district's teens sleep between 6.8 and 7.4 hours per night.", "Every teen in the district sleeps at least 6.8 hours per night.", "The mean for all teens in the district is certainly between 6.8 and 7.4 hours."], answer: 0, explain: "The interval is about the population mean, not individual teens, and it gives plausible values rather than a guarantee.", pattern: "Interpreting Confidence Intervals Correctly", difficulty: "easy", trapFor: [null, 0, 0, 1], },
  { q: "A polling company wants a smaller margin of error for its next poll without changing its confidence level. What should it do?", choices: ["Survey a larger random sample.", "Survey a smaller random sample.", "Raise the confidence level to 99%.", "Survey only people likely to respond."], answer: 0, explain: "Larger random samples give more precise estimates. Raising the confidence level widens the margin of error, and surveying only likely responders adds bias.", pattern: "Sample Size's Effect on Margin of Error", difficulty: "easy", trapFor: [null, 0, 1, null], },
  { q: "Poll X surveyed 300 randomly chosen residents of a city, and Poll Y surveyed 1,200 randomly chosen residents of the same city. Both polls asked the same question and used a 95% confidence level. Which is most likely true?", choices: ["Poll Y has a smaller margin of error than Poll X.", "Poll X has a smaller margin of error than Poll Y.", "The two polls have the same margin of error.", "Poll Y's estimate equals the true value."], answer: 0, explain: "Poll Y's much larger sample gives a more precise estimate, so its margin of error is smaller. No poll's estimate is guaranteed to equal the true value.", pattern: "Sample Size's Effect on Margin of Error", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "A researcher uses the same sample to build a 90% confidence interval and a 99% confidence interval for a population mean. How does the 99% interval compare with the 90% interval?", choices: ["It is wider.", "It is narrower.", "It is the same width.", "It is centered on a higher value."], answer: 0, explain: "To be more confident of capturing the mean, the interval has to cover more values, so it gets wider. Both intervals are centered on the same sample mean.", pattern: "Sample Size's Effect on Margin of Error", difficulty: "medium", trapFor: [null, 1, null, null], },
],
  "m-statistical-claims": [
  { q: "A study randomly assigns participants to two groups and finds a treatment effect. What can be concluded?", choices: ["Correlation only, no causation", "A causal relationship, due to random assignment", "The result applies to all people everywhere", "Nothing can be concluded"], answer: 1, explain: "Random assignment in an experiment supports a causal conclusion for the sampled population.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "An observational study finds ice cream sales correlate with drowning incidents. What's the best interpretation?", choices: ["Hot weather likely increases both ice cream sales and swimming.", "Eating ice cream makes people more likely to drown.", "Drowning incidents lead people to buy more ice cream.", "The study proves that one of the trends causes the other."], answer: 0, explain: "Without random assignment, a lurking/confounding variable is the most reasonable explanation for correlation.", pattern: "Distinguishing Correlation from Causation", difficulty: "easy", trapFor: [null, 0, 0, 0], },
  { q: "A study finds that students who take music lessons have higher test scores, but the study did not randomly assign students to take lessons. What is the most appropriate conclusion?", choices: ["Music lessons are associated with higher scores but may not cause them.", "Taking music lessons causes students to earn higher test scores.", "The study shows no connection between music lessons and test scores.", "Music lessons would raise the test scores of any student who took them."], answer: 0, explain: "Without random assignment, the study can only establish association, not a definitive causal claim.", pattern: "Distinguishing Correlation from Causation", difficulty: "medium", trapFor: [null, 0, null, 0], },
  { q: "A company claims a new supplement causes weight loss based on a study with no control group. What is the primary weakness of this claim?", choices: ["Without a control group, other causes of the weight loss can't be ruled out.", "The study included too many participants to draw clear conclusions.", "Weight loss is too difficult to measure accurately in a study.", "The participants may not have liked the taste of the supplement."], answer: 0, explain: "A control group is needed to isolate the supplement's effect from other possible causes of weight change.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "medium", trapFor: [null, 0, 0, 0], },
  { q: "A randomized controlled trial with random assignment and a placebo group finds a drug reduces symptoms significantly more than the placebo. What can be concluded about this sampled population?", choices: ["The drug likely caused the greater symptom reduction in this population.", "Only an association between the drug and symptom relief is supported.", "The drug's effect is proven for every patient who has the condition.", "The placebo group's improvement shows that the drug had no effect."], answer: 0, explain: "Random assignment plus a placebo control is specifically designed to support causal conclusions for the population studied.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "medium", trapFor: [null, null, 1, null], },
  { q: "A study is conducted on a randomly selected, representative sample of a country's population, but no random assignment to groups occurs. What can this study's results be generalized to?", choices: ["The broader population, but only in terms of association, not causation.", "The broader population, including strong causal claims.", "Only the specific individuals studied.", "No generalization is possible at all."], answer: 0, explain: "Random sampling (not random assignment) supports generalizing findings to the broader population, but only in terms of association.", pattern: "Distinguishing Correlation from Causation", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "A researcher wants to determine if a new teaching method causes improved learning outcomes. Which study design would best support a causal claim?", choices: ["Surveying students who already chose the new method versus those who didn't.", "Randomly assigning students to either the new method or the traditional method.", "Interviewing teachers about their opinions of the method.", "Reviewing historical grades from before the method existed."], answer: 1, explain: "Random assignment to conditions is the design feature that specifically supports causal conclusions, unlike self-selected or observational comparisons.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A study observes that neighborhoods with more parks have lower crime rates, but does not randomly assign parks to neighborhoods. What is the most appropriate conclusion?", choices: ["The two are associated, but other factors may explain the link.", "Building more parks in a neighborhood will directly lower its crime rate.", "Neighborhoods with high crime rates choose to build fewer parks.", "The study shows that parks have no effect at all on crime."], answer: 0, explain: "Without random assignment, only an association can be claimed; other factors (like neighborhood investment) may explain both variables.", pattern: "Distinguishing Correlation from Causation", difficulty: "medium", trapFor: [null, 0, 0, null], },
  { q: "Researchers surveyed 2,000 randomly selected adults in a country and found that those who drank more coffee reported fewer headaches. Which conclusion is best supported?", choices: ["Among the country's adults, drinking more coffee is associated with fewer headaches.", "Drinking coffee prevents headaches among the country's adults.", "The association applies only to the 2,000 adults who were surveyed.", "Adults in the country who get headaches should drink more coffee."], answer: 0, explain: "Random sampling lets the association extend to all the country's adults, but with no random assignment it can't show that coffee causes fewer headaches.", pattern: "Distinguishing Correlation from Causation", difficulty: "medium", trapFor: [null, 0, null, 0], },
  { q: "Cities with more fire trucks tend to have more fires each year. Which is the most likely explanation for this association?", choices: ["Larger cities tend to have both more fire trucks and more fires.", "Fire trucks cause fires to break out in cities.", "Having many fires makes a city's fire trucks less effective.", "The association proves that fire trucks do not prevent fires."], answer: 0, explain: "City size drives both numbers, a classic confounding variable. Nothing suggests trucks cause fires.", pattern: "Distinguishing Correlation from Causation", difficulty: "easy", trapFor: [null, 0, null, 1], },
  { q: "A study of 500 volunteers found that those who meditated daily reported lower stress than those who did not. The volunteers chose for themselves whether to meditate. Which conclusion is appropriate?", choices: ["Among these volunteers, daily meditation is associated with lower stress.", "Daily meditation caused lower stress among these volunteers.", "Daily meditation causes lower stress in all adults.", "Among all adults, daily meditation is associated with lower stress."], answer: 0, explain: "People chose whether to meditate (no random assignment), so only an association is supported, and volunteers aren't a random sample, so it applies only to them.", pattern: "Distinguishing Correlation from Causation", difficulty: "hard", trapFor: [null, 0, 0, null], },
  { q: "A study finds that students who eat breakfast earn higher grades than students who don't. Which of the following, if it differed between the two groups, could be a confounding variable?", choices: ["Family income, which could affect both breakfast habits and grades", "The number of students who took part in the study", "The day of the week on which grades were recorded", "The number of grades recorded for each student"], answer: 0, explain: "A confounding variable is linked to both breakfast and grades. Family income could affect both; the others aren't related to breakfast habits.", pattern: "Distinguishing Correlation from Causation", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Data from 50 countries show that countries with more internet users per person have longer average life expectancies. Which is the most reasonable interpretation?", choices: ["A country's wealth may lead to both more internet use and longer lives.", "Using the internet makes people in a country live longer.", "Living longer causes people in a country to use the internet more.", "The data show no relationship between the two variables."], answer: 0, explain: "A third factor such as wealth can raise both. The data show an association, but not that either one causes the other.", pattern: "Distinguishing Correlation from Causation", difficulty: "easy", trapFor: [null, 0, 0, null], },
  { q: "A random sample of 1,000 households in a state found a strong positive association between household size and the number of hours of television the household watches. Which conclusion is supported?", choices: ["Larger households in the state tend to watch more hours of television.", "Adding people to a household causes it to watch more television.", "Watching more television causes households to grow larger.", "The association holds only for the 1,000 households surveyed."], answer: 0, explain: "The random sample supports an association for the state's households, but no causal claim in either direction.", pattern: "Distinguishing Correlation from Causation", difficulty: "medium", trapFor: [null, 0, 0, null], },
  { q: "A researcher finds a strong negative association between the number of hours per week teens spend outdoors and how often they report feeling anxious. Which statement is supported?", choices: ["Teens who spend more time outdoors tend to report feeling anxious less often.", "Spending time outdoors reduces how often teens feel anxious.", "Anxious teens should be required to spend more time outdoors.", "Teens who spend more time outdoors tend to report feeling anxious more often."], answer: 0, explain: "A negative association means one goes up as the other goes down. That's all the data show; they don't show that time outdoors reduces anxiety.", pattern: "Distinguishing Correlation from Causation", difficulty: "easy", trapFor: [null, 0, 0, null], },
  { q: "A researcher randomly selected 300 students from a university and then randomly assigned half of them to use a new study app. The app group scored higher on the final exam. To whom can the conclusion that the app caused higher scores be applied?", choices: ["All students at the university", "Only the 150 students who used the app", "All college students in the country", "No one, because causal claims need a larger sample"], answer: 0, explain: "Random assignment supports a causal conclusion, and random selection from this university lets it extend to all of the university's students, but not beyond them.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "hard", trapFor: [null, null, null, 0], },
  { q: "A gym wants to know whether a new warm-up routine reduces injuries. Which study design would best allow the gym to conclude that the routine causes fewer injuries?", choices: ["Randomly assign members to the new routine or the old one, then compare injury rates.", "Compare injury rates of members who chose the new routine with those who didn't.", "Ask members whether they think the new routine has reduced their injuries.", "Compare this year's injury rate with last year's rate, before the routine existed."], answer: 0, explain: "Only random assignment makes the two groups alike in everything except the routine. Members who choose the routine may already be more careful.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "In an experiment, 80 volunteers were randomly assigned to sleep either 6 hours or 8 hours before taking a memory test. The 8-hour group scored higher on average. Which conclusion is appropriate?", choices: ["For people like these volunteers, more sleep likely caused the higher scores.", "More sleep causes higher memory scores for all adults.", "Only an association is shown, since the participants were volunteers.", "More sleep is proven to have raised every volunteer's score."], answer: 0, explain: "Random assignment supports cause and effect, but volunteers aren't a random sample of all adults. Using volunteers limits who the result applies to; it doesn't reduce the result to an association.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "hard", trapFor: [null, null, 0, 1], },
  { q: "An online poll on a news website asked visitors whether they supported a new tax, and 72% said no. Why can't this result be applied to all of the region's residents?", choices: ["The respondents chose to take part, so they may not represent all residents.", "The poll did not randomly assign respondents to different groups.", "A result of 72% is too high to be an accurate measurement.", "The poll asked only one question about the new tax."], answer: 0, explain: "Self-selected respondents (people who visit the site and choose to answer) can differ from the population. Random assignment matters for experiments, not for polls like this one.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A company found that employees who used its standing desks took fewer sick days than other employees. Employees could request a standing desk if they wanted one. What is the main flaw in concluding that standing desks cause fewer sick days?", choices: ["Employees who requested the desks may already have had healthier habits.", "The company may not have studied enough of its employees to be sure.", "Standing desks cost more than regular desks do.", "Sick days are recorded differently from one department to another."], answer: 0, explain: "Employees chose the desks, so the two groups may differ in ways that affect health. That self-selection, not the number of employees, is the flaw.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "In a randomized experiment, 200 patients were randomly assigned to take a new drug or a placebo. 30% of the drug group improved, and 28% of the placebo group improved. Which conclusion is best?", choices: ["The results give little evidence that the drug works better than the placebo.", "The drug is 2% more effective than the placebo, so it should be prescribed.", "Because of random assignment, the drug is proven to be effective.", "The placebo caused its group to improve more than the drug group did."], answer: 0, explain: "A 2-point difference between groups of about 100 is small enough to be chance. Random assignment makes a causal conclusion possible, but only if there's a real difference to explain.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "hard", trapFor: [null, 1, 1, null], },
  { q: "A school tried a new math curriculum in its honors classes, and those students scored higher than students in regular classes. What is the biggest problem with concluding that the curriculum caused the higher scores?", choices: ["Honors students would likely have scored higher even without the curriculum.", "The school may not have tested enough students to reach a conclusion.", "Math scores are difficult to compare fairly between different classes.", "The curriculum was used for only one school year."], answer: 0, explain: "The groups differed before the curriculum began, so the comparison can't separate the curriculum from the students. There was no random assignment.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "Which study design supports both a causal conclusion and generalizing that conclusion to a larger population?", choices: ["Randomly select people from the population, then randomly assign treatments.", "Randomly select people from the population, then let them choose treatments.", "Use volunteers, then randomly assign the volunteers to treatments.", "Use volunteers, then let the volunteers choose their own treatments."], answer: 0, explain: "Random selection supports generalizing to the population; random assignment supports cause and effect. Only the first design has both.", pattern: "Evaluating Study Design for Causal Claims", difficulty: "hard", trapFor: [null, null, null, null], },
],
  "m-area-volume": [
  { q: "A cube has a side length of 4. What is its volume?", choices: ["16", "48", "64", "12"], answer: 2, explain: "Volume = side³ = 4³ = 64.", pattern: "Composite Figures and Formula Selection", difficulty: "easy", trapFor: [0, null, null, null], },
  { q: "If a square's side length doubles, by what factor does its area increase?", choices: ["2", "4", "8", "16"], answer: 1, explain: "Area scales with the square of the linear scale factor: 2² = 4.", pattern: "Scale Factor Effects on Area and Volume", difficulty: "easy", trapFor: [0, null, 1, null], },
  { q: "A rectangular prism has length 6, width 4, and height 3. What is its volume?", choices: ["13", "72", "36", "24"], answer: 1, explain: "Volume = length × width × height = 6 × 4 × 3 = 72.", pattern: "Composite Figures and Formula Selection", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "The figure shows a right circular cylinder with a radius of 3 and a height of 10.\n\nWhat is the volume of the cylinder, in terms of π?", choices: ["30π", "60π", "90π", "100π"], answer: 2, explain: "Volume = πr²h = π(9)(10) = 90π.", pattern: "Composite Figures and Formula Selection", difficulty: "easy", figure: {"kind": "solid", "shape": "cylinder", "radius": 3, "height": 10, "labels": {"radius": "3", "height": "10"}}, trapFor: [null, null, null, null], },
  { q: "A triangle has a base of 8 and a height of 5. What is its area?", choices: ["13", "20", "40", "80"], answer: 1, explain: "Area = (1/2)(base)(height) = (1/2)(8)(5) = 20.", pattern: "Composite Figures and Formula Selection", difficulty: "easy", trapFor: [null, null, 0, null], },
  { q: "If a cube's side length triples, by what factor does its volume increase?", choices: ["3", "9", "27", "81"], answer: 2, explain: "Volume scales with the cube of the linear scale factor: 3³ = 27.", pattern: "Scale Factor Effects on Area and Volume", difficulty: "medium", trapFor: [0, 1, null, null], },
  { q: "A circle has a radius of 5. What is its area in terms of π?", choices: ["10π", "25π", "50π", "100π"], answer: 1, explain: "Area = πr² = π(25) = 25π.", pattern: "Composite Figures and Formula Selection", difficulty: "easy", trapFor: [0, null, null, 1], },
  { q: "A rectangular garden is 12 feet by 9 feet. What is its perimeter?", choices: ["21 feet", "42 feet", "48 feet", "108 feet"], answer: 1, explain: "Perimeter = 2(length + width) = 2(12 + 9) = 42 feet.", pattern: "Composite Figures and Formula Selection", difficulty: "easy", trapFor: [null, null, null, 0], },
  { q: "A sphere has a radius of 3. What is its volume in terms of π?", choices: ["12π", "27π", "36π", "108π"], answer: 2, explain: "Volume = (4/3)πr³ = (4/3)π(27) = 36π.", pattern: "Composite Figures and Formula Selection", difficulty: "medium", trapFor: [null, null, null, 0], },
  { q: "The figure shows a right circular cone with a radius of 4 and a height of 9.\n\nWhat is the volume of the cone, in terms of π?", choices: ["36π", "48π", "108π", "144π"], answer: 1, explain: "Volume = (1/3)πr²h = (1/3)π(16)(9) = 48π.", pattern: "Composite Figures and Formula Selection", difficulty: "medium", figure: {"kind": "solid", "shape": "cone", "radius": 4, "height": 9, "labels": {"radius": "4", "height": "9"}}, trapFor: [null, null, null, 0], },
  { q: "A rectangle's area is 60 square units and its width is 5. What is its length?", choices: ["10", "12", "15", "20"], answer: 1, explain: "Length = Area / width = 60 / 5 = 12.", pattern: "Composite Figures and Formula Selection", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "If a rectangular prism's length and width both double while height stays the same, by what factor does its volume increase?", choices: ["2", "4", "8", "16"], answer: 1, explain: "Volume depends on length × width × height; doubling two dimensions multiplies volume by 2 × 2 = 4.", pattern: "Scale Factor Effects on Area and Volume", difficulty: "medium", trapFor: [0, null, 1, null], },
  { q: "Two rectangles are similar, and each side of the larger rectangle is 3 times as long as the corresponding side of the smaller one. The area of the smaller rectangle is 12 square inches. What is the area of the larger rectangle, in square inches?", choices: ["108", "36", "324", "48"], answer: 0, explain: "Area scales by the square of the side ratio: 12 × 3² = 108. Multiplying by 3 treats area like length; 324 cubes the ratio, which is the rule for volume.", pattern: "Scale Factor Effects on Area and Volume", difficulty: "easy", trapFor: [null, 0, 1, null], },
  { q: "The radius and the height of a cylinder are both doubled. The volume of the new cylinder is how many times the volume of the original cylinder?", choices: ["8", "4", "2", "6"], answer: 0, explain: "V = πr²h. Doubling r multiplies r² by 4, and doubling h multiplies by 2 more: 4 × 2 = 8. 4 treats volume like area.", pattern: "Scale Factor Effects on Area and Volume", difficulty: "medium", trapFor: [null, 1, 0, null], },
  { q: "Two solids are similar. The ratio of their surface areas is 9 to 25. The volume of the smaller solid is 54 cubic centimeters. What is the volume of the larger solid, in cubic centimeters?", choices: ["250", "150", "90", "1,350"], answer: 0, explain: "Areas scale by k², so k² = 25/9 and k = 5/3. Volumes scale by k³ = 125/27: 54 × 125/27 = 250. 150 uses the area ratio for volume; 90 uses the side ratio.", pattern: "Scale Factor Effects on Area and Volume", difficulty: "hard", trapFor: [null, 1, 0, null], },
  { q: "A model car is built at a scale of 1 to 20. The model's windshield has an area of 12 square inches. What is the area of the actual car's windshield, in square inches?", choices: ["4,800", "240", "96,000", "480"], answer: 0, explain: "Lengths scale by 20, so areas scale by 20² = 400: 12 × 400 = 4,800. 240 scales area like length; 96,000 cubes the scale factor.", pattern: "Scale Factor Effects on Area and Volume", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "The figure shows a floor plan made of rectangles. All angles are right angles.\n\nWhat is the area of the floor plan?", choices: ["60", "90", "76", "40"], answer: 0, explain: "Split it into a 10-by-4 rectangle (40) and a 4-by-5 rectangle on top (the left side is 9, so 9 - 4 = 5): 40 + 20 = 60. 90 is the full 10-by-9 rectangle around it.", pattern: "Composite Figures and Formula Selection", difficulty: "medium", figure: {"points": {"P1": [0, 0], "P2": [10, 0], "P3": [10, 4], "P4": [4, 4], "P5": [4, 9], "P6": [0, 9]}, "polygons": [{"points": ["P1", "P2", "P3", "P4", "P5", "P6"], "shade": true}], "segments": [{"from": "P1", "to": "P2", "label": "10"}, {"from": "P2", "to": "P3", "label": "4"}, {"from": "P6", "to": "P1", "label": "9"}, {"from": "P5", "to": "P6", "label": "4"}], "angles": [{"vertex": "P1", "from": "P2", "to": "P6", "right": true}, {"vertex": "P2", "from": "P3", "to": "P1", "right": true}, {"vertex": "P6", "from": "P1", "to": "P5", "right": true}], "kind": "geometry"}, trapFor: [null, null, null, null], },
  { q: "The figure shows a window made of a rectangle topped by a semicircle. The semicircle's diameter is the top side of the rectangle.\n\nWhat is the area of the window?", choices: ["48 + 4.5π", "48 + 9π", "48 + 18π", "48 + 3π"], answer: 0, explain: "Rectangle: 6 × 8 = 48. The semicircle has radius 3, so its area is (1/2)π(3²) = 4.5π. 48 + 9π uses a full circle; 48 + 18π uses the diameter, 6, as the radius.", pattern: "Composite Figures and Formula Selection", difficulty: "medium", figure: {"points": {"A": [0, 0], "B": [6, 0], "C": [6, 8], "D": [0, 8], "O": [3, 8]}, "polygons": [{"points": ["A", "B", "C", "D"]}], "arcs": [{"center": "O", "radius": 3, "from": 0, "to": 180}], "segments": [{"from": "A", "to": "B", "label": "6"}, {"from": "B", "to": "C", "label": "8"}], "angles": [{"vertex": "A", "from": "B", "to": "D", "right": true}, {"vertex": "B", "from": "C", "to": "A", "right": true}], "kind": "geometry"}, trapFor: [null, null, 1, null], },
  { q: "The figure shows a circle inside a square. The circle touches all four sides of the square, and the square has a side length of 10.\n\nWhat is the area of the shaded region?", choices: ["100 - 25π", "100 - 100π", "100 - 10π", "25π"], answer: 0, explain: "The square's area is 100. The circle's diameter equals the side, 10, so its radius is 5 and its area is 25π. Shaded = 100 - 25π. 100 - 100π uses the diameter as the radius.", pattern: "Composite Figures and Formula Selection", difficulty: "hard", figure: {"points": {"A": [0, 0], "B": [10, 0], "C": [10, 10], "D": [0, 10], "O": [5, 5]}, "polygons": [{"points": ["A", "B", "C", "D"], "shade": true}], "circles": [{"center": "O", "radius": 5, "blank": true}], "segments": [{"from": "A", "to": "B", "label": "10"}], "kind": "geometry"}, trapFor: [null, 1, null, null], },
  { q: "The figure shows a right circular cylinder with a diameter of 8 and a height of 5.\n\nWhat is the volume of the cylinder, in terms of π?", choices: ["80π", "320π", "80π/3", "40π"], answer: 0, explain: "The radius is 8 ÷ 2 = 4, so V = π(4²)(5) = 80π. 320π uses the diameter as the radius; 80π/3 uses the cone formula.", pattern: "Composite Figures and Formula Selection", difficulty: "easy", figure: {"kind": "solid", "shape": "cylinder", "radius": 4, "height": 5, "labels": {"diameter": "8", "height": "5"}}, trapFor: [null, 1, 0, null], },
  { q: "The figure shows a right circular cone with a diameter of 6 and a height of 4.\n\nWhat is the volume of the cone, in terms of π?", choices: ["12π", "36π", "48π", "15π"], answer: 0, explain: "The radius is 3, so V = (1/3)π(3²)(4) = 12π. 36π leaves out the 1/3 (the cylinder formula); 48π uses the diameter as the radius.", pattern: "Composite Figures and Formula Selection", difficulty: "medium", figure: {"kind": "solid", "shape": "cone", "radius": 3, "height": 4, "labels": {"diameter": "6", "height": "4"}}, trapFor: [null, 0, 1, null], },
  { q: "The figure shows a rectangular prism with length 5, width 3, and height 4.\n\nWhat is the surface area of the prism?", choices: ["94", "60", "47", "120"], answer: 0, explain: "Surface area = 2(5·3 + 5·4 + 3·4) = 2(15 + 20 + 12) = 94. 60 is the volume, and 47 counts each pair of faces once.", pattern: "Composite Figures and Formula Selection", difficulty: "medium", figure: {"kind": "solid", "shape": "prism", "length": 5, "width": 3, "height": 4, "labels": {"length": "5", "width": "3", "height": "4"}}, trapFor: [null, 0, null, null], },
  { q: "A box has a height of 2 feet. Its length is 3 feet more than its width, w. Which expression gives the volume of the box, in cubic feet?", choices: ["2w² + 6w", "6w²", "2w² + 3", "w² + 3w + 2"], answer: 0, explain: "Volume = length × width × height = (w + 3)(w)(2) = 2w² + 6w. 6w² reads '3 more than' as '3 times'; 2w² + 3 forgets to multiply the 3 by 2w.", pattern: "Building a Volume Expression Algebraically from a Word Description", difficulty: "medium", trapFor: [null, 1, 2, null], },
  { q: "A rectangle's length is twice its width, and its area is 72 square meters. What is the width of the rectangle, in meters?", choices: ["6", "12", "36", "18"], answer: 0, explain: "w(2w) = 72, so w² = 36 and w = 6. 12 is the length.", pattern: "Building a Volume Expression Algebraically from a Word Description", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "The height of a cylinder is 3 times its radius, r. Which expression gives the volume of the cylinder?", choices: ["3πr³", "9πr³", "πr³", "3πr²"], answer: 0, explain: "V = πr²h = πr²(3r) = 3πr³. 9πr³ squares the 3 along with r; 3πr² forgets that h itself contains r.", pattern: "Building a Volume Expression Algebraically from a Word Description", difficulty: "hard", trapFor: [null, 0, null, 2], },
  { q: "An open box is made from a 20-by-20-inch sheet of cardboard by cutting an x-by-x-inch square from each corner and folding up the sides. Which expression gives the volume of the box, in cubic inches?", choices: ["x(20 - 2x)²", "x(20 - x)²", "(20 - 2x)²", "x²(20 - 2x)"], answer: 0, explain: "Each side loses x at both ends, so the base is (20 - 2x) by (20 - 2x), and the height is x. 20 - x removes only one corner; (20 - 2x)² is just the base area.", pattern: "Building a Volume Expression Algebraically from a Word Description", difficulty: "hard", trapFor: [null, 0, null, 0], },
  { q: "The volume of a cube is 125 cubic centimeters. What is the total surface area of the cube, in square centimeters?", choices: ["150", "25", "125", "30"], answer: 0, explain: "The side is ∛125 = 5, so the surface area is 6 × 5² = 150. 25 is the area of one face.", pattern: "Composite Figures and Formula Selection", difficulty: "easy", trapFor: [null, 0, null, null], },
],
  "m-lines-angles-tri": [
  { q: "A triangle has angles of 50° and 60°. What is the third angle?", choices: ["60°", "70°", "80°", "90°"], answer: 1, explain: "Triangle angles sum to 180°: 180 - 50 - 60 = 70°.", pattern: "Triangle Angle Sum and Exterior Angles", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Two parallel lines are cut by a transversal. If one angle is 70°, its corresponding angle is:", choices: ["20°", "70°", "110°", "180°"], answer: 1, explain: "Corresponding angles formed by a transversal across parallel lines are equal.", pattern: "Parallel Lines Cut by a Transversal", difficulty: "easy", trapFor: [null, null, 1, null], },
  { q: "Two parallel lines are cut by a transversal. If one angle measures 65°, what is the measure of its co-interior (same-side interior) angle?", choices: ["65°", "115°", "25°", "180°"], answer: 1, explain: "Co-interior angles are supplementary: 180 - 65 = 115°.", pattern: "Parallel Lines Cut by a Transversal", difficulty: "medium", trapFor: [0, null, null, null], },
  { q: "Triangle ABC is similar to triangle DEF. If AB = 6, DE = 9, and BC = 8, what is EF?", choices: ["10", "12", "13.5", "14"], answer: 1, explain: "The scale factor is 9/6 = 1.5; EF = BC × 1.5 = 8 × 1.5 = 12.", pattern: "Similar Triangles and Proportional Sides", difficulty: "medium", trapFor: [null, null, 0, null], },
  { q: "A triangle has angles in the ratio 2:3:4. What is the measure of the largest angle?", choices: ["40°", "60°", "80°", "100°"], answer: 2, explain: "The ratio parts sum to 9, and 180/9 = 20 per part; the largest angle is 4 × 20 = 80°.", pattern: "Triangle Angle Sum and Exterior Angles", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Two triangles are congruent. If one triangle has side lengths 5, 7, and 9, what must be true of the other triangle's sides?", choices: ["They must also be 5, 7, and 9.", "They must be proportional to 5, 7, and 9 but not necessarily equal.", "They must sum to the same total as 5, 7, and 9.", "They must each be larger than 5, 7, and 9."], answer: 0, explain: "Congruent triangles have exactly equal corresponding side lengths, not just proportional ones.", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "In a triangle, one angle is a right angle and another is 35°. What is the measure of the third angle?", choices: ["45°", "55°", "65°", "90°"], answer: 1, explain: "180 - 90 - 35 = 55°.", pattern: "Triangle Angle Sum and Exterior Angles", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "Two lines are cut by a transversal, creating alternate interior angles of measure 3x and 75°. If the lines are parallel, what is x?", choices: ["20", "25", "30", "35"], answer: 1, explain: "Alternate interior angles are equal when lines are parallel: 3x = 75 → x = 25.", pattern: "Parallel Lines Cut by a Transversal", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "In the figure, point D lies on the extension of side AB of triangle ABC.\n\nWhat is the value of x?", choices: ["55", "65", "75", "115"], answer: 2, explain: "Exterior angle CBD equals the sum of the two interior angles not next to it: 115 = 40 + x, so x = 75. 65 is interior angle ABC, the one next to the exterior angle.", pattern: "Triangle Angle Sum and Exterior Angles", difficulty: "medium", figure: {"points": {"A": [0, 0], "B": [6, 0], "C": [4.3126, 3.6187], "D": [9, 0]}, "names": ["A", "B", "C", "D"], "segments": [{"from": "A", "to": "B"}, {"from": "B", "to": "C"}, {"from": "C", "to": "A"}, {"from": "B", "to": "D"}], "angles": [{"vertex": "A", "from": "B", "to": "C", "label": "40°"}, {"vertex": "B", "from": "D", "to": "C", "label": "115°"}, {"vertex": "C", "from": "A", "to": "B", "label": "x°"}], "kind": "geometry"}, trapFor: [null, 0, null, null], },
  { q: "Triangle PQR is similar to triangle XYZ with a scale factor of 2/3. If PQ = 12, what is XY?", choices: ["6", "8", "9", "18"], answer: 1, explain: "XY = PQ × (2/3) = 12 × 2/3 = 8.", pattern: "Similar Triangles and Proportional Sides", difficulty: "easy", trapFor: [null, null, null, 1], },
  { q: "A 4-foot-tall child standing near a flagpole casts a shadow 6 feet long. At the same moment, the flagpole casts a shadow 18 feet long. How tall is the flagpole?", choices: ["12 feet", "27 feet", "18 feet", "4 feet"], answer: 0, explain: "The child and the flagpole each form a right triangle with their shadow, and these two triangles are similar, so height and shadow length stay in the same ratio: height/shadow = 4/6 = 2/3. Applying that ratio to the flagpole's shadow gives its height: 18 × 2/3 = 12 feet. 27 comes from inverting the ratio (3/2 instead of 2/3). 18 and 4 each mistakenly restate one of the given shadow or height values instead of solving for the flagpole's height.", pattern: "Similar Triangles and Proportional Sides", difficulty: "easy", trapFor: [null, 1, null, null], },
  { q: "Triangle ABC is similar to triangle DEF with a scale factor of 5/2 from ABC to DEF. If the perimeter of triangle ABC is 24, what is the perimeter of triangle DEF?", choices: ["60", "9.6", "26", "120"], answer: 0, explain: "Perimeter is just a sum of side lengths, so it scales by exactly the same factor as any individual side: 24 × 5/2 = 60. 9.6 comes from inverting the scale factor (2/5 instead of 5/2). 26 comes from mistakenly adding the scale factor's numerator to the perimeter instead of multiplying. 120 comes from squaring the scale factor's effect, a rule that applies to area, not to perimeter or individual side lengths.", pattern: "Similar Triangles and Proportional Sides", difficulty: "medium", trapFor: [null, 1, null, null], },
  { q: "A 10-foot ladder leaning against a wall forms a triangle with the wall and the ground, reaching 8 feet up the wall. A larger, similarly-angled ladder setup reaches 20 feet up the wall. What is the length of that larger ladder?", choices: ["25 feet", "18 feet", "22.5 feet", "16 feet"], answer: 0, explain: "The two ladder-wall-ground triangles are similar, so every corresponding length scales by the same factor. Comparing the heights up the wall gives that factor: 20/8 = 2.5. Applying it to the ladder length gives 10 × 2.5 = 25 feet. 18 comes from adding the height difference instead of multiplying by the scale factor. 22.5 comes from a scale-factor arithmetic slip. 16 mistakenly doubles the original ladder length instead of using the actual scale factor of 2.5.", pattern: "Similar Triangles and Proportional Sides", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "Triangle ABC is similar to triangle DEF. AB = 2x, DE = 3x + 6, BC = 10, and EF = 25. What is the value of x?", choices: ["3", "6", "2", "12"], answer: 0, explain: "Since the triangles are similar, every pair of corresponding sides shares the same scale factor. The one pair with two known numeric values, BC and EF, gives that factor: 25/10 = 2.5. The same factor must relate AB and DE: 3x + 6 = 2x × 2.5, which simplifies to 3x + 6 = 5x. Subtracting 3x from both sides gives 6 = 2x, so x = 3. 6 comes from an arithmetic slip solving the final equation. 2 comes from setting up the proportion with AB and DE flipped. 12 comes from solving for 5x instead of x itself, treating an intermediate value as the final answer.", pattern: "Similar Triangles and Proportional Sides", difficulty: "hard", trapFor: [null, null, null, null], },
  { q: "In the figure, D is a point on the extension of side AB of triangle ABC.\n\nWhat is the value of x?", choices: ["70", "60", "50", "110"], answer: 0, explain: "Exterior angle CBD equals the sum of the two interior angles not next to it: 120 = 50 + x, so x = 70. 60 is interior angle ABC, the angle next to the exterior angle.", pattern: "Triangle Angle Sum and Exterior Angles", difficulty: "easy", figure: {"points": {"A": [0, 0], "B": [6, 0], "C": [3.5544, 4.2359], "D": [9, 0]}, "names": ["A", "B", "C", "D"], "segments": [{"from": "A", "to": "B"}, {"from": "B", "to": "C"}, {"from": "C", "to": "A"}, {"from": "B", "to": "D"}], "angles": [{"vertex": "A", "from": "B", "to": "C", "label": "50°"}, {"vertex": "B", "from": "D", "to": "C", "label": "120°"}, {"vertex": "C", "from": "A", "to": "B", "label": "x°"}], "kind": "geometry"}, trapFor: [null, 0, null, null], },
  { q: "In triangle ABC shown, the measures of the angles are x°, 2x°, and 3x°.\n\nWhat is the value of x?", choices: ["30", "60", "36", "90"], answer: 0, explain: "x + 2x + 3x = 180, so 6x = 180 and x = 30. 60 and 90 are the other two angles.", pattern: "Triangle Angle Sum and Exterior Angles", difficulty: "easy", figure: {"points": {"A": [0, 0], "B": [6, 0], "C": [6.0, 3.4641]}, "names": ["A", "B", "C"], "segments": [{"from": "A", "to": "B"}, {"from": "B", "to": "C"}, {"from": "C", "to": "A"}], "angles": [{"vertex": "A", "from": "B", "to": "C", "label": "x°"}, {"vertex": "B", "from": "C", "to": "A", "label": "3x°"}, {"vertex": "C", "from": "A", "to": "B", "label": "2x°"}], "kind": "geometry"}, trapFor: [null, null, null, null], },
  { q: "In triangle ABC shown, AB = AC and the measure of angle A is 40°.\n\nWhat is the measure of angle B?", choices: ["70°", "40°", "140°", "100°"], answer: 0, explain: "AB = AC makes angles B and C equal, and together they take up 180 - 40 = 140°, so each is 70°.", pattern: "Triangle Angle Sum and Exterior Angles", difficulty: "easy", figure: {"points": {"B": [0, 0], "C": [5, 0], "A": [2.5, 6.8687]}, "names": ["A", "B", "C"], "segments": [{"from": "A", "to": "B", "ticks": 1}, {"from": "A", "to": "C", "ticks": 1}, {"from": "B", "to": "C"}], "angles": [{"vertex": "A", "from": "B", "to": "C", "label": "40°"}], "kind": "geometry"}, trapFor: [null, null, null, null], },
  { q: "In the figure, point D lies on the extension of side AC of triangle ABC.\n\nWhat is the value of x?", choices: ["15", "16.25", "30", "25"], answer: 0, explain: "The exterior angle equals the sum of the two remote interior angles: 5x + 10 = 2x + (x + 40), so 2x = 30 and x = 15. Setting all three expressions to add to 180 gives 16.25.", pattern: "Triangle Angle Sum and Exterior Angles", difficulty: "hard", figure: {"points": {"A": [0, 0], "B": [6, 0], "C": [4.2727, 2.4668], "D": [6.1954, 3.5769]}, "names": ["A", "B", "C", "D"], "segments": [{"from": "A", "to": "B"}, {"from": "B", "to": "C"}, {"from": "A", "to": "D"}], "angles": [{"vertex": "A", "from": "B", "to": "C", "label": "2x°"}, {"vertex": "B", "from": "C", "to": "A", "label": "(x + 40)°"}, {"vertex": "C", "from": "D", "to": "B", "label": "(5x + 10)°"}], "kind": "geometry"}, trapFor: [null, null, null, null], },
  { q: "In the figure, lines ℓ and m are parallel.\n\nWhat is the value of x?", choices: ["65", "115", "25", "75"], answer: 0, explain: "The two labeled angles are same-side interior angles, which add to 180°: x = 180 - 115 = 65. They aren't equal, so 115 is the trap.", pattern: "Parallel Lines Cut by a Transversal", difficulty: "medium", figure: {"points": {"P": [0, 0], "Q": [1.3989, 3], "L1": [-4, 3], "L2": [8, 3], "M1": [-4, 0], "M2": [8, 0], "T1": [-0.6295, -1.35], "T2": [2.0284, 4.35], "ℓ": [8.6, 3], "m": [8.6, 0]}, "names": ["ℓ", "m"], "namePos": {"ℓ": 0, "m": 0}, "segments": [{"from": "L1", "to": "L2", "arrows": true}, {"from": "M1", "to": "M2", "arrows": true}, {"from": "T1", "to": "T2", "arrows": true}], "angles": [{"vertex": "Q", "from": "L2", "to": "P", "label": "115°"}, {"vertex": "P", "from": "M2", "to": "Q", "label": "x°"}], "kind": "geometry"}, trapFor: [null, 0, null, null], },
  { q: "In the figure, parallel lines ℓ and m are cut by a transversal.\n\nWhat is the value of x?", choices: ["20", "30", "15", "70"], answer: 0, explain: "The labeled angles are alternate interior angles, so they're equal: 4x - 10 = 70 and x = 20. Treating them as supplementary gives 4x - 10 = 110, x = 30.", pattern: "Parallel Lines Cut by a Transversal", difficulty: "medium", figure: {"points": {"P": [0, 0], "Q": [1.0919, 3], "L1": [-4, 3], "L2": [8, 3], "M1": [-4, 0], "M2": [8, 0], "T1": [-0.4914, -1.35], "T2": [1.5833, 4.35], "ℓ": [8.6, 3], "m": [8.6, 0]}, "names": ["ℓ", "m"], "namePos": {"ℓ": 0, "m": 0}, "segments": [{"from": "L1", "to": "L2", "arrows": true}, {"from": "M1", "to": "M2", "arrows": true}, {"from": "T1", "to": "T2", "arrows": true}], "angles": [{"vertex": "Q", "from": "L1", "to": "P", "label": "(4x − 10)°"}, {"vertex": "P", "from": "M2", "to": "Q", "label": "70°"}], "kind": "geometry"}, trapFor: [null, 0, null, null], },
  { q: "In the figure, lines ℓ and m are parallel.\n\nWhat is the measure, in degrees, of the angle labeled 3x°?", choices: ["60", "20", "120", "100"], answer: 0, explain: "The labeled angles are corresponding angles, so 3x = 5x - 40, which gives x = 20. The angle is 3(20) = 60°. 20 is x, not the angle.", pattern: "Parallel Lines Cut by a Transversal", difficulty: "medium", figure: {"points": {"P": [0, 0], "Q": [1.7321, 3], "L1": [-4, 3], "L2": [8, 3], "M1": [-4, 0], "M2": [8, 0], "T1": [-0.7794, -1.35], "T2": [2.5115, 4.35], "ℓ": [8.6, 3], "m": [8.6, 0]}, "names": ["ℓ", "m"], "namePos": {"ℓ": 0, "m": 0}, "segments": [{"from": "L1", "to": "L2", "arrows": true}, {"from": "M1", "to": "M2", "arrows": true}, {"from": "T1", "to": "T2", "arrows": true}], "angles": [{"vertex": "Q", "from": "L2", "to": "T2", "label": "3x°"}, {"vertex": "P", "from": "M2", "to": "Q", "label": "(5x − 40)°"}], "kind": "geometry"}, trapFor: [null, null, 1, null], },
  { q: "In the figure, lines ℓ and m are parallel, point A lies on ℓ, and point B lies on m.\n\nWhat is the value of x?", choices: ["85", "95", "15", "42.5"], answer: 0, explain: "Draw a line through P parallel to ℓ and m. It splits x into two angles that are alternate interior angles with the 35° and 50° angles, so x = 35 + 50 = 85.", pattern: "Parallel Lines Cut by a Transversal", difficulty: "hard", figure: {"points": {"A": [-2.8563, 4], "B": [-1.6782, 0], "P": [0, 2], "L1": [-6, 4], "L2": [3, 4], "M1": [-6, 0], "M2": [3, 0], "ℓ": [3.6, 4], "m": [3.6, 0]}, "names": ["A", "B", "P", "ℓ", "m"], "namePos": {"ℓ": 0, "m": 0, "A": 90, "B": 270, "P": 0}, "segments": [{"from": "L1", "to": "L2", "arrows": true}, {"from": "M1", "to": "M2", "arrows": true}, {"from": "A", "to": "P"}, {"from": "P", "to": "B"}], "angles": [{"vertex": "A", "from": "L2", "to": "P", "label": "35°"}, {"vertex": "B", "from": "M2", "to": "P", "label": "50°"}, {"vertex": "P", "from": "A", "to": "B", "label": "x°"}], "kind": "geometry"}, trapFor: [null, null, null, null], },
  { q: "In the figure, segment DE is parallel to segment BC.\n\nWhat is the length of BC?", choices: ["12.5", "7.5", "2", "9"], answer: 0, explain: "DE ∥ BC makes triangle ADE similar to triangle ABC. AB = 4 + 6 = 10, so BC/5 = 10/4 and BC = 12.5. Using DB instead of AB gives 7.5.", pattern: "Similar Triangles and Proportional Sides", difficulty: "medium", figure: {"points": {"A": [4, 9.1652], "B": [0, 0], "C": [12.5, 0], "D": [2.4, 5.4991], "E": [7.4, 5.4991]}, "names": ["A", "B", "C", "D", "E"], "segments": [{"from": "A", "to": "D", "label": "4"}, {"from": "D", "to": "B", "label": "6"}, {"from": "A", "to": "E"}, {"from": "E", "to": "C"}, {"from": "B", "to": "C"}, {"from": "D", "to": "E", "label": "5", "side": -1}], "kind": "geometry"}, trapFor: [null, 0, 1, null], },
  { q: "Triangle ABC is similar to triangle DEF, with angle A corresponding to angle D and angle B to angle E. If AB = 8, AC = 6, and DE = 12, what is DF?", choices: ["9", "4", "10", "16"], answer: 0, explain: "The scale factor from ABC to DEF is 12/8 = 1.5, so DF = 6 × 1.5 = 9. 4 uses the factor upside down; 10 adds 4 instead of multiplying.", pattern: "Similar Triangles and Proportional Sides", difficulty: "easy", trapFor: [null, 1, null, null], },
  { q: "In right triangles ABC and DEF, angles B and E are right angles and angle A is congruent to angle D. If AB = 4, BC = 3, and DE = 10, what is EF?", choices: ["7.5", "13.3", "9", "12.5"], answer: 0, explain: "Two pairs of equal angles make the triangles similar, with AB ↔ DE and BC ↔ EF. The factor is 10/4 = 2.5, so EF = 3 × 2.5 = 7.5. 13.3 pairs BC with DE.", pattern: "Similar Triangles and Proportional Sides", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "In triangles ABC and DEF, angle A is congruent to angle D. Which additional fact would be enough to prove that the triangles are similar?", choices: ["Angle B is congruent to angle E.", "AB = DE", "Angle C measures 90°.", "BC = EF"], answer: 0, explain: "Two pairs of congruent angles guarantee similarity (AA). One angle plus one pair of equal sides isn't enough, and a single angle in one triangle tells you nothing about the other.", pattern: "Similar Triangles and Proportional Sides", difficulty: "medium", trapFor: [null, 2, 2, 2], },
  { q: "In the figure, two lines intersect.\n\nWhat is the value of x?", choices: ["20", "25", "70", "10"], answer: 0, explain: "The labeled angles are vertical angles, so they're equal: 3x + 10 = 5x - 30, giving x = 20. Treating them as supplementary gives 8x - 20 = 180, x = 25.", pattern: "Vertical Angles and Basic Angle Relationships", difficulty: "medium", figure: {"points": {"O": [0, 0], "P1": [4.0, 0.0], "P2": [-4.0, 0.0], "Q1": [1.3681, 3.7588], "Q2": [-1.3681, -3.7588]}, "segments": [{"from": "P2", "to": "P1", "arrows": true}, {"from": "Q2", "to": "Q1", "arrows": true}], "angles": [{"vertex": "O", "from": "P1", "to": "Q1", "label": "(3x + 10)°"}, {"vertex": "O", "from": "P2", "to": "Q2", "label": "(5x − 30)°"}], "kind": "geometry"}, trapFor: [null, 0, null, null], },
  { q: "In the figure, three lines intersect at a point.\n\nWhat is the value of a?", choices: ["80", "40", "100", "60"], answer: 0, explain: "The angles 60°, a°, and 40° lie side by side along one straight line, so they add to 180°: a = 180 - 60 - 40 = 80. The 40° angle isn't vertical to a°, so a isn't 40.", pattern: "Vertical Angles and Basic Angle Relationships", difficulty: "medium", figure: {"points": {"O": [0, 0], "E": [4.0, 0.0], "Wp": [-4.0, 0.0], "U": [2.0, 3.4641], "U2": [-2.0, -3.4641], "V": [-3.0642, 2.5712], "V2": [3.0642, -2.5712]}, "segments": [{"from": "Wp", "to": "E", "arrows": true}, {"from": "U2", "to": "U", "arrows": true}, {"from": "V2", "to": "V", "arrows": true}], "angles": [{"vertex": "O", "from": "E", "to": "U", "label": "60°"}, {"vertex": "O", "from": "U", "to": "V", "label": "a°"}, {"vertex": "O", "from": "V", "to": "Wp", "label": "40°"}], "kind": "geometry"}, trapFor: [null, 1, 2, null], },
  { q: "Angles 1 and 2 form a linear pair, and the measure of angle 1 is 3 times the measure of angle 2. What is the measure of angle 1?", choices: ["135°", "45°", "67.5°", "90°"], answer: 0, explain: "A linear pair adds to 180°: 3a + a = 180, so a = 45 and angle 1 = 135°. 45° is angle 2.", pattern: "Vertical Angles and Basic Angle Relationships", difficulty: "easy", trapFor: [null, null, null, null], },
],
  "m-right-tri-trig": [
  { q: "In a right triangle, the side opposite a 30° angle is 5. What is the hypotenuse?", choices: ["5", "10", "5√2", "5√3"], answer: 1, explain: "In a 30-60-90 triangle, the hypotenuse is twice the side opposite the 30° angle: 2 × 5 = 10.", pattern: "Special Right Triangles (30-60-90 and 45-45-90)", difficulty: "easy", trapFor: [null, null, 1, 1], },
  { q: "If sin(x) = 0.6, what is cos(90° - x)?", choices: ["0.4", "0.6", "0.8", "1"], answer: 1, explain: "sin(x) = cos(90° - x) for complementary angles, so cos(90°-x) = 0.6.", pattern: "The Sine-Cosine Complementary Angle Relationship", difficulty: "medium", trapFor: [null, null, 0, null], },
  { q: "A right triangle has legs of length 6 and 8. What is the length of the hypotenuse?", choices: ["10", "12", "14", "48"], answer: 0, explain: "By the Pythagorean theorem: √(6² + 8²) = √(36+64) = √100 = 10.", pattern: "Using the Pythagorean Theorem Alone to Find a Missing Side", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "In a 45-45-90 triangle, each leg has length 7. What is the length of the hypotenuse?", choices: ["7", "7√2", "14", "7√3"], answer: 1, explain: "In a 45-45-90 triangle, the hypotenuse equals a leg times √2: 7√2.", pattern: "Special Right Triangles (30-60-90 and 45-45-90)", difficulty: "easy", trapFor: [null, null, null, 1], },
  { q: "The side lengths of right triangle ABC are 3, 4, and 5, and sin A = 3/5. What is cos A?", choices: ["3/5", "4/5", "5/3", "5/4"], answer: 1, explain: "With sides 3, 4, 5 (3 opposite, 4 adjacent, 5 hypotenuse), cos(A) = adjacent/hypotenuse = 4/5.", pattern: "SOH-CAH-TOA Setup", difficulty: "medium", trapFor: [1, null, null, null], },
  { q: "The figure shows a 12-foot ladder leaning against a vertical wall. The ladder makes a 60° angle with the level ground.\n\nHow high up the wall does the ladder reach?", choices: ["6 feet", "6√3 feet", "12 feet", "12√3 feet"], answer: 1, explain: "Height = hypotenuse × sin(60°) = 12 × (√3/2) = 6√3 feet.", pattern: "SOH-CAH-TOA Setup", difficulty: "medium", figure: {"points": {"F": [0, 0], "B": [6, 0], "T": [6, 10.3923]}, "segments": [{"from": "F", "to": "T", "label": "12"}, {"from": "F", "to": "B"}, {"from": "B", "to": "T"}], "angles": [{"vertex": "F", "from": "B", "to": "T", "label": "60°"}, {"vertex": "B", "from": "T", "to": "F", "right": true}], "kind": "geometry"}, trapFor: [1, null, null, null], },
  { q: "In a right triangle, the leg opposite angle x has length 5 and the leg adjacent to angle x has length 12. What is the length of the hypotenuse?", choices: ["13", "17", "60", "169"], answer: 0, explain: "By the Pythagorean theorem: √(5² + 12²) = √(25+144) = √169 = 13.", pattern: "Using the Pythagorean Theorem Alone to Find a Missing Side", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A right triangle has a hypotenuse of 10 and one leg of 6. What is the length of the other leg?", choices: ["4", "6", "8", "16"], answer: 2, explain: "By the Pythagorean theorem: √(10² - 6²) = √(100-36) = √64 = 8.", pattern: "Using the Pythagorean Theorem Alone to Find a Missing Side", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "In a right triangle, if cos(x) = 0.8, what is sin(90° - x)?", choices: ["0.2", "0.6", "0.8", "1"], answer: 2, explain: "cos(x) = sin(90° - x) for complementary angles, so sin(90°-x) = 0.8.", pattern: "The Sine-Cosine Complementary Angle Relationship", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "The figure shows a support cable anchored to level ground 15 feet from the base of a vertical pole. The cable meets the top of the pole and makes a 40° angle with the ground.\n\nWhich expression gives the height of the pole, in feet?", choices: ["15 · tan(40°)", "15 / tan(40°)", "15 · sin(40°)", "15 / cos(40°)"], answer: 0, explain: "Height/adjacent = tan(angle), so height = adjacent × tan(40°) = 15 · tan(40°).", pattern: "SOH-CAH-TOA Setup", difficulty: "medium", figure: {"points": {"A": [0, 0], "B": [15, 0], "T": [15, 12.5865]}, "segments": [{"from": "A", "to": "B", "label": "15"}, {"from": "B", "to": "T"}, {"from": "A", "to": "T"}], "angles": [{"vertex": "A", "from": "B", "to": "T", "label": "40°"}, {"vertex": "B", "from": "T", "to": "A", "right": true}], "kind": "geometry"}, trapFor: [null, 1, 1, 1], },
  { q: "In right triangle ABC shown, angle C is a right angle.\n\nWhat is the value of sin A?", choices: ["5/13", "12/13", "5/12", "13/5"], answer: 0, explain: "sin A = opposite/hypotenuse. The side opposite A is BC = 5 and the hypotenuse is 13: 5/13. 12/13 is cos A (the adjacent side); 5/12 is tan A.", pattern: "SOH-CAH-TOA Setup", difficulty: "easy", figure: {"points": {"C": [0, 0], "A": [12, 0], "B": [0, 5]}, "names": ["A", "B", "C"], "segments": [{"from": "C", "to": "A", "label": "12"}, {"from": "C", "to": "B", "label": "5"}, {"from": "A", "to": "B", "label": "13"}], "angles": [{"vertex": "C", "from": "A", "to": "B", "right": true}], "kind": "geometry"}, trapFor: [null, 0, 1, null], },
  { q: "In right triangle ABC shown, angle C is a right angle.\n\nWhat is the value of cos B?", choices: ["8/17", "15/17", "8/15", "15/8"], answer: 0, explain: "First find the hypotenuse: √(8² + 15²) = 17. The side adjacent to B is BC = 8, so cos B = 8/17. 15/17 uses the side opposite B; 8/15 skips finding the hypotenuse.", pattern: "Using the Pythagorean Theorem Before Computing a Trig Ratio", difficulty: "medium", figure: {"points": {"C": [0, 0], "A": [15, 0], "B": [0, 8]}, "names": ["A", "B", "C"], "segments": [{"from": "C", "to": "A", "label": "15"}, {"from": "C", "to": "B", "label": "8"}, {"from": "A", "to": "B"}], "angles": [{"vertex": "C", "from": "A", "to": "B", "right": true}], "kind": "geometry"}, trapFor: [null, 1, 0, null], },
  { q: "In right triangle ABC shown, AB = 20 and the measure of angle A is 32°.\n\nWhich expression gives the value of x?", choices: ["20 sin 32°", "20 cos 32°", "20 tan 32°", "20 / sin 32°"], answer: 0, explain: "x is opposite angle A and 20 is the hypotenuse, so sin 32° = x/20 and x = 20 sin 32°. Cosine would give the adjacent side.", pattern: "SOH-CAH-TOA Setup", difficulty: "medium", figure: {"points": {"C": [0, 0], "A": [16.96096192312852, 0], "B": [0, 10.598385284664097]}, "names": ["A", "B", "C"], "segments": [{"from": "C", "to": "A"}, {"from": "C", "to": "B", "label": "x"}, {"from": "A", "to": "B", "label": "20"}], "angles": [{"vertex": "C", "from": "A", "to": "B", "right": true}, {"vertex": "A", "from": "B", "to": "C", "label": "32°"}], "kind": "geometry"}, trapFor: [null, 0, 1, null], },
  { q: "In right triangle ABC shown, the hypotenuse AB has length 12 and the measure of angle A is 30°.\n\nWhat is the length of AC?", choices: ["6√3", "6", "12√3", "6√2"], answer: 0, explain: "In a 30-60-90 triangle the sides are x, x√3, 2x. The hypotenuse 2x = 12, so x = 6 (the side opposite 30°, BC) and AC, opposite 60°, is 6√3. 6√2 uses the 45-45-90 ratio.", pattern: "Special Right Triangles (30-60-90 and 45-45-90)", difficulty: "medium", figure: {"points": {"C": [0, 0], "A": [10.392304845413264, 0], "B": [0, 6]}, "names": ["A", "B", "C"], "segments": [{"from": "C", "to": "A"}, {"from": "C", "to": "B"}, {"from": "A", "to": "B", "label": "12"}], "angles": [{"vertex": "C", "from": "A", "to": "B", "right": true}, {"vertex": "A", "from": "B", "to": "C", "label": "30°"}], "kind": "geometry"}, trapFor: [null, null, null, 1], },
  { q: "The diagonal of square ABCD shown has length 10.\n\nWhat is the side length of the square?", choices: ["5√2", "10√2", "5", "10√3"], answer: 0, explain: "A diagonal splits the square into two 45-45-90 triangles, where hypotenuse = side × √2. So side = 10/√2 = 5√2. 10√2 multiplies instead of dividing.", pattern: "Special Right Triangles (30-60-90 and 45-45-90)", difficulty: "medium", figure: {"points": {"A": [0, 0], "B": [7.0711, 0], "C": [7.0711, 7.0711], "D": [0, 7.0711]}, "names": ["A", "B", "C", "D"], "polygons": [{"points": ["A", "B", "C", "D"]}], "segments": [{"from": "A", "to": "C", "label": "10", "side": -1}], "angles": [{"vertex": "A", "from": "B", "to": "D", "right": true}, {"vertex": "B", "from": "C", "to": "A", "right": true}, {"vertex": "C", "from": "D", "to": "B", "right": true}, {"vertex": "D", "from": "A", "to": "C", "right": true}], "kind": "geometry"}, trapFor: [null, null, null, 1], },
  { q: "The figure shows equilateral triangle ABC with side length 8. Segment CM is the altitude from C to AB.\n\nWhat is the length of CM?", choices: ["4√3", "8√3", "4", "4√2"], answer: 0, explain: "The altitude splits the triangle into two 30-60-90 triangles with hypotenuse 8 and short leg 4. The altitude is the long leg: 4√3. 4√2 uses the 45-45-90 ratio.", pattern: "Special Right Triangles (30-60-90 and 45-45-90)", difficulty: "medium", figure: {"points": {"A": [0, 0], "B": [8, 0], "C": [4, 6.9282], "M": [4, 0]}, "names": ["A", "B", "C", "M"], "segments": [{"from": "A", "to": "B", "label": "8"}, {"from": "B", "to": "C", "label": "8"}, {"from": "C", "to": "A", "label": "8"}, {"from": "C", "to": "M", "dashed": true}], "angles": [{"vertex": "M", "from": "B", "to": "C", "right": true}], "kind": "geometry"}, trapFor: [null, null, null, 1], },
  { q: "In right triangle PQR shown, angle Q is a right angle, PQ = 7, and PR = 25.\n\nWhat is the value of tan P?", choices: ["24/7", "7/24", "24/25", "7/25"], answer: 0, explain: "First QR = √(25² - 7²) = √576 = 24. For angle P, the opposite side is QR = 24 and the adjacent side is PQ = 7: tan P = 24/7. 7/24 swaps opposite and adjacent.", pattern: "Using the Pythagorean Theorem Before Computing a Trig Ratio", difficulty: "hard", figure: {"points": {"Q": [0, 0], "P": [7, 0], "R": [0, 24]}, "names": ["P", "Q", "R"], "segments": [{"from": "Q", "to": "P", "label": "7"}, {"from": "Q", "to": "R"}, {"from": "P", "to": "R", "label": "25"}], "angles": [{"vertex": "Q", "from": "P", "to": "R", "right": true}], "kind": "geometry"}, trapFor: [null, 1, null, null], },
  { q: "What is the measure of a 150° angle in radians?", choices: ["5π/6", "5π/12", "3π/4", "150π"], answer: 0, explain: "Multiply by π/180: 150 × π/180 = 5π/6. 5π/12 uses 360° for π.", pattern: "Radian Measure and Coterminal Angles", difficulty: "easy", trapFor: [null, 2, null, null], },
  { q: "Which angle measure, between 0 and 2π radians, is coterminal with an angle of 17π/6 radians?", choices: ["5π/6", "π/6", "11π/6", "17π/12"], answer: 0, explain: "Subtract one full rotation: 17π/6 - 12π/6 = 5π/6, which is already between 0 and 2π.", pattern: "Radian Measure and Coterminal Angles", difficulty: "medium", trapFor: [null, 1, 1, 2], },
  { q: "What is the measure, in degrees, of an angle of 3π/4 radians?", choices: ["135", "270", "67.5", "240"], answer: 0, explain: "Multiply by 180/π: (3/4)(180) = 135. 270 treats π as 360°.", pattern: "Radian Measure and Coterminal Angles", difficulty: "easy", trapFor: [null, 2, null, null], },
  { q: "A right triangle has a hypotenuse of length 9 and one leg of length 3√5. What is the length of the other leg?", choices: ["6", "3√14", "√66", "36"], answer: 0, explain: "(3√5)² = 9 × 5 = 45, so the other leg is √(81 - 45) = √36 = 6. Adding instead of subtracting gives √126 = 3√14; squaring 3√5 as 15 gives √66.", pattern: "Using the Pythagorean Theorem Alone to Find a Missing Side", difficulty: "hard", trapFor: [null, 0, 2, null], },
  { q: "The figure shows a 13-foot ladder leaning against a vertical wall, with its base 5 feet from the wall on level ground.\n\nHow high up the wall does the ladder reach, in feet?", choices: ["12", "√194", "8", "18"], answer: 0, explain: "The ladder is the hypotenuse: √(13² - 5²) = √144 = 12. √194 adds the squares instead of subtracting.", pattern: "Using the Pythagorean Theorem Alone to Find a Missing Side", difficulty: "easy", figure: {"points": {"F": [0, 0], "B": [5, 0], "T": [5, 12]}, "segments": [{"from": "F", "to": "T", "label": "13"}, {"from": "F", "to": "B", "label": "5"}, {"from": "B", "to": "T"}], "angles": [{"vertex": "B", "from": "T", "to": "F", "right": true}], "kind": "geometry"}, trapFor: [null, 0, null, null], },
  { q: "In a right triangle, A and B are the two acute angles, and sin A = 0.28. What is the value of cos B?", choices: ["0.28", "0.72", "0.96", "3.57"], answer: 0, explain: "A and B are complementary, so cos B = sin A = 0.28. 0.96 is cos A, the cosine of the same angle.", pattern: "The Sine-Cosine Complementary Angle Relationship", difficulty: "medium", trapFor: [null, null, 0, null], },
  { q: "For an acute angle, sin((2x + 10)°) = cos((x + 20)°). What is the value of x?", choices: ["20", "10", "50", "60"], answer: 0, explain: "Sine of one angle equals cosine of its complement, so (2x + 10) + (x + 20) = 90, giving 3x = 60 and x = 20. Setting the two angles equal gives x = 10.", pattern: "The Sine-Cosine Complementary Angle Relationship", difficulty: "hard", trapFor: [null, 0, null, null], },
  { q: "The figure shows a cable anchored to level ground 30 feet from the base of a vertical pole. The cable meets the top of the pole and makes a 55° angle with the ground.\n\nWhich expression gives the length of the cable, in feet?", choices: ["30 / cos 55°", "30 cos 55°", "30 / sin 55°", "30 tan 55°"], answer: 0, explain: "The cable is the hypotenuse and 30 is the side adjacent to the 55° angle: cos 55° = 30/cable, so cable = 30/cos 55°. Using sine treats 30 as the opposite side.", pattern: "SOH-CAH-TOA Setup", difficulty: "hard", figure: {"points": {"A": [0, 0], "B": [30, 0], "T": [30, 42.8444]}, "segments": [{"from": "A", "to": "B", "label": "30"}, {"from": "B", "to": "T"}, {"from": "A", "to": "T"}], "angles": [{"vertex": "A", "from": "B", "to": "T", "label": "55°"}, {"vertex": "B", "from": "T", "to": "A", "right": true}], "kind": "geometry"}, trapFor: [null, 1, 0, 1], },
],
  "m-circles": [
  { q: "What is the equation of a circle with center (2, -3) and radius 5?", choices: ["(x-2)² + (y+3)² = 5", "(x-2)² + (y+3)² = 25", "(x+2)² + (y-3)² = 25", "(x-2)² + (y-3)² = 25"], answer: 1, explain: "Standard form: (x-h)² + (y-k)² = r², with (h,k) = (2,-3) and r² = 25.", pattern: "The Circle Equation (Center-Radius Form)", difficulty: "medium", trapFor: [1, null, 0, 0], },
  { q: "In the figure, O is the center of the circle, the circle has a radius of 4, and angle AOB is a right angle.\n\nWhat is the area of the sector formed by radii OA and OB?", choices: ["π", "2π", "4π", "16π"], answer: 2, explain: "Sector area = (angle/360) × πr² = (90/360) × π(16) = 4π.", pattern: "Arc Length and Sector Area as Fractions of the Whole Circle", difficulty: "easy", figure: {"points": {"O": [0, 0], "A": [4, 0], "B": [0, 4]}, "names": ["O", "A", "B"], "circles": [{"center": "O", "radius": 4}], "polygons": [], "segments": [{"from": "O", "to": "A", "label": "4"}, {"from": "O", "to": "B"}], "angles": [{"vertex": "O", "from": "A", "to": "B", "right": true}], "kind": "geometry"}, trapFor: [null, 1, null, 0], },
  { q: "A circle has the equation (x+1)² + (y-4)² = 36. What is its radius?", choices: ["6", "12", "18", "36"], answer: 0, explain: "Since r² = 36, the radius r = 6.", pattern: "The Circle Equation (Center-Radius Form)", difficulty: "easy", trapFor: [null, null, null, 1], },
  { q: "An arc has a central angle of 60° in a circle with a radius of 9. What is the arc length in terms of π?", choices: ["1.5π", "3π", "6π", "9π"], answer: 1, explain: "Arc length = (angle/360) × 2πr = (60/360) × 2π(9) = (1/6)(18π) = 3π.", pattern: "Arc Length and Sector Area as Fractions of the Whole Circle", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A circle has the equation x² + y² = 49. What is the length of its diameter?", choices: ["7", "14", "49", "98"], answer: 1, explain: "Since r² = 49, r = 7, and diameter = 2r = 14.", pattern: "The Circle Equation (Center-Radius Form)", difficulty: "easy", trapFor: [null, null, 1, null], },
  { q: "A tangent line touches a circle at point P. What is the measure of the angle between the tangent line and the radius drawn to point P?", choices: ["45°", "60°", "90°", "180°"], answer: 2, explain: "A tangent line is always perpendicular to the radius at the point of tangency, forming a 90° angle.", pattern: "Circle Theorems: Central Angles, Arcs, and Tangent Lines", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A circle has a circumference of 20π. What is its radius?", choices: ["5", "10", "20", "40"], answer: 1, explain: "Circumference = 2πr → 20π = 2πr → r = 10.", pattern: "Arc Length and Sector Area as Fractions of the Whole Circle", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "A circle is centered at the origin with radius 6. Which point lies on this circle?", choices: ["(6, 6)", "(0, 6)", "(6, 1)", "(3, 3)"], answer: 1, explain: "The equation is x² + y² = 36. Testing (0,6): 0 + 36 = 36, which satisfies the equation.", pattern: "Solving the Circle Equation for a Coordinate's Possible Values", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A sector of a circle with radius 10 has an area of 25π. What is the central angle of the sector, in degrees?", choices: ["45°", "60°", "90°", "120°"], answer: 2, explain: "Sector area = (angle/360) × πr² → 25π = (angle/360) × 100π → angle/360 = 0.25 → angle = 90°.", pattern: "Arc Length and Sector Area as Fractions of the Whole Circle", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A circle has center (0, 0) and passes through the point (3, 4). What is the circle's equation?", choices: ["x² + y² = 7", "x² + y² = 12", "x² + y² = 25", "x² + y² = 49"], answer: 2, explain: "The radius equals the distance from the center to the point: √(3²+4²) = 5, so r² = 25.", pattern: "The Circle Equation (Center-Radius Form)", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A circle in the xy-plane has the equation x² + y² - 6x + 4y - 12 = 0. What is the radius of the circle?", choices: ["5", "12", "√12", "25"], answer: 0, explain: "Complete the square: (x - 3)² + (y + 2)² = 12 + 9 + 4 = 25, so the radius is 5. 25 is r², not r; √12 ignores the constants added while completing the square.", pattern: "The Circle Equation (Center-Radius Form)", difficulty: "hard", trapFor: [null, null, null, 1], },
  { q: "What is the center of the circle with equation (x + 4)² + (y - 1)² = 9?", choices: ["(-4, 1)", "(4, -1)", "(-4, -1)", "(4, 1)"], answer: 0, explain: "The form is (x - h)² + (y - k)² = r², and x + 4 = x - (-4), so h = -4 and k = 1. Reading the signs as written gives (4, -1).", pattern: "The Circle Equation (Center-Radius Form)", difficulty: "easy", trapFor: [null, 0, 0, 0], },
  { q: "A circle in the xy-plane has center (-2, 5) and passes through the point (1, 1). Which equation represents the circle?", choices: ["(x + 2)² + (y - 5)² = 25", "(x - 2)² + (y + 5)² = 25", "(x + 2)² + (y - 5)² = 5", "(x - 1)² + (y - 1)² = 25"], answer: 0, explain: "The radius is the distance from (-2, 5) to (1, 1): √(3² + 4²) = 5, so r² = 25. The second choice flips the center's signs, and the third forgets to square the radius.", pattern: "The Circle Equation (Center-Radius Form)", difficulty: "medium", trapFor: [null, 0, 1, null], },
  { q: "The figure shows a circle in the xy-plane. The center of the circle is marked, and the circle passes through the point (7, 2).\n\nWhich equation represents the circle?", choices: ["(x - 3)² + (y - 2)² = 16", "(x + 3)² + (y + 2)² = 16", "(x - 3)² + (y - 2)² = 4", "(x - 2)² + (y - 3)² = 16"], answer: 0, explain: "The center is (3, 2) and the radius is 7 - 3 = 4, so r² = 16. The second choice flips the signs, and the third leaves the radius unsquared.", pattern: "The Circle Equation (Center-Radius Form)", difficulty: "medium", figure: {"points": {"C": [3, 2]}, "dots": ["C"], "circles": [{"center": "C", "radius": 4}], "axes": {"x": [-2, 8], "y": [-3, 7], "step": 1}, "kind": "geometry"}, trapFor: [null, 0, 1, null], },
  { q: "In the figure, O is the center of the circle, the radius is 6, and the measure of angle AOB is 120°.\n\nWhat is the length of the minor arc AB?", choices: ["4π", "12π", "2π", "6π"], answer: 0, explain: "Arc length = (120/360) × 2π(6) = (1/3)(12π) = 4π. 12π is the sector's area, (1/3)(36π).", pattern: "Arc Length and Sector Area as Fractions of the Whole Circle", difficulty: "medium", figure: {"points": {"O": [0, 0], "A": [5.6382, 2.0521], "B": [-4.5963, 3.8567]}, "names": ["O", "A", "B"], "namePos": {"O": 270}, "circles": [{"center": "O", "radius": 6}], "segments": [{"from": "O", "to": "A", "label": "6"}, {"from": "O", "to": "B"}], "angles": [{"vertex": "O", "from": "A", "to": "B", "label": "120°"}], "kind": "geometry"}, trapFor: [null, 1, null, null], },
  { q: "A sector of a circle with radius 6 has an area of 15π. What is the central angle of the sector, in degrees?", choices: ["150", "75", "300", "135"], answer: 0, explain: "The whole circle's area is 36π, and 15π/36π = 5/12 of it. (5/12)(360°) = 150°.", pattern: "Arc Length and Sector Area as Fractions of the Whole Circle", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "A circle has a radius of 9. What is the length of an arc of the circle intercepted by a central angle of 2π/3 radians?", choices: ["6π", "3π", "27π", "18π"], answer: 0, explain: "For an angle in radians, arc length = rθ = 9(2π/3) = 6π. 27π is the sector's area, (1/2)r²θ.", pattern: "Arc Length and Sector Area as Fractions of the Whole Circle", difficulty: "medium", trapFor: [null, null, 1, null], },
  { q: "An arc of a circle with radius 10 has a length of 5π. What is the measure, in degrees, of the central angle that intercepts the arc?", choices: ["90", "45", "180", "30"], answer: 0, explain: "The circumference is 20π, and 5π is 1/4 of it, so the angle is (1/4)(360°) = 90°.", pattern: "Arc Length and Sector Area as Fractions of the Whole Circle", difficulty: "easy", trapFor: [null, null, null, null], },
  { q: "The circle (x - 1)² + (y + 2)² = 25 contains two points with an x-coordinate of 4. What are the y-coordinates of these points?", choices: ["2 and -6", "2 only", "-2 and 6", "4 and -4"], answer: 0, explain: "Substitute x = 4: 9 + (y + 2)² = 25, so (y + 2)² = 16 and y + 2 = ±4. Then y = 2 or y = -6. '2 only' misses the negative square root.", pattern: "Solving the Circle Equation for a Coordinate's Possible Values", difficulty: "medium", trapFor: [null, 0, null, null], },
  { q: "Which point lies inside the circle x² + y² = 50?", choices: ["(5, 4)", "(5, 5)", "(6, 4)", "(7, 1)"], answer: 0, explain: "A point is inside when x² + y² < 50. (5, 4) gives 41. (5, 5) and (7, 1) give exactly 50, so they lie on the circle, and (6, 4) gives 52, outside it.", pattern: "Solving the Circle Equation for a Coordinate's Possible Values", difficulty: "medium", trapFor: [null, null, null, null], },
  { q: "The point (6, b) lies on the circle x² + y² = 100. What are all possible values of b?", choices: ["8 and -8", "8 only", "4 and -4", "2√34"], answer: 0, explain: "36 + b² = 100, so b² = 64 and b = ±8. Both points are on the circle.", pattern: "Solving the Circle Equation for a Coordinate's Possible Values", difficulty: "easy", trapFor: [null, 0, null, null], },
  { q: "In the figure, O is the center of the circle, and points A, B, and C lie on the circle. The measure of central angle AOB is 100°.\n\nWhat is the value of x?", choices: ["50", "100", "200", "80"], answer: 0, explain: "An inscribed angle is half the central angle that intercepts the same arc: x = 100/2 = 50. Treating the inscribed angle like a central angle gives 100.", pattern: "Circle Theorems: Central Angles, Arcs, and Tangent Lines", difficulty: "medium", figure: {"points": {"O": [0, 0], "A": [-4.6985, -1.7101], "B": [2.5, -4.3301], "C": [0.8682, 4.924]}, "names": ["O", "A", "B", "C"], "namePos": {"O": 90}, "dots": ["O"], "circles": [{"center": "O", "radius": 5}], "segments": [{"from": "O", "to": "A"}, {"from": "O", "to": "B"}, {"from": "C", "to": "A"}, {"from": "C", "to": "B"}], "angles": [{"vertex": "O", "from": "A", "to": "B", "label": "100°"}, {"vertex": "C", "from": "A", "to": "B", "label": "x°"}], "kind": "geometry"}, trapFor: [null, 0, null, null], },
  { q: "In the figure, the line is tangent to the circle with center O at point P. The radius OP is 5, and PQ = 12.\n\nWhat is the length of OQ?", choices: ["13", "17", "7", "√119"], answer: 0, explain: "A tangent is perpendicular to the radius at the point of tangency, so triangle OPQ has a right angle at P: OQ = √(5² + 12²) = 13. √119 treats OQ as a leg.", pattern: "Circle Theorems: Central Angles, Arcs, and Tangent Lines", difficulty: "medium", figure: {"points": {"O": [0, 0], "P": [0, -5], "Q": [12, -5], "T1": [-3, -5], "T2": [15, -5]}, "names": ["O", "P", "Q"], "namePos": {"P": 270, "Q": 270}, "dots": ["O"], "circles": [{"center": "O", "radius": 5}], "segments": [{"from": "T1", "to": "T2", "arrows": true}, {"from": "O", "to": "P", "label": "5"}, {"from": "P", "to": "Q", "label": "12", "side": -1}, {"from": "O", "to": "Q"}], "angles": [{"vertex": "P", "from": "Q", "to": "O", "right": true}], "kind": "geometry"}, trapFor: [null, null, null, 1], },
  { q: "In the figure, O is the center of the circle, the radius is 7, and the measure of angle AOB is 60°.\n\nWhat is the length of chord AB?", choices: ["7", "7√3", "14", "7√2"], answer: 0, explain: "OA and OB are both radii, so triangle AOB is isosceles; with a 60° angle between them, the other two angles are also 60°, making the triangle equilateral. AB = 7.", pattern: "Circle Theorems: Central Angles, Arcs, and Tangent Lines", difficulty: "medium", figure: {"points": {"O": [0, 0], "A": [6.0622, 3.5], "B": [0.0, 7.0]}, "names": ["O", "A", "B"], "namePos": {"O": 270}, "circles": [{"center": "O", "radius": 7}], "segments": [{"from": "O", "to": "A", "label": "7"}, {"from": "O", "to": "B"}, {"from": "A", "to": "B"}], "angles": [{"vertex": "O", "from": "A", "to": "B", "label": "60°"}], "kind": "geometry"}, trapFor: [null, 2, 2, 2], },
  { q: "In the figure, AB is a diameter of the circle with center O, and C lies on the circle. AC = 6 and BC = 8.\n\nWhat is the radius of the circle?", choices: ["5", "10", "7", "14"], answer: 0, explain: "An angle inscribed in a semicircle is a right angle, so AB = √(6² + 8²) = 10. The radius is half the diameter: 5. 10 is the diameter.", pattern: "Circle Theorems: Central Angles, Arcs, and Tangent Lines", difficulty: "hard", figure: {"points": {"O": [0, 0], "A": [-5, 0], "B": [5, 0], "C": [-1.4, 4.8]}, "names": ["A", "B", "C", "O"], "namePos": {"O": 270}, "dots": ["O"], "circles": [{"center": "O", "radius": 5}], "segments": [{"from": "A", "to": "B"}, {"from": "A", "to": "C", "label": "6"}, {"from": "C", "to": "B", "label": "8"}], "angles": [{"vertex": "C", "from": "A", "to": "B", "right": true}], "kind": "geometry"}, trapFor: [null, null, null, null], },
],
};
